import React, { Fragment } from "react";
import {
  Button,
  Grid,
  makeStyles,
  Typography,
  useMediaQuery,
  useTheme,
  Tooltip,
  TextField,
  MenuItem,
} from "@material-ui/core";

import DatePicker from "../../Shared/DatePicker";

import { ExpandMore } from "@material-ui/icons";
import { typesOfItems } from "../../../configs/contracts/TYPES_OF_ITEMS";
import Spinner from "../../UI/Spinner";

import TaxOrServiceForm from "../FormComponents/TaxOrServiceForm";
import FreeItemForm from "../FormComponents/FreeItemForm";
import { useSelector } from "react-redux";
import { months } from "../../../configs/contracts/DAYS_MONTHS";
import { disabledHook, formatData } from "./hooks";
import Rental from "../FormComponents/Rental";

const useStyles = makeStyles((theme) => ({
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "left",
  },
  buttons: {
    justifyContent: "center",
    marginTop: theme.spacing(3.5),
    "& .MuiTooltip-tooltip": {
      backgroundColor: "red",
    },
  },
}));

const Form = ({
  title,
  setOpen,
  isLoading,
  onClikHandler,
  data,
  hasChanged,
  setHasChanged,
  currentItemType,
  itemType,
  setItemType,
  expirationDate,
  setExpirationDate,
  monthsValue,
  setMonths,
  rentalData,
  setRentalData,
  setFormRental,
  dataService,
  setDataService,
  setFormService,
  dataFreeItem,
  setDataFreeItem,
  setFormFreeItem,
}) => {
  const classes = useStyles();

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("800"), {
    defaultMatches: true,
  });

  const services = useSelector((state) => state.services.services);

  const auxNotes = {
    1: {
      value: rentalData.notes.value,
      onChange: (e) => setRentalData(e),
      isValid: rentalData.notes.isValid,
    },
    2: {
      value: dataService.notes.value,
      onChange: (e) => setDataService(e),
      isValid: dataService.notes.isValid,
    },
    3: {
      value: dataFreeItem.notes.value,
      onChange: (e) => setDataFreeItem(e),
      isValid: dataFreeItem.notes.isValid,
    },
  };

  const onChangeData = () => {
    if (setHasChanged && hasChanged === false) {
      setHasChanged(true);
    }
  };

  const handleDateChange = (date) => {
    let formatDate = date.toISOString();
    setExpirationDate(formatDate);
    onChangeData();
  };

  const onChange = (e) => {
    setItemType(e);

    if (data ? (currentItemType !== 1 ? true : false) : true) {
      setFormRental((rentalData) => {
        let copy = { ...rentalData };
        for (let key in rentalData) {
          copy[key] = {
            value: "",
            isValid: true,
          };
        }
        return copy;
      });
    }

    if (data ? (currentItemType !== 2 ? true : false) : true) {
      setFormService((dataService) => {
        let copy = { ...dataService };
        for (let key in dataService) {
          copy[key] = {
            value:
              key === "paymentMethod"
                ? "1"
                : key === "tenantPay"
                ? "100"
                : key === "ownerPay"
                ? "0"
                : key === "payable"
                ? "true"
                : "",
            isValid: true,
          };
        }
        return copy;
      });
    }

    if (data ? (currentItemType !== 3 ? true : false) : true) {
      setFormFreeItem((dataFreeItem) => {
        let copy = { ...dataFreeItem };
        for (let key in dataFreeItem) {
          copy[key] = { value: key === "payable" ? "true" : "", isValid: true };
        }
        return copy;
      });
    }
  };

  const onClick = () => {
    let aux = {
      itemType: parseInt(itemType, 10),
      expirationDate,
    };

    if (!data) {
      aux.months = parseInt(monthsValue, 10);
    }

    onClikHandler(
      formatData(
        data ? true : false,
        itemType,
        aux,
        rentalData,
        dataService,
        dataFreeItem
      )
    );
  };

  let disabled = () =>
    disabledHook(
      data,
      hasChanged,
      itemType,
      expirationDate,
      monthsValue,
      dataService,
      dataFreeItem
    );

  return isLoading ? (
    <Spinner height={itemType === "" ? 172 : 446} />
  ) : (
    <Fragment>
      <Typography variant="h6">{title}</Typography>
      <Grid container className={classes.grid} spacing={2}>
        <Grid item xs={data ? 12 : 6}>
          <DatePicker
            required={true}
            label="Vencimiento"
            selectedDate={expirationDate}
            handleDateChange={(e) => handleDateChange(e)}
          />
        </Grid>
        {!data && (
          <Grid item xs={6}>
            <TextField
              label="Meses"
              id="months"
              value={monthsValue}
              onChange={(e) => {
                setMonths(e.target.value);
                onChangeData();
              }}
              select
              SelectProps={{
                IconComponent: ExpandMore,
              }}
              fullWidth
            >
              <MenuItem value=""></MenuItem>
              {months.map((entry, index) => (
                <MenuItem key={`select-${entry}-${index}`} value={entry}>
                  {entry}
                </MenuItem>
              ))}
            </TextField>
          </Grid>
        )}
        <Grid item xs={12}>
          <TextField
            disabled={data ? true : false}
            label="Tipo de item"
            id="itemType"
            value={itemType}
            onChange={(e) => {
              onChange(e.target.value);
            }}
            select
            SelectProps={{
              IconComponent: ExpandMore,
            }}
            fullWidth
          >
            <MenuItem value=""></MenuItem>
            {Object.entries(typesOfItems).map((entry, index) => (
              <MenuItem key={`select-${entry[0]}-${index}`} value={entry[0]}>
                {entry[1]}
              </MenuItem>
            ))}
          </TextField>
        </Grid>

        {itemType === "1" && (
          <Rental
            onChangeData={onChangeData}
            data={rentalData}
            setData={setRentalData}
            isMobile={isMobile}
            xs={6}
            addOrEditItem={true}
          />
        )}
        {itemType === "2" && (
          <TaxOrServiceForm
            feeAmount={true}
            onChangeData={onChangeData}
            services={services}
            data={dataService}
            setData={setDataService}
            setForm={setFormService}
            isMobile={isMobile}
            disabledButton={true}
            xs={6}
            addOrEditItem={true}
          />
        )}
        {itemType === "3" && (
          <FreeItemForm
            feeAmount={true}
            edit={data ? true : false}
            onChangeData={onChangeData}
            data={dataFreeItem}
            setData={setDataFreeItem}
            isMobile={isMobile}
            disabledButton={true}
            xs={6}
            addOrEditItem={true}
          />
        )}

        {itemType !== "" && (
          <Grid item xs={12}>
            <TextField
              id="notes"
              name="notes"
              label="Notas"
              multiline
              rows={4}
              value={auxNotes[itemType].value}
              variant="outlined"
              onChange={(e) => {
                auxNotes[itemType].onChange(e);
                onChangeData();
              }}
              fullWidth
              inputProps={{
                minLength: 2,
                maxLength: 100,
                pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
              }}
              error={!auxNotes[itemType].isValid}
            />
          </Grid>
        )}
      </Grid>
      <Grid container className={classes.buttons} spacing={1}>
        <Grid item xs={12} sm={6}>
          <Button
            id="cancel-button"
            variant="outlined"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Cancelar
          </Button>
        </Grid>
        <Grid item xs={12} sm={6}>
          <Tooltip
            title={
              !disabled() && hasChanged
                ? ""
                : "Debe rellenar todos los campos para poder continuar"
            }
            leaveDelay={5000}
            interactive
          >
            <div>
              <Button
                disabled={!disabled() && hasChanged ? false : true}
                variant="contained"
                color="primary"
                disableElevation
                fullWidth
                onClick={onClick}
              >
                Aceptar
              </Button>
            </div>
          </Tooltip>
        </Grid>
      </Grid>
    </Fragment>
  );
};

export default Form;
