import React, { useState } from "react";
import {
  IconButton,
  makeStyles,
  MenuItem,
  TextField,
  Tooltip,
} from "@material-ui/core";

import ContactsAutoComplete from "../../Shared/ContactsAutoComplete";
import { useForm } from "../../../hooks/use-form";
import { types } from "../../../configs/contracts/TenantsAndGuarantors/TYPES";

import AddIcon from "@material-ui/icons/Add";
import { ExpandMore } from "@material-ui/icons";

const useStyles = makeStyles((theme) => ({
  container: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "flex-end",
  },
  addButton: {
    padding: theme.spacing(0.5),
  },
}));

const TenantsAndGuarantors = ({ contacts, onChangeData, addUser }) => {
  const classes = useStyles();

  const [contact, setContact] = useState("");
  const [form, onChangeHandler, setForm] = useForm({ type: "" });

  const onClick = () => {
    addUser(contact, form.type.value);
    setContact("");
    setForm((form) => {
      let copy = { ...form };
      for (let key in form) {
        copy[key] = { value: "", isValid: true };
      }
      return copy;
    });
    onChangeData();
  };

  return (
    <div className={classes.container}>
      <div style={{ width: "100%", paddingRight: 16 }}>
        <ContactsAutoComplete
          label="Usuario"
          contacts={contacts}
          contact={contact}
          setState={(value) => {
            if (value) {
              setContact(value._id);
            } else {
              setContact("");
            }
          }}
        />
      </div>

      <TextField
        style={{ width: "100%", paddingRight: 16 }}
        label="Tipo"
        id="type"
        value={form.type.value}
        onChange={(e) => {
          e.target.id = "type";
          onChangeHandler(e);
        }}
        select
        SelectProps={{
          IconComponent: ExpandMore,
        }}
        fullWidth
      >
        <MenuItem value=""></MenuItem>
        {Object.entries(types).map((entry, index) => (
          <MenuItem key={`select-${entry[0]}-${index}`} value={entry[0]}>
            {entry[1]}
          </MenuItem>
        ))}
      </TextField>

      <Tooltip
        title={
          form.type.value !== "" && contact !== ""
            ? `Agregar ${types[form.type.value].toLowerCase()}`
            : ""
        }
      >
        <div>
          <IconButton
            disabled={form.type.value !== "" && contact !== "" ? false : true}
            className={classes.addButton}
            variant="contained"
            aria-label="add"
            onClick={onClick}
          >
            <AddIcon />
          </IconButton>
        </div>
      </Tooltip>
    </div>
  );
};

export default TenantsAndGuarantors;
