import axios from "axios";
import {
  GET_CATEGORIES,
  ADD_CATEGORY,
  EDIT_CATEGORY,
  DELETE_CATEGORY,
} from "./actionTypes";
import { setSnackData } from "./snackDataActions";

export const getCategories = (id, token, setIsLoading) => (dispatch) => {
  axios
    .get(`${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/categories`, {
      headers: {
        Authorization: "Bearer " + token,
      },
    })
    .then((res) => {
      const categories = res.data.sort((a, b) => a.name.localeCompare(b.name));
      
      dispatch({
        type: GET_CATEGORIES,
        payload: categories,
      });
      if (setIsLoading) setIsLoading(false);
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }
      if (setIsLoading) setIsLoading(false);
    });
};

export const addCategory =
  (id, token, data, setOpen, setIsLoading) => (dispatch, getState) => {
    let categories = getState().categories.categories;
    axios
      .post(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/categories`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        categories.push(res.data);
        dispatch({
          type: ADD_CATEGORY,
          payload: categories,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Categoría creada",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const editCategory =
  (id, token, idCat, data, setOpen, setIsLoading) => (dispatch, getState) => {
    let categories = getState().categories.categories;
    axios
      .put(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/categories/${idCat}`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        let i = categories.findIndex((category) => {
          if (category._id === idCat) {
            return true;
          }
          return false;
        });

        if (i !== -1) {
          categories[i] = Object.assign(categories[i], data);
        }

        dispatch({
          type: EDIT_CATEGORY,
          payload: categories,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Categoría editada",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const deleteCategory =
  (id, token, idCat, setOpen, setIsLoading) => (dispatch, getState) => {
    let categories = getState().categories.categories;
    axios
      .delete(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/categories/${idCat}`,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        let i = categories.findIndex((category) => {
          if (category._id === idCat) {
            return true;
          }
          return false;
        });

        i !== -1 && categories.splice(i, 1);

        dispatch({
          type: DELETE_CATEGORY,
          payload: categories,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Categoría eliminada",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };
