import React, { useState, useEffect, Fragment } from "react";
import {
  IconButton,
  makeStyles,
  Tooltip,
  Button,
  Hidden,
} from "@material-ui/core";
import AddIcon from "@material-ui/icons/Add";
import ReloadIcon from "@material-ui/icons/Cached";
import Tabs from "../../Shared/Tabs";

import Modal from "../../Shared/Modal";

import { useSelector, useDispatch } from "react-redux";

import Spinner from "../../UI/Spinner";
import Expenses from "./Expenses/Expenses";
import CurrentAccount from "./CurrentAccount/CurrentAccount";
import { getExpenses } from "../../../Redux/Action/expensesActions";
import { Alert } from "@material-ui/lab";
import { getTransactions } from "../../../Redux/Action/functionalUnitsActions";
import Payments from "../../Payments/Payments";
import { getPayments } from "../../../Redux/Action/paymentsActions";
import AddPayment from "../../Payments/AddPayment";
import { getBoxes } from "../../../Redux/Action/boxesActions";
import { NumberFormatCustom } from "../../../hooks/format-number-hook";

const useStyles = makeStyles((theme) => ({
  root: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    marginTop: theme.spacing(3),
    marginBottom: theme.spacing(3),
    "@media (min-width:960px)": {
      margin: "auto",
      marginBottom: theme.spacing(6),
    },
  },
  container: {
    width: "100%",
    display: "flex",
    marginBottom: theme.spacing(2),
    alignItems: "center",
    flexDirection: "column",
    justifyContent: "space-between",
    "@media (min-width:830px)": {
      flexDirection: "row",
    },
  },
  tabsContainer: {
    "@media (max-width:830px)": {
      width: "100%",
    },
  },
  actionsButtons: {
    display: "flex",
    alignItems: "center",
    justifyContent: "flex-end",
    "@media (max-width:830px)": {
      marginTop: theme.spacing(1),
      width: "100%",
    },
  },
  reload: {
    padding: theme.spacing(0.75),
    marginRight: theme.spacing(2.5),
  },
  add: {
    padding: theme.spacing(0.75),
  },
  titleSection: {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
  },
  title: {
    marginRight: theme.spacing(1),
    fontSize: "20px",
    "@media (min-width:650px)": {
      fontSize: "24px",
    },
  },
}));

const labels = ["Expensas", "Cta. Corriente", "Pagos"];

const TabPanel = ({ children, value, index }) => {
  return (
    <div id={`tabPanel${index}`} style={{ width: "100%", display: "contents" }}>
      {value === index && children}
    </div>
  );
};

const Data = ({
  id,
  user,
  currentUF,
  expenses,
  expendituresTypes,
  onClickHandler,
}) => {
  const classes = useStyles();
  const dispatch = useDispatch();

  const boxes = useSelector((state) => state.boxes.boxes);
  const transactions = useSelector(
    (state) => state.transactions.transactionsFU
  );

  const [isLoading, setIsLoading] = useState(true);
  const [isLoadingComponent, setIsLoadingComponent] = useState(true);
  const [open, setOpen] = useState(false);
  const [value, setValue] = useState(0);

  const handleChange = (e) => {
    if (value !== e) {
      setIsLoadingComponent(true);
      setValue(e);
    }
  };

  const reloadActions = {
    0: () => {
      setIsLoadingComponent(true);
      dispatch(getExpenses(id, user.token, setIsLoadingComponent));
    },
    1: () => {
      setIsLoadingComponent(true);
      dispatch(
        getTransactions(id, currentUF._id, user.token, setIsLoadingComponent)
      );
    },
    2: () => {
      setIsLoadingComponent(true);
      dispatch(
        getPayments(id, currentUF._id, user.token, setIsLoadingComponent)
      );
    },
  };

  useEffect(() => {
    dispatch(getBoxes(id, user.token, setIsLoading));
  }, [dispatch, id, user.token]);

  return isLoading ? (
    <Spinner />
  ) : (
    <Fragment>
      <div className={classes.container}>
        <div className={classes.tabsContainer}>
          <Tabs
            value={value}
            setValue={(e) => handleChange(e)}
            labels={labels}
            variant="fullWidth"
          />
        </div>
        <div className={classes.actionsButtons}>
          {!isLoadingComponent && (
            <Tooltip title="Recargar tabla">
              <IconButton
                className={classes.reload}
                variant="contained"
                aria-label="add"
                onClick={reloadActions[value]}
              >
                <ReloadIcon />
              </IconButton>
            </Tooltip>
          )}
          {value === 1 && !isLoadingComponent && (
            <Tooltip
              title={
                transactions.balance >= 0 ? "Saldo positivo" : "Saldo negativo"
              }
            >
              <Alert
                style={{ padding: "4px 16px" }}
                icon={false}
                severity={transactions.balance >= 0 ? "success" : "error"}
              >
                {"Saldo: "}
                {NumberFormatCustom(transactions.balance.replace(/\./g, ","))}
              </Alert>
            </Tooltip>
          )}
          {user.isAdmin && value === 2 && !isLoadingComponent && (
            <Fragment>
              <Hidden xsDown>
                <Button
                  variant="contained"
                  disableElevation
                  startIcon={<AddIcon />}
                  onClick={() => setOpen(true)}
                >
                  Registrar pago
                </Button>
              </Hidden>
              <Hidden smUp>
                <Tooltip title="Registrar pago">
                  <IconButton
                    className={classes.reload}
                    variant="contained"
                    aria-label="add"
                    onClick={() => setOpen(true)}
                  >
                    <AddIcon />
                  </IconButton>
                </Tooltip>
              </Hidden>
            </Fragment>
          )}
        </div>
      </div>
      <TabPanel value={value} index={0}>
        <Expenses
          expenses={expenses}
          currentUF={currentUF}
          expendituresTypes={expendituresTypes}
          isLoadingComponent={isLoadingComponent}
          setIsLoadingComponent={setIsLoadingComponent}
        />
      </TabPanel>
      <TabPanel value={value} index={1}>
        <CurrentAccount
          id={id}
          token={user.token}
          currentUF={currentUF}
          isLoadingComponent={isLoadingComponent}
          setIsLoadingComponent={setIsLoadingComponent}
        />
      </TabPanel>
      <TabPanel value={value} index={2}>
        <Payments
          id={id}
          user={user}
          currentUF={currentUF}
          boxes={boxes}
          isLoadingComponent={isLoadingComponent}
          setIsLoadingComponent={setIsLoadingComponent}
        />
      </TabPanel>
      <Modal
        handleClose={() => setOpen(false)}
        open={open}
        component={
          <AddPayment
            id={id}
            idUF={currentUF._id}
            token={user.token}
            boxes={boxes}
            setOpen={setOpen}
          />
        }
      />
    </Fragment>
  );
};

export default Data;
