import React from "react";
import TextField from "@material-ui/core/TextField";
import Grid from "@material-ui/core/Grid";

export default function EstablishmentInputs({ onChangeHandler, form }) {
  return (
    <>
      <Grid item xs={12} sm={6}>
        <TextField
          name="name"
          variant="outlined"
          required
          fullWidth
          id="establishmentName"
          label="Nombre"
          onChange={onChangeHandler}
          value={form.establishmentName.value}
          inputProps={{
            minLength: 2,
            maxLength: 100,
            pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
          }}
          InputLabelProps={{ required: false }}
        />
      </Grid>
      <Grid item xs={12} sm={6}>
        <TextField
          variant="outlined"
          required
          fullWidth
          id="establishmentAddress"
          label="Dirección"
          name="address"
          onChange={onChangeHandler}
          value={form.establishmentAddress.value}
          inputProps={{
            minLength: 2,
            maxLength: 100,
            pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
          }}
          InputLabelProps={{ required: false }}
        />
      </Grid>
      <Grid item xs={12} sm={6}>
        <TextField
          type="tel"
          name="phone"
          variant="outlined"
          required
          fullWidth
          id="establishmentPhone"
          label="Teléfono"
          onChange={onChangeHandler}
          value={form.establishmentPhone.value}
          inputProps={{
            maxLength: 20,
            pattern: "^[0-9()-+]+$",
          }}
          InputLabelProps={{ required: false }}
        />
      </Grid>
      <Grid item xs={12} sm={6}>
        <TextField
          variant="outlined"
          required
          fullWidth
          id="establishmentEmail"
          label="Email"
          name="email"
          type="email"
          onChange={onChangeHandler}
          value={form.establishmentEmail.value}
          inputProps={{
            maxLength: 256,
          }}
          InputLabelProps={{ required: false }}
        />
      </Grid>
    </>
  );
}
