import {
  GET_BANKS,
  ADD_BANK,
  EDIT_BANK,
  DELETE_BANK,
} from "../Action/actionTypes";

const initialState = { banks: [] };

export const banksReducer = (state = initialState, action) => {
  switch (action.type) {
    case GET_BANKS:
      return {
        ...state,
        banks: action.payload,
      };
    case ADD_BANK:
      return {
        ...state,
        banks: action.payload,
      };
    case EDIT_BANK:
      return {
        ...state,
        banks: action.payload,
      };
    case DELETE_BANK:
      return {
        ...state,
        banks: action.payload,
      };
    default:
      return state;
  }
};

export default banksReducer;
