import React, { useState } from "react";
import {
  Button,
  Grid,
  makeStyles,
  TextField,
  Typography,
  useMediaQuery,
  useTheme,
  FormControl,
  InputLabel,
  Input,
  RadioGroup,
  FormControlLabel,
  Radio,
  Checkbox,
  IconButton,
  Tooltip,
} from "@material-ui/core";
import NumberFormat from "react-number-format";
import Spinner from "../UI/Spinner";
import DatePicker from "../Shared/DatePicker";
import { useForm } from "../../hooks/use-form";

import Alert from "@material-ui/lab/Alert";
import EditIcon from "@material-ui/icons/EditOutlined";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    width: theme.spacing(50),
    padding: theme.spacing(5),
    "@media (max-width:650px)": {
      width: theme.spacing(30),
      padding: theme.spacing(1),
    },
    "@media (max-width:400px)": {
      width: theme.spacing(20),
      padding: 0,
    },
  },
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  expendituresSection: {
    display: "flex",
    marginTop: theme.spacing(2),
  },
  title: {
    fontSize: "14px",
    textAlign: "initial",
  },
  marginBottom: {
    marginBottom: theme.spacing(2.5),
  },
  expenditureClass: {
    width: "100%",
    marginTop: theme.spacing(2),
    "& .MuiFormControlLabel-root": {
      "& .MuiTypography-body1": {
        fontSize: "13px",
      },
    },
  },
  buttons: {
    marginTop: theme.spacing(2.5),
  },
  iconButton: {
    color: "#1260BD",
  },
}));

function NumberFormatPercentage(props) {
  const { inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={2}
      isNumericString
      suffix="%"
    />
  );
}

function NumberFormatCustom(props) {
  const { inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={2}
      isNumericString
      prefix="$"
    />
  );
}

const Form = ({
  title,
  setOpen,
  isLoading,
  onClikHandler,
  expenditures,
  setExpenditures,
  recurringExpenditures,
  setRecurringExpenditures,
  editExpenditure,
  getAmounts,
  amounts,
  dataAmounts,
  setData,
}) => {
  const classes = useStyles();

  const [selectedDate, setSelectedDate] = useState({
    date: null,
    expirationDate: null,
  });
  const [interest, setInterest] = useState("0");

  const [form, onChangeHandler] = useForm({ name: "", notes: "" });

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const setAmount = (id, event) => {
    setExpenditures((expenditures) => {
      let i = expenditures.findIndex((expenditure) => {
        if (expenditure.expenditureType === id) {
          return true;
        }
        return false;
      });

      let copy = [...expenditures];

      if (i !== -1) {
        copy[i].amount = event.target.value;
        if (event.target.value < 0) {
          copy[i].isValid = false;
        } else {
          copy[i].isValid = true;
        }
      }

      return copy;
    });
  };

  const handleDateChange = (key, date) => {
    let formatDate = date.toISOString();

    let aux = [];
    let data = { date: formatDate };

    setSelectedDate({ ...selectedDate, [key]: formatDate });

    if (key === "date") {
      setData({ ...dataAmounts, date: formatDate });

      for (let i = 0; i < recurringExpenditures.length; i++) {
        if (recurringExpenditures[i].checked) {
          aux.push(recurringExpenditures[i].expenditure._id);
        }
      }

      if (aux.length > 0) {
        data.recurrentExpenditures = aux;
      }

      getAmounts(data);
    }
  };

  const setChecked = (id, event) => {
    let aux = [];
    let data = { date: selectedDate.date };

    setRecurringExpenditures((recurringExpenditures) => {
      let i = recurringExpenditures.findIndex((expenditure) => {
        if (expenditure.expenditure._id === id) {
          return true;
        }
        return false;
      });

      let copy = [...recurringExpenditures];

      if (i !== -1) {
        copy[i].checked = event.target.checked;
      }

      return copy;
    });

    for (let i = 0; i < recurringExpenditures.length; i++) {
      if (recurringExpenditures[i].checked) {
        aux.push(recurringExpenditures[i].expenditure._id);
      }
    }

    if (aux.length > 0) {
      data.recurrentExpenditures = aux;
      setData({ ...dataAmounts, recurrentExpenditures: aux });
    }

    if (data.date !== null) {
      getAmounts(data);
    }
  };

  const setMode = (id, index, event) => {
    setExpenditures((expenditures) => {
      let i = expenditures.findIndex((expenditure) => {
        if (expenditure.expenditureType === id) {
          return true;
        }
        return false;
      });

      let copy = [...expenditures];

      if (i !== -1) {
        copy[i].mode = event.target.value;
        if (event.target.value === "expenditures") {
          copy[i].isValid = true;
          copy[i].amount = "0";
        }
      }

      return copy;
    });
  };

  const formatData = () => {
    let aux = [];
    let expendituresTypesModes = [...expenditures];

    let data = {
      name: form.name.value,
      date: selectedDate.date,
      expirationDate: selectedDate.expirationDate,
      interest: interest,
    };

    for (let i = 0; i < expendituresTypesModes.length; i++) {
      delete expendituresTypesModes[i].isValid;
    }

    data.expendituresTypesModes = expendituresTypesModes;

    for (let i = 0; i < recurringExpenditures.length; i++) {
      if (recurringExpenditures[i].checked) {
        aux.push(recurringExpenditures[i].expenditure._id);
      }
    }

    if (aux.length > 0) {
      data.recurrentExpenditures = aux;
    }

    if (form.notes.value !== "" && form.notes.isValid) {
      data.notes = form.notes.value;
    }

    onClikHandler(data);
  };

  let disabled =
    interest === "" ||
    interest > 100 ||
    interest < 0 ||
    Object.entries(form)
      .filter((entry) => entry[0] !== "notes")
      .some((entry) => entry[1].value === "" || entry[1].isValid !== true) ||
    expenditures.length < 0 ||
    expenditures
      .filter((entry) => entry.mode === "fixed")
      .some((entry) => entry.amount === "" || entry.isValid !== true) ||
    Object.entries(selectedDate).some((entry) => entry[1] === null);

  return isLoading ? (
    <Spinner />
  ) : (
    <div>
      <Typography variant="h6">{title}</Typography>
      <Grid container className={classes.grid} spacing={2}>
        <Grid item xs={12} sm={6}>
          <DatePicker
            label="Conformación"
            selectedDate={selectedDate.date}
            handleDateChange={(e) => handleDateChange("date", e)}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <DatePicker
            label="Vencimiento"
            selectedDate={selectedDate.expirationDate}
            handleDateChange={(e) => handleDateChange("expirationDate", e)}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            value={form.name.value}
            required
            autoComplete="off"
            fullWidth
            id="name"
            name="name"
            label="Título"
            inputProps={{
              minLength: 2,
              maxLength: 100,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
            }}
            error={!form.name.isValid}
            helperText={
              !form.name.isValid &&
              (form.name.value.length < 2
                ? "Pocos caracteres"
                : "Titulo inválido")
            }
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            InputProps={{
              inputComponent: NumberFormatPercentage,
            }}
            value={interest}
            required
            autoComplete="off"
            fullWidth
            id="interest"
            name="interest"
            label="Interés pago fuera de termino por día"
            placeholder="0"
            inputProps={{
              min: "0",
              max: "100",
              pattern: "[0-9]+",
              step: ".01",
            }}
            error={interest > 100 || interest < 0}
            onChange={(e) => setInterest(e.target.value)}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            id="notes"
            label="Notas (Opcional)"
            multiline
            rows={4}
            defaultValue={form.notes.value}
            variant="outlined"
            onChange={(e) => {
              onChangeHandler(e);
            }}
            fullWidth
            inputProps={{
              maxLength: 300,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
            }}
            error={!form.notes.isValid}
          />
        </Grid>
        {recurringExpenditures && recurringExpenditures.length > 0 && (
          <Grid item xs={12} className={classes.expendituresSection}>
            <Typography className={classes.title}>
              Gastos recurrentes a incluir (Seleccionar fecha de conformación
              primero)
            </Typography>
          </Grid>
        )}
        {recurringExpenditures &&
          recurringExpenditures.length > 0 &&
          recurringExpenditures.map((expenditure, index) => (
            <Alert
              key={index}
              icon={false}
              className={classes.expenditureClass}
            >
              <Grid
                container
                spacing={1}
                alignItems="center"
                justifycontent="flex-end"
              >
                <Grid
                  item
                  xs={2}
                  style={{ display: "flex", justifyContent: "flex-start" }}
                >
                  <Checkbox
                    disabled={selectedDate.date === null ? true : false}
                    color="primary"
                    checked={expenditure.checked}
                    onChange={setChecked.bind(
                      this,
                      expenditure.expenditure._id
                    )}
                    inputProps={{ "aria-label": "primary checkbox" }}
                  />
                </Grid>
                <Grid item xs={5}>
                  <FormControl style={{ width: "100%" }}>
                    <InputLabel htmlFor="my-input">Categoria</InputLabel>
                    <Input
                      disabled={!expenditure.checked}
                      id={`expenditure-category-${expenditure.expenditure.category.name}`}
                      value={expenditure.expenditure.category.name}
                      name={`expenditure-category-${expenditure.expenditure.category.name}`}
                      fullWidth
                      readOnly={true}
                    />
                  </FormControl>
                </Grid>
                <Grid item xs={5}>
                  <FormControl style={{ width: "100%" }}>
                    <InputLabel htmlFor="my-input">Subcategoria</InputLabel>
                    <Input
                      disabled={!expenditure.checked}
                      id={`expenditure-subcategory-${
                        expenditure.expenditure.subcategory
                          ? expenditure.expenditure.subcategory.name
                          : "..."
                      }`}
                      value={
                        expenditure.expenditure.subcategory
                          ? expenditure.expenditure.subcategory.name
                          : "..."
                      }
                      name={`expenditure-subcategory-${
                        expenditure.expenditure.subcategory
                          ? expenditure.expenditure.subcategory.name
                          : "..."
                      }`}
                      fullWidth
                      readOnly={true}
                    />
                  </FormControl>
                </Grid>
                <Grid
                  item
                  xs={2}
                  style={{ display: "flex", justifyContent: "flex-start" }}
                >
                  <Tooltip title="Editar gasto">
                    <div>
                      <IconButton
                        disabled={!expenditure.checked}
                        className={classes.iconButton}
                        onClick={() => {
                          editExpenditure(expenditure.expenditure);
                        }}
                      >
                        <EditIcon />
                      </IconButton>
                    </div>
                  </Tooltip>
                </Grid>
                <Grid item xs={10}>
                  <FormControl style={{ width: "100%" }}>
                    <InputLabel htmlFor="my-input">Monto</InputLabel>
                    <Input
                      disabled={!expenditure.checked}
                      inputComponent={NumberFormatCustom}
                      id={`expenditure-amount-${expenditure.expenditure.amount.amount}`}
                      value={expenditure.expenditure.amount.amount}
                      name={`expenditure-amount-${expenditure.expenditure.amount.amount}`}
                      fullWidth
                      readOnly={true}
                    />
                  </FormControl>
                </Grid>
              </Grid>
            </Alert>
          ))}
        {expenditures && expenditures.length > 0 && (
          <Grid item xs={12} className={classes.expendituresSection}>
            <Typography className={classes.title}>
              Complete los siguientes datos para cubrir el monto deseado
              (Seleccionar fecha de conformación primero)
            </Typography>
          </Grid>
        )}
      </Grid>
      {expenditures &&
        expenditures.length > 0 &&
        expenditures.map((expenditure, index) => (
          <Alert key={index} icon={false} className={classes.expenditureClass}>
            <Grid container spacing={1}>
              <Grid item xs={12}>
                <RadioGroup
                  aria-label="recurrent"
                  name="recurrent"
                  value={expenditure.mode}
                  onChange={setMode.bind(
                    this,
                    expenditure.expenditureType,
                    index
                  )}
                  row
                  style={{ justifyContent: "space-between" }}
                >
                  <FormControlLabel
                    disabled={selectedDate.date === null ? true : false}
                    value="fixed"
                    control={<Radio color="primary" />}
                    label="Monto fijo"
                  />
                  <FormControlLabel
                    disabled={selectedDate.date === null ? true : false}
                    value="expenditures"
                    control={<Radio color="primary" />}
                    label="Calculo por gastos"
                  />
                </RadioGroup>
              </Grid>
              <Grid item xs={6}>
                <FormControl style={{ width: "100%" }}>
                  <InputLabel htmlFor="my-input">Clase de gasto</InputLabel>
                  <Input
                    disabled={selectedDate.date === null ? true : false}
                    id={`expenditureType-${expenditure.name}`}
                    value={expenditure.name}
                    name={`expenditureType-${expenditure.name}`}
                    fullWidth
                    readOnly={true}
                  />
                </FormControl>
              </Grid>
              <Grid item xs={6}>
                <TextField
                  disabled={
                    selectedDate.date === null
                      ? true
                      : expenditure.mode !== "fixed"
                      ? true
                      : false
                  }
                  InputProps={{
                    inputComponent: NumberFormatCustom,
                  }}
                  value={
                    expenditure.mode !== "expenditures"
                      ? expenditure.amount
                      : amounts.length > 0
                      ? amounts[index].amount
                      : "0"
                  }
                  required
                  autoComplete="off"
                  fullWidth
                  id={`percentaje-${expenditure.name}`}
                  name={`percentaje-${expenditure.name}`}
                  label="Valor"
                  placeholder="0"
                  helperText={
                    expenditure.mode === "fixed" &&
                    (!expenditures[index].isValid &&
                    expenditures[index].amount < 0
                      ? "No puede ser negativo"
                      : "")
                  }
                  error={
                    expenditures[index].mode === "fixed" &&
                    !expenditures[index].isValid
                  }
                  onChange={setAmount.bind(this, expenditure.expenditureType)}
                  InputLabelProps={{ required: false }}
                />
              </Grid>
            </Grid>
          </Alert>
        ))}
      <Grid container className={classes.buttons} spacing={1}>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            id="cancel-button"
            variant="outlined"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Cancelar
          </Button>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            disabled={disabled}
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={formatData}
          >
            Aceptar
          </Button>
        </Grid>
      </Grid>
    </div>
  );
};

export default Form;
