import {
  GET_EXPENDITURES,
  ADD_EXPENDITURE,
  EDIT_EXPENDITURE,
  DELETE_EXPENDITURE,
} from "../Action/actionTypes";

const initialState = { expenditures: [], filteredExpenditures: [] };

export const expendituresReducer = (state = initialState, action) => {
  switch (action.type) {
    case GET_EXPENDITURES:
      return {
        ...state,
        expenditures: action.payload.expenditures,
        filteredExpenditures: action.payload.filteredExpenditures,
      };
    case ADD_EXPENDITURE:
      return {
        ...state,
        expenditures: action.payload.expenditures,
        filteredExpenditures: action.payload.filteredExpenditures,
      };
    case EDIT_EXPENDITURE:
      return {
        ...state,
        expenditures: action.payload.expenditures,
        filteredExpenditures: action.payload.filteredExpenditures,
      };
    case DELETE_EXPENDITURE:
      return {
        ...state,
        expenditures: action.payload.expenditures,
        filteredExpenditures: action.payload.filteredExpenditures,
      };
    default:
      return state;
  }
};

export default expendituresReducer;
