import React, { useState } from "react";
import {
  Button,
  Grid,
  makeStyles,
  TextField,
  Typography,
  useMediaQuery,
  useTheme,
  MenuItem,
  FormControl,
  InputLabel,
  Input,
  FormLabel,
  RadioGroup,
  FormControlLabel,
  Radio,
  Tooltip,
} from "@material-ui/core";
import NumberFormat from "react-number-format";
import { ExpandMore } from "@material-ui/icons";
import Spinner from "../UI/Spinner";
import { useForm } from "../../hooks/use-form";
import DatePicker from "../Shared/DatePicker";
import { Fragment } from "react";
import UploadFile from "./UploadFile";
import { currency } from "../../configs/CURRENCY";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    width: theme.spacing(50),
    padding: theme.spacing(5),
    "@media (max-width:650px)": {
      width: theme.spacing(30),
      padding: theme.spacing(1),
    },
    "@media (max-width:400px)": {
      width: theme.spacing(20),
      padding: 0,
    },
  },
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  expendituresSection: {
    display: "flex",
    marginTop: theme.spacing(2),
    marginBottom: theme.spacing(2),
  },
  title: {
    fontSize: "14px",
  },
  marginBottom: {
    marginBottom: theme.spacing(2.5),
  },
  buttons: {
    marginTop: theme.spacing(2.5),
    "& .MuiTooltip-tooltip": {
      backgroundColor: "red",
    },
  },
  file: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "flex-end",
  },
}));

function NumberFormatPercentage(props) {
  const { inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={2}
      isNumericString
      suffix="%"
    />
  );
}

function NumberFormatCustom(props) {
  const { inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={2}
      isNumericString
      prefix="$"
    />
  );
}

const payStates = ["Pago", "Pendiente"];

const initialState = {
  category: "",
  subcategory: "",
  provider: "",
  currency: "ARS",
  description: "",
  number: "",
  status: "",
  box: "",
  isRecurrent: "false",
};

const Form = ({
  categories,
  subcategories,
  providers,
  title,
  setOpen,
  isLoading,
  onClikHandler,
  data,
  hasChanged,
  setHasChanged,
  expenditures,
  setExpenditures,
  boxes,
  establishment,
}) => {
  const classes = useStyles();

  const [amount, setAmount] = useState(data ? data.amount.amount : "");
  const [selectedDate, setSelectedDate] = useState(
    data
      ? { date: data.date, expirationDate: data.expirationDate }
      : { date: null, expirationDate: null }
  );
  const [file, setFile] = useState(data ? data.file : null);

  const [form, onChangeHandler] = useForm(
    data
      ? {
          category: data.category._id,
          subcategory: data.subcategory ? data.subcategory._id : "",
          provider: data.provider._id,
          currency: data.amount.currency,
          description: data.description || "",
          number: data.number,
          status: data.status,
          box: data.box || "",
          isRecurrent: data.isRecurrent ? "true" : "false",
        }
      : initialState
  );

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const onChangeData = () => {
    if (setHasChanged && hasChanged === false) {
      setHasChanged(true);
    }
  };

  const handleDateChange = (key, date) => {
    let formatDate = date.toISOString();
    onChangeData();
    setSelectedDate({ ...selectedDate, [key]: formatDate });
  };

  const setPercentage = (id, event) => {
    setExpenditures((expenditures) => {
      let i = expenditures.findIndex((expenditure) => {
        if (expenditure.expenditureType === id) {
          return true;
        }
        return false;
      });

      let copy = [...expenditures];

      if (i !== -1) {
        copy[i].percentage = event.target.value;
      }

      return copy;
    });

    onChangeData();
  };

  const formatData = () => {
    let data = {
      category: form.category.value,
      provider: form.provider.value,
      amount: { amount: amount, currency: form.currency.value },
      number: form.number.value,
      status: form.status.value,
      expirationDate: selectedDate.expirationDate,
      date: selectedDate.date,
      expendituresTypesPercentages: expenditures,
      isRecurrent: form.isRecurrent.value === "true" ? true : false,
    };

    if (form.description.value !== "") {
      data.description = form.description.value;
    }

    if (form.status.value === "Pago") {
      data.box = form.box.value;
    }

    if (file !== null) {
      data.file = file;
    }

    if (form.subcategory.value !== "") {
      data.subcategory = form.subcategory.value;
    }

    onClikHandler(data);
  };

  let disabled =
    hasChanged &&
    expenditures.length > 0 &&
    !Object.entries(selectedDate).some((entry) => entry[1] === null) &&
    !isNaN(amount) &&
    amount > 0 &&
    form.description.isValid &&
    !Object.entries(form)
      .filter(
        (entry) =>
          entry[0] !== "subcategory" &&
          entry[0] !== "description" &&
          entry[0] !== "box"
      )
      .some((entry) => entry[1].value === "") &&
    (form.status.value === "Pago"
      ? form.box.value !== ""
        ? true
        : false
      : true)
      ? false
      : true;

  return isLoading ? (
    <Spinner />
  ) : (
    <div>
      <Typography variant="h6">{title}</Typography>
      <Grid container className={classes.grid} spacing={2}>
        <Grid item xs={12}>
          <FormControl component="fieldset" fullWidth>
            <Grid container alignItems="center">
              <Grid item xs={6}>
                <FormLabel component="legend">Recurrente :</FormLabel>
              </Grid>
              <Grid item xs={6}>
                <RadioGroup
                  aria-label="recurrent"
                  name="recurrent"
                  value={form.isRecurrent.value}
                  onChange={(e) => {
                    e.target.id = "isRecurrent";
                    onChangeHandler(e);
                    onChangeData();
                  }}
                  row
                >
                  <FormControlLabel
                    value="true"
                    control={<Radio color="primary" />}
                    label="Sí"
                  />
                  <FormControlLabel
                    value="false"
                    control={<Radio color="primary" />}
                    label="No"
                  />
                </RadioGroup>
              </Grid>
            </Grid>
          </FormControl>
        </Grid>
        <Grid item xs={12}>
          <TextField
            label="Categoria"
            id="category"
            value={form.category.value}
            onChange={(e) => {
              e.target.id = "category";
              onChangeHandler(e);
              onChangeHandler({ target: { id: "subcategory", value: "" } });
              onChangeData();
            }}
            select
            SelectProps={{
              IconComponent: ExpandMore,
            }}
            fullWidth
          >
            <MenuItem value=""></MenuItem>
            {categories.map((category, index) => (
              <MenuItem key={`select-${category._id}`} value={category._id}>
                {category.name}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
        <Grid item xs={12}>
          <TextField
            disabled={form.category.value === "" ? true : false}
            label="Subcategoria (Opcional)"
            id="subcategory"
            value={form.subcategory.value}
            onChange={(e) => {
              e.target.id = "subcategory";
              onChangeHandler(e);
              onChangeData();
            }}
            select
            SelectProps={{
              IconComponent: ExpandMore,
            }}
            fullWidth
          >
            <MenuItem value=""></MenuItem>
            {subcategories(form.category.value).map((subcategory, index) => (
              <MenuItem
                key={`select-${subcategory._id}`}
                value={subcategory._id}
              >
                {subcategory.name}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
        <Grid item xs={12}>
          <TextField
            label="Proveedor"
            id="provider"
            value={form.provider.value}
            onChange={(e) => {
              e.target.id = "provider";
              onChangeHandler(e);
              onChangeData();
            }}
            select
            SelectProps={{
              IconComponent: ExpandMore,
            }}
            fullWidth
          >
            <MenuItem value=""></MenuItem>
            {providers.map((provider, index) => (
              <MenuItem key={`select-${provider._id}`} value={provider._id}>
                {provider.name}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
        <Grid item xs={isMobile ? 6 : 12} sm={6}>
          <TextField
            InputProps={{
              inputComponent: NumberFormatCustom,
            }}
            required
            autoComplete="off"
            label="Monto"
            id="amount"
            name="amount"
            value={amount}
            onChange={(e) => {
              setAmount(e.target.value);
              onChangeData();
            }}
            fullWidth
            inputProps={{
              min: "0",
              pattern: "[0-9.]+",
              step: ".01",
            }}
            helperText={
              amount < 0
                ? "No puede ser negativo"
                : parseFloat(amount, 10) === 0
                ? "No puede ser $0"
                : null
            }
            error={amount !== "" && amount <= 0 ? true : false}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={isMobile ? 6 : 12} sm={6}>
          <TextField
            label="Moneda"
            id="currency"
            value={form.currency.value}
            onChange={(e) => {
              e.target.id = "currency";
              onChangeHandler(e);
              onChangeData();
            }}
            select
            SelectProps={{
              IconComponent: ExpandMore,
            }}
            fullWidth
          >
            <MenuItem value=""></MenuItem>
            {currency.map((currency, index) => (
              <MenuItem key={`select-${currency}`} value={currency}>
                {currency}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
        <Grid item xs={12}>
          <TextField
            id="description"
            label="Descripción (opcional)"
            multiline
            rows={4}
            defaultValue={form.description.value}
            variant="outlined"
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            fullWidth
            inputProps={{
              minLength: 2,
              maxLength: 100,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
            }}
            error={!form.description.isValid}
          />
        </Grid>
        <Grid item xs={isMobile ? 6 : 12} sm={file ? 6 : 10}>
          <TextField
            value={form.number.value}
            required
            autoComplete="off"
            fullWidth
            id="number"
            name="number"
            label="Factura Nº"
            inputProps={{
              minLength: "1",
              maxLength: "20",
              pattern: "^[0-9 -]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            InputLabelProps={{ required: false }}
            error={!form.number.isValid}
          />
        </Grid>
        <Tooltip title={!file ? "Subir factura (opcional)" : ""}>
          <Grid item xs={isMobile ? 6 : 12} sm={file ? 6 : 2}>
            <UploadFile
              data={data}
              file={file}
              establishment={establishment}
              setFile={(e) => {
                setFile(e);
                onChangeData();
              }}
            />
          </Grid>
        </Tooltip>
        <Grid item xs={isMobile ? 6 : 12} sm={6}>
          <DatePicker
            label="Imputación"
            selectedDate={selectedDate.date}
            handleDateChange={(e) => handleDateChange("date", e)}
          />
        </Grid>
        <Grid item xs={isMobile ? 6 : 12} sm={6}>
          <DatePicker
            label="Vencimiento"
            selectedDate={selectedDate.expirationDate}
            handleDateChange={(e) => handleDateChange("expirationDate", e)}
          />
        </Grid>
        <Grid item xs={isMobile ? 6 : 12} sm={6}>
          <TextField
            label="Estado de pago"
            id="status"
            value={form.status.value}
            onChange={(e) => {
              e.target.id = "status";
              if (e.target.value === "Pendiente" || e.target.value === "") {
                onChangeHandler({
                  target: {
                    value: "",
                    id: "box",
                  },
                });
              }
              onChangeHandler(e);
              onChangeData();
            }}
            select
            SelectProps={{
              IconComponent: ExpandMore,
            }}
            fullWidth
          >
            <MenuItem value=""></MenuItem>
            {payStates.map((state, index) => (
              <MenuItem key={`select-${state}-${index}`} value={state}>
                {state}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
        <Grid item xs={isMobile ? 6 : 12} sm={6}>
          <TextField
            disabled={form.status.value !== "Pago"}
            fullWidth
            label="Caja"
            id="box"
            value={form.box.value}
            onChange={(e) => {
              e.target.id = "box";
              onChangeHandler(e);
              onChangeData();
            }}
            select
            SelectProps={{
              IconComponent: ExpandMore,
            }}
          >
            <MenuItem value=""></MenuItem>
            {boxes.map((box, index) => (
              <MenuItem key={`select-${index}`} value={box._id}>
                {box.name}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
        <Grid item xs={12} className={classes.expendituresSection}>
          <Typography className={classes.title}>Clase de gastos:</Typography>
        </Grid>
        {expenditures &&
          expenditures.length > 0 &&
          expenditures.map((expenditure, index) => (
            <Fragment key={index}>
              <Grid item xs={6}>
                <FormControl style={{ width: "100%" }}>
                  <InputLabel htmlFor="my-input">Clase de gasto</InputLabel>
                  <Input
                    id={`expenditureType-${expenditure.name}`}
                    value={expenditure.name}
                    name={`expenditureType-${expenditure.name}`}
                    fullWidth
                    readOnly={true}
                  />
                </FormControl>
              </Grid>
              <Grid item xs={6}>
                <TextField
                  InputProps={{
                    inputComponent: NumberFormatPercentage,
                  }}
                  value={expenditure.percentage}
                  required
                  autoComplete="off"
                  fullWidth
                  id={`percentaje-${expenditure.name}`}
                  name={`percentaje-${expenditure.name}`}
                  label="Porcentaje"
                  placeholder="0"
                  inputProps={{
                    min: "0",
                    max: "100",
                    pattern: "[0-9]+",
                    step: ".01",
                  }}
                  error={expenditures[index].percentage > 100}
                  onChange={setPercentage.bind(
                    this,
                    expenditure.expenditureType
                  )}
                  InputLabelProps={{ required: false }}
                />
              </Grid>
            </Fragment>
          ))}
      </Grid>
      <Grid container className={classes.buttons} spacing={1}>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            id="cancel-button"
            variant="outlined"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Cancelar
          </Button>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Tooltip
            title={
              disabled
                ? "Debe rellenar todos los campos para poder continuar"
                : ""
            }
            leaveDelay={5000}
            interactive
          >
            <div>
              <Button
                disabled={disabled}
                variant="contained"
                color="primary"
                disableElevation
                fullWidth
                onClick={formatData}
              >
                Aceptar
              </Button>
            </div>
          </Tooltip>
        </Grid>
      </Grid>
    </div>
  );
};

export default Form;
