import React, { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { makeStyles } from "@material-ui/core";
import Form from "./Form";
import { addSubcategory } from "../../Redux/Action/subcategoriesActions";
import { getCategories } from "../../Redux/Action/categoriesActions";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    padding: theme.spacing(1),
  },
}));

const AddSubcategory = ({ id, token, setOpen }) => {
  const classes = useStyles();
  const dispatch = useDispatch();
  const categories = useSelector((state) => state.categories.categories);

  const [isLoading, setIsLoading] = useState(true);

  const postSubcategory = (data) => {
    setIsLoading(true);
    dispatch(addSubcategory(id, token, data, setOpen, setIsLoading));
  };

  useEffect(() => {
    dispatch(getCategories(id, token, setIsLoading));
  }, [id, token, dispatch]);

  return (
    <div className={classes.container}>
      <Form
        categories={categories}
        title="Nueva subcategoría"
        setOpen={setOpen}
        isLoading={isLoading}
        onClikHandler={postSubcategory}
        hasChanged={true}
      />
    </div>
  );
};

export default AddSubcategory;
