import React from "react";
import { makeStyles, Typography } from "@material-ui/core";
import months from "../../../configs/MONTHS";
import { NumberFormatCustom } from "../../../hooks/format-number-hook";

import { depositKeeper } from "../../../configs/contracts/DEPOSIT_KEEPER";

const useStyles = makeStyles((theme) => ({
  container: {
    maxHeight: 220,
    overflowY: "auto",
    display: "flex",
    flexDirection: "column",
    height: "100%",
    width: "100%",
    marginLeft: theme.spacing(3),
    "@media (max-width:690px)": {
      marginLeft: 0,
      marginTop: theme.spacing(2),
    },
  },
  text: {
    color: theme.palette.grey[700],
    fontWeight: 400,
  },
  title: {
    color: "#49AC08",
    margin: theme.spacing(1, 0, 1, 0),
  },
  increment: {
    display: "flex",
    justifyContent: "space-between",
  },
}));

const DepositAndIncrements = ({ deposit, depositKeeperValue, items }) => {
  const classes = useStyles();

  const getIncrements = () => {
    let aux = [];
    let amount = 0;

    let filter = items
      .filter((entry) => entry.itemType === 1)
      .sort((a, b) => {
        let dateA = new Date(a.createdAt);
        let dateB = new Date(b.createdAt);

        if (dateA.getTime() > dateB.getTime()) {
          return -1;
        }
        if (dateA.getTime() < dateB.getTime()) {
          return 1;
        }

        return 0;
      });

    for (let i = 0; i < filter.length; i++) {
      if (filter[i].amount > amount) {
        amount = filter[i].amount;
        aux.push(filter[i]);
      }
    }

    return aux;
  };

  const getIncrement = (entry) => {
    let aux = new Date(entry.expirationDate);
    let month = aux.getMonth();
    let year = aux.getFullYear();

    return `${months[month]} de ${year}`;
  };

  return (
    <div className={classes.container}>
      {depositKeeperValue && (
        <div style={{ paddingRight: 10 }}>
          <Typography
            variant="h6"
            className={classes.title}
            style={{ marginTop: 0 }}
          >
            Deposito
          </Typography>
          <Typography variant="h6" className={classes.text}>
            {NumberFormatCustom(deposit.toString())}{" "}
            {`entregado ${
              depositKeeperValue === 1 ? "a la" : "al"
            } ${depositKeeper[depositKeeperValue].toLowerCase()}`}
          </Typography>
        </div>
      )}
      <div style={{ paddingRight: 10 }}>
        <Typography variant="h6" className={classes.title}>
          Incrementos contrato:
        </Typography>

        {getIncrements().map((entry, index) => (
          <div key={`increment-${index}`} className={classes.increment}>
            <Typography variant="h6" className={classes.text}>
              {getIncrement(entry)}
            </Typography>
            <Typography variant="h6" className={classes.text}>
              {NumberFormatCustom(entry.amount.toString())}
            </Typography>
          </div>
        ))}
      </div>
    </div>
  );
};

export default DepositAndIncrements;
