import {
  GET_EXPENSES,
  ADD_EXPENSE,
  DELETE_EXPENSE,
  GET_EXPENDITURES_AMOUNTS,
} from "../Action/actionTypes";

const initialState = {
  expenses: [],
  filteredExpenses: [],
  expendituresTypesAmounts: [],
};

export const expensesReducer = (state = initialState, action) => {
  switch (action.type) {
    case GET_EXPENSES:
      return {
        ...state,
        expenses: action.payload.expenses,
        filteredExpenses: action.payload.filteredExpenses,
        expendituresTypesAmounts: action.payload.expendituresTypesAmounts,
      };
    case ADD_EXPENSE:
      return {
        ...state,
        expenses: action.payload.expenses,
        filteredExpenses: action.payload.filteredExpenses,
        expendituresTypesAmounts: action.payload.expendituresTypesAmounts,
      };
    case GET_EXPENDITURES_AMOUNTS:
      return {
        ...state,
        expenses: action.payload.expenses,
        filteredExpenses: action.payload.filteredExpenses,
        expendituresTypesAmounts: action.payload.expendituresTypesAmounts,
      };
    case DELETE_EXPENSE:
      return {
        ...state,
        expenses: action.payload.expenses,
        filteredExpenses: action.payload.filteredExpenses,
        expendituresTypesAmounts: action.payload.expendituresTypesAmounts,
      };
    default:
      return state;
  }
};

export default expensesReducer;
