import React from "react";
import TextField from "@material-ui/core/TextField";
import Grid from "@material-ui/core/Grid";

export default function EstablishmentIdInput({ onChangeHandler, form }) {
  return (
    <Grid item xs={12}>
      <TextField
        autoComplete="id"
        name="id"
        variant="outlined"
        required
        fullWidth
        id="id"
        label="Id"
        onChange={onChangeHandler}
        value={form.id.value}
        inputProps={{
          minLength: 6,
          maxLength: 6,
          pattern: "^[0-9a-fA-F]+$",
        }}
        InputLabelProps={{ required: false }}
      />
    </Grid>
  );
}
