import React, { Fragment, useState } from "react";
import { makeStyles } from "@material-ui/core/styles";
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  Paper,
  IconButton,
  Checkbox,
  Tooltip,
} from "@material-ui/core";

import FolderIcon from "@material-ui/icons/FolderOpenOutlined";
import DeleteIcon from "@material-ui/icons/DeleteOutlineOutlined";
import EditIcon from "@material-ui/icons/EditOutlined";
import VisibilityIcon from "@material-ui/icons/VisibilityOutlined";

const useStyles = makeStyles(() => ({
  container: {
    display: "flex",
    flexDirection: "column",
    justifyContent: "space-between",
    boxShadow: "none",
    border: "1px solid #E6EBE8",
    borderRadius: 12,
    overflow: "hidden",

    "& .MuiTableCell-head": {
      color: "#3D4A57",
      backgroundColor: "#F4F7F5",
      fontWeight: 700,
      fontSize: 12,
      letterSpacing: "0.04em",
      borderBottom: "1px solid #E6EBE8",
    },

    "& .MuiLinearProgress-root": {
      backgroundColor: "#4ec5005c",
    },
    "& .MuiLinearProgress-bar": {
      backgroundColor: "#41a500",
    },

    "& .Mui-checked": {
      color: "#49AC08",
    },
  },
  iconButton: {
    padding: 0,
  },
  rowActions: {
    width: "120px",
  },
  banner: {
    backgroundColor: "#FFF6F4",
    borderBottom: "1px solid #F6D2C8",
    paddingTop: 8,
    paddingBottom: 8,
    textAlign: "center",
  },
  todayMark: {
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
  },
  todayLine: {
    display: "inline-block",
    width: 56,
    height: 1,
    margin: "0 10px",
    backgroundColor: "#F24726",
    opacity: 0.45,
  },
  todayPill: {
    display: "inline-block",
    backgroundColor: "#F24726",
    color: "#FFFFFF",
    borderRadius: 999,
    padding: "2px 10px",
    fontSize: 11,
    fontWeight: 700,
    letterSpacing: "0.12em",
    lineHeight: "16px",
  },
  paginationContainer: {
    width: "100%",
    backgroundColor: "#FFF",
    "& .MuiTablePagination-toolbar": {
      paddingRight: 0,
      paddingLeft: 10,
    },
  },
}));

const SimpleTable = ({
  dataIcon,
  columns,
  noPagination,
  columnsMoreActions,
  selecting,
  dataSelecting,
  rows,
  Cells,
  MoreActions,
  disableColumnDetails,
  disableColumnEdit,
  disableColumnDelete,
  disabledDetails,
  disabledDelete,
  disableRemoveConditional,
  messageDisbledDelete,
  detailsAction,
  editAction,
  deleteAction,
  setAction,
  currentMonthBanner,
  currentMonth,
  reduced,
}) => {
  const classes = useStyles();

  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(
    noPagination ? rows.length : 15
  );

  const [colspan] = useState(() => {
    let aux = 0;

    aux += columns.length;

    if (columnsMoreActions) {
      aux += columnsMoreActions.length;
    }

    if (selecting) {
      aux += 1;
    }

    return aux;
  });

  const [disabledColumns] = useState(() => {
    let values = [disableColumnDetails, disableColumnEdit, disableColumnDelete];
    let aux = 0;
    for (let i = 0; i < values.length; i++) {
      if (values[i] === true) {
        aux += 1;
      }
    }
    return aux;
  });

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  return (
    <Fragment>
      <TableContainer
        component={Paper}
        className={classes.container}
        style={reduced ? null : { flex: 1 }}
      >
        <Table aria-label="simple table">
          <TableHead>
            <TableRow>
              {selecting && (
                <TableCell padding="checkbox">
                  <Checkbox
                    indeterminate={dataSelecting.indeterminate}
                    checked={dataSelecting.checked}
                    onChange={dataSelecting.onChange}
                  />
                </TableCell>
              )}
              {columns
                .slice(
                  0,
                  disabledColumns === 3
                    ? columns.length - 1
                    : columns.length - (3 - disabledColumns)
                )
                .map((column, index) => (
                  <TableCell key={`tHead-${index}`}>{column}</TableCell>
                ))}
              {disabledColumns === 3 &&
                columns.slice(columns.length - 1).map((column, index) => (
                  <TableCell key={`tHead-2-${index}`} align="center">
                    {column}
                  </TableCell>
                ))}
              {columnsMoreActions &&
                columnsMoreActions.map((column, index) => (
                  <TableCell key={`tHead-3-${index}`} align="center">
                    {column}
                  </TableCell>
                ))}
              {columns
                .slice(columns.length - (3 - disabledColumns))
                .map((column, index) => (
                  <TableCell key={`tHead-4-${index}`} align="center">
                    {column}
                  </TableCell>
                ))}
            </TableRow>
          </TableHead>
          <TableBody>
            {rows
              .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
              .map((row, index) => (
                <Fragment key={row._id || `tRow-${index}`}>
                  {currentMonthBanner &&
                    currentMonth(
                      index,
                      row,
                      page === 0 && index === 0
                        ? null
                        : rows.slice(
                            (page > 0 && index === 0 ? page - 1 : page) *
                              rowsPerPage,
                            (page > 0 && index === 0 ? page - 1 : page) *
                              rowsPerPage +
                              rowsPerPage
                          )[index - 1]
                    ) && (
                      <TableRow>
                        <TableCell colSpan={colspan} className={classes.banner}>
                          <span className={classes.todayMark}>
                            <span className={classes.todayLine} />
                            <span className={classes.todayPill}>HOY</span>
                            <span className={classes.todayLine} />
                          </span>
                        </TableCell>
                      </TableRow>
                    )}
                  <TableRow>
                    <Cells row={row} />
                    {MoreActions && <MoreActions row={row} />}
                    {!disableColumnDetails && (
                      <TableCell align="center" className={classes.rowActions}>
                        <IconButton
                          disabled={disabledDetails}
                          className={classes.iconButton}
                          style={{
                            color: disabledDetails ? "#BBB2B2" : "#49AC08",
                          }}
                          onClick={() => {
                            setAction("details");
                            detailsAction(row);
                          }}
                        >
                          {dataIcon ? <FolderIcon /> : <VisibilityIcon />}
                        </IconButton>
                      </TableCell>
                    )}
                    {!disableColumnEdit && (
                      <TableCell align="center" className={classes.rowActions}>
                        <IconButton
                          className={classes.iconButton}
                          style={{ color: "#1260BD" }}
                          onClick={() => {
                            setAction("edit");
                            editAction(row);
                          }}
                        >
                          <EditIcon />
                        </IconButton>
                      </TableCell>
                    )}
                    {!disableColumnDelete && (
                      <Tooltip
                        title={
                          disableRemoveConditional &&
                          disableRemoveConditional(row)
                            ? messageDisbledDelete
                            : ""
                        }
                      >
                        <TableCell
                          align="center"
                          className={classes.rowActions}
                        >
                          <IconButton
                            disabled={
                              (disableRemoveConditional &&
                                disableRemoveConditional(row)) ||
                              disabledDelete
                            }
                            className={classes.iconButton}
                            style={{
                              color:
                                (disableRemoveConditional &&
                                  disableRemoveConditional(row)) ||
                                disabledDelete
                                  ? "#BBB2B2"
                                  : "#CA0303",
                            }}
                            onClick={() => {
                              setAction("delete");
                              deleteAction(row);
                            }}
                          >
                            <DeleteIcon />
                          </IconButton>
                        </TableCell>
                      </Tooltip>
                    )}
                  </TableRow>
                </Fragment>
              ))}
          </TableBody>
        </Table>
      </TableContainer>
      {!noPagination && (
        <div className={classes.paginationContainer}>
          <TablePagination
            rowsPerPageOptions={[15, 30, 50, 100]}
            component="div"
            count={rows.length}
            rowsPerPage={rowsPerPage}
            page={page}
            onChangePage={handleChangePage}
            onChangeRowsPerPage={handleChangeRowsPerPage}
            labelRowsPerPage="Cantidad"
            labelDisplayedRows={({ from, to, count }) => {
              return `${from}-${to} de ${count}`;
            }}
          />
        </div>
      )}
    </Fragment>
  );
};

export default SimpleTable;
