import {
  GET_TRANSACTIONS_CONTACTS,
  GET_TRANSACTIONS_FU,
} from "../Action/actionTypes";

const initialState = { transactionsFU: {}, transactionsContact: {} };

export const transactionsReducer = (state = initialState, action) => {
  switch (action.type) {
    case GET_TRANSACTIONS_FU:
      return {
        ...state,
        transactionsFU: action.payload,
      };
    case GET_TRANSACTIONS_CONTACTS:
      return {
        ...state,
        transactionsContact: action.payload,
      };
    default:
      return state;
  }
};

export default transactionsReducer;
