import axios from "axios";
import {
  ADD_CONTACT,
  DELETE_CONTACT,
  EDIT_CONTACT,
  GET_CONTACTS,
  ENABLE_CONTACT,
  GET_TRANSACTIONS_CONTACTS,
} from "./actionTypes";

import { setSnackData } from "./snackDataActions";

export const getContacts = (token, setIsLoading) => (dispatch) => {
  axios
    .get(`${process.env.REACT_APP_BACKEND_URL}/contacts`, {
      headers: {
        Authorization: "Bearer " + token,
      },
    })
    .then((res) => {
      const contacts = res.data.sort((a, b) => a.name.localeCompare(b.name));

      dispatch({
        type: GET_CONTACTS,
        payload: contacts,
      });
      if (setIsLoading) setIsLoading(false);
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }
      if (setIsLoading) setIsLoading(false);
    });
};

export const getTransactions =
  (token, id, setIsLoading, setAmount) => (dispatch) => {
    axios
      .get(`${process.env.REACT_APP_BACKEND_URL}/contacts/${id}/transactions`, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((res) => {
        let transactions = res.data;

        dispatch({
          type: GET_TRANSACTIONS_CONTACTS,
          payload: transactions,
        });

        if (setAmount) setAmount(res.data.balance);
        if (setIsLoading) setIsLoading(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const addContact =
  (token, data, setOpen, setIsLoading, preload) => (dispatch, getState) => {
    let contacts = getState().contacts.contacts;

    const formData = new FormData();

    for (let key in data) {
      formData.append(key, data[key]);
    }

    axios
      .post(`${process.env.REACT_APP_BACKEND_URL}/contacts`, formData, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((res) => {
        contacts.push(res.data);
        dispatch({
          type: ADD_CONTACT,
          payload: contacts,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Contacto creado",
            severity: "success",
          })
        );
        if (preload) preload(res.data._id);
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const editContact =
  (token, data, id, setOpen, setIsLoading) => (dispatch, getState) => {
    let contacts = getState().contacts.contacts;

    const formData = new FormData();

    for (let key in data) {
      formData.append(key, data[key]);
    }

    axios
      .put(`${process.env.REACT_APP_BACKEND_URL}/contacts/${id}`, formData, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((res) => {
        data.image = res.data.image;

        let i = contacts.findIndex((contact) => {
          if (contact._id === id) {
            return true;
          }
          return false;
        });

        if (i !== -1) {
          contacts[i] = Object.assign(contacts[i], data);
        }

        dispatch({
          type: EDIT_CONTACT,
          payload: contacts,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Contacto editado",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const deleteContact =
  (token, id, setOpen, setIsLoading) => (dispatch, getState) => {
    let contacts = getState().contacts.contacts;
    axios
      .delete(`${process.env.REACT_APP_BACKEND_URL}/contacts/${id}`, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((_) => {
        let i = contacts.findIndex((contact) => {
          if (contact._id === id) {
            return true;
          }
          return false;
        });

        i !== -1 && contacts.splice(i, 1);
        dispatch({
          type: DELETE_CONTACT,
          payload: contacts,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Contacto eliminado",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const enableWebAccess =
  (token, id, setOpen, setIsLoading) => (dispatch, getState) => {
    let aux = getState().contacts.contacts;
    let contacts = Array.from(aux);

    axios
      .post(
        `${process.env.REACT_APP_BACKEND_URL}/users/create-user/${id}`,
        {},
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        let i = contacts.findIndex((contact) => {
          if (contact._id === id) {
            return true;
          }
          return false;
        });

        if (i !== -1) contacts[i].hasUser = true;

        dispatch({
          type: ENABLE_CONTACT,
          payload: contacts,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Contacto habilitado",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };
