import React from "react";
import { makeStyles } from "@material-ui/core";
import { useSelector } from "react-redux";

import ImageComponent from "./DetailsComponents/ImageComponent";
import TenantsAndGurantorsTable from "./DetailsComponents/TenantsAndGurantorsTable";
import DepositAndIncrements from "./DetailsComponents/DepositAndIncrements";

const useStyles = makeStyles((theme) => ({
  grid: {
    display: "flex",
    justifyContent: "space-between",
    width: "100%",
    alignItems: "flex-start",
    marginBottom: theme.spacing(4),
    "@media (max-width:1100px)": {
      flexDirection: "column",
    },
  },
  container: {
    display: "flex",
    justifyContent: "space-between",
    width: "100%",
    height: "100%",
    alignItems: "flex-start",
    "@media (max-width:690px)": {
      flexDirection: "column",
    },
  },
  tableContainer: {
    width: "70%",
    marginLeft: theme.spacing(3),
    "@media (max-width:1100px)": {
      width: "100%",
      marginLeft: 0,
      marginTop: theme.spacing(2),
    },
  },
}));

const ContractInformation = ({
  image,
  establishment,
  tenants,
  guarantors,
  deposit,
  depositKeeper,
  items,
  setAction,
  setCurrentContact,
  setOpen,
  seeCurrentAccount,
}) => {
  const classes = useStyles();

  const contacts = useSelector((state) => state.contacts.contacts);

  const onClickHandler = (current, action) => {
    let aux = {};

    let i = contacts.findIndex((contact) => {
      if (contact._id === current._id) {
        return true;
      }
      return false;
    });

    if (i !== -1) aux = contacts[i];

    setAction(action);

    setCurrentContact(aux);

    if (action) {
      setOpen(true);
    } else {
      seeCurrentAccount(aux._id);
    }
  };

  return (
    <div className={classes.grid}>
      <div className={classes.container}>
        <ImageComponent establishment={establishment} image={image} />
        <DepositAndIncrements
          deposit={deposit}
          depositKeeperValue={depositKeeper}
          items={items}
        />
      </div>
      <div className={classes.tableContainer}>
        <TenantsAndGurantorsTable
          onClickHandler={onClickHandler}
          tenants={tenants}
          guarantors={guarantors}
        />
      </div>
    </div>
  );
};

export default ContractInformation;
