import axios from "axios";
import { demoResponse } from "./resolve";

const DEMO_MESSAGE = "Esta es una demo: los cambios no se guardan.";

export const requestPath = (config) => {
  let raw = String(config.url || "").split("?")[0];
  if (raw.startsWith("http")) {
    try {
      raw = new URL(raw).pathname;
    } catch (error) {
      raw = raw.replace(/^https?:\/\/[^/]+/, "");
    }
  }
  if (base && (raw === base || raw.startsWith(`${base}/`))) {
    raw = raw.slice(base.length) || "/";
  }
  return raw.replace(/\/+$/, "") || "/";
};

const base = String(process.env.PUBLIC_URL || "").replace(/\/+$/, "");

const isFile = (path) => path.includes("/files/");

const isRead = (config, path) => {
  const method = (config.method || "get").toLowerCase();
  if (method === "get" || method === "head") return true;
  return path.endsWith("/expenses/expenditures-types-amounts");
};

const ok = (config, data) => ({
  data,
  status: 200,
  statusText: "OK",
  headers: {},
  config,
  request: {},
});

const bodyOf = (config) => {
  if (!config.data || typeof config.data !== "string") return config.data || {};
  try {
    return JSON.parse(config.data);
  } catch (error) {
    return {};
  }
};

if (process.env.REACT_APP_DEMO === "true") {
  const http = axios.defaults.adapter;

  axios.defaults.adapter = (config) => {
    const path = requestPath(config);
    if (isFile(path)) return http(config);

    if (!isRead(config, path)) {
      const error = new Error(DEMO_MESSAGE);
      error.response = { data: { message: DEMO_MESSAGE }, status: 400 };
      error.config = config;
      return Promise.reject(error);
    }

    return Promise.resolve(ok(config, demoResponse(path, bodyOf(config))));
  };
}
