import React, { Fragment, useEffect, useState } from "react";
import {
  Container,
  IconButton,
  makeStyles,
  TableCell,
  Tooltip,
} from "@material-ui/core";

import { useDispatch, useSelector } from "react-redux";

import { useParams, useHistory } from "react-router-dom";

import BackButtonComponent from "../components/Shared/BackButtonComponent";
import Table from "../components/Shared/Table";
import Spinner from "../components/UI/Spinner";
import { getFormatDate } from "../hooks/date-hook";
import { NumberFormatCustom } from "../hooks/format-number-hook";
import Tabs from "../components/Shared/Tabs";
import { Alert } from "@material-ui/lab";

import ReloadIcon from "@material-ui/icons/Cached";
import { getTransactions } from "../Redux/Action/scheduleActions";

const useStyles = makeStyles((theme) => ({
  root: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    marginTop: theme.spacing(2),
    marginBottom: theme.spacing(2),
  },
  container: {
    width: "100%",
    display: "flex",
    marginBottom: theme.spacing(2),
    alignItems: "center",
    flexDirection: "row",
    justifyContent: "space-between",
  },
  actionsButtons: {
    display: "flex",
    alignItems: "center",
    justifyContent: "flex-end",
  },
  reload: {
    padding: theme.spacing(0.75),
    "@media (min-width:600px)": {
      marginRight: theme.spacing(2.5),
    },
  },
}));

const TabPanel = ({ children, value, index }) => {
  return (
    <div id={`tabPanel${index}`} style={{ width: "100%", display: "contents" }}>
      {value === index && children}
    </div>
  );
};

const Cells = ({ row }) => {
  return (
    <Fragment>
      <TableCell component="th" scope="row">
        {getFormatDate(row.updatedAt)}
      </TableCell>
      <TableCell component="th" scope="row">
        {row.concept}
      </TableCell>
      <TableCell
        component="th"
        scope="row"
        align="center"
        style={{ color: row.type === "DEBIT" ? "#C10909" : "#28BD00" }}
      >
        {NumberFormatCustom(row.amount.toString().replace(/\./g, ","))}
      </TableCell>
    </Fragment>
  );
};

const CurrentAccount = ({ user }) => {
  const classes = useStyles();
  const dispatch = useDispatch();
  const history = useHistory();

  const { id } = useParams();

  const [isLoading, setIsLoading] = useState(true);
  const [value, setValue] = useState(0);

  const columns = ["Fecha", "Concepto", "Monto"];

  const transactions = useSelector(
    (state) => state.transactions.transactionsContact
  );

  const contact = useSelector((state) => state.contacts.contacts).filter(
    (entry) => entry._id === id
  )[0];

  const labels = [
    ...(contact
      ? [`Cuenta corriente - ${contact.name} ${contact.lastname}`]
      : ["Cuenta corriente"]),
  ];

  const handleChange = (e) => {
    setValue(e);
  };

  const reloadAction = (e) => {
    setIsLoading(true);
    dispatch(getTransactions(user.token, id, setIsLoading));
  };

  useEffect(() => {
    dispatch(getTransactions(user.token, id, setIsLoading));
  }, [dispatch, user.token, id]);

  return (
    <Container className={classes.root} maxWidth="xl">
      {isLoading ? (
        <Spinner />
      ) : (
        <Fragment>
          {history.action !== "POP" && (
            <BackButtonComponent
              title="Volver"
              onClick={() => history.goBack()}
              mrgBottom={24}
            />
          )}

          <div className={classes.container}>
            <div>
              <Tabs
                value={value}
                setValue={(e) => handleChange(e)}
                labels={labels}
              />
            </div>
            <div className={classes.actionsButtons}>
              <Tooltip title="Recargar tabla">
                <IconButton
                  className={classes.reload}
                  variant="contained"
                  aria-label="add"
                  onClick={reloadAction}
                >
                  <ReloadIcon />
                </IconButton>
              </Tooltip>

              <Tooltip title={true ? "Saldo positivo" : "Saldo negativo"}>
                <Alert
                  style={{ padding: "4px 16px" }}
                  icon={false}
                  severity={transactions.balance >= 0 ? "success" : "error"}
                >
                  {"Saldo: "}
                  {NumberFormatCustom(transactions.balance.replace(/\./g, ","))}
                </Alert>
              </Tooltip>
            </div>
          </div>

          <TabPanel value={value} index={0}>
            <Table
              columns={columns}
              rows={
                transactions.transactions &&
                transactions.transactions.length > 0
                  ? transactions.transactions.sort((a, b) => {
                      let dateA = new Date(a.createdAt);
                      let dateB = new Date(b.createdAt);

                      if (dateA.getTime() > dateB.getTime()) {
                        return -1;
                      }
                      if (dateA.getTime() < dateB.getTime()) {
                        return 1;
                      }

                      return 0;
                    })
                  : []
              }
              Cells={Cells}
              disableColumnEdit={true}
              disableColumnDelete={true}
              disableColumnDetails={true}
            />
          </TabPanel>
        </Fragment>
      )}
    </Container>
  );
};

export default CurrentAccount;
