import React, { useState, Fragment, useEffect } from "react";

import Spinner from "../UI/Spinner";
import Table from "../Shared/Table";
import Modal from "../Shared/Modal";

import { Box, LinearProgress, TableCell, Typography } from "@material-ui/core";
import { useDispatch, useSelector } from "react-redux";
import { getContracts } from "../../Redux/Action/contractsActions";

import { propertyTypes } from "../../configs/PROPERTY_TYPES";
import { getFormatDate } from "../../hooks/date-hook";
import { NumberFormatCustom } from "../../hooks/format-number-hook";
import EditContract from "./EditContract";
import { useHistory } from "react-router-dom/cjs/react-router-dom.min";
import DeleteContract from "./DeleteContract";

function LinearProgressWithLabel(props) {
  return (
    <Box display="flex" alignItems="center">
      <Box width="100%" mr={1}>
        <LinearProgress variant="determinate" {...props} />
      </Box>
      <Box minWidth={35}>
        <Typography variant="body2" color="textSecondary">{`${parseFloat(
          props.value
        )}%`}</Typography>
      </Box>
    </Box>
  );
}

const Cells = ({ row }) => {
  const finishingDate = () => {
    let aux = new Date(row.startingDate);
    aux.setMonth(aux.getMonth() + parseFloat(row.months, 10));

    return getFormatDate(aux);
  };

  const getDiff = () => {
    let start = new Date(row.startingDate);
    let ends = new Date(row.startingDate).setMonth(
      start.getMonth() + parseFloat(row.months, 10)
    );

    let diff = ends - start;

    return diff / (1000 * 60 * 60 * 24);
  };

  const getAmount = () => {
    let sum = 0;

    let months = parseFloat(row.months, 10);
    let amount = parseFloat(row.amount, 10);
    let increasePercentage = parseFloat(row.increasePercentage, 10);
    let increaseMonths = parseFloat(row.increaseMonths, 10);
    let aux = Math.ceil(months / increaseMonths);

    for (let i = 0; i < aux; i++) {
      if (months > 0 && increaseMonths >= months) {
        sum += months * amount;
        months -= months;
      } else if (months > 0 && increaseMonths <= months) {
        sum += increaseMonths * amount;
        amount = (amount * (increasePercentage + 100)) / 100;
        months -= increaseMonths;
      }
    }

    return sum;
  };

  const obtainValidity = () => {
    let startDay = new Date(row.startingDate);
    let currentDate = new Date();

    let aux = currentDate - startDay;

    let totalDays = getDiff();
    let busyDays = Math.ceil(aux / (1000 * 60 * 60 * 24));

    let validity = (busyDays * 100) / totalDays;

    return validity < 0 ? 0 : parseFloat(validity).toFixed(2);
  };

  return (
    <Fragment>
      <TableCell component="th" scope="row">
        {propertyTypes[row.property.type]}
      </TableCell>
      <TableCell component="th" scope="row">
        {row.property.address}
      </TableCell>
      <TableCell component="th" scope="row" style={{ width: 180 }}>
        <LinearProgressWithLabel value={parseFloat(obtainValidity())} />
      </TableCell>
      <TableCell component="th" scope="row">
        {row.months}
      </TableCell>
      <TableCell component="th" scope="row">
        {getFormatDate(row.startingDate)}
      </TableCell>
      <TableCell component="th" scope="row">
        {finishingDate(row.startingDate)}
      </TableCell>
      <TableCell component="th" scope="row">
        {`${getDiff()} días`}
      </TableCell>
      <TableCell component="th" scope="row">
        {NumberFormatCustom(getAmount())}
      </TableCell>
      <TableCell component="th" scope="row">
        {row.property.owners.map((entry) => (
          <Typography
            key={`owner-propert-${entry.owner._id}`}
          >{`${entry.owner.name} ${entry.owner.lastname}`}</Typography>
        ))}
      </TableCell>
    </Fragment>
  );
};

const Contracts = ({
  user,
  isLoadingComponent,
  setIsLoadingComponent,
  contacts,
  estates,
}) => {
  const dispatch = useDispatch();
  const history = useHistory();

  const [open, setOpen] = useState(false);
  const [current, setCurrent] = useState(null);
  const [action, setAction] = useState();

  const columns = [
    "Tipo",
    "Dirección",
    "Vigencia",
    "Meses",
    "Inicio",
    "Fin",
    "Vence en",
    "Total",
    "Propietario(s)",
    "Detalles",
    "Editar",
    "Eliminar",
  ];

  const rows = useSelector((state) => state.contracts.contracts);

  const detailsAction = (current) => {
    history.push(`/alquileres/contratos/${current._id}/detalles`);
  };

  const editAction = (current) => {
    setCurrent(current);
    setOpen(true);
  };

  const deleteAction = (current) => {
    setCurrent(current);
    setOpen(true);
  };

  const actions = {
    details: <div>Detalles contrato</div>,
    edit: (
      <EditContract
        user={user}
        current={current}
        setOpen={setOpen}
        contacts={contacts}
        estates={estates}
      />
    ),
    delete: <DeleteContract setOpen={setOpen} current={current} />,
  };

  useEffect(() => {
    dispatch(getContracts(user.token, setIsLoadingComponent));
  }, [dispatch, user.token, setIsLoadingComponent]);

  return isLoadingComponent ? (
    <Spinner />
  ) : (
    <Fragment>
      <Table
        columns={columns}
        rows={rows}
        Cells={Cells}
        detailsAction={detailsAction}
        editAction={editAction}
        deleteAction={deleteAction}
        setAction={setAction}
      />
      <Modal
        handleClose={() => setOpen(false)}
        open={open}
        component={actions[action]}
        maxWidth={action !== "delete" && 900}
      />
    </Fragment>
  );
};

export default Contracts;
