import React, { useState, Fragment, useEffect } from "react";
import {
  Button,
  Container,
  Hidden,
  IconButton,
  makeStyles,
  Tooltip,
} from "@material-ui/core";

import { useDispatch, useSelector } from "react-redux";

import Spinner from "../components/UI/Spinner";
import PageHeader from "../components/UI/PageHeader";
import Tabs from "../components/Shared/Tabs";
import Modal from "../components/Shared/Modal";

import AddIcon from "@material-ui/icons/Add";
import ReloadIcon from "@material-ui/icons/Cached";

import { getContacts } from "../Redux/Action/scheduleActions";
import { getContracts } from "../Redux/Action/contractsActions";
import { getEstates } from "../Redux/Action/estatesActions";
import { getServices } from "../Redux/Action/servicesActions";
import { getBanks } from "../Redux/Action/banksActions";

import Contracts from "../components/Contracts/Contracts";
import Estates from "../components/Estates/Estates";
import Services from "../components/Taxes/Services";
import Banks from "../components/Banks/Banks";

import AddContract from "../components/Contracts/AddContract";
import AddEstate from "../components/Estates/AddEstate";
import AddService from "../components/Taxes/AddService";
import AddBank from "../components/Banks/AddBank";

const useStyles = makeStyles((theme) => ({
  root: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    marginTop: theme.spacing(2),
    marginBottom: theme.spacing(2),
  },
  container: {
    width: "100%",
    display: "flex",
    marginBottom: theme.spacing(2),
    alignItems: "center",
    flexDirection: "row",
    justifyContent: "space-between",
  },
  actionsButtons: {
    display: "flex",
    alignItems: "center",
    justifyContent: "flex-end",
  },
  reload: {
    padding: theme.spacing(0.75),
    "@media (min-width:600px)": {
      marginRight: theme.spacing(2.5),
    },
  },
}));

const labelsRentals = ["Contratos", "Propiedades"];
const labelsServices = ["Impuestos/Servicios"];
const labelsBanks = ["Bancos"];

const TabPanel = ({ children, value, index }) => {
  return (
    <div id={`tabPanel${index}`} style={{ width: "100%", display: "contents" }}>
      {value === index && children}
    </div>
  );
};

const RentalPage = ({ user }) => {
  const classes = useStyles();

  const dispatch = useDispatch();

  const contacts = useSelector((state) => state.contacts.contacts);
  const estates = useSelector((state) => state.estates.estates);

  const [isLoading, setIsLoading] = useState(true);
  const [isLoadingComponent, setIsLoadingComponent] = useState(true);
  const [open, setOpen] = useState(false);
  const [value, setValue] = useState(0);
  const [menuItems, setMenuItems] = useState({
    Alquileres: true,
    "Impuestos/Servicios": false,
    Bancos: false,
  });
  const [anchorEl, setAnchorEl] = React.useState(null);

  const handleChange = (e) => {
    if (value !== e) {
      setIsLoadingComponent(true);
      setValue(e);
    }
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  const onClickHandler = (item) => {
    let menu = menuItems;

    for (let key in menu) {
      if (key === item) {
        menu[key] = true;
      } else {
        menu[key] = false;
      }
    }

    setMenuItems({ ...menuItems, ...menu });
    handleClose();

    setValue(0);
    setIsLoadingComponent(true);

    if (item === "Alquileres") {
      dispatch(getContracts(user.token, setIsLoadingComponent));
    } else if (item === "Impuestos/Servicios") {
      dispatch(getServices(user.token, setIsLoadingComponent));
    } else {
      dispatch(getBanks(user.token, setIsLoadingComponent));
    }
  };

  const reloadActionsRentals = {
    0: () => {
      setIsLoadingComponent(true);
      dispatch(getContracts(user.token, setIsLoadingComponent));
    },
    1: () => {
      setIsLoadingComponent(true);
      dispatch(getEstates(user.token, setIsLoadingComponent));
    },
  };

  const reloadActionsServices = {
    0: () => {
      setIsLoadingComponent(true);
      dispatch(getServices(user.token, setIsLoadingComponent));
    },
  };

  const reloadActionsBanks = {
    0: () => {
      setIsLoadingComponent(true);
      dispatch(getBanks(user.token, setIsLoadingComponent));
    },
  };

  const addActionsRentals = {
    0: (
      <AddContract
        user={user}
        setOpen={setOpen}
        contacts={contacts}
        estates={estates}
      />
    ),
    1: <AddEstate user={user} setOpen={setOpen} contacts={contacts} />,
  };

  const addActionsServices = {
    0: <AddService user={user} setOpen={setOpen} />,
  };

  const addActionsBanks = {
    0: <AddBank user={user} setOpen={setOpen} />,
  };

  useEffect(() => {
    dispatch(getContacts(user.token));
    dispatch(getEstates(user.token));
    dispatch(getContracts(user.token, setIsLoading));
  }, [dispatch, user.token]);

  return (
    <Container className={classes.root} maxWidth="xl">
      {isLoading ? (
        <Spinner />
      ) : (
        <Fragment>
          <PageHeader
            justify="space-between"
            marginBottom={24}
            user={user}
            title={user.establishmentName}
            enabledConfigMenu={true}
            titleConfig="Configuración de inmobiliaria"
            menuItems={menuItems}
            anchorEl={anchorEl}
            setAnchorEl={setAnchorEl}
            handleClose={handleClose}
            onClickHandler={onClickHandler}
            horizontal="right"
          />

          {menuItems["Alquileres"] && (
            <Fragment>
              <div className={classes.container}>
                <div>
                  <Tabs
                    value={value}
                    setValue={(e) => handleChange(e)}
                    labels={labelsRentals}
                  />
                </div>
                <div className={classes.actionsButtons}>
                  <Tooltip title="Recargar tabla">
                    <IconButton
                      className={classes.reload}
                      variant="contained"
                      aria-label="add"
                      onClick={reloadActionsRentals[value]}
                    >
                      <ReloadIcon />
                    </IconButton>
                  </Tooltip>
                  <Hidden xsDown>
                    <Button
                      variant="contained"
                      disableElevation
                      startIcon={<AddIcon />}
                      onClick={() => setOpen(true)}
                    >
                      Agregar
                    </Button>
                  </Hidden>
                  <Hidden smUp>
                    <IconButton
                      className={classes.reload}
                      variant="contained"
                      aria-label="add"
                      onClick={() => setOpen(true)}
                    >
                      <AddIcon />
                    </IconButton>
                  </Hidden>
                </div>
              </div>
              <TabPanel value={value} index={0}>
                <Contracts
                  user={user}
                  isLoadingComponent={isLoadingComponent}
                  setIsLoadingComponent={setIsLoadingComponent}
                  contacts={contacts}
                  estates={estates}
                />
              </TabPanel>
              <TabPanel value={value} index={1}>
                <Estates
                  user={user}
                  contacts={contacts}
                  isLoadingComponent={isLoadingComponent}
                  setIsLoadingComponent={setIsLoadingComponent}
                />
              </TabPanel>
              <Modal
                handleClose={() => setOpen(false)}
                open={open}
                component={addActionsRentals[value]}
                maxWidth={value === 0 && 900}
              />
            </Fragment>
          )}

          {menuItems["Impuestos/Servicios"] && (
            <Fragment>
              <div className={classes.container}>
                <div>
                  <Tabs
                    value={value}
                    setValue={(e) => handleChange(e)}
                    labels={labelsServices}
                  />
                </div>
                <div className={classes.actionsButtons}>
                  <Tooltip title="Recargar tabla">
                    <IconButton
                      className={classes.reload}
                      variant="contained"
                      aria-label="add"
                      onClick={reloadActionsServices[value]}
                    >
                      <ReloadIcon />
                    </IconButton>
                  </Tooltip>
                  <Hidden xsDown>
                    <Button
                      variant="contained"
                      disableElevation
                      startIcon={<AddIcon />}
                      onClick={() => setOpen(true)}
                    >
                      Agregar
                    </Button>
                  </Hidden>
                  <Hidden smUp>
                    <IconButton
                      className={classes.reload}
                      variant="contained"
                      aria-label="add"
                      onClick={() => setOpen(true)}
                    >
                      <AddIcon />
                    </IconButton>
                  </Hidden>
                </div>
              </div>
              <TabPanel value={value} index={0}>
                <Services
                  user={user}
                  isLoadingComponent={isLoadingComponent}
                  setIsLoadingComponent={setIsLoadingComponent}
                />
              </TabPanel>
              <Modal
                handleClose={() => setOpen(false)}
                open={open}
                component={addActionsServices[value]}
              />
            </Fragment>
          )}

          {menuItems["Bancos"] && (
            <Fragment>
              <div className={classes.container}>
                <div>
                  <Tabs
                    value={value}
                    setValue={(e) => handleChange(e)}
                    labels={labelsBanks}
                  />
                </div>
                <div className={classes.actionsButtons}>
                  <Tooltip title="Recargar tabla">
                    <IconButton
                      className={classes.reload}
                      variant="contained"
                      aria-label="add"
                      onClick={reloadActionsBanks[value]}
                    >
                      <ReloadIcon />
                    </IconButton>
                  </Tooltip>
                  <Hidden xsDown>
                    <Button
                      variant="contained"
                      disableElevation
                      startIcon={<AddIcon />}
                      onClick={() => setOpen(true)}
                    >
                      Agregar
                    </Button>
                  </Hidden>
                  <Hidden smUp>
                    <IconButton
                      className={classes.reload}
                      variant="contained"
                      aria-label="add"
                      onClick={() => setOpen(true)}
                    >
                      <AddIcon />
                    </IconButton>
                  </Hidden>
                </div>
              </div>
              <TabPanel value={value} index={0}>
                <Banks
                  user={user}
                  isLoadingComponent={isLoadingComponent}
                  setIsLoadingComponent={setIsLoadingComponent}
                />
              </TabPanel>
              <Modal
                handleClose={() => setOpen(false)}
                open={open}
                component={addActionsBanks[value]}
              />
            </Fragment>
          )}
        </Fragment>
      )}
    </Container>
  );
};

export default RentalPage;
