import {
  GET_EXPENDITURES_TYPES,
  ADD_EXPENDITURE_TYPE,
  EDIT_EXPENDITURE_TYPE,
  DELETE_EXPENDITURE_TYPE,
} from "../Action/actionTypes";

const initialState = { expendituresTypes: [] };

export const expendituresTypesReducer = (state = initialState, action) => {
  switch (action.type) {
    case GET_EXPENDITURES_TYPES:
      return {
        ...state,
        expendituresTypes: action.payload,
      };
    case ADD_EXPENDITURE_TYPE:
      return {
        ...state,
        expendituresTypes: action.payload,
      };
    case EDIT_EXPENDITURE_TYPE:
      return {
        ...state,
        expendituresTypes: action.payload,
      };
    case DELETE_EXPENDITURE_TYPE:
      return {
        ...state,
        expendituresTypes: action.payload,
      };
    default:
      return state;
  }
};

export default expendituresTypesReducer;
