import React from "react";
import { makeStyles } from "@material-ui/core/styles";
import {
  IconButton,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableRow,
  Paper,
  Typography,
  Avatar,
  Tooltip,
} from "@material-ui/core";

import VisibilityIcon from "@material-ui/icons/VisibilityOutlined";
import AccountBalanceWalletIcon from "@material-ui/icons/AccountBalanceWallet";
import { deepPurple } from "@material-ui/core/colors";

const useStyles = makeStyles((theme) => ({
  tableContainer: {
    borderRadius: theme.spacing(0.75),
    padding: theme.spacing(1, 1.25),
    boxShadow: "none",
    maxHeight: 220,
    overflowY: "auto",
    display: "flex",
    "@media (min-width:1100px)": {
      minHeight: 220,
    },
  },
  table: {
    "& .MuiTableCell-body": {
      color: "#000000",
      fontSize: "14px",
      lineHeight: "20px",
      letterSpacing: "0.02em",
      padding: theme.spacing(1),
      cursor: "pointer",
    },
  },
  titleSection: {
    display: "flex",
    alignItems: "center",
    "& .MuiBadge-dot": {
      backgroundColor: theme.palette.secondary.light,
    },
  },
  avatar: {
    fontSize: 12,
    color: theme.palette.getContrastText(deepPurple[500]),
    backgroundColor: deepPurple[500],
    "@media (max-width:660px)": {
      width: theme.spacing(3.75),
      height: theme.spacing(3.75),
      fontSize: "1rem",
    },
  },
  titleChat: {
    marginLeft: theme.spacing(1),
  },
  rowActions: {
    width: 0,
    "@media (min-width:650px)": {
      width: "80px",
    },
  },
  iconButton: {
    padding: 0,
  },
}));

const TenantsAndGurantorsTable = ({ onClickHandler, tenants, guarantors }) => {
  const classes = useStyles();

  return (
    <TableContainer className={classes.tableContainer} component={Paper}>
      <Table className={classes.table} aria-label="simple table">
        <TableBody>
          {guarantors.map((row, index) => (
            <TableRow key={index}>
              <TableCell component="th" scope="row">
                <div className={classes.titleSection}>
                  <Avatar className={classes.avatar}>
                    {`${row.name[0]}${row.lastname[0]}`}
                  </Avatar>

                  <Typography className={classes.titleChat} variant="body2">
                    {`${row.name} ${row.lastname} `}{" "}
                    <span style={{ color: "#158900" }}>{`(Garante)`}</span>
                  </Typography>
                </div>
              </TableCell>
              <TableCell></TableCell>
              <TableCell align="center" className={classes.rowActions}>
                <Tooltip title="Detalles">
                  <IconButton
                    className={classes.iconButton}
                    onClick={() => onClickHandler(row, "contactDetails")}
                    style={{ color: "#49AC08" }}
                  >
                    <VisibilityIcon />
                  </IconButton>
                </Tooltip>
              </TableCell>
            </TableRow>
          ))}
          {tenants.map((row, index) => (
            <TableRow key={index}>
              <TableCell
                component="th"
                scope="row"
                style={index === tenants.length - 1 ? { border: "none" } : null}
              >
                <div className={classes.titleSection}>
                  <Avatar className={classes.avatar}>
                    {`${row.name[0]}${row.lastname[0]}`}
                  </Avatar>

                  <Typography className={classes.titleChat} variant="body2">
                    {`${row.name} ${row.lastname}`}{" "}
                    <span style={{ color: "#158900" }}>{`(Inquilino)`}</span>
                  </Typography>
                </div>
              </TableCell>
              {index === 0 ? (
                <TableCell
                  align="center"
                  className={classes.rowActions}
                  style={
                    index === tenants.length - 1 ? { border: "none" } : null
                  }
                >
                  <Tooltip title="Cuenta corriente">
                    <IconButton
                      className={classes.iconButton}
                      onClick={() => onClickHandler(row)}
                      style={{ color: "#4488BB" }}
                    >
                      <AccountBalanceWalletIcon />
                    </IconButton>
                  </Tooltip>
                </TableCell>
              ) : (
                <TableCell
                  className={classes.rowActions}
                  style={
                    index === tenants.length - 1 ? { border: "none" } : null
                  }
                ></TableCell>
              )}
              <TableCell
                align="center"
                className={classes.rowActions}
                style={index === tenants.length - 1 ? { border: "none" } : null}
              >
                <Tooltip title="Detalles">
                  <IconButton
                    className={classes.iconButton}
                    onClick={() => onClickHandler(row, "contactDetails")}
                    style={{ color: "#49AC08" }}
                  >
                    <VisibilityIcon />
                  </IconButton>
                </Tooltip>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
};

export default TenantsAndGurantorsTable;
