let lengthMonths = 60;
let lengthDays = 30;

let auxMonths = new Array(lengthMonths);
let auxDays = new Array(lengthDays);

for (let i = 0; i < auxMonths.length; i++) {
  auxMonths[i] = i + 1;
}

for (let i = 0; i < auxDays.length; i++) {
  auxDays[i] = i + 1;
}

export const months = auxMonths;
export const days = auxDays;
