import React, { Fragment } from "react";
import { makeStyles } from "@material-ui/core/styles";
import {
  IconButton,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableRow,
  Paper,
  TableHead,
  Switch,
  withStyles,
  Grid,
} from "@material-ui/core";

import ArrowUpwardIcon from "@material-ui/icons/ArrowUpward";
import ArrowDownwardIcon from "@material-ui/icons/ArrowDownward";
import { NumberFormatCustom } from "../../../hooks/format-number-hook";

const AntSwitch = withStyles((theme) => ({
  root: {
    width: 29,
    height: 16,
    padding: 0,
  },
  switchBase: {
    padding: 2,
    color: theme.palette.grey[700],
    "&$checked": {
      transform: "translateX(13px)",
      color: theme.palette.common.white,
      "& + $track": {
        opacity: 1,
        backgroundColor: "#49AC08",
        borderColor: "#49AC08",
      },
    },
  },
  thumb: {
    width: 12,
    height: 12,
    boxShadow: "none",
    color: "#FAFAFA",
  },
  track: {
    border: `1px solid ${theme.palette.grey[700]}`,
    borderRadius: 16 / 2,
    opacity: 1,
    backgroundColor: theme.palette.grey[700],
  },
  checked: {},
}))(Switch);

const useStyles = makeStyles((theme) => ({
  tableContainer: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    justifyContent: "space-between",
    boxShadow: "none",
    backgroundColor: "#F7F9F8",
    border: "1px solid #E6EBE8",
    borderRadius: 12,
    padding: theme.spacing(1, 1.25),
    maxHeight: 200,

    "& .MuiTableCell-head": {
      color: "#000000",
      fontSize: "14px",
      lineHeight: "20px",
      letterSpacing: "0.02em",
      padding: theme.spacing(1),
    },

    "& .MuiTableCell-body": {
      color: "#000000",
      fontSize: "14px",
      lineHeight: "20px",
      letterSpacing: "0.02em",
      padding: theme.spacing(1),
      borderColor: "#E6EBE8",
    },
  },

  titleSection: {
    display: "flex",
    alignItems: "center",
    "& .MuiBadge-dot": {
      backgroundColor: theme.palette.secondary.light,
    },
  },

  titleChat: {
    marginLeft: theme.spacing(1),
  },
  rowActions: {
    width: 0,
    "@media (min-width:650px)": {
      width: "80px",
    },
  },
  iconButton: {
    padding: 0,
  },
}));

const ItemsTable = ({
  isIndividualService,
  thereIsAtLeastOneService,
  items,
  checked,
  moveElement,
  handleChange,
}) => {
  const classes = useStyles();

  const onClickHandler = (fromIndex, toIndex) => {
    moveElement(fromIndex, toIndex);
  };

  return (
    <TableContainer
      className={classes.tableContainer}
      component={Paper}
      style={thereIsAtLeastOneService ? { maxHeight: 230 } : null}
    >
      <Table aria-label="simple table">
        <TableHead>
          {!isIndividualService && thereIsAtLeastOneService && (
            <TableRow>
              <TableCell colSpan={4}></TableCell>
              <TableCell
                align="center"
                colSpan={3}
                style={{ border: "1px groove", borderBottom: "none" }}
              >
                Servicios
              </TableCell>
              <TableCell colSpan={2}></TableCell>
            </TableRow>
          )}
          <TableRow>
            <TableCell>Nombre</TableCell>
            <TableCell
              align="center"
              style={checked === "true" ? { minWidth: 160 } : null}
            >{`Monto${
              checked === "true" ? "\n(con intereses)" : ""
            }`}</TableCell>
            {!isIndividualService && (
              <Fragment>
                <TableCell align="center" style={{ minWidth: 80 }}>
                  % Interes
                </TableCell>
                <TableCell align="center">Intereses</TableCell>
              </Fragment>
            )}

            {(isIndividualService || thereIsAtLeastOneService) && (
              <Fragment>
                <TableCell
                  align="center"
                  style={{
                    minWidth: 110,
                    ...(!isIndividualService &&
                      thereIsAtLeastOneService && {
                        border: "1px groove",
                        borderTop: "none",
                        borderRight: "none",
                      }),
                  }}
                >
                  Inquilino paga
                </TableCell>
                <TableCell
                  align="center"
                  style={{
                    minWidth: 125,
                    ...(!isIndividualService &&
                      thereIsAtLeastOneService && {
                        borderBottom: "1px groove",
                      }),
                  }}
                >
                  Propietario paga
                </TableCell>
              </Fragment>
            )}
            {(isIndividualService || thereIsAtLeastOneService) && (
              <TableCell
                align="center"
                style={{
                  minWidth: 153,
                  ...(!isIndividualService && {
                    border: "1px groove",
                    borderTop: "none",
                    borderLeft: "none",
                  }),
                }}
              >
                Ingresa dinero a caja
              </TableCell>
            )}
            <TableCell align="center"></TableCell>
            <TableCell align="center"></TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {items.map((entry, index) => (
            <TableRow key={index}>
              <TableCell
                component="th"
                scope="row"
                style={
                  index + 1 === items.length ? { borderBottom: "none" } : null
                }
              >
                {entry.name}
              </TableCell>

              <TableCell
                align="center"
                component="th"
                scope="row"
                style={
                  index + 1 === items.length ? { borderBottom: "none" } : null
                }
              >
                {NumberFormatCustom(
                  checked === "true"
                    ? entry.interestAmount
                      ? entry.amount + entry.interestAmount
                      : entry.amount
                    : entry.amount
                )}
              </TableCell>

              {!isIndividualService && (
                <Fragment>
                  <TableCell
                    align="center"
                    component="th"
                    scope="row"
                    style={
                      index + 1 === items.length
                        ? { borderBottom: "none" }
                        : null
                    }
                  >
                    {entry.dailyInterestPercentage
                      ? `${parseFloat(entry.dailyInterestPercentage)}%`
                      : "0%"}
                  </TableCell>
                  <TableCell
                    align="center"
                    component="th"
                    scope="row"
                    style={
                      index + 1 === items.length
                        ? { borderBottom: "none" }
                        : null
                    }
                  >
                    {entry.interestAmount
                      ? NumberFormatCustom(entry.interestAmount)
                      : "$0"}
                  </TableCell>
                </Fragment>
              )}

              {(isIndividualService || thereIsAtLeastOneService) && (
                <Fragment>
                  <TableCell
                    align="center"
                    component="th"
                    scope="row"
                    style={
                      index + 1 === items.length
                        ? { borderBottom: "none" }
                        : null
                    }
                  >
                    {entry.itemType === 2
                      ? entry.paymentMethod === 1
                        ? `${entry.tenantPercentage}%`
                        : entry.tenantAmount
                        ? NumberFormatCustom(entry.tenantAmount)
                        : "$0"
                      : "-"}
                  </TableCell>
                  <TableCell
                    align="center"
                    component="th"
                    scope="row"
                    style={
                      index + 1 === items.length
                        ? { borderBottom: "none" }
                        : null
                    }
                  >
                    {entry.itemType === 2
                      ? entry.paymentMethod === 1
                        ? `${entry.ownerPercentage}%`
                        : entry.ownerAmount
                        ? NumberFormatCustom(entry.ownerAmount)
                        : "$0"
                      : "-"}
                  </TableCell>
                </Fragment>
              )}
              {(isIndividualService || thereIsAtLeastOneService) && (
                <TableCell
                  align="center"
                  component="th"
                  scope="row"
                  style={
                    index + 1 === items.length ? { borderBottom: "none" } : null
                  }
                >
                  {entry.itemType === 2 ? (
                    <Grid
                      container
                      alignItems="center"
                      justify="center"
                      spacing={1}
                    >
                      <Grid item>No</Grid>
                      <Grid item>
                        <AntSwitch
                          checked={entry.cashToBox}
                          onChange={(e) => handleChange(e, entry._id)}
                          name="checked-cashToBox"
                        />
                      </Grid>
                      <Grid item>Si</Grid>
                    </Grid>
                  ) : (
                    "-"
                  )}
                </TableCell>
              )}
              <TableCell
                align="center"
                className={classes.rowActions}
                style={
                  index + 1 === items.length ? { borderBottom: "none" } : null
                }
              >
                <IconButton
                  className={classes.iconButton}
                  onClick={() => onClickHandler(index, index - 1)}
                  style={index === 0 ? null : { color: "#49AC08" }}
                  disabled={index === 0 ? true : false}
                >
                  <ArrowUpwardIcon />
                </IconButton>
              </TableCell>
              <TableCell
                align="center"
                className={classes.rowActions}
                style={
                  index + 1 === items.length ? { borderBottom: "none" } : null
                }
              >
                <IconButton
                  className={classes.iconButton}
                  onClick={() => onClickHandler(index, index + 1)}
                  style={
                    index + 1 === items.length ? null : { color: "#49AC08" }
                  }
                  disabled={index + 1 === items.length ? true : false}
                >
                  <ArrowDownwardIcon />
                </IconButton>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
};

export default ItemsTable;
