import axios from "axios";
import {
  GET_EXPENDITURES_TYPES,
  ADD_EXPENDITURE_TYPE,
  EDIT_EXPENDITURE_TYPE,
  DELETE_EXPENDITURE_TYPE,
} from "./actionTypes";

import { setSnackData } from "./snackDataActions";

export const getExpendituresTypes = (id, token, setIsLoading) => (dispatch) => {
  axios
    .get(
      `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/expenditures-types`,
      {
        headers: {
          Authorization: "Bearer " + token,
        },
      }
    )
    .then((res) => {
      dispatch({
        type: GET_EXPENDITURES_TYPES,
        payload: res.data,
      });
      if (setIsLoading) setIsLoading(false);
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }
      if (setIsLoading) setIsLoading(false);
    });
};

export const addExpenditureType =
  (id, token, data, setOpen, setIsLoading) => (dispatch, getState) => {
    let expenditures = getState().expendituresTypes.expendituresTypes;
    axios
      .post(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/expenditures-types`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        expenditures.push(res.data);
        dispatch({
          type: ADD_EXPENDITURE_TYPE,
          payload: expenditures,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Clase de gasto creada",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const editExpenditureType =
  (id, token, idET, data, setOpen, setIsLoading) => (dispatch, getState) => {
    let expenditures = getState().expendituresTypes.expendituresTypes;
    axios
      .put(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/expenditures-types/${idET}`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        let i = expenditures.findIndex((expenditure) => {
          if (expenditure._id === idET) {
            return true;
          }
          return false;
        });

        if (i !== -1) {
          expenditures[i] = Object.assign(expenditures[i], data);
        }

        dispatch({
          type: EDIT_EXPENDITURE_TYPE,
          payload: expenditures,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Clase de gasto editada",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const deleteExpenditureType =
  (id, token, idET, setOpen, setIsLoading) => (dispatch, getState) => {
    let expenditures = getState().expendituresTypes.expendituresTypes;
    axios
      .delete(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/expenditures-types/${idET}`,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        let i = expenditures.findIndex((expenditure) => {
          if (expenditure._id === idET) {
            return true;
          }
          return false;
        });

        i !== -1 && expenditures.splice(i, 1);

        dispatch({
          type: DELETE_EXPENDITURE_TYPE,
          payload: expenditures,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Clase de gasto eliminada",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };
