import { IconButton, TableCell } from "@material-ui/core";
import React, { Fragment, useState } from "react";
import { useSelector } from "react-redux";
import { getFormatDate } from "../../hooks/date-hook";
import Modal from "../Shared/Modal";
import Table from "../Shared/Table";
import Spinner from "../UI/Spinner";

import FileIcon from "@material-ui/icons/Description";
import DeleteReceipt from "./DeleteReceipt";

const Cells = ({ row, establishment }) => {
  return (
    <Fragment>
      <TableCell component="th" scope="row">
        {getFormatDate(row.date)}
      </TableCell>
      <TableCell style={{ minWidth: 80 }} component="th" scope="row">
        {row.items.length}
      </TableCell>
      <TableCell
        style={{
          minWidth: 100,
        }}
        component="th"
        scope="row"
      >
        {/* Enlaces a comprobantes */}
        <div style={{ display: "flex", flexDirection: "column" }}>
          {row.owners.map((entry, index) => {
            if (entry.liquidation) {
              return (
                <a
                  key={`link-to-pdf-${index}`}
                  style={{
                    outline: "none",
                    textDecoration: "none",
                    color: "#49AC08",
                    ...(index > 0 && { paddingTop: 8 }),
                  }}
                  href={`${process.env.REACT_APP_BACKEND_URL}/files/${establishment}/${entry.liquidation}.pdf`}
                  rel="noreferrer"
                  target="_blank"
                >
                  {`Comprobante: ${entry.liquidation}`}
                </a>
              );
            }

            return null;
          })}
        </div>
      </TableCell>
      <TableCell style={{ minWidth: 150 }} component="th" scope="row">
        {row.notes || ""}
      </TableCell>
      <TableCell style={{ minWidth: 150 }} component="th" scope="row">
        {`${row.creator?.name} ${row.creator?.lastname}`}
      </TableCell>
      <TableCell style={{ width: 120 }} component="th" scope="row">
        <a
          href={`${process.env.REACT_APP_BACKEND_URL}/files/${establishment}/${row._id}.pdf`}
          rel="noreferrer"
          target="_blank"
        >
          <IconButton
            disableRipple
            style={{ padding: 0 }}
            variant="contained"
            color="primary"
          >
            <FileIcon />
          </IconButton>
        </a>
      </TableCell>
    </Fragment>
  );
};

const Receipts = ({ user, establishment, idContract, isLoadingTable }) => {
  const [open, setOpen] = useState(false);
  const [current, setCurrent] = useState(null);
  const [action, setAction] = useState();

  const columns = [
    "Fecha",
    "Items",
    "Comprobante(s) de liquidación",
    "Notas",
    "Por",
    "Ver PDF",
    "Eliminar",
  ];

  const rows = useSelector((state) => state.contracts.receipts);

  const deleteAction = (current) => {
    setCurrent(current);
    setOpen(true);
  };

  const disabledDelete = (row) => {
    let aux = row.owners.filter((entry) => entry.liquidation);

    if (aux.length > 0) {
      return true;
    }

    return false;
  };

  const actions = {
    delete: (
      <DeleteReceipt
        user={user}
        setOpen={setOpen}
        current={current}
        idContract={idContract}
      />
    ),
  };

  return isLoadingTable ? (
    <Spinner height={300} />
  ) : (
    <Fragment>
      <Table
        columns={columns}
        rows={rows}
        Cells={(row) => <Cells row={row.row} establishment={establishment} />}
        deleteAction={deleteAction}
        setAction={setAction}
        disableColumnDetails={true}
        disableColumnEdit={true}
        disableRemoveConditional={disabledDelete}
        messageDisbledDelete="No se puede eliminar el comprobante porque forma parte de una liquidación"
      />
      <Modal
        handleClose={() => setOpen(false)}
        open={open}
        component={actions[action]}
      />
    </Fragment>
  );
};

export default Receipts;
