import React from "react";
import { Grid, makeStyles } from "@material-ui/core";
import { Line, Doughnut } from "react-chartjs-2";
import { getFormatDate } from "../../hooks/date-hook";

const useStyles = makeStyles((theme) => ({
  grid: {
    marginTop: theme.spacing(2),
    marginBottom: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "space-around",
    alignItems: "center",
  },
}));

const colors = [
  "rgba(0, 150, 136)",
  "rgba(63, 81, 181)",
  "rgba(244, 67, 54)",
  "rgba(103, 58, 183)",
  "rgba(33, 150, 243)",
  "rgba(76, 175, 80)",
  "rgba(255, 152, 0)",
  "rgba(255, 87, 34)",
  "rgba(121, 85, 72)",
  "rgba(158, 158, 158)",
  "rgba(96, 125, 139)",
];

const Graphics = ({ expenses, expenditures }) => {
  const classes = useStyles();

  // Suma de una expensa
  let totalExpendituresTypesAmount = 0;

  // Suma de los gastos que abrcan esa expensa
  let totalExpendituresAmount = 0;

  // Suma de lo recaudado
  let collected = 0;

  let data = {
    labels: [],
    datasets: [
      {
        label: "Gastos",
        data: [],
        fill: false,
        backgroundColor: colors[2],
        borderColor: colors[2],
        tension: 0.1,
      },
      {
        label: "Expensa",
        data: [],
        fill: false,
        backgroundColor: colors[1],
        borderColor: colors[1],
        tension: 0.1,
      },

      {
        label: "Recaudado",
        data: [],
        fill: false,
        backgroundColor: colors[0],
        borderColor: colors[0],
        tension: 0.1,
      },
    ],
  };

  const expensesData = () => {
    for (let i = 0; i < expenses.length; i++) {
      totalExpendituresTypesAmount += expenses[i].expendituresTypes.reduce(
        (acc, et) => (acc += et.amount),
        0
      );

      collected += expenses[i].functionalUnits.reduce(
        (acc, fu) =>
          (acc += fu.paidAmounts.reduce((acc, pa) => (acc += pa.amount), 0)),
        0
      );

      totalExpendituresAmount += expenses[i].expendituresTypes.reduce(
        (acc, et) => (acc += et.expendituresAmount),
        0
      );

      data.labels.push(getFormatDate(expenses[i].date));

      data.datasets[0].data.push(totalExpendituresAmount);
      data.datasets[1].data.push(totalExpendituresTypesAmount);
      data.datasets[2].data.push(collected);

      totalExpendituresAmount = 0;
      totalExpendituresTypesAmount = 0;
      collected = 0;
    }

    return data;
  };

  const expenditureData = () => {
    let aux = {};
    let data = {
      labels: [],
      datasets: [
        {
          data: [],
          backgroundColor: colors,
        },
      ],
    };

    for (let i = 0; i < expenditures.length; i++) {
      aux[expenditures[i].category.name]
        ? (aux[expenditures[i].category.name] += expenditures[i].amount.amount)
        : (aux[expenditures[i].category.name] = expenditures[i].amount.amount);
    }

    for (let key in aux) {
      data.labels.push(key);
      data.datasets[0].data.push(aux[key]);
    }

    return data;
  };

  return (
    <Grid container className={classes.grid} spacing={5}>
      <Grid item xs={12} sm={8}>
        <Line
          data={expensesData}
          options={{
            maintainAspectRatio: false,
          }}
        />
      </Grid>
      <Grid item xs={12} sm={4}>
        <Doughnut
          data={expenditureData}
          options={{
            maintainAspectRatio: false,
          }}
        />
      </Grid>
    </Grid>
  );
};

export default React.memo(Graphics);
