import React, { Fragment, useState } from "react";
import {
  Button,
  Grid,
  makeStyles,
  Typography,
  useMediaQuery,
  useTheme,
  Tooltip,
  IconButton,
} from "@material-ui/core";

import Spinner from "../UI/Spinner";

import Modal from "../Shared/Modal";

import AddEstate from "../Estates/AddEstate";
import ItemCard from "../Shared/ItemCard";
import TenantsAndGuarantors from "./FormComponents/TenantsAndGuarantors";
import EstatesAutoComplete from "../Shared/EstatesAutoComplete";

import { types } from "../../configs/contracts/TenantsAndGuarantors/TYPES";
import Rental from "./FormComponents/Rental";
import Contract from "./FormComponents/Contract";
import TaxesAndOthers from "./FormComponents/TaxesAndOthers";

import AddIcon from "@material-ui/icons/Add";
import ReceiptIcon from "@material-ui/icons/Receipt";
import { typesOrTaxes } from "../../configs/contracts/taxes/TYPES_OR_TAXES";

import PersonIcon from "@material-ui/icons/Person";
import AttachFileIcon from "@material-ui/icons/AttachFile";

const useStyles = makeStyles((theme) => ({
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "left",

    "& .Mui-checked": {
      color: "#49AC08",
    },
  },
  estates: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "flex-end",
  },
  addButton: {
    marginTop: theme.spacing(2),
    marginLeft: theme.spacing(1),
    padding: theme.spacing(0.5),
  },
  cardContainer: {
    padding: theme.spacing(0.5, 0.5, 0, 0),
    overflowX: "hidden",
    overflowY: "auto",
    maxHeight: theme.spacing(13.75),
  },
  buttons: {
    justifyContent: "center",
    marginTop: theme.spacing(3.5),
    "& .MuiTooltip-tooltip": {
      backgroundColor: "red",
    },
  },
}));

const Form = ({
  title,
  user,
  contacts,
  estates,
  reloadEstates,
  property,
  setProperty,
  tenants,
  setTenants,
  guarantors,
  setGuarantors,
  rentalData,
  setRentalData,
  contractData,
  setContractData,
  pdf,
  setPdf,
  items,
  setItems,
  services,
  setServices,
  setOpen,
  isLoading,
  onClikHandler,
  establishment,
  hasChanged,
  setHasChanged,
}) => {
  const classes = useStyles();

  const [openAddProperty, setOpenAddProperty] = useState(false);

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("800"), {
    defaultMatches: true,
  });

  const onChangeData = () => {
    if (setHasChanged && hasChanged === false) {
      setHasChanged(true);
    }
  };

  const addUser = (contact, type) => {
    let i = contacts.findIndex((entry) => {
      if (entry._id === contact) {
        return true;
      }
      return false;
    });

    let j = tenants.concat(guarantors).findIndex((entry) => {
      if (entry._id === contact) {
        return true;
      }
      return false;
    });

    if (i !== -1 && j === -1) {
      if (type === "1") {
        setTenants([...tenants, contacts[i]]);
      } else {
        setGuarantors([...guarantors, contacts[i]]);
      }
    }
  };

  const deleteUser = (id, type) => {
    if (type === "1") {
      setTenants((tenants) => {
        let copy = [...tenants];
        let i = copy.findIndex((entry) => {
          if (entry._id === id) {
            return true;
          }
          return false;
        });

        i !== -1 && copy.splice(i, 1);

        return copy;
      });
    } else {
      setGuarantors((guarantors) => {
        let copy = [...guarantors];
        let i = copy.findIndex((entry) => {
          if (entry._id === id) {
            return true;
          }
          return false;
        });

        i !== -1 && copy.splice(i, 1);

        return copy;
      });
    }

    onChangeData();
  };

  const addTax = (obj, type) => {
    if (type === "0") {
      setItems((items) => {
        let copy = [...items];

        copy.push(obj);

        return copy;
      });
    } else {
      setServices((services) => {
        let copy = [...services];

        copy.push(obj);

        return copy;
      });
    }

    onChangeData();
  };

  const deleteTax = (index, type) => {
    if (type === "0") {
      setItems((items) => {
        let copy = [...items];

        copy.splice(index, 1);

        return copy;
      });
    } else {
      setServices((services) => {
        let copy = [...services];

        copy.splice(index, 1);

        return copy;
      });
    }

    onChangeData();
  };

  const setFile = (event) => {
    if (event.target.files && event.target.files[0]) {
      let file = event.target.files[0];

      setPdf(file);

      onChangeData();
    }
  };

  const deleteFile = (index) => {
    setPdf(null);
    onChangeData();
  };
  let disabled =
    hasChanged &&
    property !== "" &&
    guarantors.length > 0 &&
    tenants.length > 0 &&
    !Object.entries(rentalData).some((entry) => entry[1].value === "") &&
    !Object.entries(rentalData).some((entry) => entry[1].isValid === false) &&
    !Object.entries(contractData).some((entry) => entry[1].value === "") &&
    !Object.entries(contractData).some((entry) => !entry[1].value)
      ? false
      : true;

  return isLoading ? (
    <Spinner height={843} />
  ) : (
    <Fragment>
      <Typography variant="h6">{title}</Typography>
      <Grid container className={classes.grid} spacing={2}>
        <Grid item xs={12} sm={5}>
          <div className={classes.estates}>
            <EstatesAutoComplete
              label="Propiedad"
              estates={estates}
              property={property}
              setState={(value) => {
                if (value) {
                  setProperty(value._id);
                } else {
                  setProperty("");
                }
                onChangeData();
              }}
            />
            <Tooltip title="Agregar propietario">
              <div>
                <IconButton
                  className={classes.addButton}
                  variant="contained"
                  aria-label="add"
                  onClick={() => setOpenAddProperty(true)}
                >
                  <AddIcon />
                </IconButton>
              </div>
            </Tooltip>
          </div>
        </Grid>

        <Grid item xs={12} sm={7}>
          <TenantsAndGuarantors
            contacts={contacts}
            onChangeData={onChangeData}
            addUser={addUser}
            isMobile={isMobile}
          />
        </Grid>
        {tenants.concat(guarantors).length > 0 && (
          <Grid item xs={12}>
            <div className={classes.cardContainer}>
              {tenants.length > 0 &&
                tenants.map((entry, index) => (
                  <ItemCard
                    key={`itemCard-tenants-${index}`}
                    title={`${entry.name} ${entry.lastname}`}
                    subtitle={`(${types[1]})`}
                    Icon={PersonIcon}
                    action={() => deleteUser(entry._id, "1")}
                  />
                ))}
              {guarantors.length > 0 &&
                guarantors.map((entry, index) => (
                  <ItemCard
                    key={`itemCard-guarantors-${index}`}
                    title={`${entry.name} ${entry.lastname}`}
                    subtitle={`(${types[2]})`}
                    Icon={PersonIcon}
                    action={() => deleteUser(entry._id, "2")}
                  />
                ))}
            </div>
          </Grid>
        )}

        <Grid item xs={12} style={{ paddingTop: 24 }}>
          <Typography variant="h6">
            Alquiler{" "}
            <span style={{ color: "#158900", fontSize: 14 }}>
              (Obligatorio)
            </span>
          </Typography>
        </Grid>
        <Rental
          onChangeData={onChangeData}
          data={rentalData}
          setData={setRentalData}
          isMobile={isMobile}
        />

        <Grid item xs={12} style={{ paddingTop: 24 }}>
          <Typography variant="h6">
            Impuestos y otros{" "}
            <span style={{ color: "#158900", fontSize: 14 }}>(Opcional)</span>{" "}
          </Typography>
        </Grid>
        <TaxesAndOthers addTax={addTax} isMobile={isMobile} />

        {items.concat(services).length > 0 && (
          <Grid item xs={12}>
            <div className={classes.cardContainer}>
              {items.length > 0 &&
                items.map((entry, index) => (
                  <ItemCard
                    key={`itemCard-items-${index}`}
                    title={entry.name}
                    subtitle={`(${typesOrTaxes[0]})`}
                    Icon={ReceiptIcon}
                    action={() => deleteTax(index, "0")}
                  />
                ))}
              {services.length > 0 &&
                services.map((entry, index) => (
                  <ItemCard
                    key={`serviceCard-${index}`}
                    title={entry.service.name}
                    subtitle={`(${typesOrTaxes[1]})`}
                    Icon={ReceiptIcon}
                    action={() => deleteTax(index, "1")}
                  />
                ))}
            </div>
          </Grid>
        )}

        <Grid item xs={12} style={{ paddingTop: 24 }}>
          <Typography variant="h6">
            Contrato{" "}
            <span style={{ color: "#158900", fontSize: 14 }}>
              (Obligatorio)
            </span>
          </Typography>
        </Grid>
        <Contract
          rentalData={rentalData}
          data={contractData}
          setData={setContractData}
          onChangeData={onChangeData}
          isMobile={isMobile}
          setFile={setFile}
          pdf={pdf}
        />
        <Grid item xs={12}>
          {pdf !== null && (
            <ItemCard
              onClickCard={() => {
                if (pdf.pdf) {
                  window.open(
                    `${process.env.REACT_APP_BACKEND_URL}/files/${establishment}/${pdf.pdf}`,
                    "_blank"
                  );
                }
              }}
              key={`pdf-card`}
              title={pdf.name}
              Icon={AttachFileIcon}
              action={deleteFile}
            />
          )}
        </Grid>
      </Grid>
      <Grid container className={classes.buttons} spacing={1}>
        <Grid item xs={6} sm={isMobile ? 6 : 3}>
          <Button
            id="cancel-button"
            variant="outlined"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Cancelar
          </Button>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 6 : 3}>
          <Tooltip
            title={
              disabled
                ? "Debe rellenar todos los campos para poder continuar"
                : ""
            }
            leaveDelay={5000}
            interactive
          >
            <div>
              <Button
                disabled={disabled}
                variant="contained"
                color="primary"
                disableElevation
                fullWidth
                onClick={onClikHandler}
              >
                Aceptar
              </Button>
            </div>
          </Tooltip>
        </Grid>
      </Grid>
      <Modal
        handleClose={() => setOpenAddProperty(false)}
        open={openAddProperty}
        component={
          <AddEstate
            user={user}
            contacts={contacts}
            setOpen={(value) => {
              reloadEstates();
              setOpenAddProperty(value);
            }}
            preload={(e) => {
              setProperty(e);
            }}
          />
        }
      />
    </Fragment>
  );
};

export default Form;
