import { GET_DATA_SERVER, EDIT_DATA_SERVER } from "../Action/actionTypes";

const initialState = { dataServer: {} };

export const emailServerReducer = (state = initialState, action) => {
  switch (action.type) {
    case GET_DATA_SERVER:
      return {
        ...state,
        dataServer: action.payload,
      };
    case EDIT_DATA_SERVER:
      return {
        ...state,
        dataServer: action.payload,
      };
    default:
      return state;
  }
};

export default emailServerReducer;
