import React from "react";
import {
  Button,
  Grid,
  makeStyles,
  TextField,
  Typography,
  useMediaQuery,
  useTheme,
} from "@material-ui/core";
import Spinner from "../UI/Spinner";
import { useForm } from "../../hooks/use-form";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    width: theme.spacing(50),
    padding: theme.spacing(5),
    "@media (max-width:650px)": {
      width: theme.spacing(30),
      padding: theme.spacing(1),
    },
    "@media (max-width:400px)": {
      width: theme.spacing(20),
      padding: 0,
    },
  },
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  marginBottom: {
    marginBottom: theme.spacing(2.5),
  },
}));

const initialState = {
  name: "",
  address: "",
  location: "",
  cuit: "",
  phone: "",
  email: "",
};

const Form = ({
  title,
  setOpen,
  isLoading,
  onClikHandler,
  data,
  hasChanged,
  setHasChanged,
}) => {
  const classes = useStyles();

  const [form, onChangeHandler] = useForm(
    data
      ? {
          name: data.name,
          address: data.address || "",
          location: data.location || "",
          cuit: data.cuit || "",
          phone: data.phone || "",
          email: data.email || "",
        }
      : initialState
  );

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const onChangeData = () => {
    if (setHasChanged && hasChanged === false) {
      setHasChanged(true);
    }
  };

  const formatData = () => {
    let data = {
      name: form.name.value,
    };

    for (let key in form) {
      if (form[key].value !== "" && form[key].isValid === true) {
        data[key] = form[key].value;
      }
    }

    onClikHandler(data);
  };

  let disabled =
    hasChanged &&
    !Object.entries(form)
      .filter((entry) => entry[1] !== "name")
      .some((entry) => entry[1].value !== "" && entry[1].isValid === false) &&
    form.name.value !== "" &&
    form.name.isValid === true
      ? false
      : true;

  return isLoading ? (
    <Spinner height={508} />
  ) : (
    <div>
      <Typography variant="h6">{title}</Typography>
      <Grid container className={classes.grid} spacing={1}>
        <Grid item xs={12}>
          <TextField
            value={form.name.value}
            required
            autoComplete="off"
            fullWidth
            id="name"
            name="name"
            label="Nombre"
            inputProps={{
              minLength: 2,
              maxLength: 100,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.name.isValid}
            helperText={
              !form.name.isValid &&
              (form.name.value.length < 2
                ? "Pocos caracteres"
                : "Nombre inválido")
            }
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            value={form.address.value}
            required
            autoComplete="off"
            fullWidth
            name="address"
            id="address"
            label="Dirección"
            inputProps={{
              minLength: 2,
              maxLength: 100,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ . -]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.address.isValid}
            helperText={
              !form.address.isValid &&
              (form.address.value.length < 2
                ? "Pocos caracteres"
                : "Dirección inválida")
            }
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            value={form.location.value}
            required
            autoComplete="off"
            fullWidth
            name="location"
            id="location"
            label="Localidad"
            inputProps={{
              minLength: 2,
              maxLength: 100,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ . -]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.location.isValid}
            helperText={
              !form.location.isValid &&
              (form.location.value.length < 2
                ? "Pocos caracteres"
                : "Localidad inválida")
            }
            InputLabelProps={{ required: false }}
          />
        </Grid>

        <Grid item xs={12}>
          <TextField
            id="cuit"
            label="Cuit"
            value={form.cuit.value}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            fullWidth
            required
            autoComplete="off"
            type="text"
            inputProps={{
              pattern: "[0-9]+",
              minLength: "10",
              maxLength: "11",
            }}
            error={!form.cuit.isValid}
            helperText={
              !form.cuit.isValid &&
              (form.cuit.value.length < 10
                ? "Minimo 10 caracteres"
                : "Ingrese un cuit válido")
            }
            InputLabelProps={{ required: false }}
          />
        </Grid>

        <Grid item xs={12}>
          <TextField
            value={form.phone.value}
            required
            type="tel"
            autoComplete="off"
            fullWidth
            name="phone"
            id="phone"
            label="Teléfono"
            inputProps={{
              maxLength: 20,
              pattern: "^[0-9()-+ -]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.phone.isValid}
            helperText={!form.phone.isValid && "Teléfono inválido"}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            className={classes.marginBottom}
            value={form.email.value}
            id="email"
            required
            type="email"
            autoComplete="off"
            fullWidth
            name="email"
            label="Email"
            inputProps={{
              maxLength: 256,
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.email.isValid}
            helperText={!form.email.isValid && "Email inválido"}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            id="cancel-button"
            variant="outlined"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Cancelar
          </Button>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            disabled={disabled}
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={formatData}
          >
            Aceptar
          </Button>
        </Grid>
      </Grid>
    </div>
  );
};

export default Form;
