import React, { Fragment, useRef } from "react";
import {
  Button,
  FormControl,
  FormControlLabel,
  FormHelperText,
  Grid,
  Input,
  InputLabel,
  makeStyles,
  MenuItem,
  TextField,
} from "@material-ui/core";

import { ExpandMore } from "@material-ui/icons";

import NumberFormat from "react-number-format";
import { currency } from "../../../configs/CURRENCY";
import DatePicker from "../../Shared/DatePicker";
import { depositKeeper } from "../../../configs/contracts/DEPOSIT_KEEPER";

import PictureAsPdfIcon from "@material-ui/icons/PictureAsPdf";

const useStyles = makeStyles((theme) => ({
  addButton: {
    backgroundColor: "#49AC08",
    color: "#FAFAFA",
    textTransform: "capitalize",
    fontSize: 12,
    "&:hover": {
      backgroundColor: "#49ac089e",
    },
  },
  pdfContainer: {
    display: "flex",
    alignItems: "center",
  },
}));

function NumberFormatCustom(props) {
  const { min, id, inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
            id: id,
            validity: {
              valid: parseFloat(values.value, 10) >= parseFloat(min, 10),
            },
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={3}
      isNumericString
      prefix="$"
    />
  );
}

function NumberFormatPercentage(props) {
  const { min, max, id, inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
            id: id,
            validity: {
              valid:
                parseFloat(values.value, 10) <= parseFloat(max, 10) &&
                parseFloat(values.value, 10) >= parseFloat(min, 10),
            },
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={3}
      isNumericString
      suffix="%"
    />
  );
}

const Contract = ({
  rentalData,
  data,
  setData,
  onChangeData,
  isMobile,
  setFile,
  pdf,
}) => {
  const classes = useStyles();

  const ref = useRef();
  const onClickHandler = () => {
    ref.current.click();
  };

  const handleDateChange = (date) => {
    let formatDate = date.toISOString();
    onChangeData();
    setData({ target: { id: "startingDate", value: formatDate } });
  };

  const getAmount = () => {
    let aux = 0;
    let sum = 0;
    let amount = 0;
    let months = 0;
    let increaseMonths = 0;
    let increasePercentage = 0;

    if (
      data.feePercentage.value !== "" &&
      rentalData.months.value !== "" &&
      rentalData.amount.value !== "" &&
      rentalData.increasePercentage.value !== "" &&
      rentalData.increaseMonths.value !== ""
    ) {
      months = parseFloat(rentalData.months.value, 10);
      amount = parseFloat(rentalData.amount.value, 10);
      increasePercentage = parseFloat(rentalData.increasePercentage.value, 10);
      increaseMonths = parseFloat(rentalData.increaseMonths.value, 10);
      aux = Math.ceil(months / increaseMonths);

      for (let i = 0; i < aux; i++) {
        if (months > 0 && increaseMonths >= months) {
          sum += months * amount;
          months -= months;
        } else if (months > 0 && increaseMonths <= months) {
          sum += increaseMonths * amount;
          amount = (amount * (increasePercentage + 100)) / 100;
          months -= increaseMonths;
        }
      }

      return (parseFloat(data.feePercentage.value, 10) * sum) / 100;
    }

    return "0";
  };

  const finishingDate = () => {
    if (data.startingDate.value !== null && rentalData.months.value !== "") {
      let aux = new Date(data.startingDate.value);
      aux.setMonth(aux.getMonth() + parseFloat(rentalData.months.value, 10));
      return aux;
    }

    return null;
  };

  return (
    <Fragment>
      <Grid item xs={isMobile ? 6 : 3}>
        <TextField
          InputProps={{
            inputComponent: NumberFormatCustom,
          }}
          required
          autoComplete="off"
          label="Deposito en garantía"
          id="deposit"
          name="deposit"
          value={data.deposit.value}
          onChange={(e) => {
            setData(e);
            onChangeData();
          }}
          fullWidth
          inputProps={{
            min: "0",
            pattern: "[0-9.]+",
            step: ".01",
          }}
          error={!data.deposit.isValid}
          InputLabelProps={{ required: false }}
        />
      </Grid>
      <Grid item xs={isMobile ? 6 : 3}>
        <TextField
          label="Moneda"
          id="currency"
          value={data.currency.value}
          onChange={(e) => {
            e.target.id = "currency";
            setData(e);
            onChangeData();
          }}
          select
          SelectProps={{
            IconComponent: ExpandMore,
          }}
          fullWidth
        >
          <MenuItem value=""></MenuItem>
          {currency.map((currency, index) => (
            <MenuItem key={`select-${currency}`} value={currency}>
              {currency}
            </MenuItem>
          ))}
        </TextField>
      </Grid>
      <Grid item xs={isMobile ? 6 : 3}>
        <TextField
          label="Queda con"
          id="depositKeeper"
          value={data.depositKeeper.value}
          onChange={(e) => {
            e.target.id = "depositKeeper";
            setData(e);
            onChangeData();
          }}
          select
          SelectProps={{
            IconComponent: ExpandMore,
          }}
          fullWidth
        >
          <MenuItem value=""></MenuItem>
          {Object.entries(depositKeeper).map((entry, index) => (
            <MenuItem key={`select-${entry[0]}-${index}`} value={entry[0]}>
              {entry[1]}
            </MenuItem>
          ))}
        </TextField>
      </Grid>
      <Grid item xs={isMobile ? 6 : 3}>
        <TextField
          InputProps={{
            inputComponent: NumberFormatPercentage,
          }}
          value={data.feePercentage.value}
          autoComplete="off"
          fullWidth
          id="feePercentage"
          name="feePercentage"
          label="Honorarios"
          placeholder="0"
          inputProps={{
            min: "0",
            max: "100",
            pattern: "[0-9]+",
            step: ".01",
          }}
          error={!data.feePercentage.isValid}
          onChange={(e) => {
            setData(e);
            onChangeData();
          }}
        />
      </Grid>
      <Grid item xs={isMobile ? 6 : 3}>
        <FormControl style={{ width: "100%" }}>
          <InputLabel htmlFor="my-input">Monto honorarios</InputLabel>
          <Input
            id="amountFee"
            value={getAmount()}
            name="amountFee"
            fullWidth
            readOnly={true}
            inputComponent={NumberFormatCustom}
          />
          <FormHelperText id="helper-text-password">
            Solo lectura
          </FormHelperText>
        </FormControl>
      </Grid>
      <Grid item xs={isMobile ? 6 : 3}>
        <DatePicker
          label="Inicia"
          selectedDate={data.startingDate.value}
          handleDateChange={(e) => handleDateChange(e)}
        />
      </Grid>
      <Grid item xs={isMobile ? 6 : 3}>
        <DatePicker
          readOnly={true}
          label="Finaliza"
          selectedDate={finishingDate()}
          handleDateChange={(e) => handleDateChange(e)}
        />
      </Grid>
      <Grid
        item
        xs={isMobile ? 12 : 3}
        className={classes.pdfContainer}
        style={{ paddingBottom: 16 }}
      >
        <FormControlLabel
          style={{ display: "none" }}
          control={
            <input
              accept=".pdf"
              /* size={500} */
              id="contained-button-file"
              type="file"
              onChange={setFile}
              ref={ref}
            />
          }
        />

        <Button
          disabled={pdf !== null ? true : false}
          fullWidth
          disableElevation
          variant="contained"
          startIcon={<PictureAsPdfIcon />}
          className={classes.addButton}
          onClick={onClickHandler}
        >
          Cargar PDF
        </Button>
      </Grid>
    </Fragment>
  );
};

export default Contract;
