import React, { useState, Fragment, useEffect } from "react";

import Spinner from "../UI/Spinner";
import Table from "../Shared/Table";
import Modal from "../Shared/Modal";

import { TableCell, Typography } from "@material-ui/core";
import { useDispatch, useSelector } from "react-redux";
import { propertyTypes } from "../../configs/PROPERTY_TYPES";
import { getEstates } from "../../Redux/Action/estatesActions";

import EditEstate from "./EditEstate";
import DeleteEstate from "./DeleteEstate";

const Cells = ({ row }) => {
  return (
    <Fragment>
      <TableCell component="th" scope="row">
        {propertyTypes[row.type]}
      </TableCell>
      <TableCell component="th" scope="row">
        {row.address}
      </TableCell>
      <TableCell component="th" scope="row">
        {row.province}
      </TableCell>
      <TableCell component="th" scope="row">
        {row.department}
      </TableCell>
      <TableCell component="th" scope="row">
        {row.location}
      </TableCell>
      <TableCell component="th" scope="row">
        {row.number}
      </TableCell>
      <TableCell component="th" scope="row">
        {row.owners.map((entry, index) => (
          <Typography
            key={`owner-${entry._id}`}
          >{`${entry.owner.name} ${entry.owner.lastname}`}</Typography>
        ))}
      </TableCell>
      <TableCell component="th" scope="row">
        {row.owners.map((entry, index) => (
          <Typography
            key={`owner-${entry._id}`}
          >{`${entry.percentage}%`}</Typography>
        ))}
      </TableCell>
    </Fragment>
  );
};

const Estates = ({
  user,
  contacts,
  isLoadingComponent,
  setIsLoadingComponent,
}) => {
  const dispatch = useDispatch();
  const [open, setOpen] = useState(false);
  const [current, setCurrent] = useState(null);
  const [action, setAction] = useState();

  const columns = [
    "Tipo",
    "Dirección",
    "Provincia",
    "Partido",
    "Localidad",
    "Legajo",
    "Propietario(s)",
    "Porcentaje",
    "Editar",
    "Eliminar",
  ];

  const rows = useSelector((state) => state.estates.estates);

  const deleteAction = (current) => {
    setCurrent(current);
    setOpen(true);
  };

  const editAction = (current) => {
    setCurrent(current);
    setOpen(true);
  };

  const actions = {
    edit: (
      <EditEstate
        user={user}
        setOpen={setOpen}
        contacts={contacts}
        current={current}
      />
    ),
    delete: <DeleteEstate setOpen={setOpen} current={current} />,
  };

  useEffect(() => {
    dispatch(getEstates(user.token, setIsLoadingComponent));
  }, [dispatch, user.token, setIsLoadingComponent]);

  return isLoadingComponent ? (
    <Spinner />
  ) : (
    <Fragment>
      <Table
        columns={columns}
        rows={rows}
        Cells={Cells}
        disableColumnDetails={true}
        deleteAction={deleteAction}
        editAction={editAction}
        setAction={setAction}
      />
      <Modal
        handleClose={() => setOpen(false)}
        open={open}
        component={actions[action]}
      />
    </Fragment>
  );
};

export default Estates;
