import React from "react";
import { makeStyles } from "@material-ui/core/styles";
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableRow,
  Paper,
  TableHead,
} from "@material-ui/core";

import { NumberFormatCustom } from "../../../hooks/format-number-hook";

const useStyles = makeStyles((theme) => ({
  tableContainer: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    justifyContent: "space-between",
    boxShadow: "none",
    backgroundColor: "#F7F9F8",
    border: "1px solid #E6EBE8",
    borderRadius: 12,
    padding: theme.spacing(1, 1.25),
    maxHeight: 225,

    "& .MuiTableCell-head": {
      color: "#000000",
      fontSize: "14px",
      lineHeight: "20px",
      letterSpacing: "0.02em",
      padding: theme.spacing(1),
    },

    "& .MuiTableCell-body": {
      color: "#000000",
      fontSize: "14px",
      lineHeight: "20px",
      letterSpacing: "0.02em",
      padding: theme.spacing(1),
      borderColor: "#E6EBE8",
    },
  },

  titleSection: {
    display: "flex",
    alignItems: "center",
    "& .MuiBadge-dot": {
      backgroundColor: theme.palette.secondary.light,
    },
  },

  titleChat: {
    marginLeft: theme.spacing(1),
  },
  rowActions: {
    width: 0,
    "@media (min-width:650px)": {
      width: "80px",
    },
  },
  iconButton: {
    padding: 0,
  },
}));

const PaymentInformation = ({ amounts, checked }) => {
  const classes = useStyles();

  return (
    <TableContainer className={classes.tableContainer} component={Paper}>
      <Table aria-label="simple table">
        <TableHead>
          <TableRow>
            <TableCell colSpan={4}>Informacion del cobro</TableCell>
          </TableRow>
          <TableRow>
            <TableCell
              style={{ minWidth: checked === "true" ? 152 : 100 }}
            >{`Total (${
              checked === "true" ? `con intereses` : `Items`
            })`}</TableCell>
            <TableCell align="center">Pagos</TableCell>
            <TableCell align="center">Descuentos</TableCell>
            {amounts.positiveBalance > 0 && (
              <TableCell align="center" style={{ minWidth: 120 }}>
                Saldo a favor
              </TableCell>
            )}
            {amounts.totalAmount > 0 &&
              amounts.payments + amounts.discounts >
                (checked === "true"
                  ? amounts.totalAmount +
                    amounts.taxes -
                    amounts.positiveBalance
                  : amounts.totalAmount - amounts.positiveBalance) && (
                <TableCell align="center" style={{ minWidth: 120 }}>
                  Nuevo saldo a favor
                </TableCell>
              )}
            <TableCell align="center" style={{ minWidth: 100 }}>
              Falta pagar
            </TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          <TableRow>
            <TableCell
              component="th"
              scope="row"
              style={{ borderBottom: "none" }}
            >
              {NumberFormatCustom(
                checked === "true"
                  ? amounts.totalAmount + amounts.taxes
                  : amounts.totalAmount
              )}
            </TableCell>
            <TableCell
              align="center"
              component="th"
              scope="row"
              style={{ borderBottom: "none" }}
            >
              {NumberFormatCustom(amounts.payments)}
            </TableCell>
            <TableCell
              align="center"
              component="th"
              scope="row"
              style={{ borderBottom: "none" }}
            >
              {NumberFormatCustom(amounts.discounts)}
            </TableCell>
            {amounts.positiveBalance > 0 && (
              <TableCell
                align="center"
                component="th"
                scope="row"
                style={{ borderBottom: "none" }}
              >
                {NumberFormatCustom(amounts.positiveBalance)}
              </TableCell>
            )}
            {amounts.totalAmount > 0 &&
              amounts.payments + amounts.discounts >
                (checked === "true"
                  ? amounts.totalAmount +
                    amounts.taxes -
                    amounts.positiveBalance
                  : amounts.totalAmount - amounts.positiveBalance) && (
                <TableCell
                  align="center"
                  component="th"
                  scope="row"
                  style={{ borderBottom: "none" }}
                >
                  {NumberFormatCustom(
                    amounts.payments +
                      amounts.discounts -
                      (checked === "true"
                        ? amounts.totalAmount +
                          amounts.taxes -
                          amounts.positiveBalance
                        : amounts.totalAmount - amounts.positiveBalance)
                  )}
                </TableCell>
              )}
            <TableCell
              align="center"
              component="th"
              scope="row"
              style={{ borderBottom: "none" }}
            >
              {NumberFormatCustom(amounts.remainsToPay)}
            </TableCell>
          </TableRow>
        </TableBody>
      </Table>
    </TableContainer>
  );
};

export default PaymentInformation;
