import {
  GET_SERVICES,
  ADD_SERVICE,
  EDIT_SERVICE,
  DELETE_SERVICE,
} from "../Action/actionTypes";

const initialState = { services: [] };

export const servicesReducer = (state = initialState, action) => {
  switch (action.type) {
    case GET_SERVICES:
      return {
        ...state,
        services: action.payload,
      };
    case ADD_SERVICE:
      return {
        ...state,
        services: action.payload,
      };
    case EDIT_SERVICE:
      return {
        ...state,
        services: action.payload,
      };
    case DELETE_SERVICE:
      return {
        ...state,
        services: action.payload,
      };
    default:
      return state;
  }
};

export default servicesReducer;
