import React, { useState } from "react";
import { useDispatch } from "react-redux";
import Form from "./Form";
import { editExpenditureType } from "../../Redux/Action/expendituresTypesActions";

const EditExpenditureType = ({ id, token, setOpen, expenditure }) => {
  const dispatch = useDispatch();

  const [isLoading, setIsLoading] = useState(false);
  const [hasChanged, setHasChanged] = useState(false);

  const onClikHandler = (data) => {
    setIsLoading(true);
    dispatch(
      editExpenditureType(
        id,
        token,
        expenditure._id,
        data,
        setOpen,
        setIsLoading
      )
    );
  };

  return (
    <Form
      title="Editar clase de gasto"
      setOpen={setOpen}
      isLoading={isLoading}
      onClikHandler={onClikHandler}
      hasChanged={hasChanged}
      setHasChanged={setHasChanged}
      data={expenditure}
    />
  );
};

export default EditExpenditureType;
