import React from "react";
import {
  makeStyles,
  Popover,
  Tooltip,
  IconButton,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Button,
} from "@material-ui/core";
import SettingsIcon from "@material-ui/icons/Settings";
import CheckCircleIcon from "@material-ui/icons/CheckCircle";

const useStyles = makeStyles((theme) => ({
  typography: {
    padding: theme.spacing(2),
  },
  paper: {
    minWidth: 200,
    "@media (min-width:960px)": {
      maxHeight: "60vh",
    },
    "& .MuiListItemIcon-root": {
      minWidth: "40px",
    },
  },
}));

const Menu = ({
  icButtonFalse,
  disabled,
  title,
  handleClose,
  onClickHandler,
  anchorEl,
  setAnchorEl,
  menuItems,
  horizontal,
}) => {
  const classes = useStyles();

  const handleClick = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const open = Boolean(anchorEl);
  const id = open ? "simple-popover" : undefined;

  return (
    <div>
      {icButtonFalse ? (
        <Button
          disabled={disabled}
          variant="contained"
          disableElevation
          fullWidth
          onClick={handleClick}
        >
          {title}
        </Button>
      ) : (
        <Tooltip title={title}>
          <IconButton disabled={disabled} onClick={handleClick}>
            <SettingsIcon />
          </IconButton>
        </Tooltip>
      )}
      <Popover
        id={id}
        open={open}
        anchorEl={anchorEl}
        onClose={handleClose}
        anchorOrigin={{
          vertical: "bottom",
          horizontal: horizontal || "center",
        }}
        transformOrigin={{
          vertical: "top",
          horizontal: horizontal || "center",
        }}
      >
        <div className={classes.paper}>
          <List component="nav">
            {Object.entries(menuItems).map((item, index) => {
              return (
                <ListItem
                  key={`menu-item-${index}`}
                  button
                  onClick={onClickHandler.bind(
                    this,
                    icButtonFalse ? item[1] : item[0]
                  )}
                >
                  {!icButtonFalse && menuItems[item[0]] && (
                    <ListItemIcon>
                      <CheckCircleIcon />
                    </ListItemIcon>
                  )}
                  <ListItemText primary={item[0]} />
                </ListItem>
              );
            })}
          </List>
        </div>
      </Popover>
    </div>
  );
};

export default Menu;
