export const formatData = (
  edit,
  itemType,
  data,
  rentalData,
  dataService,
  dataFreeItem
) => {
  if (itemType === "1") {
    for (let key in rentalData) {
      if (rentalData[key].value !== "") {
        if (key === "amount") {
          data[key] = parseFloat(rentalData[key].value);
        } else if (key === "fee") {
          data[key] = parseFloat(rentalData[key].value);
        } else {
          data[key] = rentalData[key].value;
        }
      }
    }
  }

  if (itemType === "2") {
    for (let key in dataService) {
      if (dataService[key].value !== "") {
        if (key === "payable") {
          data[key] = dataService[key].value === "true" ? true : false;
        } else if (key === "amount") {
          data[key] = parseFloat(dataService[key].value);
        } else if (key === "paymentMethod") {
          data[key] = parseInt(dataService[key].value, 10);
        } else if (key === "fee") {
          data[key] = parseFloat(dataService[key].value);
        } else {
          data[key] = dataService[key].value;
        }
      }
    }

    if (data.paymentMethod === 1) {
      data.tenantPercentage = parseFloat(data.tenantPay);
      data.ownerPercentage = parseFloat(data.ownerPay);

      delete data.tenantPay;
      delete data.ownerPay;
    } else {
      let a = parseFloat(data.tenantPay || "0");
      let b = parseFloat(data.ownerPay || "0");

      if (a > b) {
        data.tenantAmount = parseFloat(data.tenantPay);
      } else {
        data.ownerAmount = parseFloat(data.ownerPay);
      }

      delete data.tenantPay;
      delete data.ownerPay;
    }
  }

  if (itemType === "3") {
    for (let key in dataFreeItem) {
      if (dataFreeItem[key].value !== "") {
        if (key === "amount") {
          data[key] = parseFloat(dataFreeItem[key].value);
        } else if (key === "payable") {
          data[key] = dataFreeItem[key].value === "true" ? true : false;
        } else if (
          key === "dailyInterestPercentage" ||
          key === "increasePercentage"
        ) {
          data[key] = parseFloat(dataFreeItem[key].value);
        } else data[key] = dataFreeItem[key].value;
      }
    }

    if (edit) {
      delete data.increaseMonths;
      delete data.increasePercentage;
    }
  }

  return data;
};

export const auxDisabled = (dataService) => {
  let aux = false;

  if (dataService.paymentMethod === "1") {
    aux =
      dataService.tenantPay.value !== "" &&
      dataService.tenantPay.isValid === true &&
      dataService.ownerPay.value !== "" &&
      dataService.ownerPay.isValid === true;
  } else {
    aux = Object.entries(dataService)
      .filter((entry) => entry[0] === "tenantPay" || entry[0] === "ownerPay")
      .some((entry) => entry[1].value !== "");
  }

  return aux;
};

export const disabledHook = (
  data,
  hasChanged,
  itemType,
  expirationDate,
  monthsValue,
  dataService,
  dataFreeItem
) => {
  let obligatory =
    hasChanged &&
    expirationDate !== null &&
    (!data ? monthsValue !== "" : true);

  if (itemType === "1") {
    return obligatory ? false : true;
  }
  if (itemType === "2") {
    return obligatory &&
      dataService.service.value !== "" &&
      dataService.paymentMethod.value !== "" &&
      auxDisabled(dataService)
      ? false
      : true;
  }
  if (itemType === "3") {
    return obligatory &&
      dataFreeItem.name.value !== "" &&
      dataFreeItem.name.isValid === true
      ? false
      : true;
  }

  return true;
};
