import React, { useState } from "react";
import {
  makeStyles,
  Typography,
  Grid,
  FormControl,
  InputLabel,
  Input,
  Button,
  useTheme,
  useMediaQuery,
  Radio,
  FormControlLabel,
} from "@material-ui/core";
import { getFormatDate } from "../../hooks/date-hook";
import { Alert } from "@material-ui/lab";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    padding: theme.spacing(1),
  },
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  expendituresSection: {
    display: "flex",
    marginTop: theme.spacing(2),
    marginBottom: theme.spacing(2),
  },
  title: {
    fontSize: "14px",
  },
  expenditureClass: {
    marginTop: theme.spacing(2),
    "& .MuiFormControlLabel-root": {
      "& .MuiTypography-body1": {
        fontSize: "13px",
      },
    },
  },
  buttons: {
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
    marginTop: theme.spacing(2.5),
  },
  marginTop: {
    marginTop: theme.spacing(3.5),
  },
}));

const Details = ({ setOpen, expense, expendituresTypes }) => {
  const classes = useStyles();

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const [total] = useState(() => {
    let sum = 0;
    for (let i = 0; i < expense.expendituresTypes.length; i++) {
      sum += expense.expendituresTypes[i].amount;
    }

    return sum;
  });

  const getName = (id) => {
    let name = expendituresTypes.filter((entry) => entry._id === id)[0].name;
    return name;
  };

  return (
    <div className={classes.container}>
      <Typography variant="h6">Detalles de la expensa</Typography>
      <Grid container className={classes.grid} spacing={1}>
        <Grid item xs={12} sm={6}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Conformación</InputLabel>
            <Input
              id="date"
              value={getFormatDate(expense.date)}
              name="date"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        <Grid item xs={12} sm={6}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Vencimiento</InputLabel>
            <Input
              id="expirationDate"
              value={getFormatDate(expense.expirationDate)}
              name="expirationDate"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        <Grid item xs={12}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Título</InputLabel>
            <Input
              id="title"
              value={expense.name ? expense.name : "Titulo"}
              name="title"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        <Grid item xs={12}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">
              Interés pago fuera de termino por día
            </InputLabel>
            <Input
              id="interest"
              value={`${expense.interest}%`}
              name="interest"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>

        <Grid item xs={12} className={classes.expendituresSection}>
          <Typography className={classes.title}>Clase de gastos:</Typography>
        </Grid>
      </Grid>
      {expense.expendituresTypes.map((expenditure, index) => (
        <Alert key={index} icon={false} className={classes.expenditureClass}>
          <Grid container spacing={1}>
            <Grid
              item
              xs={12}
              style={{ display: "flex", justifyContent: "flex-start" }}
            >
              {expenditure.mode === "fixed" ? (
                <FormControlLabel
                  label="Monto fijo"
                  control={<Radio checked={true} color="primary" />}
                />
              ) : (
                <FormControlLabel
                  label="Calculo por gastos"
                  control={<Radio checked={true} color="primary" />}
                />
              )}
            </Grid>
            <Grid item xs={6}>
              <FormControl style={{ width: "100%" }}>
                <InputLabel htmlFor="my-input">Clase</InputLabel>
                <Input
                  id={`expenditure-${index}`}
                  value={getName(expenditure.expenditureType)}
                  name={`expenditure-${index}`}
                  fullWidth
                  readOnly={true}
                />
              </FormControl>
            </Grid>
            <Grid item xs={6}>
              <FormControl style={{ width: "100%" }}>
                <InputLabel htmlFor="my-input">Valor</InputLabel>
                <Input
                  id={`expenditure-amount-${index}`}
                  value={`$${expenditure.amount}`}
                  name={`expenditure-amount-${index}`}
                  fullWidth
                  readOnly={true}
                />
              </FormControl>
            </Grid>
          </Grid>
        </Alert>
      ))}
      <Grid
        container
        className={classes.buttons}
        justifycontent="center"
        spacing={1}
      >
        <Grid item xs={12}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Total</InputLabel>
            <Input
              id="totalAmount"
              value={`$${total}`}
              name="totalAmount"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            className={classes.marginTop}
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Aceptar
          </Button>
        </Grid>
      </Grid>
    </div>
  );
};

export default Details;
