import React from "react";
import {
  makeStyles,
  Typography,
  Grid,
  FormControl,
  InputLabel,
  Input,
  Button,
} from "@material-ui/core";
import SelectImage from "../Shared/SelectImage";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    padding: theme.spacing(1),
  },
  imageContainer: {
    display: "flex",
    flexDirection: "row",
    justifyContent: "space-between",
    alignItems: "flex-start",
    marginTop: theme.spacing(2),
  },
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  marginTop: {
    marginTop: theme.spacing(2.5),
  },
}));

const Details = ({ contact, setOpen }) => {
  const classes = useStyles();

  return (
    <div className={classes.container}>
      <Typography variant="h6">Detalles del contacto</Typography>
      <div className={classes.imageContainer}>
        <div style={{ marginRight: 16 }}>
          <SelectImage
            heigth={128}
            width={128}
            image={contact.image}
            backgroundSize={"150px"}
            establishment={contact.establishment}
            onlyPreview={true}
          />
        </div>
        <Grid
          container
          className={classes.grid}
          style={{ marginTop: 0 }}
          spacing={2}
        >
          <Grid item xs={12}>
            <FormControl style={{ width: "100%" }}>
              <InputLabel htmlFor="my-input">Nombre completo</InputLabel>
              <Input
                id="name"
                value={`${contact.name} ${contact.lastname}`}
                name="name"
                fullWidth
                readOnly={true}
              />
            </FormControl>
          </Grid>
          <Grid item xs={12}>
            <FormControl style={{ width: "100%" }}>
              <InputLabel htmlFor="my-input">Teléfono</InputLabel>
              <Input
                id="phone"
                value={contact.phone}
                name="phone"
                fullWidth
                readOnly={true}
              />
            </FormControl>
          </Grid>
        </Grid>
      </div>
      <Grid container className={classes.grid} spacing={2}>
        <Grid item xs={12}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Email</InputLabel>
            <Input
              id="email"
              value={contact.email}
              name="email"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        <Grid item xs={12}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">DNI</InputLabel>
            <Input
              id="dni"
              value={contact.DNI}
              name="dni"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        <Grid item xs={12}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Dirección</InputLabel>
            <Input
              id="address"
              value={contact.address}
              name="address"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        <Grid item xs={12} sm={6}>
          <Button
            className={classes.marginTop}
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Aceptar
          </Button>
        </Grid>
      </Grid>
    </div>
  );
};

export default Details;
