import React, { Fragment, useState } from "react";
import { makeStyles } from "@material-ui/core/styles";
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableRow,
  Paper,
  TableHead,
  Checkbox,
  IconButton,
} from "@material-ui/core";

import { NumberFormatCustom } from "../../hooks/format-number-hook";

import DeleteIcon from "@material-ui/icons/DeleteOutlineOutlined";
import CustomModal from "../Shared/Modal";
import DeleteRecurringDiscount from "./DeleteRecurringDiscount";

const useStyles = makeStyles((theme) => ({
  tableContainer: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    justifyContent: "space-between",
    boxShadow: "none",
    backgroundColor: "#F7F9F8",
    border: "1px solid #E6EBE8",
    borderRadius: 12,
    padding: theme.spacing(1, 1.25),
    maxHeight: 200,

    "& .Mui-checked": {
      color: "#49AC08",
    },

    "& .PrivateSwitchBase-root": {
      padding: 0,
    },

    "& .MuiTableCell-head": {
      color: "#000000",
      fontSize: "14px",
      lineHeight: "20px",
      letterSpacing: "0.02em",
      padding: theme.spacing(1),
    },

    "& .MuiTableCell-body": {
      color: "#000000",
      fontSize: "14px",
      lineHeight: "20px",
      letterSpacing: "0.02em",
      padding: theme.spacing(1),
      borderColor: "#E6EBE8",
    },
  },
}));

const RecurringDiscountsTable = ({
  amounts,
  token,
  items,
  setItems,
  dataSelecting,
  setChecked,
}) => {
  const classes = useStyles();

  const [current, setCurrent] = useState(null);
  const [open, setOpen] = useState(false);

  const onClickDelete = (entry) => {
    setCurrent(entry);
    setOpen(true);
  };

  return (
    <Fragment>
      <TableContainer className={classes.tableContainer} component={Paper}>
        <Table aria-label="simple table">
          <TableHead>
            <TableRow>
              <TableCell align="center" colSpan={4}>
                Descuentos Recurrentes
              </TableCell>
            </TableRow>
          </TableHead>
          <TableHead>
            <TableRow>
              <TableCell align="center">
                <Checkbox
                  style={{ padding: 0 }}
                  indeterminate={dataSelecting.indeterminate}
                  checked={dataSelecting.checked}
                  onChange={dataSelecting.onChange}
                />
              </TableCell>
              <TableCell align="center">Concepto</TableCell>
              <TableCell align="center">Importe</TableCell>
              <TableCell align="center">Eliminar</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {items.map((entry, index) => (
              <TableRow key={`${entry._id}`}>
                <TableCell
                  align="center"
                  component="th"
                  scope="row"
                  style={{
                    ...(index + 1 === items.length && { borderBottom: "none" }),
                  }}
                >
                  <Checkbox
                    disabled={
                      amounts.toLiquidate <= entry.amount ? true : false
                    }
                    style={{ padding: 0 }}
                    checked={entry.checked}
                    onChange={(e) => setChecked(e, entry._id)}
                  />
                </TableCell>
                <TableCell
                  align="center"
                  component="th"
                  scope="row"
                  style={{
                    ...(index + 1 === items.length && { borderBottom: "none" }),
                  }}
                >
                  {entry.concept}
                </TableCell>
                <TableCell
                  align="center"
                  component="th"
                  scope="row"
                  style={{
                    ...(index + 1 === items.length && { borderBottom: "none" }),
                  }}
                >
                  {NumberFormatCustom(entry.amount)}
                </TableCell>
                <TableCell
                  align="center"
                  component="th"
                  scope="row"
                  style={{
                    ...(index + 1 === items.length && { borderBottom: "none" }),
                  }}
                >
                  <IconButton
                    style={{
                      color: "#CA0303",
                      padding: 0,
                    }}
                    onClick={() => onClickDelete(entry._id)}
                  >
                    <DeleteIcon />
                  </IconButton>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      {current && (
        <CustomModal
          handleClose={() => {
            setOpen(false);
            setCurrent(null);
          }}
          open={open}
          component={
            <DeleteRecurringDiscount
              setOpen={setOpen}
              token={token}
              discount={current}
              setItems={setItems}
            />
          }
        />
      )}
    </Fragment>
  );
};

export default RecurringDiscountsTable;
