import React, { useState } from "react";
import { useDispatch } from "react-redux";
import { makeStyles } from "@material-ui/core";

import Form from "./Form";
import { getContacts } from "../../Redux/Action/scheduleActions";

import { editEstate } from "../../Redux/Action/estatesActions";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    padding: theme.spacing(1),
  },
}));

const EditEstate = ({ user, setOpen, contacts, current }) => {
  const classes = useStyles();
  const dispatch = useDispatch();

  const [isLoading, setIsLoading] = useState(false);

  const [hasChanged, setHasChanged] = useState(false);

  const [owners, setOwners] = useState(current.owners);

  const [percentage, setPercentage] = useState(() => {
    let sum = 0;

    for (let i = 0; i < current.owners.length; i++) {
      sum += parseFloat(owners[i].percentage);
    }

    if (sum === 100) {
      return "0";
    }

    let aux = 100 - sum;
    return aux.toString();
  });

  const [overallPercentage, setOverallPercentage] = useState(() => {
    let sum = 0;

    for (let i = 0; i < current.owners.length; i++) {
      sum += parseFloat(owners[i].percentage);
    }

    return sum;
  });

  const onClikHandler = (data) => {
    setIsLoading(true);
    dispatch(editEstate(user.token, data, current, setOpen, setIsLoading));
  };

  const reloadContacts = () => {
    setIsLoading(true);
    dispatch(getContacts(user.token, setIsLoading));
  };

  return (
    <div className={classes.container}>
      <Form
        title="Editar propiedad"
        data={current}
        contacts={contacts}
        getContacts={reloadContacts}
        setOpen={setOpen}
        isLoading={isLoading}
        percentage={percentage}
        setPercentage={setPercentage}
        overallPercentage={overallPercentage}
        setOverallPercentage={setOverallPercentage}
        owners={owners}
        setOwners={setOwners}
        onClikHandler={onClikHandler}
        hasChanged={hasChanged}
        setHasChanged={setHasChanged}
      />
    </div>
  );
};

export default EditEstate;
