import {
  GET_FUNCTIONAL_UNITS,
  ADD_FUNCTIONAL_UNIT,
  EDIT_FUNCTIONAL_UNIT,
  DELETE_FUNCTIONAL_UNIT,
} from "../Action/actionTypes";

const initialState = { functionalUnits: [] };

export const functionalUnitsReducer = (state = initialState, action) => {
  switch (action.type) {
    case GET_FUNCTIONAL_UNITS:
      return {
        ...state,
        functionalUnits: action.payload,
      };
    case ADD_FUNCTIONAL_UNIT:
      return {
        ...state,
        functionalUnits: action.payload,
      };
    case EDIT_FUNCTIONAL_UNIT:
      return {
        ...state,
        functionalUnits: action.payload,
      };
    case DELETE_FUNCTIONAL_UNIT:
      return {
        ...state,
        functionalUnits: action.payload,
      };
    default:
      return state;
  }
};

export default functionalUnitsReducer;
