import React, { useState } from "react";
import {
  Button,
  Grid,
  makeStyles,
  TextField,
  Typography,
  useMediaQuery,
  useTheme,
} from "@material-ui/core";
import Spinner from "../UI/Spinner";
import { useForm } from "../../hooks/use-form";
import SelectImage from "../Shared/SelectImage";
import { useEffect } from "react";
import axios from "axios";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    width: theme.spacing(50),
    padding: theme.spacing(5),
    "@media (max-width:650px)": {
      width: theme.spacing(30),
      padding: theme.spacing(1),
    },
    "@media (max-width:400px)": {
      width: theme.spacing(20),
      padding: 0,
    },
  },
  imageContainer: {
    display: "flex",
    flexDirection: "row",
    justifyContent: "space-between",
    alignItems: "flex-start",
    marginTop: theme.spacing(2),
  },
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  address: {
    marginBottom: theme.spacing(2.5),
  },
}));

const initialState = {
  nameContact: "",
  lastNameContact: "",
  phoneContact: "",
  emailContact: "",
  DNIContact: "",
  addressContact: "",
};

const Form = ({
  title,
  setOpen,
  isLoading,
  onClikHandler,
  data,
  setHasChanged,
  hasChanged,
}) => {
  const classes = useStyles();
  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const [form, onChangeHandler] = useForm(
    data
      ? {
          nameContact: data.name,
          lastNameContact: data.lastname,
          phoneContact: data.phone,
          emailContact: data.email,
          DNIContact: data.DNI,
          addressContact: data.address,
        }
      : initialState
  );

  const [image, setImage] = useState(null);

  const onChangeData = () => {
    if (setHasChanged && hasChanged === false) {
      setHasChanged(true);
    }
  };

  const onImageChangeHandler = (e) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      if (
        file.type === "image/jpeg" ||
        file.type === "image/jpg" ||
        file.type === "image/png"
      ) {
        setImage(file);
      }
    }
    onChangeData();
  };

  const deleteImageHandler = () => {
    setImage(null);
    onChangeData();
  };

  const sendFormData = () => {
    let formData = {
      image: image,
      name: form.nameContact.value,
      lastname: form.lastNameContact.value,
      phone: form.phoneContact.value,
      email: form.emailContact.value,
      DNI: form.DNIContact.value,
      address: form.addressContact.value,
    };

    onClikHandler(formData);
  };

  let disabled =
    hasChanged &&
    Object.entries(form).filter(
      (entry) => entry[1].value === "" || entry[1].isValid === false
    ).length === 0
      ? false
      : true;

  useEffect(() => {
    let isMounted = true;
    if (isMounted && data && data.image) {
      (async () => {
        const res = await axios.get(
          `${process.env.REACT_APP_BACKEND_URL}/files/${data.establishment}/${data.image}`,
          {
            responseType: "blob",
            headers: { "Access-Control-Allow-Origin": "*" },
          }
        );

        setImage(res.data);
      })();
    }
    return () => {
      isMounted = false;
    };
  }, [data]);

  return isLoading ? (
    <Spinner height={508} />
  ) : (
    <div>
      <Typography variant="h6">{title}</Typography>

      <div className={classes.imageContainer}>
        <div style={{ marginRight: 16 }}>
          <SelectImage
            heigth={128}
            width={128}
            image={image}
            setImage={onImageChangeHandler}
            deleteImage={deleteImageHandler}
            backgroundSize={"150px"}
            textImage="Seleccione una imagen"
          />
        </div>
        <Grid
          container
          className={classes.grid}
          style={{ marginTop: 0 }}
          spacing={2}
        >
          <Grid item xs={12}>
            <TextField
              value={form.nameContact.value}
              required
              autoComplete="off"
              fullWidth
              id="nameContact"
              name="name"
              label="Nombre"
              inputProps={{
                minLength: 2,
                maxLength: 100,
                pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
              }}
              onChange={(e) => {
                onChangeHandler(e);
                onChangeData();
              }}
              error={!form.nameContact.isValid}
              helperText={
                !form.nameContact.isValid &&
                (form.nameContact.value.length < 2
                  ? "Pocos caracteres"
                  : "Nombre inválido")
              }
              InputLabelProps={{ required: false }}
            />
          </Grid>
          <Grid item xs={12}>
            <TextField
              value={form.lastNameContact.value}
              required
              autoComplete="off"
              fullWidth
              id="lastNameContact"
              name="lastname"
              label="Apellido"
              inputProps={{
                minLength: 2,
                maxLength: 100,
                pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
              }}
              onChange={(e) => {
                onChangeHandler(e);
                onChangeData();
              }}
              error={!form.lastNameContact.isValid}
              helperText={
                !form.lastNameContact.isValid &&
                (form.lastNameContact.value.length < 2
                  ? "Pocos caracteres"
                  : "Apellido inválido")
              }
              InputLabelProps={{ required: false }}
            />
          </Grid>
        </Grid>
      </div>
      <Grid container className={classes.grid} spacing={2}>
        <Grid item xs={12}>
          <TextField
            value={form.phoneContact.value}
            required
            type="tel"
            autoComplete="off"
            fullWidth
            name="phone"
            id="phoneContact"
            label="Teléfono"
            inputProps={{
              maxLength: 20,
              pattern: "^[0-9()-+ -]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.phoneContact.isValid}
            helperText={!form.phoneContact.isValid && "Teléfono inválido"}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            value={form.emailContact.value}
            id="emailContact"
            required
            type="email"
            autoComplete="off"
            fullWidth
            name="email"
            label="Email"
            inputProps={{
              maxLength: 256,
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.emailContact.isValid}
            helperText={!form.emailContact.isValid && "Email inválido"}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            type="number"
            value={form.DNIContact.value}
            required
            autoComplete="off"
            fullWidth
            name="identificationDocument 
            "
            id="DNIContact"
            label="DNI"
            inputProps={{
              min: "1000000",
              max: "99999999",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.DNIContact.isValid}
            helperText={
              !form.DNIContact.isValid &&
              (form.DNIContact.value.length < 7
                ? "Minimo 7 caracteres"
                : "DNI inválido")
            }
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            className={classes.address}
            value={form.addressContact.value}
            required
            autoComplete="off"
            fullWidth
            name="address"
            id="addressContact"
            label="Dirección"
            inputProps={{
              minLength: 2,
              maxLength: 100,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ . -]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.addressContact.isValid}
            helperText={
              !form.addressContact.isValid &&
              (form.addressContact.value.length < 2
                ? "Pocos caracteres"
                : "Dirección inválida")
            }
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            id="cancel-button"
            variant="outlined"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Cancelar
          </Button>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            disabled={disabled}
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={sendFormData}
          >
            Aceptar
          </Button>
        </Grid>
      </Grid>
    </div>
  );
};

export default Form;
