import React, { Fragment, useState } from "react";
import {
  Button,
  Grid,
  makeStyles,
  MenuItem,
  TextField,
} from "@material-ui/core";
import NumberFormat from "react-number-format";

import { ExpandMore } from "@material-ui/icons";
import { paymentMethods } from "../../../configs/contracts/items/PAYMENT_METHODS";
import DatePicker from "../../Shared/DatePicker";
import { useSelector } from "react-redux";

const useStyles = makeStyles((theme) => ({
  addButton: {
    backgroundColor: "#49AC08",
    color: "#FAFAFA",
    textTransform: "capitalize",
    fontSize: 12,
    "&:hover": {
      backgroundColor: "#49ac089e",
    },
  },
}));

function NumberFormatCustom(props) {
  const { min, id, inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
            id: id,
            validity: {
              valid: parseFloat(values.value, 10) > parseFloat(min, 10),
            },
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={2}
      isNumericString
      prefix="$"
    />
  );
}

const PaymentMethod = ({
  isMobile,
  data,
  setData,
  setForm,
  addPayment,
  amounts,
}) => {
  const classes = useStyles();

  const [type, setType] = useState("1");

  const banks = useSelector((state) => state.banks.banks);

  const onChangeType = (e) => {
    setType(e.target.value);
    setForm((data) => {
      let copy = { ...data };
      for (let key in data) {
        copy[key] = {
          value:
            key === "expirationDate" || key === "date"
              ? null
              : key === "amount"
              ? amounts.remainsToPay
              : "",
          isValid: true,
        };
      }
      return copy;
    });
  };

  const handleDateChange = (date) => {
    let formatDate = date.toISOString();

    setData({
      target: {
        id: parseInt(type, 10) === 2 ? "expirationDate" : "date",
        value: formatDate,
      },
    });
  };

  const onClick = () => {
    let aux = { paymentType: parseInt(type) };

    for (let key in data) {
      if (data[key].value !== "" && data[key].value !== null) {
        if (key === "amount") {
          aux[key] = parseFloat(data[key].value);
        } else {
          aux[key] = data[key].value;
        }
      }
    }

    setForm((data) => {
      let copy = { ...data };
      for (let key in data) {
        copy[key] = {
          value: key === "expirationDate" || key === "date" ? null : "",
          isValid: true,
        };
      }
      return copy;
    });

    addPayment(aux);
  };

  let disabled = {
    1: data.amount.value !== "" && data.amount.isValid === true ? false : true,
    2:
      data.bank.value !== "" &&
      data.amount.value !== "" &&
      data.amount.isValid === true &&
      data.number.value !== "" &&
      data.number.isValid === true &&
      data.expirationDate.value !== null
        ? false
        : true,
    3:
      data.bank.value !== "" &&
      data.amount.value !== "" &&
      data.amount.isValid === true &&
      data.number.value !== "" &&
      data.number.isValid === true &&
      data.date.value !== null
        ? false
        : true,
  };

  return (
    <Fragment>
      <Grid item xs={isMobile ? 6 : 4}>
        <TextField
          label="Forma de pago"
          id="type"
          value={type}
          onChange={onChangeType}
          select
          SelectProps={{
            IconComponent: ExpandMore,
          }}
          fullWidth
        >
          {Object.entries(paymentMethods).map((entry, index) => (
            <MenuItem key={`select-${entry[0]}-${index}`} value={entry[0]}>
              {entry[1]}
            </MenuItem>
          ))}
        </TextField>
      </Grid>

      {parseInt(type, 10) > 1 && (
        <Grid item xs={isMobile ? 6 : 4}>
          <TextField
            id="bank"
            name="bank"
            label="Banco"
            value={data.bank.value}
            onChange={(e) => {
              e.target.id = "bank";
              setData(e);
            }}
            select
            SelectProps={{
              IconComponent: ExpandMore,
            }}
            fullWidth
          >
            <MenuItem value=""></MenuItem>
            {banks.map((entry, index) => (
              <MenuItem key={`select-${entry._id}`} value={entry._id}>
                {entry.name}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
      )}

      {parseInt(type, 10) > 1 && (
        <Grid item xs={isMobile ? 6 : 4}>
          <TextField
            type="number"
            required
            autoComplete="off"
            label={type === "2" ? "Cheque número" : "Referencia número"}
            id="number"
            name="number"
            value={data.number.value}
            onChange={setData}
            fullWidth
            inputProps={{
              min: "0",
              pattern: "[0-9.]+",
            }}
            error={!data.number.isValid}
            InputLabelProps={{ required: false }}
          />
        </Grid>
      )}

      {parseInt(type, 10) > 1 && (
        <Grid item xs={isMobile ? 6 : 4}>
          <DatePicker
            label={type === "2" ? "Vencimiento" : "Fecha"}
            selectedDate={
              parseInt(type, 10) === 2
                ? data.expirationDate.value
                : data.date.value
            }
            handleDateChange={(e) => handleDateChange(e)}
          />
        </Grid>
      )}

      <Grid item xs={isMobile ? 6 : 4}>
        <TextField
          InputProps={{
            inputComponent: NumberFormatCustom,
          }}
          required
          autoComplete="off"
          label="Importe"
          id="amount"
          name="amount"
          value={data.amount.value}
          onChange={(e) => {
            let value = parseFloat(e.target.value);
            if (
              data.amount.value === "" &&
              data.amount.isValid === true &&
              isNaN(value) &&
              amounts.remainsToPay === 0
            ) {
              e.target.validity.valid = true;
            }

            setData(e);
          }}
          fullWidth
          inputProps={{
            min: "0",
            pattern: "[0-9.]+",
            step: ".01",
          }}
          error={!data.amount.isValid}
          InputLabelProps={{ required: false }}
        />
      </Grid>

      <Grid
        item
        xs={isMobile ? 12 : 4}
        style={{ display: "flex", alignItems: "end" }}
      >
        <Button
          disabled={disabled[type]}
          fullWidth
          disableElevation
          variant="contained"
          className={classes.addButton}
          onClick={onClick}
        >
          Agregar pago
        </Button>
      </Grid>
    </Fragment>
  );
};

export default PaymentMethod;
