import React, { useState } from "react";
import {
  makeStyles,
  Typography,
  Grid,
  FormControl,
  InputLabel,
  Input,
  Button,
} from "@material-ui/core";
import ListExpenditures from "./ListExpenditures";
import { Fragment } from "react";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    padding: theme.spacing(1),
  },
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  marginTop: {
    marginTop: theme.spacing(2.5),
  },
  expendituresSection: {
    display: "flex",
    marginTop: theme.spacing(2),
    marginBottom: theme.spacing(2),
  },
  title: {
    fontSize: "14px",
  },
}));

const Details = ({ setOpen, functionalUnit, expendituresTypes }) => {
  const classes = useStyles();

  const [expenditures] = useState(() => {
    let obj = functionalUnit.expendituresTypesPercentages.reduce(
      (obj, expenditure) => {
        return [
          ...obj,
          ...(expenditure.expenditureType
            ? [
                {
                  expenditureType: expenditure.expenditureType._id,
                  percentage: expenditure.percentage,
                },
              ]
            : []),
        ];
      },
      []
    );

    return obj;
  });

  return (
    <div className={classes.container}>
      <Typography variant="h6">Detalles de unidad funcional</Typography>
      <Grid container className={classes.grid} spacing={1}>
        <Grid item xs={12} sm={6}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Unidad Funcional</InputLabel>
            <Input
              id="number"
              value={functionalUnit.number}
              name="number"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        <Grid item xs={12} sm={6}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Propietario</InputLabel>
            <Input
              id="owner"
              value={
                functionalUnit.owner.name + " " + functionalUnit.owner.lastname
              }
              name="owner"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        <Grid item xs={12} sm={6}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Centavos ID</InputLabel>
            <Input
              id="centId"
              value={functionalUnit.centId || ""}
              name="centId"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        <Grid item xs={12} sm={6}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Piso y Letra</InputLabel>
            <Input
              id="apartment"
              value={functionalUnit.apartment}
              name="apartment"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        <Grid item xs={12}>
          {functionalUnit.expendituresTypesPercentages.length > 0 && (
            <Fragment>
              <Grid item xs={12} className={classes.expendituresSection}>
                <Typography className={classes.title}>
                  Clase de gastos:
                </Typography>
              </Grid>
              <ListExpenditures
                expenditures={expenditures}
                expendituresTypes={expendituresTypes}
              />
            </Fragment>
          )}
        </Grid>
        <Grid item xs={12} sm={6}>
          <Button
            className={classes.marginTop}
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Aceptar
          </Button>
        </Grid>
      </Grid>
    </div>
  );
};

export default Details;
