import React, { useState } from "react";
import { useDispatch } from "react-redux";

import Form from "./Form";

import { editService } from "../../Redux/Action/servicesActions";

const EditService = ({ user, setOpen, current }) => {
  const dispatch = useDispatch();

  const [isLoading, setIsLoading] = useState(false);
  const [hasChanged, setHasChanged] = useState(false);

  const onClikHandler = (data) => {
    setIsLoading(true);
    dispatch(editService(user.token, data, current, setOpen, setIsLoading));
  };

  return (
    <Form
      data={current}
      title="Editar impuesto/servicio"
      setOpen={setOpen}
      isLoading={isLoading}
      onClikHandler={onClikHandler}
      hasChanged={hasChanged}
      setHasChanged={setHasChanged}
    />
  );
};

export default EditService;
