import React, { useState } from "react";
import { useDispatch } from "react-redux";
import {
  makeStyles,
  useMediaQuery,
  useTheme,
  Grid,
  Typography,
  Button,
} from "@material-ui/core";
import Spinner from "../UI/Spinner";
import { deleteConsortium } from "../../Redux/Action/consortiumsActions";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    padding: theme.spacing(1),
  },
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  question: {
    marginBottom: theme.spacing(2.5),
  },
}));

const DeleteConsortium = ({ token, setOpen, consortium }) => {
  const classes = useStyles();
  const dispatch = useDispatch();

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const [isLoading, setIsLoading] = useState(false);

  const onClickHandler = () => {
    setIsLoading(true);
    dispatch(deleteConsortium(token, consortium._id, setOpen, setIsLoading));
  };

  return isLoading ? (
    <Spinner height={204} />
  ) : (
    <div className={classes.container}>
      <Typography variant="h6">Eliminar consorcio</Typography>
      <Grid container className={classes.grid} spacing={1}>
        <Grid item xs={12}>
          <Typography className={classes.question}>
            ¿Seguro que quiere continuar?
          </Typography>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            id="cancel-button"
            variant="outlined"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Cancelar
          </Button>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={onClickHandler}
          >
            Aceptar
          </Button>
        </Grid>
      </Grid>
    </div>
  );
};

export default DeleteConsortium;
