import axios from "axios";
import {
  GET_ESTATES,
  ADD_ESTATE,
  EDIT_ESTATE,
  DELETE_ESTATE,
} from "../Action/actionTypes";

import { setSnackData } from "./snackDataActions";

axios.defaults.withCredentials = true;

export const getEstates = (token, setIsLoading) => (dispatch) => {
  axios
    .get(`${process.env.REACT_APP_BACKEND_URL}/rentals/properties`, {
      headers: {
        Authorization: "Bearer " + token,
      },
    })
    .then((res) => {
      dispatch({
        type: GET_ESTATES,
        payload: res.data,
      });

      if (setIsLoading) setIsLoading(false);
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }

      if (setIsLoading) setIsLoading(false);
    });
};

export const addEstate =
  (token, data, setOpen, setIsLoading, preload) => (dispatch, getState) => {
    let aux = getState().estates.estates;
    let estates = Array.from(aux);

    let copyData = JSON.parse(JSON.stringify(data));

    copyData.image = data.image;

    for (let i = 0; i < copyData.owners.length; i++) {
      copyData.owners[i].owner = copyData.owners[i].owner._id;
    }

    const formData = new FormData();

    for (let key in copyData) {
      if (key === "owners") {
        formData.append(key, JSON.stringify(copyData[key]));
      } else {
        formData.append(key, copyData[key]);
      }
    }

    axios
      .post(
        `${process.env.REACT_APP_BACKEND_URL}/rentals/properties`,
        formData,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        data.image = res.data.image;
        data._id = res.data._id;

        estates.push(data);

        dispatch({
          type: ADD_ESTATE,
          payload: estates,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Propiedad creada",
            severity: "success",
          })
        );

        if (preload) preload(res.data._id);
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };

export const editEstate =
  (token, data, current, setOpen, setIsLoading) => (dispatch, getState) => {
    let aux = getState().estates.estates;
    let estates = Array.from(aux);

    let copyData = JSON.parse(JSON.stringify(data));

    copyData.image = data.image;

    for (let i = 0; i < copyData.owners.length; i++) {
      copyData.owners[i].owner = copyData.owners[i].owner._id;
    }

    const formData = new FormData();

    for (let key in copyData) {
      if (key === "owners") {
        formData.append(key, JSON.stringify(copyData[key]));
      } else {
        formData.append(key, copyData[key]);
      }
    }

    axios
      .put(
        `${process.env.REACT_APP_BACKEND_URL}/rentals/properties/${current._id}`,
        formData,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        if (res.data.image) data.image = res.data.image;

        let i = estates.findIndex((estate) => {
          if (estate._id === current._id) {
            return true;
          }
          return false;
        });

        if (i !== -1) {
          estates[i] = Object.assign(estates[i], data);
        }

        dispatch({
          type: EDIT_ESTATE,
          payload: estates,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Propiedad editada",
            severity: "success",
          })
        );

        setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };

export const deleteEstate =
  (token, id, setOpen, setIsLoading) => (dispatch, getState) => {
    let aux = getState().estates.estates;
    let estates = Array.from(aux);

    axios
      .delete(`${process.env.REACT_APP_BACKEND_URL}/rentals/properties/${id}`, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((_) => {
        let i = estates.findIndex((estate) => {
          if (estate._id === id) {
            return true;
          }
          return false;
        });

        i !== -1 && estates.splice(i, 1);

        dispatch({
          type: DELETE_ESTATE,
          payload: estates,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Propiedad eliminada",
            severity: "success",
          })
        );

        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };
