import React, { useState } from "react";
import Button from "@material-ui/core/Button";
import Link from "@material-ui/core/Link";
import Grid from "@material-ui/core/Grid";
import { makeStyles } from "@material-ui/core/styles";
import { Link as RRLink, useHistory } from "react-router-dom";

import UserInputs from "./UserInputs";
import EstablishmentFormControls from "./EstablishmentFormControls";
import EstablishmentInputs from "./EstablishmentInputs";
import EstablishmentIdInput from "./EstablishmentIdInput";
import { useForm } from "../../hooks/use-form";
import Spinner from "../UI/Spinner";
import { useDispatch } from "react-redux";
import { createUser } from "../../Redux/Action/userActions";

const useStyles = makeStyles((theme) => ({
  form: {
    width: "100%", // Fix IE 11 issue.
    marginTop: theme.spacing(3),
  },
  submit: {
    margin: theme.spacing(3, 0, 2),
  },
}));

export default function SignupForm() {
  const classes = useStyles();
  const dispatch = useDispatch();
  const history = useHistory();
  const [userForm, onUserFormChangeHandler] = useForm({
    name: "",
    lastname: "",
    email: "",
    password: "",
  });

  const [establishmentDataForm, onEstablishmentDataFormChangeHandler] =
    useState({
      type: "consortium",
      exists: "false",
    });

  const [establishmentIdForm, onEstablishmentIdFormChangeHandler] = useForm({
    id: "",
  });

  const [establishmentForm, onEstablishmentFormChangeHandler] = useForm({
    establishmentName: "",
    establishmentAddress: "",
    establishmentPhone: "",
    establishmentEmail: "",
  });

  const [isLoading, setIsLoading] = React.useState(false);

  const navigate = () => {
    history.replace("/");
  };

  const submitHandler = async (e) => {
    e.preventDefault();
    const user = {
      name: userForm.name.value,
      lastname: userForm.lastname.value,
      email: userForm.email.value,
      password: userForm.password.value,
    };
    const establishment = { ...establishmentDataForm };
    establishment.data =
      establishment.exists === "false"
        ? {
            name: establishmentForm.establishmentName.value,
            address: establishmentForm.establishmentAddress.value,
            phone: establishmentForm.establishmentPhone.value,
            email: establishmentForm.establishmentEmail.value,
          }
        : { id: establishmentIdForm.id.value };
    const data = {
      ...user,
      establishment,
    };
    try {
      setIsLoading(true);
      dispatch(createUser(data, setIsLoading, navigate));
    } catch (err) {
      setIsLoading(false);
    }
  };

  return !isLoading ? (
    <form className={classes.form} onSubmit={submitHandler}>
      <Grid container spacing={2}>
        <UserInputs form={userForm} onChangeHandler={onUserFormChangeHandler} />
        <EstablishmentFormControls
          form={establishmentDataForm}
          onChangeHandler={onEstablishmentDataFormChangeHandler}
        />
        {establishmentDataForm.exists === "false" ? (
          <EstablishmentInputs
            form={establishmentForm}
            onChangeHandler={onEstablishmentFormChangeHandler}
          />
        ) : (
          <EstablishmentIdInput
            form={establishmentIdForm}
            onChangeHandler={onEstablishmentIdFormChangeHandler}
          />
        )}
      </Grid>
      <Button
        type="submit"
        fullWidth
        variant="contained"
        color="primary"
        className={classes.submit}
      >
        Registrarse
      </Button>
      <Grid container justifycontent="flex-end">
        <Grid item>
          <Link variant="body2" component={RRLink} to="/">
            Ya tenés cuenta? Ingresá
          </Link>
        </Grid>
      </Grid>
    </form>
  ) : (
    <Spinner />
  );
}
