import { createStore, combineReducers, compose, applyMiddleware } from "redux";
import thunk from "redux-thunk";

import userReducer from "../Reducer/userReducer";
import consortiumsReducer from "../Reducer/consortiumsReducer";
import functionalUnitsReducer from "../Reducer/functionalUnitsReducer";
import scheduleReducer from "../Reducer/scheduleReducer";
import expendituresTypesReducer from "../Reducer/expendituresTypesReducer";
import expendituresReducer from "../Reducer/expendituresReducer";
import categoriesReducer from "../Reducer/categoriesReducer";
import subcategoriesReducer from "../Reducer/subcategoriesReducer";
import providersReducer from "../Reducer/providersReducer";
import expensesReducer from "../Reducer/expensesReducer";
import transactionsReducer from "../Reducer/transactionsReducer";
import boxesReducer from "../Reducer/boxesReducer";
import paymentsReducer from "../Reducer/paymentsReducer";
import snackDataReducer from "../Reducer/snackDataReducer";
import emailServerReducer from "../Reducer/emailServerReducer";
import establishmentReducer from "../Reducer/establishmentReducer";
import estatesReducer from "../Reducer/estatesReducer";
import servicesReducer from "../Reducer/servicesReducer";
import contractsReducer from "../Reducer/contractsReducer";
import banksReducer from "../Reducer/banksReducer";
import liquidationsReducer from "../Reducer/liquidationsReducer";

const composeEnhancer = window.__REDUX_DEVTOOLS_EXTENSION_COMPOSE__ || compose;

const store = createStore(
  combineReducers({
    user: userReducer,
    consortiums: consortiumsReducer,
    estates: estatesReducer,
    services: servicesReducer,
    banks: banksReducer,
    functionalunits: functionalUnitsReducer,
    contacts: scheduleReducer,
    expendituresTypes: expendituresTypesReducer,
    expenditures: expendituresReducer,
    categories: categoriesReducer,
    subcategories: subcategoriesReducer,
    providers: providersReducer,
    expenses: expensesReducer,
    transactions: transactionsReducer,
    boxes: boxesReducer,
    payments: paymentsReducer,
    emailServer: emailServerReducer,
    establishment: establishmentReducer,
    snackData: snackDataReducer,
    contracts: contractsReducer,
    liquidations: liquidationsReducer,
  }),
  composeEnhancer(applyMiddleware(thunk))
);
export default store;
