import axios from "axios";
import {
  GET_SUBCATEGORIES,
  ADD_SUBCATEGORY,
  EDIT_SUBCATEGORY,
  DELETE_SUBCATEGORY,
} from "./actionTypes";

import { setSnackData } from "./snackDataActions";

export const getSubcategories = (id, token, setIsLoading) => (dispatch) => {
  axios
    .get(
      `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/subcategories`,
      {
        headers: {
          Authorization: "Bearer " + token,
        },
      }
    )
    .then((res) => {
      const subcategories = res.data.sort((a, b) =>
        a.name.localeCompare(b.name)
      );
      
      dispatch({
        type: GET_SUBCATEGORIES,
        payload: subcategories,
      });
      if (setIsLoading) setIsLoading(false);
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }
      if (setIsLoading) setIsLoading(false);
    });
};

export const addSubcategory =
  (id, token, data, setOpen, setIsLoading) => (dispatch, getState) => {
    let subcategories = getState().subcategories.subcategories;
    let categories = getState().categories.categories;

    let i = categories.findIndex((category) => {
      if (category._id === data.category) {
        return true;
      }
      return false;
    });

    axios
      .post(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/subcategories`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        let data = res.data;
        data.category = categories[i];

        subcategories.push(data);

        dispatch({
          type: ADD_SUBCATEGORY,
          payload: subcategories,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Subcategoría creada",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const editSubcategory =
  (id, token, idSub, data, current, setOpen, setIsLoading) =>
  (dispatch, getState) => {
    let subcategories = getState().subcategories.subcategories;
    let categories = getState().categories.categories;

    let categoryIndex = categories.findIndex((category) => {
      if (category._id === data.category) {
        return true;
      }
      return false;
    });

    axios
      .put(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/subcategories/${idSub}`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        let subcategoryIndex = subcategories.findIndex((subcategory) => {
          if (subcategory._id === idSub) {
            return true;
          }
          return false;
        });

        current.name = data.name;
        current.category = categories[categoryIndex];
        current.isRecurrent = data.isRecurrent;

        if (subcategoryIndex !== -1) {
          subcategories[subcategoryIndex] = Object.assign(
            subcategories[subcategoryIndex],
            current
          );
        }

        dispatch({
          type: EDIT_SUBCATEGORY,
          payload: subcategories,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Subcategoría editada",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const deleteSubcategory =
  (id, token, idSub, setOpen, setIsLoading) => (dispatch, getState) => {
    let subcategories = getState().subcategories.subcategories;
    axios
      .delete(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/subcategories/${idSub}`,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        let i = subcategories.findIndex((subcategory) => {
          if (subcategory._id === idSub) {
            return true;
          }
          return false;
        });

        i !== -1 && subcategories.splice(i, 1);

        dispatch({
          type: DELETE_SUBCATEGORY,
          payload: subcategories,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Subcategoría eliminada",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };
