import React, { Fragment, useState } from "react";
import { Grid, MenuItem, TextField } from "@material-ui/core";

import { ExpandMore } from "@material-ui/icons";
import FreeItemForm from "./FreeItemForm";
import TaxOrServiceForm from "./TaxOrServiceForm";
import { useSelector } from "react-redux";
import { useForm } from "../../../hooks/use-form";
import { typesOrTaxes } from "../../../configs/contracts/taxes/TYPES_OR_TAXES";

const TaxesAndOthers = ({ addTax, isMobile }) => {
  const [type, setType] = useState("0");

  const services = useSelector((state) => state.services.services);

  const [dataFreeItem, setDataFreeItem, setFormFreeItem] = useForm({
    name: "",
    amount: "",
    increaseMonths: "",
    increasePercentage: "",
    monthlyFeePercentage: "",
    expirationDay: "",
    dailyInterestPercentage: "",
    payable: "true",
  });

  const [dataService, setDataService, setFormService] = useForm({
    service: "",
    amount: "",
    paymentMethod: "1",
    tenantPay: "100",
    ownerPay: "0",
    monthlyFeePercentage: "",
    expirationDay: "",
    payable: "true",
  });

  const onChange = (e) => {
    setType(e);

    if (e === "0") {
      setFormService((dataService) => {
        let copy = { ...dataService };
        for (let key in dataService) {
          copy[key] = {
            value:
              key === "paymentMethod"
                ? "1"
                : key === "tenantPay"
                ? "100"
                : key === "ownerPay"
                ? "0"
                : key === "payable"
                ? "true"
                : "",
            isValid: true,
          };
        }
        return copy;
      });
    } else {
      setFormFreeItem((dataFreeItem) => {
        let copy = { ...dataFreeItem };
        for (let key in dataFreeItem) {
          copy[key] = { value: key === "payable" ? "true" : "", isValid: true };
        }
        return copy;
      });
    }
  };

  const addTaxAndResetForm = () => {
    let data = {};

    if (type === "0") {
      for (let key in dataFreeItem) {
        if (dataFreeItem[key].value !== "") {
          if (key === "payable") {
            data[key] = dataFreeItem[key].value === "true" ? true : false;
          } else if (key === "dailyInterestPercentage") {
            data[key] = parseFloat(dataFreeItem[key].value);
          } else {
            data[key] = dataFreeItem[key].value;
          }
        }
      }

      setFormFreeItem((dataFreeItem) => {
        let copy = { ...dataFreeItem };
        for (let key in copy) {
          if (copy[key].value !== "")
            copy[key] = {
              value: key === "payable" ? "true" : "",
              isValid: true,
            };
        }
        return copy;
      });
    } else {
      for (let key in dataService) {
        if (dataService[key].value !== "") {
          if (key === "payable") {
            data[key] = dataService[key].value === "true" ? true : false;
          } else if (key === "service") {
            let aux = services.filter(
              (entry) => entry._id === dataService[key].value
            );
            data[key] = aux[0];
          } else if (key === "paymentMethod") {
            data[key] = parseInt(dataService[key].value, 10);
          } else {
            data[key] = dataService[key].value;
          }
        }
      }

      if (data.paymentMethod === 1) {
        data.tenantPercentage = parseFloat(data.tenantPay);
        data.ownerPercentage = parseFloat(data.ownerPay);

        delete data.tenantPay;
        delete data.ownerPay;
      } else {
        let a = parseFloat(data.tenantPay || "0");
        let b = parseFloat(data.ownerPay || "0");

        if (a > b) {
          data.tenantAmount = parseFloat(data.tenantPay);
        } else {
          data.ownerAmount = parseFloat(data.ownerPay);
        }

        delete data.tenantPay;
        delete data.ownerPay;
      }

      setFormService((dataService) => {
        let copy = { ...dataService };
        for (let key in copy) {
          if (copy[key].value !== "")
            copy[key] = {
              value:
                key === "paymentMethod"
                  ? "1"
                  : key === "tenantPay"
                  ? "100"
                  : key === "ownerPay"
                  ? "0"
                  : key === "payable"
                  ? "true"
                  : "",
              isValid: true,
            };
        }
        return copy;
      });
    }

    addTax(data, type);
  };

  return (
    <Fragment>
      <Grid item xs={isMobile ? 6 : 3}>
        <TextField
          label="Tipo"
          id="type"
          value={type}
          onChange={(e) => {
            onChange(e.target.value);
          }}
          select
          SelectProps={{
            IconComponent: ExpandMore,
          }}
          fullWidth
        >
          <MenuItem value=""></MenuItem>
          {Object.entries(typesOrTaxes).map((entry, index) => (
            <MenuItem key={`select-${entry[0]}-${index}`} value={entry[0]}>
              {entry[1]}
            </MenuItem>
          ))}
        </TextField>
      </Grid>

      {type === "0" && (
        <FreeItemForm
          data={dataFreeItem}
          setData={setDataFreeItem}
          isMobile={isMobile}
          onClick={addTaxAndResetForm}
        />
      )}

      {type === "1" && (
        <TaxOrServiceForm
          services={services}
          data={dataService}
          setData={setDataService}
          setForm={setFormService}
          isMobile={isMobile}
          onClick={addTaxAndResetForm}
        />
      )}
    </Fragment>
  );
};

export default TaxesAndOthers;
