import {
  GET_DATA_ESTABLISHMENT,
  EDIT_DATA_ESTABLISHMENT,
} from "../Action/actionTypes";

const initialState = { establishment: {} };

export const establishmentReducer = (state = initialState, action) => {
  switch (action.type) {
    case GET_DATA_ESTABLISHMENT:
      return {
        ...state,
        establishment: action.payload,
      };
    case EDIT_DATA_ESTABLISHMENT:
      return {
        ...state,
        establishment: action.payload,
      };
    default:
      return state;
  }
};

export default establishmentReducer;
