import React, { useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { makeStyles } from "@material-ui/core";
import Form from "./Form";
import { addConsortium } from "../../Redux/Action/consortiumsActions";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    padding: theme.spacing(1),
  },
}));

const AddConsortium = ({ setOpen }) => {
  const classes = useStyles();
  const dispatch = useDispatch();
  const user = useSelector((state) => state.user.userData);

  const [isLoading, setIsLoading] = useState(false);

  const postConsortium = (data) => {
    setIsLoading(true);
    dispatch(addConsortium(user.token, data, setOpen, setIsLoading));
  };

  return (
    <div className={classes.container}>
      <Form
        title="Nuevo consorcio"
        setOpen={setOpen}
        isLoading={isLoading}
        onClikHandler={postConsortium}
        hasChanged={true}
      />
    </div>
  );
};

export default AddConsortium;
