import React, { useState, useEffect } from "react";
import TableSort from "../Shared/TableSort";
import Modal from "../Shared/Modal";
import Spinner from "../UI/Spinner";
import DeleteExpenditure from "./DeleteExpenditure";
import EditExpenditure from "./EditExpenditure";
import DetailsExpenditure from "./Details";
import { getFormatDate } from "../../hooks/date-hook";
import { TableCell } from "@material-ui/core";
import { useDispatch, useSelector } from "react-redux";
import { getExpenditures } from "../../Redux/Action/expendituresActions";
import { getCategories } from "../../Redux/Action/categoriesActions";
import { getExpenses } from "../../Redux/Action/expensesActions";

import Graphics from "./Graphics";

const List = ({
  establishment,
  id,
  user,
  isLoadingComponent,
  setIsLoadingComponent,
  expendituresTypes,
}) => {
  const dispatch = useDispatch();
  const [open, setOpen] = useState(false);
  const [current, setCurrent] = useState(null);
  const [action, setAction] = useState();

  const categories = useSelector((state) => state.categories.categories);
  const boxes = useSelector((state) => state.boxes.boxes);
  const expenditures = useSelector((state) => state.expenditures.expenditures);
  const expenses = useSelector((state) => state.expenses.expenses).sort(
    (a, b) => {
      let dateA = new Date(a.date);
      let dateB = new Date(b.date);

      if (dateA.getTime() < dateB.getTime()) {
        return -1;
      }
      if (dateA.getTime() > dateB.getTime()) {
        return 1;
      }

      return 0;
    }
  );

  const createData = () => {
    let aux = [];
    for (let i = 0; i < expenditures.length; i++) {
      aux.push({
        _id: expenditures[i]._id,
        amount: expenditures[i].amount.amount,
        category: expenditures[i].category.name,
        subcategory: expenditures[i].subcategory
          ? expenditures[i].subcategory.name
          : "",
        provider: expenditures[i].provider.name,
        expirationDate: getFormatDate(expenditures[i].expirationDate),
      });
    }

    return aux;
  };

  const columns = [
    { id: "amount", label: "Monto" },
    { id: "category", label: "Categoria" },
    { id: "subcategory", label: "Subcategoria" },
    { id: "provider", label: "Proveedor" },
    { id: "expirationDate", label: "Fecha" },
    { id: "details", label: "Detalles" },
    ...(user.isAdmin
      ? [
          { id: "edit", label: "Editar" },
          { id: "delete", label: "Eliminar" },
        ]
      : []),
  ];

  const rows = createData();

  const Cells = ({ row }) => {
    return (
      <>
        <TableCell component="th" scope="row">
          {`$${row.amount}`}
        </TableCell>
        <TableCell component="th" scope="row">
          {row.category}
        </TableCell>
        <TableCell component="th" scope="row">
          {row.subcategory}
        </TableCell>
        <TableCell component="th" scope="row">
          {row.provider}
        </TableCell>
        <TableCell component="th" scope="row">
          {row.expirationDate}
        </TableCell>
      </>
    );
  };

  const detailsExpenditure = (id) => {
    let i = expenditures.findIndex((expenditure) => {
      if (expenditure._id === id) {
        return true;
      }
      return false;
    });
    setOpen(true);
    setCurrent(expenditures[i]);
  };

  const editExpenditure = (id) => {
    let i = expenditures.findIndex((expenditure) => {
      if (expenditure._id === id) {
        return true;
      }
      return false;
    });
    setOpen(true);
    setCurrent(expenditures[i]);
  };

  const deleteExpenditure = (id) => {
    let i = expenditures.findIndex((expenditure) => {
      if (expenditure._id === id) {
        return true;
      }
      return false;
    });
    setOpen(true);
    setCurrent(expenditures[i]);
  };

  const actions = {
    details: (
      <DetailsExpenditure
        establishment={establishment}
        setOpen={setOpen}
        expenditure={current}
        expendituresTypes={expendituresTypes}
        boxes={boxes}
      />
    ),
    delete: (
      <DeleteExpenditure id={id} setOpen={setOpen} expenditure={current} />
    ),
    edit: (
      <EditExpenditure
        establishment={establishment}
        id={id}
        token={user.token}
        setOpen={setOpen}
        expenditure={current}
        categories={categories}
        expendituresTypes={expendituresTypes}
        boxes={boxes}
      />
    ),
  };

  useEffect(() => {
    dispatch(getCategories(id, user.token));
    dispatch(getExpenditures(id, user.token));
    dispatch(getExpenses(id, user.token, setIsLoadingComponent));
  }, [id, user.token, dispatch, setIsLoadingComponent]);

  return isLoadingComponent ? (
    <Spinner />
  ) : (
    <>
      <Graphics expenses={expenses} expenditures={expenditures} />
      <TableSort
        columns={columns}
        rows={rows}
        Cells={Cells}
        detailsAction={detailsExpenditure}
        editAction={editExpenditure}
        deleteAction={deleteExpenditure}
        setAction={setAction}
        disableColumnEdit={!user.isAdmin}
        disableColumnDelete={!user.isAdmin}
      />
      <Modal
        handleClose={() => setOpen(false)}
        open={open}
        component={actions[action]}
      />
    </>
  );
};

export default List;
