import React, { useState, Fragment } from "react";
import {
  Button,
  FormControl,
  FormControlLabel,
  Grid,
  makeStyles,
  Radio,
  RadioGroup,
  TextField,
  Typography,
  useMediaQuery,
  useTheme,
} from "@material-ui/core";
import Spinner from "../UI/Spinner";
import { useForm } from "../../hooks/use-form";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    width: theme.spacing(50),
    padding: theme.spacing(5),
    "@media (max-width:650px)": {
      width: theme.spacing(30),
      padding: theme.spacing(1),
    },
    "@media (max-width:400px)": {
      width: theme.spacing(20),
      padding: 0,
    },
  },
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  marginBottom: {
    marginBottom: theme.spacing(2.5),
  },
}));

const initialState = {
  name: "",
  account: "",
  cbu: "",
};

const Form = ({
  title,
  setOpen,
  isLoading,
  onClikHandler,
  data,
  hasChanged,
  setHasChanged,
}) => {
  const classes = useStyles();

  const [form, onChangeHandler] = useForm(
    data
      ? {
          name: data.name,
          account: data.account,
          cbu: data.cbu,
        }
      : initialState
  );

  const [type, setType] = useState(data ? data.type : "BOX");

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const onChangeData = () => {
    if (setHasChanged && hasChanged === false) {
      setHasChanged(true);
    }
  };

  const formatData = () => {
    let data = {
      type: type,
      name: form.name.value,
    };

    if (form.account.value !== "") {
      data.account = form.account.value;
    }
    if (form.cbu.value !== "") {
      data.cbu = form.cbu.value;
    }

    onClikHandler(data);
  };

  let disabledBox =
    hasChanged && form.name.value !== "" && form.name.isValid === true
      ? false
      : true;

  let disabledBank =
    hasChanged &&
    Object.entries(form).filter(
      (entry) => entry[1].value === "" || entry[1].isValid === false
    ).length === 0
      ? false
      : true;

  return isLoading ? (
    <Spinner height={type === "BANK" ? 390 : 278} />
  ) : (
    <div>
      <Typography variant="h6">{title}</Typography>
      <Grid container className={classes.grid} spacing={1}>
        <Grid item xs={12}>
          <FormControl component="fieldset">
            <RadioGroup
              row
              aria-label="gender"
              name="boxes"
              value={type}
              onChange={(e) => setType(e.target.value)}
            >
              <FormControlLabel
                value="BOX"
                control={<Radio color="primary" />}
                label="Caja"
              />
              <FormControlLabel
                value="BANK"
                control={<Radio color="primary" />}
                label="Banco"
              />
            </RadioGroup>
          </FormControl>
        </Grid>
        <Grid item xs={12}>
          <TextField
            className={type === "BOX" ? classes.marginBottom : ""}
            value={form.name.value}
            required
            autoComplete="off"
            fullWidth
            id="name"
            name="name"
            label="Nombre"
            inputProps={{
              minLength: 2,
              maxLength: 100,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.name.isValid}
            helperText={
              !form.name.isValid &&
              (form.name.value.length < 2
                ? "Pocos caracteres"
                : "Nombre inválido")
            }
            InputLabelProps={{ required: false }}
          />
        </Grid>
        {type === "BANK" && (
          <Fragment>
            <Grid item xs={12}>
              <TextField
                id="account"
                label="Nro. de cuenta"
                value={form.account.value}
                onChange={(e) => {
                  onChangeHandler(e);
                  onChangeData();
                }}
                fullWidth
                required
                autoComplete="off"
                type="text"
                inputProps={{
                  minLength: "5",
                  maxLength: "22",
                  pattern: "[0-9.]+",
                }}
                error={!form.account.isValid}
                helperText={
                  !form.account.isValid ? "Ingrese una cuenta válida" : ""
                }
                InputLabelProps={{ required: false }}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                className={classes.marginBottom}
                id="cbu"
                label="CBU"
                value={form.cbu.value}
                onChange={(e) => {
                  onChangeHandler(e);
                  onChangeData();
                }}
                fullWidth
                required
                autoComplete="off"
                type="text"
                inputProps={{
                  minLength: "22",
                  maxLength: "22",
                  pattern: "[0-9.]+",
                }}
                error={!form.cbu.isValid}
                helperText={!form.cbu.isValid ? "Ingrese un cbu válido" : ""}
                InputLabelProps={{ required: false }}
              />
            </Grid>
          </Fragment>
        )}
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            id="cancel-button"
            variant="outlined"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Cancelar
          </Button>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            disabled={type === "BOX" ? disabledBox : disabledBank}
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={formatData}
          >
            Aceptar
          </Button>
        </Grid>
      </Grid>
    </div>
  );
};

export default Form;
