import {
  GET_PAYMENT_ORDERS,
  LIQUIDATE,
  GET_SETTLEMENT_RECEIPTS,
  DELETE_SETTLEMENT_RECEIPT,
  GET_RECURRING_DISCOUNTS,
  DELETE_RECURRING_DISCOUNT,
} from "../Action/actionTypes";

const initialState = {
  paymentOrders: [],
  settlementReceipts: [],
  recurringDiscounts: [],
};

export const liquidationsReducer = (state = initialState, action) => {
  switch (action.type) {
    case GET_PAYMENT_ORDERS:
      return {
        ...state,
        paymentOrders: action.payload,
      };
    case LIQUIDATE:
      return {
        ...state,
        paymentOrders: action.payload,
      };

    case GET_SETTLEMENT_RECEIPTS:
      return {
        ...state,
        settlementReceipts: action.payload,
      };

    case DELETE_SETTLEMENT_RECEIPT:
      return {
        ...state,
        settlementReceipts: action.payload,
      };

    case GET_RECURRING_DISCOUNTS:
      return {
        ...state,
        recurringDiscounts: action.payload,
      };

    case DELETE_RECURRING_DISCOUNT:
      return {
        ...state,
        recurringDiscounts: action.payload,
      };

    default:
      return state;
  }
};

export default liquidationsReducer;
