import {
  Button,
  Checkbox,
  Container,
  Grid,
  IconButton,
  makeStyles,
  TableCell,
  Tooltip,
} from "@material-ui/core";
import React, { Fragment, useState } from "react";
import { useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import PageHeader from "../components/UI/PageHeader";
import Spinner from "../components/UI/Spinner";
import {
  getContracts,
  getItemsContract,
} from "../Redux/Action/contractsActions";

import ContractInformation from "../components/Contracts/ContractInformation";
import Table from "../components/Shared/Table";
import Modal from "../components/Shared/Modal";
import BackButtonComponent from "../components/Shared/BackButtonComponent";

import DetailsContact from "../components/Schedule/Details";

import {
  useHistory,
  useParams,
} from "react-router-dom/cjs/react-router-dom.min";
import { getFormatDate } from "../hooks/date-hook";
import { NumberFormatCustom } from "../hooks/format-number-hook";
import { status } from "../configs/contracts/STATUS";

import { getContacts } from "../Redux/Action/scheduleActions";

import ReceiptIcon from "@material-ui/icons/Receipt";
import AddIcon from "@material-ui/icons/Add";
import ReloadIcon from "@material-ui/icons/Cached";

import AddItem from "../components/Contracts/AddItem";
import EditItem from "../components/Contracts/EditItem";
import DeleteItem from "../components/Contracts/DeleteItem";
import PayItems from "../components/Contracts/PayItems";

const useStyles = makeStyles((theme) => ({
  root: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    marginTop: theme.spacing(2),
    marginBottom: theme.spacing(2),
  },
  container: {
    width: "100%",
    display: "flex",
    marginBottom: theme.spacing(2),
    alignItems: "center",
    flexDirection: "row",
    justifyContent: "space-between",
  },
  grid: {
    marginBottom: theme.spacing(2),
    justifyContent: "space-between",
    alignItems: "center",
    "@media (min-width:650px)": {
      flexDirection: "row",
    },
  },
  gridButtonsActionsOne: {
    display: "flex",
    justifyContent: "flex-start",
    "@media (max-width:600px)": {
      justifyContent: "space-between",
      marginBottom: theme.spacing(2),
    },
  },
  gridButtonsActionsTwo: {
    display: "flex",
    justifyContent: "flex-end",
  },
  paymentButton: {
    minWidth: 135,
    width: "100%",
    backgroundColor: "#49AC08",
    "@media (min-width:600px)": { maxWidth: 140 },

    "&:hover": {
      backgroundColor: "#49AC08",
    },
  },
  receiptsButton: {
    width: "100%",
    backgroundColor: "#EECE06",
    color: "#1A2330",
    "@media (min-width:600px)": { minWidth: 135, maxWidth: 140 },

    "&:hover": {
      backgroundColor: "#EECE06",
    },
  },
  reload: {
    padding: theme.spacing(0.75),
    marginRight: theme.spacing(2.5),
  },

  gridButtonContract: {
    marginTop: theme.spacing(2),
    justifyContent: "space-between",
    alignItems: "center",
  },
  gridButtonsActionContract: {
    display: "flex",
    justifyContent: "flex-start",
  },
  viewFullContractButton: {
    backgroundColor: "#49AC08",
    "&:hover": {
      backgroundColor: "#49AC08",
    },
  },
}));

const Cells = ({ row, setChecked, establishment }) => {
  return (
    <Fragment>
      <TableCell padding="checkbox">
        <Checkbox
          disabled={row.status !== "paid" ? false : true}
          checked={row.checked}
          onChange={(e) => setChecked(e, row._id)}
        />
      </TableCell>
      <TableCell component="th" scope="row">
        {getFormatDate(row.expirationDate)}
      </TableCell>
      <TableCell style={{ minWidth: 100 }} component="th" scope="row">
        {row.name}
      </TableCell>
      <TableCell
        style={{
          minWidth: 100,
        }}
        component="th"
        scope="row"
      >
        {/* Enlaces a comprobantes */}
        <div style={{ display: "flex", flexDirection: "column" }}>
          {row.paymentOrders.map((entry, index) => (
            <a
              key={`link-to-pdf-${index}`}
              style={{
                outline: "none",
                textDecoration: "none",
                color: "#49AC08",
                ...(index > 0 && { paddingTop: 8 }),
              }}
              href={`${process.env.REACT_APP_BACKEND_URL}/files/${establishment}/${entry}.pdf`}
              rel="noreferrer"
              target="_blank"
            >
              {`Comprobante: ${entry}`}
            </a>
          ))}
        </div>
      </TableCell>
      <TableCell component="th" scope="row">
        {NumberFormatCustom(row.amount)}
      </TableCell>
      <TableCell component="th" scope="row">
        {NumberFormatCustom(row.fee)}
      </TableCell>
      <TableCell
        component="th"
        scope="row"
        style={{ color: row.status === "pending" ? "#F24726" : "#3ABD49" }}
      >
        {status[row.status]}
      </TableCell>
      <TableCell style={{ minWidth: 200 }} component="th" scope="row">
        {row.notes}
      </TableCell>
      <TableCell component="th" scope="row">
        {NumberFormatCustom(row.payedAmount)}
      </TableCell>
    </Fragment>
  );
};

const MoreActions = ({ row, payAction }) => {
  return (
    <TableCell align="center" style={{ width: "120px" }}>
      <IconButton
        disabled={
          row.status === "paid" ||
          (row.amount ? (row.amount > 0 ? false : true) : true)
            ? true
            : false
        }
        style={{
          padding: 0,
          ...(row.status === "paid" ||
          (row.amount ? (row.amount > 0 ? false : true) : true)
            ? {}
            : { color: "#3ABD49" }),
        }}
        onClick={() => {
          payAction(row);
        }}
      >
        <ReceiptIcon />
      </IconButton>
    </TableCell>
  );
};

const ContractDetails = ({ user }) => {
  const classes = useStyles();
  const dispatch = useDispatch();
  const params = useParams();
  const history = useHistory();

  const { id } = params;

  const columns = [
    "Vencimiento",
    "Nombre",
    "Detalles",
    "Importe",
    "Honorarios",
    "Estado",
    "Notas",
    "Pagado",
    "Editar",
    "Eliminar",
  ];
  const columnsMoreActions = ["Cobrar"];

  const [isLoading, setIsLoading] = useState(true);
  const [isLoadingTable, setIsLoadingTable] = useState(false);
  const [open, setOpen] = useState(false);
  const [recent, setRecent] = useState(true);

  const [currentContact, setCurrentContact] = useState();
  const [currentItem, setCurrentItem] = useState();

  const [action, setAction] = useState();
  const [anchorEl, setAnchorEl] = React.useState(null);

  const [rows, setRows] = useState([]);

  const [selected, setSelected] = useState([]);

  const contracts = useSelector((state) => state.contracts.contracts);
  const contract = contracts.filter((entry) => entry._id === id);

  const handleClose = () => {
    setAnchorEl(null);
  };

  const seeReceipts = () => {
    history.push(`/alquileres/contratos/${id}/comprobantes`);
  };

  const onClickHandler = (item) => {
    if (item === "viewPDF") {
      actions[item]();
    } else {
      setAction(item);
    }
    handleClose();
  };

  const reloadItems = (value) => {
    setIsLoadingTable(true);
    dispatch(
      getItemsContract(recent, user.token, id, setIsLoadingTable, setRows)
    );
  };

  const resetSelected = () => {
    setRows((rows) => {
      let copy = [...rows];
      copy.forEach((e) => {
        if (e.status !== "paid") {
          e.checked = false;
        }
      });

      return copy;
    });
    setSelected([]);
  };

  const addItem = () => {
    setAction("addItem");
    resetSelected();
    setOpen(true);
  };

  const paySelection = () => {
    setAction("paySelection");
    setOpen(true);
  };

  const payAction = (current) => {
    setAction("payItem");
    setCurrentItem(current);
    resetSelected();
    setOpen(true);
  };

  const editAction = (current) => {
    setAction("editItem");
    setCurrentItem(current);
    resetSelected();
    setOpen(true);
  };

  const deleteAction = (current) => {
    setAction("deleteItem");
    setCurrentItem(current);
    resetSelected();
    setOpen(true);
  };

  const seeFullContract = (bool) => {
    setSelected([]);
    setRecent(bool);
    setIsLoadingTable(true);
    dispatch(
      getItemsContract(bool, user.token, id, setIsLoadingTable, setRows)
    );
  };

  const seeCurrentAccount = (id) => {
    history.push(`/contactos/${id}/cuenta-corriente`);
  };

  const menuItems = {
    "Editar propiedad": "editProperty",
    ...(contract.length > 0 &&
      contract[0].pdf && { "Ver PDF de contrato": "viewPDF" }),
    "Listar todos los contratos": "listAllContracts",
    "Crear nuevo contrato": "newContract",
    "Finalizar contrato": "endContract",
  };

  const handleSelectAllClick = (event) => {
    setRows((rows) => {
      let copy = [...rows];
      let aux = [];

      for (let i = 0; i < copy.length; i++) {
        if (copy[i].status !== "paid") {
          copy[i].checked = event.target.checked ? true : false;
          if (event.target.checked) {
            aux.push(copy[i]);
          }
        }
      }

      setSelected(event.target.checked ? aux : []);

      return copy;
    });
  };

  const setChecked = (event, id) => {
    let i = rows.findIndex((entry) => {
      if (entry._id === id) {
        return true;
      }
      return false;
    });

    setRows((rows) => {
      let copy = [...rows];

      if (i !== -1) {
        copy[i].checked = event.target.checked;
      }

      return copy;
    });

    if (event.target.checked) {
      setSelected((selected) => {
        let copy = [...selected];

        copy.push(rows[i]);

        return copy;
      });
    } else {
      setSelected((selected) => {
        let i = selected.findIndex((entry) => {
          if (entry._id === id) {
            return true;
          }
          return false;
        });

        let copy = [...selected];

        if (i !== -1) {
          copy.splice(i, 1);
        }

        return copy;
      });
    }
  };

  let dataSelecting = {
    indeterminate:
      selected.length > 0 &&
      selected.length < rows.filter((entry) => entry.status !== "paid").length,
    checked:
      rows.filter((entry) => entry.status !== "paid").length > 0 &&
      selected.length ===
        rows.filter((entry) => entry.status !== "paid").length,
    onChange: handleSelectAllClick,
  };

  const currentMonth = (index, currentRow, previousRow) => {
    let currentDate = new Date();
    let currentMonth = currentDate.getMonth();
    let currentYear = currentDate.getFullYear();

    let rowDate = new Date(currentRow.expirationDate);
    let rowMonth = rowDate.getMonth();
    let rowYear = rowDate.getFullYear();

    let previousDate = null;
    let previousMonth = null;

    if (previousRow) {
      previousDate = new Date(previousRow.expirationDate);
      previousMonth = previousDate.getMonth();
    }

    let boolMonth =
      rowMonth >= currentMonth &&
      (index > 0 ? previousMonth < currentMonth : true);

    let boolYear = rowYear === currentYear;

    return boolMonth && boolYear;
  };

  const extended = () => {
    let items = contract.length > 0 ? rows : [];
    let finishingDate = null;
    let extended = false;
    let i = 0;

    if (contracts.length > 0) {
      let aux = new Date(contract[0].startingDate);
      aux.setMonth(aux.getMonth() + contract[0].months);
      finishingDate = aux;
    }

    while (!extended && i < items.length) {
      let aux = new Date(items[i].expirationDate);

      if (aux > finishingDate) {
        extended = true;
      }

      i++;
    }

    return extended;
  };

  const actions = {
    contactDetails: (
      <DetailsContact contact={currentContact} setOpen={setOpen} />
    ),
    addItem: (
      <AddItem
        id={id}
        user={user}
        setOpen={setOpen}
        setRows={setRows}
        recent={recent}
      />
    ),
    editItem: (
      <EditItem
        id={id}
        user={user}
        setOpen={setOpen}
        current={currentItem}
        setRows={setRows}
      />
    ),
    deleteItem: (
      <DeleteItem
        user={user}
        setOpen={setOpen}
        idContract={id}
        current={currentItem}
        setRows={setRows}
      />
    ),
    payItem: (
      <PayItems
        user={user}
        idContract={id}
        idContactCC={contract.length > 0 ? contract[0].tenants[0]._id : ""}
        recent={recent}
        individual={true}
        setOpen={setOpen}
        current={currentItem}
        setRows={setRows}
        tenants={contract.length > 0 ? contract[0].tenants : []}
      />
    ),
    paySelection: (
      <PayItems
        user={user}
        idContract={id}
        idContactCC={contract.length > 0 ? contract[0].tenants[0]._id : ""}
        recent={recent}
        setOpen={setOpen}
        current={selected}
        setRows={setRows}
        tenants={contract.length > 0 ? contract[0].tenants : []}
        resetSelected={resetSelected}
      />
    ),

    viewPDF: () => {
      if (contract[0].pdf)
        window.open(
          `${process.env.REACT_APP_BACKEND_URL}/files/${contract[0].establishment}/${contract[0].pdf}`,
          "_blank"
        );
    },
  };

  useEffect(() => {
    dispatch(getContacts(user.token));
    dispatch(getContracts(user.token));
    dispatch(getItemsContract(true, user.token, id, setIsLoading, setRows));
  }, [dispatch, id, user.token, setIsLoading]);

  return (
    <Container className={classes.root} maxWidth="xl">
      {isLoading ? (
        <Spinner />
      ) : (
        <Fragment>
          {history.action !== "POP" && (
            <BackButtonComponent
              title="Volver a contratos"
              onClick={() => history.goBack()}
              mrgBottom={24}
            />
          )}
          <PageHeader
            justify="space-between"
            marginBottom={24}
            user={user}
            title={
              contract.length > 0
                ? `${contract[0].property.address} - Legajo ${contract[0].property.number}`
                : "Contrato inexistente"
            }
            subtitle={contract.length > 0 && extended() && "Prorrogado"}
            enabledConfigMenu={true}
            icButtonFalse={true}
            disabledMenuButton={contract.length > 0 ? false : true}
            titleConfig="Acciones"
            menuItems={menuItems}
            anchorEl={anchorEl}
            setAnchorEl={setAnchorEl}
            handleClose={handleClose}
            onClickHandler={onClickHandler}
            horizontal="right"
          />

          <ContractInformation
            establishment={contract.length > 0 ? contract[0].establishment : ""}
            image={(contract.length > 0 && contract[0].property.image) || null}
            tenants={contract.length > 0 ? contract[0].tenants : []}
            guarantors={contract.length > 0 ? contract[0].guarantors : []}
            deposit={contract.length > 0 ? contract[0].deposit : ""}
            depositKeeper={
              contract.length > 0 ? contract[0].depositKeeper : null
            }
            items={contract.length > 0 ? rows : []}
            setAction={setAction}
            setCurrentContact={setCurrentContact}
            setOpen={setOpen}
            seeCurrentAccount={seeCurrentAccount}
          />

          <Grid container className={classes.grid}>
            <Grid item xs={12} sm={6} className={classes.gridButtonsActionsOne}>
              <Tooltip
                title={selected.length > 0 ? "Cobrar items seleccionados" : ""}
              >
                <div style={{ marginRight: 12, width: "100%", maxWidth: 140 }}>
                  <Button
                    variant="contained"
                    disableElevation
                    className={classes.paymentButton}
                    disabled={selected.length > 1 ? false : true}
                    onClick={paySelection}
                  >
                    Cobrar
                  </Button>
                </div>
              </Tooltip>

              <Button
                variant="contained"
                disableElevation
                className={classes.receiptsButton}
                onClick={seeReceipts}
              >
                Comprobantes
              </Button>
            </Grid>
            <Grid item xs={12} sm={6} className={classes.gridButtonsActionsTwo}>
              <Tooltip title="Recargar tabla">
                <IconButton
                  className={classes.reload}
                  variant="contained"
                  aria-label="add"
                  onClick={reloadItems}
                >
                  <ReloadIcon />
                </IconButton>
              </Tooltip>

              <Button
                variant="contained"
                disableElevation
                startIcon={<AddIcon />}
                onClick={addItem}
              >
                Agregar
              </Button>
            </Grid>
          </Grid>

          {isLoadingTable ? (
            <Spinner height={300} />
          ) : (
            <Fragment>
              <Table
                columns={columns}
                columnsMoreActions={columnsMoreActions}
                selecting={true}
                dataSelecting={dataSelecting}
                rows={rows}
                Cells={(row) => (
                  <Cells
                    row={row.row}
                    setChecked={setChecked}
                    establishment={
                      contract.length > 0 ? contract[0].establishment : ""
                    }
                  />
                )}
                MoreActions={(e) => (
                  <MoreActions row={e.row} payAction={payAction} />
                )}
                disableColumnDetails={true}
                editAction={editAction}
                deleteAction={deleteAction}
                setAction={setAction}
                currentMonthBanner={true}
                currentMonth={currentMonth}
                reduced={recent}
              />

              <Grid container className={classes.gridButtonContract}>
                <Grid
                  item
                  xs={12}
                  sm={6}
                  className={classes.gridButtonsActionContract}
                >
                  <Button
                    variant="contained"
                    disableElevation
                    className={classes.viewFullContractButton}
                    onClick={() => seeFullContract(!recent)}
                  >
                    {recent ? "Ver contrato completo" : "Ver contrato reducido"}
                  </Button>
                </Grid>
              </Grid>
            </Fragment>
          )}
          <Modal
            handleClose={() => setOpen(false)}
            open={open}
            component={actions[action]}
            maxWidth={
              action === "payItem" || action === "paySelection" ? 900 : null
            }
          />
        </Fragment>
      )}
    </Container>
  );
};

export default ContractDetails;
