import axios from "axios";
import { LOG_IN, LOG_OUT } from "./actionTypes";
import { setSnackData } from "./snackDataActions";

export const createUser = (data, setIsLoading, navigate) => (dispatch) => {
  axios
    .post(`${process.env.REACT_APP_BACKEND_URL}/users/signup`, data)
    .then((_) => {
      dispatch(
        setSnackData({
          open: true,
          message: "Usuario creado",
          severity: "success",
        })
      );
      navigate();
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }
      setIsLoading(false);
    });
};

export const logInUser = (data, setIsLoading) => (dispatch) => {
  axios
    .post(`${process.env.REACT_APP_BACKEND_URL}/users/login`, data)
    .then((res) => {
      dispatch({
        type: LOG_IN,
        payload: res.data,
      });
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }
      setIsLoading(false);
    });
};

export const logOutUser = () => (dispatch) => {
  if (process.env.REACT_APP_DEMO === "true") {
    dispatch(
      setSnackData({
        open: true,
        message: "En la demo no hace falta salir. Los datos de ejemplo siguen disponibles.",
        severity: "info",
      })
    );
    return;
  }

  localStorage.removeItem("userData");
  dispatch({
    type: LOG_OUT,
    payload: null,
  });
};

