import React from "react";
import {
  FormControl,
  FormControlLabel,
  FormLabel,
  Grid,
  makeStyles,
  Radio,
  RadioGroup,
} from "@material-ui/core";

const useStyles = makeStyles((theme) => ({
  radioGroup: {
    display: "flex",
    justifyContent: "flex-end",
    "& .Mui-checked": {
      color: "#49AC08",
    },
  },
}));

const RadioComponent = ({ title, isService, values, onChangeChecked }) => {
  const classes = useStyles();

  return (
    <FormControl component="fieldset" fullWidth>
      <Grid container alignItems="center">
        <Grid item xs={7}>
          <FormLabel style={{ color: "#616161" }}>{title}</FormLabel>
        </Grid>
        <Grid item xs={5}>
          <RadioGroup
            className={classes.radioGroup}
            name="radio"
            value={values[isService ? "cashToBox" : "checked"]}
            onChange={(e) =>
              onChangeChecked(e, isService ? "cashToBox" : "checked")
            }
            row
          >
            <FormControlLabel
              value="true"
              control={
                <Radio
                  color="primary"
                  disableRipple
                  style={{
                    padding: 0,
                    marginRight: 8,
                  }}
                />
              }
              label="Sí"
            />
            <FormControlLabel
              style={{ marginRight: 0 }}
              value="false"
              control={
                <Radio
                  color="primary"
                  disableRipple
                  style={{
                    padding: 0,
                    marginRight: 8,
                    marginLeft: 8,
                  }}
                />
              }
              label="No"
            />
          </RadioGroup>
        </Grid>
      </Grid>
    </FormControl>
  );
};

export default RadioComponent;
