import React, { useState, useEffect } from "react";
import {
  Button,
  Container,
  Grid,
  Hidden,
  IconButton,
  makeStyles,
  Tooltip,
  Typography,
  useMediaQuery,
  useTheme,
  TableCell,
} from "@material-ui/core";
import AddIcon from "@material-ui/icons/Add";
import ReloadIcon from "@material-ui/icons/Cached";

import Spinner from "../components/UI/Spinner";
import Table from "../components/Shared/Table";
import Modal from "../components/Shared/Modal";

import AddProvider from "../components/Providers/AddProvider";
import DeleteProvider from "../components/Providers/DeleteProvider";
import EditProvider from "../components/Providers/EditProvider";

import { useDispatch, useSelector } from "react-redux";
import { getProviders } from "../Redux/Action/providersActions";

const useStyles = makeStyles((theme) => ({
  root: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    marginTop: theme.spacing(2),
    marginBottom: theme.spacing(2),
  },
  grid: {
    marginBottom: theme.spacing(2),
    justifyContent: "flex-end",
    alignItems: "center",
    "@media (min-width:650px)": {
      flexDirection: "row",
    },
  },
  gridButton: {
    display: "flex",
    justifyContent: "flex-end",
  },
  reload: {
    padding: theme.spacing(0.75),
    marginRight: theme.spacing(2.5),
  },
  add: {
    padding: theme.spacing(0.75),
  },
  title: {
    marginBottom: 0,
    fontSize: "20px",
    width: "max-content",
    "@media (min-width:650px)": {
      fontSize: "24px",
    },
  },
}));

const Cells = ({ row }) => {
  return (
    <TableCell component="th" scope="row">
      {row.name}
    </TableCell>
  );
};

const Providers = () => {
  const classes = useStyles();
  const dispatch = useDispatch();
  const user = useSelector((state) => state.user.userData);

  const [open, setOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [current, setCurrent] = useState(null);
  const [action, setAction] = useState();

  const columns = ["Proveedor", "Editar", "Eliminar"];
  const rows = useSelector((state) => state.providers.providers);

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const reload = () => {
    setIsLoading(true);
    dispatch(getProviders(user.token, setIsLoading));
  };

  const addProvider = () => {
    setAction("add");
    setOpen(true);
  };

  const editProvider = (current) => {
    setOpen(true);
    setCurrent(current);
  };
  const deleteProvider = (current) => {
    setOpen(true);
    setCurrent(current);
  };

  const actions = {
    add: <AddProvider token={user.token} setOpen={setOpen} />,
    edit: (
      <EditProvider token={user.token} setOpen={setOpen} provider={current} />
    ),
    delete: (
      <DeleteProvider token={user.token} setOpen={setOpen} provider={current} />
    ),
  };

  useEffect(() => {
    dispatch(getProviders(user.token, setIsLoading));
  }, [user.token, dispatch]);

  return (
    <Container className={classes.root} maxWidth="xl">
      {isLoading ? (
        <Spinner />
      ) : (
        <>
          <Grid container className={classes.grid}>
            <Grid item xs={isMobile ? 6 : 12} sm={6}>
              <Typography gutterBottom className={classes.title}>
                Proveedores
              </Typography>
            </Grid>
            <Grid
              item
              xs={isMobile ? 6 : 12}
              sm={6}
              className={classes.gridButton}
            >
              <Hidden xsDown>
                <Tooltip title="Recargar tabla">
                  <IconButton
                    className={classes.reload}
                    variant="contained"
                    aria-label="add"
                    onClick={reload}
                  >
                    <ReloadIcon />
                  </IconButton>
                </Tooltip>
                <Button
                  variant="contained"
                  disableElevation
                  startIcon={<AddIcon />}
                  onClick={addProvider}
                >
                  Agregar
                </Button>
              </Hidden>
              <Hidden smUp>
                <Tooltip title="Recargar tabla">
                  <IconButton
                    className={classes.reload}
                    variant="contained"
                    aria-label="add"
                    onClick={reload}
                  >
                    <ReloadIcon />
                  </IconButton>
                </Tooltip>
                <Tooltip title="Agregar">
                  <IconButton
                    className={classes.add}
                    variant="contained"
                    aria-label="add"
                    onClick={addProvider}
                  >
                    <AddIcon />
                  </IconButton>
                </Tooltip>
              </Hidden>
            </Grid>
          </Grid>
          <Table
            columns={columns}
            rows={rows}
            Cells={Cells}
            disableColumnDetails={true}
            editAction={editProvider}
            deleteAction={deleteProvider}
            setAction={setAction}
          />
          <Modal
            handleClose={() => setOpen(false)}
            open={open}
            component={actions[action]}
          />
        </>
      )}
    </Container>
  );
};

export default Providers;
