import axios from "axios";
import { GET_PAYMENTS, ADD_PAYMENT, DELETE_PAYMENT } from "./actionTypes";
import { getFunctionalUnits } from "./functionalUnitsActions";

import { setSnackData } from "./snackDataActions";

export const getPayments = (id, idUF, token, setIsLoading) => (dispatch) => {
  axios
    .get(
      `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/payments/${idUF}`,
      {
        headers: {
          Authorization: "Bearer " + token,
        },
      }
    )
    .then((res) => {
      dispatch({
        type: GET_PAYMENTS,
        payload: res.data,
      });
      if (setIsLoading) setIsLoading(false);
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }
      if (setIsLoading) setIsLoading(false);
    });
};

export const addPayment =
  (id, idUF, token, data, setOpen, setIsLoading) => (dispatch, getState) => {
    let aux = getState().payments.payments;
    let payments = Array.from(aux);
    axios
      .post(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/payments/${idUF}`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        payments.push(res.data);
        dispatch({
          type: ADD_PAYMENT,
          payload: payments,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Pago registrado",
            severity: "success",
          })
        );
        dispatch(getFunctionalUnits(id, token));
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const deletePayment =
  (id, idPayment, token, setOpen, setIsLoading) => (dispatch, getState) => {
    let aux = getState().payments.payments;
    let payments = Array.from(aux);

    axios
      .delete(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/payments/${idPayment}`,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        let i = payments.findIndex((payment) => {
          if (payment._id === idPayment) {
            return true;
          }
          return false;
        });

        i !== -1 && payments.splice(i, 1);

        dispatch({
          type: DELETE_PAYMENT,
          payload: payments,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Pago eliminado",
            severity: "success",
          })
        );
        dispatch(getFunctionalUnits(id, token));
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };
