import axios from "axios";
import {
  GET_FUNCTIONAL_UNITS,
  ADD_FUNCTIONAL_UNIT,
  EDIT_FUNCTIONAL_UNIT,
  DELETE_FUNCTIONAL_UNIT,
  GET_TRANSACTIONS_FU,
} from "./actionTypes";

import { setSnackData } from "./snackDataActions";
import { getExpenses } from "./expensesActions";

export const getFunctionalUnits = (id, token, setIsLoading) => (dispatch) => {
  axios
    .get(
      `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/functional-units`,
      {
        headers: {
          Authorization: "Bearer " + token,
        },
      }
    )
    .then((res) => {
      dispatch({
        type: GET_FUNCTIONAL_UNITS,
        payload: res.data,
      });
      if (setIsLoading) setIsLoading(false);
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }
      if (setIsLoading) setIsLoading(false);
    });
};

export const getTransactions =
  (id, idUF, token, setIsLoading) => (dispatch) => {
    axios
      .get(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/functional-units/${idUF}/transactions`,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        let transactions = res.data;

        dispatch({
          type: GET_TRANSACTIONS_FU,
          payload: transactions,
        });
        if (setIsLoading) setIsLoading(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const postFunctionalUnit =
  (id, token, data, setOpen, setIsLoading) => (dispatch, getState) => {
    for (let i = 0; i < data.expendituresTypesPercentages.length; i++) {
      if (data.expendituresTypesPercentages[i].percentage === "") {
        data.expendituresTypesPercentages[i].percentage = 0;
      }
    }
    let fuAux = getState().functionalunits.functionalUnits;
    let etAux = getState().expendituresTypes.expendituresTypes;

    let functionalUnits = Array.from(fuAux);
    let expendituresTypes = Array.from(etAux);
    let contacts = getState().contacts.contacts;

    let owner = contacts.filter((contact) => contact._id === data.owner)[0];

    const getExpenditureType = (id) => {
      let expenditureType = expendituresTypes.filter(
        (expenditure) => expenditure._id === id
      )[0];

      return expenditureType;
    };

    axios
      .post(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/functional-units`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        let data = res.data;
        data.owner = owner;
        data.balance = res.data.balance;

        const populateExpenditures = data.expendituresTypesPercentages.map(
          (expenditure) =>
            (expenditure = {
              percentage: expenditure.percentage,
              expenditureType: getExpenditureType(expenditure.expenditureType),
            })
        );

        data.expendituresTypesPercentages = populateExpenditures;

        functionalUnits.push(data);

        dispatch({
          type: ADD_FUNCTIONAL_UNIT,
          payload: functionalUnits,
        });

        dispatch(getExpenses(id, token));

        dispatch(
          setSnackData({
            open: true,
            message: "Unidad funcional creada",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const editFunctionalUnit =
  (id, idUF, token, data, current, setOpen, setIsLoading) =>
  (dispatch, getState) => {
    for (let i = 0; i < data.expendituresTypesPercentages.length; i++) {
      if (data.expendituresTypesPercentages[i].percentage === "") {
        data.expendituresTypesPercentages[i].percentage = 0;
      }
    }

    let fuAux = getState().functionalunits.functionalUnits;
    let etAux = getState().expendituresTypes.expendituresTypes;

    let functionalUnits = Array.from(fuAux);
    let expendituresTypes = Array.from(etAux);

    let contacts = getState().contacts.contacts;

    let owner = contacts.filter((contact) => contact._id === data.owner)[0];

    const getExpenditureType = (id) => {
      let expenditureType = expendituresTypes.filter(
        (expenditure) => expenditure._id === id
      )[0];

      return expenditureType;
    };

    axios
      .put(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/functional-units/${idUF}`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        current.balance = res.data.balance;

        if (data.initialBalance < 0) {
          current.initialBalance = data.initialBalance;
          current.debtInterest = data.debtInterest;
          current.debtInterests = data.debtInterests;
          current.debtDate = data.debtDate;
        }

        if (data.initialBalance >= 0) {
          delete current.debtInterest;
          delete current.debtInterests;
          delete current.debtDate;
        }

        current.initialBalance = data.initialBalance;

        current.owner = owner;

        current.centId = data.centId || "";

        current.apartment = data.apartment;
        current.number = data.number;

        const populateExpenditures = data.expendituresTypesPercentages.map(
          (expenditure) =>
            (expenditure = {
              percentage: expenditure.percentage,
              expenditureType: getExpenditureType(expenditure.expenditureType),
            })
        );

        current.expendituresTypesPercentages = populateExpenditures;

        let i = functionalUnits.findIndex((functionalUnit) => {
          if (functionalUnit._id === idUF) {
            return true;
          }
          return false;
        });

        if (i !== -1) {
          functionalUnits[i] = Object.assign(functionalUnits[i], current);
        }

        dispatch({
          type: EDIT_FUNCTIONAL_UNIT,
          payload: functionalUnits,
        });

        dispatch(getExpenses(id, token));

        dispatch(
          setSnackData({
            open: true,
            message: "Unidad funcional editada",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const deleteFunctionalUnit =
  (id, idUF, token, setOpen, setIsLoading) => (dispatch, getState) => {
    let fuAux = getState().functionalunits.functionalUnits;
    let functionalUnits = Array.from(fuAux);

    axios
      .delete(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/functional-units/${idUF}`,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        let i = functionalUnits.findIndex((functionalUnit) => {
          if (functionalUnit._id === idUF) {
            return true;
          }
          return false;
        });

        i !== -1 && functionalUnits.splice(i, 1);

        dispatch({
          type: DELETE_FUNCTIONAL_UNIT,
          payload: functionalUnits,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Unidad funcional eliminada",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };
