import React, { Fragment } from "react";
import {
  Button,
  Grid,
  makeStyles,
  Typography,
  useMediaQuery,
  useTheme,
  TextField,
  RadioGroup,
  FormLabel,
  FormControl,
  FormControlLabel,
  Radio,
} from "@material-ui/core";

import Spinner from "../UI/Spinner";

import { NumberFormatCustom } from "../../hooks/format-number-hook";

import ItemCard from "../Shared/ItemCard";
import SettlementInformation from "./SettlementInformation";
import ItemsTable from "./ItemsTable";
import DiscountsForm from "./DiscountsForm";

import { addDiscount, deleteDiscount } from "./hooks";

import MoneyOffIcon from "@material-ui/icons/MoneyOff";
import RecurringDiscountsTable from "./RecurringDiscountsTable";

const useStyles = makeStyles((theme) => ({
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "left",
  },
  cardContainer: {
    padding: theme.spacing(0.5, 0.5, 0, 0),
    overflowX: "hidden",
    overflowY: "auto",
    maxHeight: theme.spacing(13.75),
  },
  radioGroup: {
    display: "flex",
    justifyContent: "flex-end",
    "& .Mui-checked": {
      color: "#49AC08",
    },
  },
  toLiquidate: {
    flex: 1,
    display: "flex",
    flexDirection: "row",
    justifyContent: "space-between",
    boxShadow: "none",
    backgroundColor: "#F7F9F8",
    border: "1px solid #E6EBE8",
    borderRadius: 12,
    padding: theme.spacing(2),
  },
  buttons: {
    justifyContent: "center",
    marginTop: theme.spacing(3.5),
    "& .MuiTooltip-tooltip": {
      backgroundColor: "red",
    },
  },
}));

const Form = ({
  token,
  title,
  setOpen,
  isLoading,
  onClickHandler,
  amounts,
  setAmounts,
  items,
  values,
  setValues,
  rDiscounts,
  setRDiscounts,
  setChecked,
  dataSelecting,
  dataDiscounts,
  setDataDiscounts,
  setFormDiscounts,
  discounts,
  setDiscounts,
}) => {
  const classes = useStyles();

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("800"), {
    defaultMatches: true,
  });

  let disabled = false;

  return isLoading ? (
    <Spinner height={843} />
  ) : (
    <Fragment>
      <Typography variant="h6">{title}</Typography>
      <Grid container className={classes.grid} spacing={2}>
        <Grid item xs={12}>
          <ItemsTable items={items} />
        </Grid>

        {rDiscounts.length > 0 && (
          <Grid item xs={12}>
            <RecurringDiscountsTable
              amounts={amounts}
              token={token}
              items={rDiscounts}
              setItems={setRDiscounts}
              dataSelecting={dataSelecting}
              setChecked={setChecked}
            />
          </Grid>
        )}

        <Grid item xs={12} style={{ padding: "8px" }}>
          <Typography variant="h6">
            Agregar descuento
            <span
              style={{ color: "#158900", fontSize: 14 }}
            >{`\n(Opcional)`}</span>
          </Typography>
        </Grid>

        <DiscountsForm
          isMobile={isMobile}
          data={dataDiscounts}
          setData={setDataDiscounts}
          setForm={setFormDiscounts}
          addDiscount={(data) =>
            addDiscount(
              data,
              setDataDiscounts,
              discounts,
              setDiscounts,
              amounts,
              setAmounts
            )
          }
          amounts={amounts}
        />

        {discounts.length > 0 && (
          <Grid item xs={12}>
            <div className={classes.cardContainer}>
              {discounts.map((entry, index) => (
                <ItemCard
                  key={`itemCard-payments-${index}`}
                  title={`${entry.concept} (Descuento${
                    entry.isRecurrent === "true" ? `\n recurrente` : ``
                  })`}
                  subtitle={NumberFormatCustom(parseFloat(entry.amount))}
                  Icon={MoneyOffIcon}
                  action={() =>
                    deleteDiscount(
                      index,
                      discounts,
                      setDiscounts,
                      amounts,
                      setAmounts
                    )
                  }
                />
              ))}
            </div>
          </Grid>
        )}

        <Grid item xs={12} style={{ paddingTop: "16px" }}>
          <TextField
            id="notes"
            label="Notas"
            placeholder="(Opcional. Para el comprobante)"
            multiline
            value={values.notes.value}
            variant="outlined"
            onChange={(e) => {
              setValues({
                ...values,
                notes: {
                  value: e.target.value,
                  isValid: e.target.validity.valid,
                },
              });
            }}
            fullWidth
            inputProps={{
              maxLength: 300,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
            }}
            error={!values.notes.isValid}
          />
        </Grid>

        <Grid item xs={12} style={{ paddingTop: "16px" }}>
          <FormControl component="fieldset" fullWidth>
            <Grid container alignItems="center">
              <Grid item xs={7}>
                <FormLabel style={{ color: "#616161" }}>
                  ¿Enviar comprobante por correo?
                </FormLabel>
              </Grid>
              <Grid item xs={5}>
                <RadioGroup
                  className={classes.radioGroup}
                  name="radio"
                  value={values.sendEmail}
                  onChange={(e) => {
                    setValues({ ...values, sendEmail: e.target.value });
                  }}
                  row
                >
                  <FormControlLabel
                    value="true"
                    control={
                      <Radio
                        color="primary"
                        disableRipple
                        style={{
                          padding: 0,
                          marginRight: 8,
                        }}
                      />
                    }
                    label="Sí"
                  />
                  <FormControlLabel
                    style={{ marginRight: 0 }}
                    value="false"
                    control={
                      <Radio
                        color="primary"
                        disableRipple
                        style={{
                          padding: 0,
                          marginRight: 8,
                          marginLeft: 8,
                        }}
                      />
                    }
                    label="No"
                  />
                </RadioGroup>
              </Grid>
            </Grid>
          </FormControl>
        </Grid>

        <Grid item xs={12} style={{ marginTop: 8 }}>
          <SettlementInformation amounts={amounts} />
        </Grid>

        <Grid item xs={12}>
          <div className={classes.toLiquidate}>
            <Typography>Total a liquidar</Typography>
            <Typography>{NumberFormatCustom(amounts.toLiquidate)}</Typography>
          </div>
        </Grid>
      </Grid>
      <Grid container className={classes.buttons} spacing={1}>
        <Grid item xs={6} sm={isMobile ? 6 : 3}>
          <Button
            id="cancel-button"
            variant="outlined"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Cancelar
          </Button>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 6 : 3}>
          <Button
            disabled={disabled}
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={onClickHandler}
          >
            Liquidar
          </Button>
        </Grid>
      </Grid>
    </Fragment>
  );
};

export default Form;
