import React, { useState } from "react";
import { useDispatch } from "react-redux";
import Form from "./Form";
import { addExpenditureType } from "../../Redux/Action/expendituresTypesActions";

const AddExpenditureType = ({ id, token, setOpen }) => {
  const dispatch = useDispatch();

  const [isLoading, setIsLoading] = useState(false);

  const onClikHandler = (data) => {
    setIsLoading(true);
    dispatch(addExpenditureType(id, token, data, setOpen, setIsLoading));
  };

  return (
    <Form
      title="Nueva clase de gasto"
      setOpen={setOpen}
      isLoading={isLoading}
      onClikHandler={onClikHandler}
      hasChanged={true}
    />
  );
};

export default AddExpenditureType;
