import React from "react";
import {
  Card,
  CardContent,
  IconButton,
  makeStyles,
  Typography,
} from "@material-ui/core";

import CloseIcon from "@material-ui/icons/Close";

const useStyles = makeStyles((theme) => ({
  root: {
    "& .MuiCardContent-root": {
      padding: theme.spacing(1.25, 1.5),
      display: "flex",
      alignItems: "center",
    },
    marginBottom: theme.spacing(1),
    backgroundColor: "#F7F9F8",
    border: "1px solid #E6EBE8",
    boxShadow: "none",
    borderRadius: 10,
  },
  title: {
    marginRigth: theme.spacing(2),
    whiteSpace: "nowrap",
    textOverflow: "ellipsis",
    overflowX: "hidden",
    overflowY: "auto",
    color: "#000000",
  },
  deleteButton: {
    marginLeft: "auto",
    padding: 0,
  },
}));

const ItemCard = ({
  onClickCard,
  title,
  subtitle,
  Icon,
  CustomAction,
  action,
}) => {
  const classes = useStyles();
  return (
    <Card className={classes.root} onClick={onClickCard}>
      <CardContent>
        {Icon && <Icon color="primary" />}
        <Typography
          className={classes.title}
          style={Icon ? { marginLeft: 16 } : null}
        >
          {title}{" "}
          {subtitle && <span style={{ color: "#158900" }}>{subtitle}</span>}
        </Typography>
        {CustomAction ? (
          <CustomAction />
        ) : (
          <IconButton
            className={classes.deleteButton}
            onClick={(event) => {
              action();
              event.stopPropagation();
            }}
          >
            <CloseIcon style={{ color: "red" }} />
          </IconButton>
        )}
      </CardContent>
    </Card>
  );
};

export default ItemCard;
