import React, { Fragment, useState } from "react";
import {
  Button,
  Checkbox,
  Container,
  Grid,
  IconButton,
  makeStyles,
  TableCell,
  Tooltip,
} from "@material-ui/core";

import { useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import PageHeader from "../components/UI/PageHeader";
import Spinner from "../components/UI/Spinner";

import Table from "../components/Shared/Table";
import Modal from "../components/Shared/Modal";
import BackButtonComponent from "../components/Shared/BackButtonComponent";

import {
  useHistory,
  useParams,
} from "react-router-dom/cjs/react-router-dom.min";

import { getContacts } from "../Redux/Action/scheduleActions";

import ReloadIcon from "@material-ui/icons/Cached";

import PayItems from "../components/Liquidations/PayItems";

import {
  getPaymentOrders,
  getRecurringDiscounts,
} from "../Redux/Action/liquidationsActions";
import months from "../configs/MONTHS";
import { NumberFormatCustom } from "../hooks/format-number-hook";

const useStyles = makeStyles((theme) => ({
  root: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    marginTop: theme.spacing(2),
    marginBottom: theme.spacing(2),
  },
  grid: {
    marginBottom: theme.spacing(2),
    justifyContent: "space-between",
    alignItems: "center",
    "@media (min-width:650px)": {
      flexDirection: "row",
    },
  },
  gridButtonsActionsOne: {
    display: "flex",
    justifyContent: "flex-start",
    "@media (max-width:600px)": {
      justifyContent: "space-between",
      marginBottom: theme.spacing(2),
    },
  },
  gridButtonsActionsTwo: {
    display: "flex",
    justifyContent: "flex-end",
  },
  paymentButton: {
    minWidth: 135,
    width: "100%",
    backgroundColor: "#49AC08",
    "@media (min-width:600px)": { maxWidth: 140 },

    "&:hover": {
      backgroundColor: "#49AC08",
    },
  },
  receiptsButton: {
    width: "100%",
    backgroundColor: "#EECE06",
    color: "#1A2330",
    "@media (min-width:600px)": { minWidth: 135, maxWidth: 140 },

    "&:hover": {
      backgroundColor: "#EECE06",
    },
  },
  reload: {
    padding: theme.spacing(0.75),
    marginRight: theme.spacing(2.5),
  },
}));

const Cells = ({ row, setChecked }) => {
  const getPeriod = (date) => {
    let aux = new Date(date);

    return `${months[aux.getMonth()]} de ${aux.getFullYear()}`;
  };

  const getAmount = () => {
    let sum = 0;

    for (let item of row.payedItems) {
      if (item.cashToBox !== undefined && item.cashToBox === false) {
        item.amount.amount = 0;
      } else if (
        item.item.payable !== undefined &&
        item.item.payable === false
      ) {
        item.amount.amount = 0;
      } else {
        sum += item.amount.amount + item.amount.tax;
      }

      if (item.amount.fee) sum -= item.amount.fee;
    }

    for (let item of row.discounts) {
      sum -= item.amount;
    }

    return NumberFormatCustom(sum);
  };

  return (
    <Fragment>
      <TableCell padding="checkbox">
        <Checkbox
          disabled={row.status !== "paid" ? false : true}
          checked={row.checked}
          onChange={(e) => setChecked(e, row._id)}
        />
      </TableCell>
      <TableCell component="th" scope="row">
        {row.contract.property.address}
      </TableCell>
      <TableCell component="th" scope="row">
        {getPeriod(row.date)}
      </TableCell>
      <TableCell component="th" scope="row" align="center">
        {getAmount()}
      </TableCell>
    </Fragment>
  );
};

const Liquidations = ({ user }) => {
  const classes = useStyles();
  const dispatch = useDispatch();
  const params = useParams();
  const history = useHistory();

  const { id } = params;

  const columns = ["Dirección", "Periodo", "Monto"];

  const [open, setOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isLoadingTable, setIsLoadingTable] = useState(false);

  const [action, setAction] = useState();

  const [rows, setRows] = useState([]);

  const [selected, setSelected] = useState([]);

  const recurringDiscounts = useSelector(
    (state) => state.liquidations.recurringDiscounts
  );

  const contacts = useSelector((state) => state.contacts.contacts);
  const contact = contacts.filter((entry) => entry._id === id);

  const seeReceipts = () => {
    history.push(`/contactos/liquidaciones/${id}/comprobantes`);
  };

  const reloadItems = () => {
    setIsLoadingTable(true);
    resetSelected();
    dispatch(getPaymentOrders(user.token, id, setIsLoadingTable, setRows));
  };

  const paySelection = () => {
    setAction("paySelection");
    setOpen(true);
  };

  const resetSelected = () => {
    setRows((rows) => {
      let copy = [...rows];
      copy.forEach((e) => {
        e.checked = false;
      });

      return copy;
    });
    setSelected([]);
  };

  const handleSelectAllClick = (event) => {
    setRows((rows) => {
      let copy = [...rows];
      let aux = [];

      for (let i = 0; i < copy.length; i++) {
        copy[i].checked = event.target.checked ? true : false;
        if (event.target.checked) {
          aux.push(copy[i]);
        }
      }

      setSelected(event.target.checked ? aux : []);

      return copy;
    });
  };

  const setChecked = (event, id) => {
    let i = rows.findIndex((entry) => {
      if (entry._id === id) {
        return true;
      }
      return false;
    });

    setRows((rows) => {
      let copy = [...rows];

      if (i !== -1) {
        copy[i].checked = event.target.checked;
      }

      return copy;
    });

    if (event.target.checked) {
      setSelected((selected) => {
        let copy = [...selected];

        copy.push(rows[i]);

        return copy;
      });
    } else {
      setSelected((selected) => {
        let i = selected.findIndex((entry) => {
          if (entry._id === id) {
            return true;
          }
          return false;
        });

        let copy = [...selected];

        if (i !== -1) {
          copy.splice(i, 1);
        }

        return copy;
      });
    }
  };

  let dataSelecting = {
    indeterminate: selected.length > 0 && selected.length < rows.length,
    checked: rows.length > 0 && selected.length === rows.length,
    onChange: handleSelectAllClick,
  };

  const actions = {
    paySelection: (
      <PayItems
        user={user}
        ownerId={id}
        setOpen={setOpen}
        paymentOrders={selected}
        setRows={setRows}
        resetSelected={resetSelected}
        recurringDiscounts={recurringDiscounts}
      />
    ),
  };

  useEffect(() => {
    dispatch(getContacts(user.token));
    dispatch(getRecurringDiscounts(user.token, id));
    dispatch(getPaymentOrders(user.token, id, setIsLoading, setRows));
  }, [dispatch, id, user.token, setIsLoading]);

  return (
    <Container className={classes.root} maxWidth="xl">
      {isLoading ? (
        <Spinner />
      ) : (
        <Fragment>
          {history.action !== "POP" && (
            <BackButtonComponent
              title="Volver a contactos"
              onClick={() => history.goBack()}
              mrgBottom={24}
            />
          )}
          <PageHeader
            justify="space-between"
            marginBottom={24}
            title={
              contact.length > 0
                ? `${contact[0].name} ${contact[0].lastname} - ${contact[0].address}`
                : "Contacto inexistente"
            }
            user={user}
          />

          <Grid container className={classes.grid}>
            <Grid item xs={12} sm={6} className={classes.gridButtonsActionsOne}>
              <Tooltip
                title={
                  selected.length > 0 ? "Liquidar items seleccionados" : ""
                }
              >
                <div style={{ marginRight: 12, width: "100%", maxWidth: 140 }}>
                  <Button
                    variant="contained"
                    disableElevation
                    className={classes.paymentButton}
                    disabled={selected.length > 0 ? false : true}
                    onClick={paySelection}
                  >
                    Liquidar
                  </Button>
                </div>
              </Tooltip>

              <Button
                variant="contained"
                disableElevation
                className={classes.receiptsButton}
                onClick={seeReceipts}
              >
                Comprobantes
              </Button>
            </Grid>
            <Grid item xs={12} sm={6} className={classes.gridButtonsActionsTwo}>
              <Tooltip title="Recargar tabla">
                <IconButton
                  className={classes.reload}
                  variant="contained"
                  aria-label="add"
                  onClick={reloadItems}
                >
                  <ReloadIcon />
                </IconButton>
              </Tooltip>
            </Grid>
          </Grid>

          {isLoadingTable ? (
            <Spinner height={300} />
          ) : (
            <Table
              columns={columns}
              selecting={true}
              dataSelecting={dataSelecting}
              rows={rows}
              Cells={(row) => <Cells row={row.row} setChecked={setChecked} />}
              disableColumnDetails={true}
              disableColumnEdit={true}
              disableColumnDelete={true}
            />
          )}

          <Modal
            handleClose={() => setOpen(false)}
            open={open}
            component={actions[action]}
            maxWidth={900}
          />
        </Fragment>
      )}
    </Container>
  );
};

export default Liquidations;
