import React, { useEffect, useState } from "react";
import { useDispatch } from "react-redux";
import { useForm } from "../../hooks/use-form";
import {
  getRecurringDiscounts,
  liquidate,
} from "../../Redux/Action/liquidationsActions";

import Form from "./Form";
import {
  addRecurringDiscount,
  calculateAmounts,
  deleteRecurringDiscount,
} from "./hooks";

const PayItems = ({
  user,
  ownerId,
  setOpen,
  paymentOrders,
  setRows,
  resetSelected,
  recurringDiscounts,
}) => {
  const dispatch = useDispatch();

  const [isLoading, setIsLoading] = useState(true);

  const [amounts, setAmounts] = useState({});
  const [items, setItems] = useState([]);
  const [discounts, setDiscounts] = useState([]);
  const [selected, setSelected] = useState([]);
  const [rDiscounts, setRDiscounts] = useState(recurringDiscounts);

  const [values, setValues] = useState({
    sendEmail: "true",
    notes: { value: "", isValid: true },
  });

  const [dataDiscounts, setDataDiscounts, setFormDiscounts] = useForm({
    concept: "",
    isRecurrent: "false",
    amount: "",
    cashFromBox: "false",
  });

  const handleSelectAllClick = (event) => {
    setRDiscounts((rows) => {
      let copy = [...rows];
      let aux = [];

      let sum = 0;

      for (let i = 0; i < copy.length; i++) {
        if (amounts.toLiquidate > copy[i].amount) {
          copy[i].checked = event.target.checked ? true : false;
        }
        if (event.target.checked) {
          aux.push(copy[i]);
        }
      }

      for (let entry of copy) {
        if (amounts.toLiquidate > entry.amount) {
          sum += entry.amount;
        }
      }

      if (event.target.checked) {
        addRecurringDiscount({ amount: sum }, amounts, setAmounts);
      } else {
        deleteRecurringDiscount({ amount: sum }, amounts, setAmounts);
      }

      setSelected(event.target.checked ? aux : []);

      return copy;
    });
  };

  const setChecked = (event, id) => {
    let i = rDiscounts.findIndex((entry) => {
      if (entry._id === id) {
        return true;
      }
      return false;
    });

    setRDiscounts((rows) => {
      let copy = [...rows];

      if (i !== -1) {
        copy[i].checked = event.target.checked;
      }

      return copy;
    });

    if (event.target.checked) {
      addRecurringDiscount(rDiscounts[i], amounts, setAmounts);
      setSelected((selected) => {
        let copy = [...selected];

        copy.push(rDiscounts[i]);

        return copy;
      });
    } else {
      deleteRecurringDiscount(rDiscounts[i], amounts, setAmounts);
      setSelected((selected) => {
        let i = selected.findIndex((entry) => {
          if (entry._id === id) {
            return true;
          }
          return false;
        });

        let copy = [...selected];

        if (i !== -1) {
          copy.splice(i, 1);
        }

        return copy;
      });
    }
  };

  let dataSelecting = {
    indeterminate: selected.length > 0 && selected.length < rDiscounts.length,
    checked: rDiscounts.length > 0 && selected.length === rDiscounts.length,
    onChange: handleSelectAllClick,
  };

  const onClickHandler = () => {
    setIsLoading(true);

    let data = {
      owner: ownerId,
      paymentOrders: [],
      sendEmail: values.sendEmail === "true" ? true : false,
    };

    if (selected.length > 0) {
      let aux = [];

      for (let entry of selected) {
        aux.push(entry._id);
      }

      data.recurrentDiscounts = aux;
    }

    if (discounts.length > 0) {
      let aux = [];
      for (let entry of discounts) {
        aux.push({
          amount: parseFloat(entry.amount),
          concept: entry.concept,
          isRecurrent: entry.isRecurrent === "true" ? true : false,
          ...(entry.isRecurrent === "false" && {
            cashFromBox: entry.cashFromBox === "true" ? true : false,
          }),
        });
      }

      data.discounts = aux;
    }

    for (let entry of paymentOrders) {
      data.paymentOrders.push(entry._id);
    }

    if (values.notes.value !== "") data.notes = values.notes.value;

    dispatch(
      liquidate(
        user.token,
        data,
        setOpen,
        setIsLoading,
        setRows,
        resetSelected,
        ownerId
      )
    );
  };

  useEffect(() => {
    (async () => {
      let obj = {
        totalAmount: 0,
        totalFees: 0,
        totalDiscounts: 0,
        toLiquidate: 0,
      };

      let aux = calculateAmounts(obj, paymentOrders);

      setAmounts(obj);
      setItems(aux);
      dispatch(getRecurringDiscounts(user.token, ownerId, setIsLoading));
    })();
  }, [dispatch, paymentOrders, user.token, ownerId]);

  return (
    <Form
      token={user.token}
      title="Liquidar"
      setOpen={setOpen}
      isLoading={isLoading}
      onClickHandler={onClickHandler}
      amounts={amounts}
      setAmounts={setAmounts}
      items={items}
      values={values}
      setValues={setValues}
      rDiscounts={rDiscounts}
      setRDiscounts={setRDiscounts}
      setChecked={setChecked}
      dataSelecting={dataSelecting}
      dataDiscounts={dataDiscounts}
      setDataDiscounts={setDataDiscounts}
      setFormDiscounts={setFormDiscounts}
      discounts={discounts}
      setDiscounts={setDiscounts}
    />
  );
};

export default PayItems;
