import React, { useEffect, useState } from "react";
import {
  Button,
  FormControl,
  Grid,
  IconButton,
  Input,
  InputAdornment,
  InputLabel,
  makeStyles,
  TextField,
} from "@material-ui/core";
import Spinner from "../UI/Spinner";

import Visibility from "@material-ui/icons/Visibility";
import VisibilityOff from "@material-ui/icons/VisibilityOff";
import { useForm } from "../../hooks/use-form";

const useStyles = makeStyles((theme) => ({
  container: {
    flex: "1",
    display: "flex",
    flexDirection: "column",
    width: "100%",
    height: "100%",
    justifyContent: "space-around",
  },
  grid: {
    width: "100%",
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  marginBottom: {
    marginBottom: theme.spacing(2.5),
  },

  buttons: {
    marginTop: theme.spacing(3),
    justifyContent: "flex-end",
    alignItems: "center",
  },
}));

const initialState = {
  port: "",
  host: "",
  from: "",
  user: "",
  password: "",
};

const Form = ({
  data,
  edit,
  isLoading,
  onClickHandler,
  hasChanged,
  setHasChanged,
}) => {
  const classes = useStyles();

  const [form, onChangeHandler, setForm] = useForm(initialState);

  const [showPassword, setShowPassword] = useState(false);

  const onChangeData = () => {
    if (setHasChanged && hasChanged === false) {
      setHasChanged(true);
    }
  };

  const handleMouseDownPassword = (event) => {
    event.preventDefault();
  };

  const onCLick = () => {
    let data = {};

    for (let key in form) {
      data[key] = form[key].value;
    }

    onClickHandler(data, setForm);
  };

  let disabled =
    hasChanged &&
    Object.entries(form).filter(
      (entry) => entry[1].value === "" || entry[1].isValid === false
    ).length === 0
      ? false
      : true;

  useEffect(() => {
    if (!edit) {
      setForm((form) => {
        let copy = { ...form };
        for (let key in form) {
          copy[key] = { value: data[key] || "", isValid: true };
        }
        return copy;
      });

      setHasChanged(false);
    }
  }, [data, edit, setForm, setHasChanged]);

  return isLoading ? (
    <Spinner />
  ) : (
    <div className={classes.container}>
      <Grid container className={classes.grid} spacing={1}>
        <Grid item xs={12} sm={12}>
          <TextField
            disabled={!edit}
            className={classes.marginBottom}
            value={form.port.value}
            required
            type="number"
            autoComplete="off"
            fullWidth
            id="port"
            name="port"
            label="Puerto"
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            inputProps={{
              min: 1,
              max: 99999,
            }}
            error={!form.port.isValid}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            disabled={!edit}
            className={classes.marginBottom}
            value={form.host.value}
            required
            autoComplete="off"
            fullWidth
            id="host"
            name="host"
            label="Host"
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            disabled={!edit}
            className={classes.marginBottom}
            value={form.from.value}
            required
            autoComplete="off"
            fullWidth
            id="from"
            name="from"
            label="Remitente"
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            inputProps={{
              pattern: "[a-z0-9._%+-]+@[a-z0-9.-]+.[a-z]{2,4}$",
            }}
            error={!form.from.isValid}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            disabled={!edit}
            className={classes.marginBottom}
            value={form.user.value}
            required
            autoComplete="off"
            fullWidth
            id="user"
            name="user"
            label="Usuario"
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            inputProps={{
              pattern: "[a-z0-9._%+-]+@[a-z0-9.-]+.[a-z]{2,4}$",
            }}
            error={!form.user.isValid}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <FormControl
            disabled={!edit}
            fullWidth
            className={classes.marginBottom}
            error={!form.password.isValid}
          >
            <InputLabel>Contraseña</InputLabel>
            <Input
              id="password"
              name="password"
              type={showPassword ? "text" : "password"}
              value={form.password.value}
              onChange={(e) => {
                onChangeHandler(e);
                onChangeData();
              }}
              autoComplete="off"
              required
              fullWidth
              inputProps={{ minLength: "6" }}
              endAdornment={
                <InputAdornment position="end">
                  <IconButton
                    disabled={!edit}
                    aria-label="toggle password visibility"
                    onClick={() => setShowPassword(!showPassword)}
                    onMouseDown={handleMouseDownPassword}
                  >
                    {showPassword ? <Visibility /> : <VisibilityOff />}
                  </IconButton>
                </InputAdornment>
              }
            />
          </FormControl>
        </Grid>
      </Grid>

      <Grid container className={classes.buttons} spacing={1}>
        <Grid item xs={12} sm={3}>
          <Button
            disabled={!edit || disabled}
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={onCLick}
          >
            Aceptar
          </Button>
        </Grid>
      </Grid>
    </div>
  );
};

export default Form;
