import React, { useEffect } from "react";
import { TableCell } from "@material-ui/core";
import Table from "../../../Shared/Table";

import Spinner from "../../../UI/Spinner";

import { getFormatDate } from "../../../../hooks/date-hook";
import { getTransactions } from "../../../../Redux/Action/functionalUnitsActions";
import { useDispatch, useSelector } from "react-redux";
import { NumberFormatCustom } from "../../../../hooks/format-number-hook";

const columns = ["Fecha", "Concepto", "Monto"];

const Cells = ({ row }) => {
  return (
    <>
      <TableCell component="th" scope="row">
        {getFormatDate(row.updatedAt)}
      </TableCell>
      <TableCell component="th" scope="row">
        {row.concept}
      </TableCell>
      <TableCell
        component="th"
        scope="row"
        align="center"
        style={{ color: row.type === "DEBIT" ? "#C10909" : "#28BD00" }}
      >
        {NumberFormatCustom(row.amount.toString().replace(/\./g, ","))}
      </TableCell>
    </>
  );
};

const CurrentAccount = ({
  currentUF,
  id,
  token,
  isLoadingComponent,
  setIsLoadingComponent,
}) => {
  const dispatch = useDispatch();
  const transactions = useSelector(
    (state) => state.transactions.transactionsFU
  );

  useEffect(() => {
    dispatch(getTransactions(id, currentUF._id, token, setIsLoadingComponent));
  }, [currentUF, dispatch, id, token, setIsLoadingComponent]);

  return isLoadingComponent ? (
    <Spinner />
  ) : (
    <Table
      columns={columns}
      rows={
        transactions.transactions && transactions.transactions.length > 0
          ? transactions.transactions.sort((a, b) => {
              let dateA = new Date(a.createdAt);
              let dateB = new Date(b.createdAt);

              if (dateA.getTime() > dateB.getTime()) {
                return -1;
              }
              if (dateA.getTime() < dateB.getTime()) {
                return 1;
              }

              return 0;
            })
          : []
      }
      Cells={Cells}
      disableColumnEdit={true}
      disableColumnDelete={true}
      disableColumnDetails={true}
    />
  );
};

export default CurrentAccount;
