import React, { useState, useEffect, Fragment } from "react";
import {
  IconButton,
  Typography,
  TableCell,
  Table,
  TableHead,
  TableRow,
  TableBody,
} from "@material-ui/core";
import FileIcon from "@material-ui/icons/Description";
import CollapsibleTable from "../Shared/CollapsibleTable";
import Modal from "../Shared/Modal";

import Spinner from "../UI/Spinner";

import DeleteExpense from "./DeleteExpense";
import DetailsExpense from "./Details";

import { getExpenses } from "../../Redux/Action/expensesActions";
import { getExpenditures } from "../../Redux/Action/expendituresActions";
import { getCategories } from "../../Redux/Action/categoriesActions";

import { useDispatch, useSelector } from "react-redux";

import { getFormatDate } from "../../hooks/date-hook";

import SendIcon from "@material-ui/icons/Send";
import SendEmail from "./SendEmail";
import { getFunctionalUnits } from "../../Redux/Action/functionalUnitsActions";

const columnsMoreActions = ["Enviar"];

const columns = [
  "Conformación",
  "Titulo",
  "Intereses por dia",
  "Ver PDF",
  "Detalles",
  "Eliminar",
];

const Cells = ({ row, establishment }) => {
  return (
    <Fragment>
      <TableCell component="th" scope="row">
        {getFormatDate(row.date)}
      </TableCell>
      <TableCell component="th" scope="row">
        {row.name ? row.name : "Expensa sin titulo"}
      </TableCell>
      <TableCell component="th" scope="row">
        {`${row.interest}%`}
      </TableCell>
      <TableCell component="th" scope="row">
        <a
          href={`${process.env.REACT_APP_BACKEND_URL}/files/${establishment}/${row._id}.pdf`}
          rel="noreferrer"
          target="_blank"
        >
          <IconButton variant="contained" color="primary">
            <FileIcon />
          </IconButton>
        </a>
      </TableCell>
    </Fragment>
  );
};

const MoreActions = ({ row, action }) => {
  return (
    <>
      <TableCell align="center" style={{ width: "120px" }}>
        <IconButton
          style={{ color: "#48B", padding: 0 }}
          onClick={() => {
            action(row);
          }}
        >
          <SendIcon />
        </IconButton>
      </TableCell>
    </>
  );
};

const DataCollapsible = ({
  id,
  token,
  row,
  dispatch,
  isLoading,
  setIsLoading,
}) => {
  const expenditures = useSelector(
    (state) => state.expenditures.filteredExpenditures
  );

  useEffect(() => {
    if (isLoading) {
      dispatch(getExpenditures(id, token, setIsLoading, row._id));
    }
  }, [id, token, row, dispatch, isLoading, setIsLoading]);

  return isLoading ? (
    <Spinner />
  ) : (
    <Fragment>
      <Typography variant="h6" gutterBottom>
        Gastos
      </Typography>
      <Table size="small" aria-label="purchases">
        <TableHead>
          <TableRow>
            <TableCell>Monto</TableCell>
            <TableCell>Categoria</TableCell>
            <TableCell>Subcategoria</TableCell>
            <TableCell>Proveedor</TableCell>
            <TableCell>Fecha</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {expenditures.map((expenditure) => (
            <TableRow key={expenditure._id}>
              <TableCell
                component="th"
                scope="row"
              >{`$${expenditure.amount.amount}`}</TableCell>
              <TableCell component="th" scope="row">
                {expenditure.category.name}
              </TableCell>
              <TableCell component="th" scope="row">
                {expenditure.subcategory ? expenditure.subcategory.name : "..."}
              </TableCell>
              <TableCell component="th" scope="row">
                {expenditure.provider.name}
              </TableCell>
              <TableCell component="th" scope="row">
                {getFormatDate(expenditure.expirationDate)}
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </Fragment>
  );
};

const Expenses = ({
  establishment,
  id,
  token,
  isLoadingComponent,
  setIsLoadingComponent,
  expendituresTypes,
}) => {
  const dispatch = useDispatch();

  const functionalUnits = useSelector(
    (state) => state.functionalunits.functionalUnits
  ).sort((a, b) => {
    if (a.number > b.number) {
      return 1;
    }
    if (a.number < b.number) {
      return -1;
    }

    return 0;
  });

  const [isLoadingDC, setIsLoadingDC] = useState(true);

  const [open, setOpen] = useState(false);
  const [action, setAction] = useState(false);
  const [current, setCurrent] = useState();

  const rows = useSelector((state) => state.expenses.expenses).sort((a, b) => {
    let dateA = new Date(a.date);
    let dateB = new Date(b.date);

    if (dateA.getTime() > dateB.getTime()) {
      return -1;
    }
    if (dateA.getTime() < dateB.getTime()) {
      return 1;
    }

    return 0;
  });

  const detailsExpense = (current) => {
    setCurrent(current);
    setAction("details");
    setOpen(true);
  };

  const deleteExpense = (current) => {
    setCurrent(current);
    setAction("delete");
    setOpen(true);
  };

  const sendEmail = (current) => {
    setCurrent(current);
    setAction("sendEmail");
    setOpen(true);
  };

  const actions = {
    delete: <DeleteExpense id={id} setOpen={setOpen} expense={current} />,
    details: (
      <DetailsExpense
        setOpen={setOpen}
        expense={current}
        expendituresTypes={expendituresTypes}
      />
    ),
    sendEmail: (
      <SendEmail
        id={id}
        token={token}
        setOpen={setOpen}
        expense={current}
        functionalUnits={functionalUnits}
      />
    ),
  };

  useEffect(() => {
    dispatch(getCategories(id, token));
    dispatch(getFunctionalUnits(id, token));
    dispatch(getExpenses(id, token, setIsLoadingComponent));
  }, [id, token, dispatch, setIsLoadingComponent]);

  return isLoadingComponent ? (
    <Spinner />
  ) : (
    <Fragment>
      <CollapsibleTable
        columns={columns}
        columnsMoreActions={columnsMoreActions}
        rows={rows}
        Cells={(row) => <Cells row={row.row} establishment={establishment} />}
        MoreActions={(row) => <MoreActions row={row.row} action={sendEmail} />}
        detailsAction={detailsExpense}
        disableColumnEdit={true}
        setAction={setAction}
        deleteAction={deleteExpense}
        DataCollapsible={(row) => (
          <DataCollapsible
            row={row.row}
            id={id}
            token={token}
            dispatch={dispatch}
            isLoading={isLoadingDC}
            setIsLoading={setIsLoadingDC}
          />
        )}
        setIsLoadingDC={setIsLoadingDC}
      />
      <Modal
        handleClose={() => setOpen(false)}
        open={open}
        component={actions[action]}
        maxWidth={action === "sendEmail" ? 600 : null}
      />
    </Fragment>
  );
};

export default Expenses;
