import React, { useState, useEffect, Fragment } from "react";
import {
  Button,
  Container,
  Grid,
  Hidden,
  IconButton,
  makeStyles,
  Tooltip,
  Typography,
  useMediaQuery,
  useTheme,
  TableCell,
} from "@material-ui/core";
import AddIcon from "@material-ui/icons/Add";
import ReloadIcon from "@material-ui/icons/Cached";
import Table from "../components/Shared/Table";
import Modal from "../components/Shared/Modal";
import AddConsortium from "../components/Consortium/AddConsortium";
import EditConsortium from "../components/Consortium/EditConsortium";
import DeleteConsortium from "../components/Consortium/DeleteConsortium";
import { useHistory } from "react-router";
import { useDispatch, useSelector } from "react-redux";
import { getConsortiums } from "../Redux/Action/consortiumsActions";
import Spinner from "../components/UI/Spinner";

const useStyles = makeStyles((theme) => ({
  root: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    marginTop: theme.spacing(2),
    marginBottom: theme.spacing(2),
  },
  grid: {
    marginBottom: theme.spacing(2),
    justifyContent: "flex-end",
    alignItems: "center",
    "@media (min-width:650px)": {
      flexDirection: "row",
    },
  },
  gridButton: {
    display: "flex",
    justifyContent: "flex-end",
  },
  reload: {
    padding: theme.spacing(0.75),
    marginRight: theme.spacing(2.5),
  },
  add: {
    padding: theme.spacing(0.75),
  },
  title: {
    marginBottom: 0,
    fontSize: "20px",
    width: "max-content",
    "@media (min-width:650px)": {
      fontSize: "24px",
    },
  },
}));

const Cells = ({ row }) => {
  return (
    <TableCell component="th" scope="row">
      {row.name}
    </TableCell>
  );
};

const ConsortiumPage = ({ user }) => {
  const classes = useStyles();
  const history = useHistory();
  const dispatch = useDispatch();

  const [isLoading, setIsLoading] = useState(true);
  const [open, setOpen] = useState(false);
  const [currentConsortium, setCurrentConsortium] = useState(null);
  const [action, setAction] = useState(false);

  const columns = [
    "Nombre del consorcio",
    "Ver datos",
    ...(user.isAdmin ? ["Editar", "Eliminar"] : []),
  ];
  const rows = useSelector((state) => state.consortiums.consortiums).sort(
    (a, b) => {
      if (a.name.toUpperCase() > b.name.toUpperCase()) {
        return 1;
      }
      if (a.name.toUpperCase() < b.name.toUpperCase()) {
        return -1;
      }

      return 0;
    }
  );

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const reload = () => {
    setIsLoading(true);
    dispatch(getConsortiums(user.token, setIsLoading));
  };

  const addConsortium = () => {
    setAction("add");
    setOpen(true);
  };

  const detailsConsortium = (current) => {
    history.push(`/consorcios/${current._id}/detalles`);
  };

  const editConsortium = (current) => {
    setOpen(true);
    setCurrentConsortium(current);
  };

  const deleteConsortium = (current) => {
    setOpen(true);
    setCurrentConsortium(current);
  };

  const actions = {
    add: <AddConsortium setOpen={setOpen} />,
    edit: <EditConsortium consortium={currentConsortium} setOpen={setOpen} />,
    delete: (
      <DeleteConsortium
        token={user.token}
        setOpen={setOpen}
        consortium={currentConsortium}
      />
    ),
  };

  useEffect(() => {
    dispatch(getConsortiums(user.token, setIsLoading));
  }, [user.token, dispatch]);

  return (
    <Container className={classes.root} maxWidth="xl">
      {isLoading ? (
        <Spinner />
      ) : (
        <Fragment>
          <Grid container className={classes.grid}>
            <Grid item xs={isMobile ? 6 : 12} sm={6}>
              <Typography gutterBottom className={classes.title}>
                Listado de Consorcios
              </Typography>
            </Grid>
            <Grid
              item
              xs={isMobile ? 6 : 12}
              sm={6}
              className={classes.gridButton}
            >
              <Hidden xsDown>
                <Tooltip title="Recargar tabla">
                  <IconButton
                    className={classes.reload}
                    variant="contained"
                    aria-label="add"
                    onClick={reload}
                  >
                    <ReloadIcon />
                  </IconButton>
                </Tooltip>
                {user.isAdmin && (
                  <Button
                    variant="contained"
                    disableElevation
                    startIcon={<AddIcon />}
                    onClick={addConsortium}
                  >
                    Agregar
                  </Button>
                )}
              </Hidden>
              <Hidden smUp>
                <Tooltip title="Recargar tabla">
                  <IconButton
                    className={classes.reload}
                    variant="contained"
                    aria-label="add"
                    onClick={reload}
                  >
                    <ReloadIcon />
                  </IconButton>
                </Tooltip>
                {user.isAdmin && (
                  <Tooltip title="Agregar">
                    <IconButton
                      className={classes.add}
                      variant="contained"
                      aria-label="add"
                      onClick={addConsortium}
                    >
                      <AddIcon />
                    </IconButton>
                  </Tooltip>
                )}
              </Hidden>
            </Grid>
          </Grid>
          <Table
            dataIcon={true}
            columns={columns}
            rows={rows}
            Cells={Cells}
            detailsAction={detailsConsortium}
            editAction={editConsortium}
            deleteAction={deleteConsortium}
            setAction={setAction}
            disableColumnEdit={!user.isAdmin}
            disableColumnDelete={!user.isAdmin}
          />
          <Modal
            handleClose={() => setOpen(false)}
            open={open}
            component={actions[action]}
          />
        </Fragment>
      )}
    </Container>
  );
};

export default ConsortiumPage;
