import React from "react";
import TextField from "@material-ui/core/TextField";
import Grid from "@material-ui/core/Grid";

export default function UserInputs({ onChangeHandler, form }) {
  return (
    <>
      <Grid item xs={12} sm={6}>
        <TextField
          name="name"
          variant="outlined"
          required
          fullWidth
          id="name"
          label="Nombre"
          autoFocus
          onChange={onChangeHandler}
          value={form.name.value}
          inputProps={{
            minLength: 2,
            maxLength: 50,
            pattern: "[a-zA-ZñÑáéíóúÁÉÍÓÚüÜ ]+",
          }}
          InputLabelProps={{ required: false }}
        />
      </Grid>
      <Grid item xs={12} sm={6}>
        <TextField
          variant="outlined"
          required
          fullWidth
          id="lastname"
          label="Apellido"
          name="lastname"
          onChange={onChangeHandler}
          value={form.lastname.value}
          inputProps={{
            minLength: 2,
            maxLength: 100,
            pattern: "[a-zA-ZñÑáéíóúÁÉÍÓÚüÜ ]+",
          }}
          InputLabelProps={{ required: false }}
        />
      </Grid>
      <Grid item xs={12} sm={6}>
        <TextField
          variant="outlined"
          required
          fullWidth
          id="email"
          label="Email"
          name="email"
          type="email"
          onChange={onChangeHandler}
          value={form.email.value}
          inputProps={{
            maxLength: 256,
          }}
          InputLabelProps={{ required: false }}
        />
      </Grid>
      <Grid item xs={12} sm={6}>
        <TextField
          variant="outlined"
          required
          fullWidth
          name="password"
          label="Password"
          type="password"
          id="password"
          autoComplete="new-password"
          onChange={onChangeHandler}
          value={form.password.value}
          inputProps={{
            pattern: "[a-zA-Z0-9@#!$&?.*]*$",
            minLength: 8,
          }}
          InputLabelProps={{ required: false }}
        />
      </Grid>
    </>
  );
}
