import {
  GET_PROVIDERS,
  ADD_PROVIDER,
  EDIT_PROVIDER,
  DELETE_PROVIDER,
} from "../Action/actionTypes";

const initialState = { providers: [] };

export const providersReducer = (state = initialState, action) => {
  switch (action.type) {
    case GET_PROVIDERS:
      return {
        ...state,
        providers: action.payload,
      };
    case ADD_PROVIDER:
      return {
        ...state,
        providers: action.payload,
      };
    case EDIT_PROVIDER:
      return {
        ...state,
        providers: action.payload,
      };
    case DELETE_PROVIDER:
      return {
        ...state,
        providers: action.payload,
      };
    default:
      return state;
  }
};

export default providersReducer;
