import {
  GET_PAYMENTS,
  ADD_PAYMENT,
  DELETE_PAYMENT,
} from "../Action/actionTypes";

const initialState = { payments: [] };

export const paymentsReducer = (state = initialState, action) => {
  switch (action.type) {
    case GET_PAYMENTS:
      return {
        ...state,
        payments: action.payload,
      };
    case ADD_PAYMENT:
      return {
        ...state,
        payments: action.payload,
      };
    case DELETE_PAYMENT:
      return {
        ...state,
        payments: action.payload,
      };

    default:
      return state;
  }
};

export default paymentsReducer;
