import React, { useState } from "react";
import { useEffect } from "react";

import { useDispatch } from "react-redux";
import Form from "./DetailsComponents/AddItemForm";

import { getServices } from "../../Redux/Action/servicesActions";
import { useForm } from "../../hooks/use-form";
import { editItem } from "../../Redux/Action/itemActions";

const EditItem = ({ id, user, setOpen, current, setRows }) => {
  const dispatch = useDispatch();

  const [isLoading, setIsLoading] = useState(true);

  const [hasChanged, setHasChanged] = useState(false);

  const [itemType, setItemType] = useState(current.itemType.toString());

  const [expirationDate, setExpirationDate] = useState(current.expirationDate);

  const [monthsValue, setMonths] = useState(
    current.months ? current.months.toString() : ""
  );

  const [rentalData, setRentalData, setFormRental] = useForm({
    amount: current.itemType === 1 ? current.amount || "" : "",
    fee: current.itemType === 1 ? current.fee || "" : "",
    notes: current.itemType === 1 ? current.notes || "" : "",
  });

  const [dataService, setDataService, setFormService] = useForm({
    service: current.itemType === 2 ? current.service : "",
    amount: current.service && current.amount ? current.amount : "",
    paymentMethod: current.paymentMethod || 1,
    tenantPay: current.paymentMethod
      ? current.paymentMethod === 1
        ? current.tenantPercentage !== undefined
          ? current.tenantPercentage
          : ""
        : current.tenantAmount !== undefined
        ? current.tenantAmount
        : ""
      : "",
    ownerPay: current.paymentMethod
      ? current.paymentMethod === 1
        ? current.ownerPercentage !== undefined
          ? current.ownerPercentage
          : ""
        : current.ownerAmount !== undefined
        ? current.ownerAmount
        : ""
      : "",
    fee: current.service && current.fee ? current.fee : "",
    notes: current.itemType === 2 ? current.notes || "" : "",
    payable:
      current.payable !== undefined
        ? current.payable === true
          ? "true"
          : "false"
        : "true",
  });

  const [dataFreeItem, setDataFreeItem, setFormFreeItem] = useForm({
    name: current.name || "",
    amount: current.name && current.amount ? current.amount : "",
    increaseMonths: current.increaseMonths || "",
    increasePercentage: current.increasePercentage || "",
    fee: current.name && current.fee ? current.fee : "",
    dailyInterestPercentage: current.dailyInterestPercentage || "",
    payable:
      current.payable !== undefined
        ? current.payable === true
          ? "true"
          : "false"
        : "true",
    notes: current.itemType === 3 ? current.notes || "" : "",
  });

  const onClikHandler = (data) => {
    setIsLoading(true);
    dispatch(
      editItem(
        user.token,
        id,
        current._id,
        data,
        setOpen,
        setIsLoading,
        setRows
      )
    );
  };

  useEffect(() => {
    dispatch(getServices(user.token, setIsLoading));
  }, [user.token, dispatch]);

  return (
    <Form
      title={`Editar Item (${current.name})`}
      setOpen={setOpen}
      isLoading={isLoading}
      onClikHandler={onClikHandler}
      data={true}
      hasChanged={hasChanged}
      setHasChanged={setHasChanged}
      currentItemType={current.itemType}
      itemType={itemType}
      setItemType={setItemType}
      expirationDate={expirationDate}
      setExpirationDate={setExpirationDate}
      monthsValue={monthsValue}
      setMonths={setMonths}
      rentalData={rentalData}
      setRentalData={setRentalData}
      setFormRental={setFormRental}
      dataService={dataService}
      setDataService={setDataService}
      setFormService={setFormService}
      dataFreeItem={dataFreeItem}
      setDataFreeItem={setDataFreeItem}
      setFormFreeItem={setFormFreeItem}
    />
  );
};

export default EditItem;
