import React, { useState } from "react";
import { useDispatch } from "react-redux";
import Form from "./Form";
import { addCategory } from "../../Redux/Action/categoriesActions";

const AddCategory = ({ id, token, setOpen }) => {
  const dispatch = useDispatch();

  const [isLoading, setIsLoading] = useState(false);

  const postCategory = (data) => {
    setIsLoading(true);
    dispatch(addCategory(id, token, data, setOpen, setIsLoading));
  };

  return (
    <Form
      title="Nueva categoría"
      setOpen={setOpen}
      isLoading={isLoading}
      onClikHandler={postCategory}
      hasChanged={true}
    />
  );
};

export default AddCategory;
