import {
  GET_CONSORTIUMS,
  ADD_CONSORTIUM,
  EDIT_CONSORTIUM,
  DELETE_CONSORTIUM,
} from "../Action/actionTypes";

const initialState = { consortiums: [] };

export const consortiumsReducer = (state = initialState, action) => {
  switch (action.type) {
    case GET_CONSORTIUMS:
      return {
        ...state,
        consortiums: action.payload,
      };
    case ADD_CONSORTIUM:
      return {
        ...state,
        consortiums: action.payload,
      };
    case EDIT_CONSORTIUM:
      return {
        ...state,
        consortiums: action.payload,
      };
    case DELETE_CONSORTIUM:
      return {
        ...state,
        consortiums: action.payload,
      };
    default:
      return state;
  }
};

export default consortiumsReducer;
