import React, { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { makeStyles } from "@material-ui/core";
import Form from "./Form";
import { editSubcategory } from "../../Redux/Action/subcategoriesActions";
import { getCategories } from "../../Redux/Action/categoriesActions";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    padding: theme.spacing(1),
  },
}));

const EditSubcategory = ({ id, token, setOpen, subcategory }) => {
  const classes = useStyles();
  const dispatch = useDispatch();
  const categories = useSelector((state) => state.categories.categories);

  const [isLoading, setIsLoading] = useState(false);
  const [hasChanged, setHasChanged] = useState(false);

  const onClickHandler = (data) => {
    setIsLoading(true);
    dispatch(
      editSubcategory(
        id,
        token,
        subcategory._id,
        data,
        subcategory,
        setOpen,
        setIsLoading
      )
    );
  };

  useEffect(() => {
    dispatch(getCategories(id, token, setIsLoading));
  }, [id, token, dispatch]);

  return (
    <div className={classes.container}>
      <Form
        categories={categories}
        title="Editar subcategoría"
        setOpen={setOpen}
        isLoading={isLoading}
        onClikHandler={onClickHandler}
        hasChanged={hasChanged}
        setHasChanged={setHasChanged}
        data={subcategory}
      />
    </div>
  );
};

export default EditSubcategory;
