import axios from "axios";
import { GET_DATA_ESTABLISHMENT, EDIT_DATA_ESTABLISHMENT } from "./actionTypes";
import { setSnackData } from "./snackDataActions";

export const getEstablishmentData =
  (token, setIsLoading, setImage) => (dispatch) => {
    axios
      .get(`${process.env.REACT_APP_BACKEND_URL}/establishment`, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((res) => {
        dispatch({
          type: GET_DATA_ESTABLISHMENT,
          payload: res.data,
        });
        if (setIsLoading) setIsLoading(false);
        if (setImage) setImage(res.data.image);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const editEstablishmentData =
  (token, data, setEdit, setIsLoading) => (dispatch, getState) => {
    let aux = getState().establishment.establishment;
    let establishment = { ...aux };

    const formData = new FormData();

    for (let key in data) {
      formData.append(key, data[key]);
    }

    axios
      .put(`${process.env.REACT_APP_BACKEND_URL}/establishment`, formData, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((res) => {
        data.image = res.data.image;

        establishment = Object.assign(establishment, data);

        dispatch({
          type: EDIT_DATA_ESTABLISHMENT,
          payload: establishment,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Establecimiento actualizado",
            severity: "success",
          })
        );

        if (setEdit) setEdit(false);
        if (setIsLoading) setIsLoading(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };
