import React, { useState, useEffect, Fragment } from "react";
import {
  Container,
  IconButton,
  makeStyles,
  Tooltip,
  Button,
  Hidden,
} from "@material-ui/core";
import AddIcon from "@material-ui/icons/Add";
import ReloadIcon from "@material-ui/icons/Cached";
import Tabs from "../components/Shared/Tabs";
import { useHistory, useParams } from "react-router-dom";

import Modal from "../components/Shared/Modal";
import ListFunctionalUnits from "../components/FunctionalUnits/List";
import ListExpenditures from "../components/Expenditure/List";
import ExpenditureTypes from "../components/ExpendituresTypes/ExpenditureTypes";
import Categories from "../components/Categories/Categories";
import Subcategories from "../components/Subcategories/Subcategories";
import Expenses from "../components/Expenses/Expenses";

import DataUF from "../components/FunctionalUnits/DataUF/Data";

import AddFunctionalUnit from "../components/FunctionalUnits/AddFunctionalUnit";
import AddExpenditure from "../components/Expenditure/AddExpenditure";

import { useSelector, useDispatch } from "react-redux";
import { getConsortiums } from "../Redux/Action/consortiumsActions";
import { getFunctionalUnits } from "../Redux/Action/functionalUnitsActions";
import { getExpenditures } from "../Redux/Action/expendituresActions";
import { getExpenses } from "../Redux/Action/expensesActions";

import Spinner from "../components/UI/Spinner";

import Boxes from "../components/Boxes/Boxes";
import { getBoxes } from "../Redux/Action/boxesActions";
import PageHeader from "../components/UI/PageHeader";
import AddExpense from "../components/Expenses/AddExpense";
import { getCategories } from "../Redux/Action/categoriesActions";
import { getProviders } from "../Redux/Action/providersActions";
import BackButtonComponent from "../components/Shared/BackButtonComponent";

const useStyles = makeStyles((theme) => ({
  root: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    marginTop: theme.spacing(2),
    marginBottom: theme.spacing(2),
  },
  container: {
    width: "100%",
    display: "flex",
    marginBottom: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "space-between",
  },
  containerAux: {
    alignItems: "center",
    "@media (max-width:830px)": {
      flexDirection: "column",
    },
  },
  tabsContainer: {
    "@media (max-width:830px)": {
      width: "100%",
    },
  },
  actionsButtons: {
    display: "flex",
    alignItems: "center",
  },
  actionsButtonsAux: {
    justifyContent: "flex-end",
    "@media (max-width:830px)": {
      marginTop: theme.spacing(1),
      width: "100%",
    },
  },
  reload: {
    padding: theme.spacing(0.75),
    marginRight: theme.spacing(2.5),
  },
  add: {
    padding: theme.spacing(0.75),
  },
}));

const TabPanel = ({ children, value, index }) => {
  return (
    <div id={`tabPanel${index}`} style={{ width: "100%", display: "contents" }}>
      {value === index && children}
    </div>
  );
};

const ConsortiumDetails = ({ user }) => {
  const classes = useStyles();
  const dispatch = useDispatch();

  const history = useHistory();

  const expendituresTypes = useSelector(
    (state) => state.expendituresTypes.expendituresTypes
  );
  const expenses = useSelector((state) => state.expenses.expenses);
  const filteredExpenses = useSelector(
    (state) => state.expenses.filteredExpenses
  );
  const consortiums = useSelector((state) => state.consortiums.consortiums);
  const expenditures = useSelector((state) => state.expenditures.expenditures);
  const categories = useSelector((state) => state.categories.categories);
  const providers = useSelector((state) => state.providers.providers);
  const functionalUnits = useSelector(
    (state) => state.functionalunits.functionalUnits
  );

  const expensesComplete = expenses.concat(filteredExpenses);

  const params = useParams();
  const { id } = params;
  const labels = ["UF", "Gastos", ...(user.isAdmin ? ["Expensas"] : [])];

  const [isLoading, setIsLoading] = useState(true);
  const [isLoadingComponent, setIsLoadingComponent] = useState(true);
  const [open, setOpen] = useState(false);
  const [value, setValue] = useState(0);
  const [currentUF, setCurrentUF] = useState();
  const [UFViews, setUFViews] = useState({
    functionalUnitData: false,
  });

  const [menuItems, setMenuItems] = useState({
    "UF y gastos": true,
    Cajas: false,
    "Clase de gastos": false,
    Categorias: false,
    Subcategorias: false,
  });

  const consortium = consortiums.filter((entry) => entry._id === id);

  const handleChange = (e) => {
    if (value !== e) {
      setIsLoadingComponent(true);
      setValue(e);
    }
  };

  const [anchorEl, setAnchorEl] = React.useState(null);

  const handleClose = () => {
    setAnchorEl(null);
  };

  const onClickHandler = (item, current) => {
    let menu = menuItems;
    let views = UFViews;

    if (current) {
      setCurrentUF(current);
    }

    if (Object.entries(UFViews).some((entry) => entry[0] === item)) {
      for (let key in menu) {
        menu[key] = false;
      }

      for (let key in views) {
        if (key === item) {
          views[key] = true;
        } else {
          views[key] = false;
        }
      }
    } else {
      for (let key in views) {
        views[key] = false;
      }

      for (let key in menu) {
        if (key === item) {
          menu[key] = true;
        } else {
          menu[key] = false;
        }
      }
    }

    setUFViews({ ...UFViews, ...views });
    setMenuItems({ ...menuItems, ...menu });
    handleClose();

    if (item === "UF y gastos") {
      setValue(0);
      setIsLoadingComponent(true);
      dispatch(getConsortiums(user.token));
      dispatch(getExpenses(id, user.token, setIsLoadingComponent));
    }
  };

  const buttonsActions = {
    0: {
      title:
        expendituresTypes.length <= 0
          ? "Es necesario cargar una o más clases de gastos"
          : "Agregar",
      disabled: !expendituresTypes.length > 0,
    },

    1: {
      title:
        categories.length <= 0
          ? "Es necesario cargar categorias"
          : providers.length <= 0
          ? "Es necesario cargar proveedores"
          : "Agregar",
      disabled: categories.length > 0 && providers.length > 0 ? false : true,
    },

    2: {
      title:
        expendituresTypes.length <= 0
          ? "Es necesario cargar gastos"
          : functionalUnits.length <= 0
          ? "Es necesario cargar UF"
          : "Generar expensa",
      disabled:
        expendituresTypes.length > 0 && functionalUnits.length > 0
          ? false
          : true,
    },
  };

  const reloadActions = {
    0: () => {
      setIsLoadingComponent(true);
      dispatch(getFunctionalUnits(id, user.token, setIsLoadingComponent));
      dispatch(getExpenses(id, user.token, setIsLoadingComponent));
    },
    1: () => {
      setIsLoadingComponent(true);
      dispatch(getExpenditures(id, user.token, setIsLoadingComponent));
    },
    2: () => {
      setIsLoadingComponent(true);
      dispatch(getExpenses(id, user.token, setIsLoadingComponent));
    },
  };

  const addActions = {
    0: (
      <AddFunctionalUnit
        id={id}
        token={user.token}
        setOpen={setOpen}
        expendituresTypes={expendituresTypes}
      />
    ),
    1: (
      <AddExpenditure
        id={id}
        token={user.token}
        setOpen={setOpen}
        expendituresTypes={expendituresTypes}
      />
    ),
    2: (
      <AddExpense
        id={id}
        token={user.token}
        setOpen={setOpen}
        expendituresTypes={expendituresTypes}
        expenditures={expenditures}
        establishment={consortium.length > 0 ? consortium[0].establishment : ""}
      />
    ),
  };

  useEffect(() => {
    if (user.isAdmin) {
      dispatch(getProviders(user.token));
    }
    dispatch(getConsortiums(user.token));
    dispatch(getExpenses(id, user.token));
    dispatch(getExpenditures(id, user.token));
    dispatch(getCategories(id, user.token));
    dispatch(getFunctionalUnits(id, user.token));
    dispatch(getBoxes(id, user.token, setIsLoading));
  }, [id, user.token, user.isAdmin, dispatch]);

  return (
    <Container className={classes.root} maxWidth="xl">
      {isLoading ? (
        <Spinner />
      ) : (
        <Fragment>
          {UFViews["functionalUnitData"] ? (
            <BackButtonComponent
              title="Volver al consorcio"
              onClick={() => onClickHandler("UF y gastos", null)}
            />
          ) : (
            <BackButtonComponent
              title="Volver a consorcios"
              onClick={() => history.push("/consorcios")}
            />
          )}
          <PageHeader
            user={user}
            title={
              consortium.length > 0
                ? UFViews["functionalUnitData"]
                  ? `${consortium[0].name} - ${currentUF.apartment}`
                  : consortium[0].name
                : "¡Consorcio inexistente!"
            }
            enabledConfigMenu={
              !Object.entries(UFViews).some((entry) => entry[1] === true)
            }
            titleConfig="Configuración de consorcio"
            menuItems={menuItems}
            anchorEl={anchorEl}
            setAnchorEl={setAnchorEl}
            handleClose={handleClose}
            onClickHandler={onClickHandler}
          />
          {menuItems["UF y gastos"] && (
            <Fragment>
              <div
                className={`${classes.container} ${
                  user.isAdmin && classes.containerAux
                }`}
              >
                <div className={`${user.isAdmin && classes.tabsContainer}`}>
                  <Tabs
                    value={value}
                    setValue={(e) => handleChange(e)}
                    labels={labels}
                    variant={user.isAdmin ? "fullWidth" : null}
                  />
                </div>
                <div
                  className={`${classes.actionsButtons} ${
                    user.isAdmin && classes.actionsButtonsAux
                  }`}
                >
                  <Tooltip title="Recargar tabla">
                    <IconButton
                      className={classes.reload}
                      variant="contained"
                      aria-label="add"
                      onClick={reloadActions[value]}
                    >
                      <ReloadIcon />
                    </IconButton>
                  </Tooltip>
                  {user.isAdmin && (
                    <Fragment>
                      <Hidden xsDown>
                        <Tooltip title={buttonsActions[value].title}>
                          <div>
                            <Button
                              disabled={buttonsActions[value].disabled}
                              variant="contained"
                              disableElevation
                              startIcon={<AddIcon />}
                              onClick={() => setOpen(true)}
                            >
                              {value === 2 ? "Generar expensa" : "Agregar"}
                            </Button>
                          </div>
                        </Tooltip>
                      </Hidden>
                      <Hidden smUp>
                        <Tooltip title={buttonsActions[value].title}>
                          <div>
                            <IconButton
                              disabled={buttonsActions[value].disabled}
                              className={classes.reload}
                              variant="contained"
                              aria-label="add"
                              onClick={() => setOpen(true)}
                            >
                              <AddIcon />
                            </IconButton>
                          </div>
                        </Tooltip>
                      </Hidden>
                    </Fragment>
                  )}
                </div>
              </div>
              <TabPanel value={value} index={0}>
                <ListFunctionalUnits
                  UFViews={UFViews}
                  setUFViews={setUFViews}
                  onClickHandler={onClickHandler}
                  id={id}
                  user={user}
                  isLoadingComponent={isLoadingComponent}
                  setIsLoadingComponent={setIsLoadingComponent}
                />
              </TabPanel>
              <TabPanel value={value} index={1}>
                <ListExpenditures
                  establishment={
                    consortium.length > 0 ? consortium[0].establishment : ""
                  }
                  id={id}
                  user={user}
                  isLoadingComponent={isLoadingComponent}
                  setIsLoadingComponent={setIsLoadingComponent}
                  expendituresTypes={expendituresTypes}
                />
              </TabPanel>
              <TabPanel value={value} index={2}>
                <Expenses
                  establishment={
                    consortium.length > 0 ? consortium[0].establishment : ""
                  }
                  id={id}
                  token={user.token}
                  isLoadingComponent={isLoadingComponent}
                  setIsLoadingComponent={setIsLoadingComponent}
                  expendituresTypes={expendituresTypes}
                />
              </TabPanel>
              <Modal
                handleClose={() => setOpen(false)}
                open={open}
                component={addActions[value]}
              />
            </Fragment>
          )}
          {menuItems["Cajas"] && <Boxes id={id} token={user.token} />}
          {menuItems["Clase de gastos"] && (
            <ExpenditureTypes id={id} token={user.token} />
          )}
          {menuItems["Categorias"] && <Categories id={id} token={user.token} />}
          {menuItems["Subcategorias"] && (
            <Subcategories id={id} token={user.token} />
          )}
          {UFViews["functionalUnitData"] && (
            <DataUF
              id={id}
              user={user}
              currentUF={currentUF}
              expenses={expensesComplete}
              expendituresTypes={expendituresTypes}
              onClickHandler={onClickHandler}
            />
          )}
        </Fragment>
      )}
    </Container>
  );
};

export default ConsortiumDetails;
