import React from "react";
import { makeStyles } from "@material-ui/core/styles";
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableRow,
  Paper,
  TableHead,
} from "@material-ui/core";

import { NumberFormatCustom } from "../../hooks/format-number-hook";

const useStyles = makeStyles((theme) => ({
  tableContainer: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    justifyContent: "space-between",
    boxShadow: "none",
    backgroundColor: "#F7F9F8",
    border: "1px solid #E6EBE8",
    borderRadius: 12,
    padding: theme.spacing(1, 1.25),
    maxHeight: 200,

    "& .MuiTableCell-head": {
      color: "#000000",
      fontSize: "14px",
      lineHeight: "20px",
      letterSpacing: "0.02em",
      padding: theme.spacing(1),
    },

    "& .MuiTableCell-body": {
      color: "#000000",
      fontSize: "14px",
      lineHeight: "20px",
      letterSpacing: "0.02em",
      padding: theme.spacing(1),
      borderColor: "#E6EBE8",
    },
  },
}));

const ItemsTable = ({ items }) => {
  const classes = useStyles();

  const getDate = (date) => {
    let aux = new Date(date);

    return `${aux.getDate()}/${aux.getMonth() + 1}/${aux.getFullYear()}`;
  };

  return (
    <TableContainer className={classes.tableContainer} component={Paper}>
      <Table aria-label="simple table">
        <TableHead>
          <TableRow>
            <TableCell align="center">Tipo</TableCell>
            <TableCell align="center">Dirección</TableCell>
            <TableCell align="center">Mes</TableCell>
            <TableCell align="center">Vencimiento</TableCell>
            <TableCell align="center">Importe</TableCell>
            <TableCell align="center">Honorarios</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {items.map((entry, index) => (
            <TableRow key={index}>
              <TableCell
                align="center"
                component="th"
                scope="row"
                style={
                  index + 1 === items.length ? { borderBottom: "none" } : null
                }
              >
                {entry.item
                  ? entry.item.name
                  : `${entry.concept} - (Descuento)`}
              </TableCell>
              <TableCell
                align="center"
                component="th"
                scope="row"
                style={
                  index + 1 === items.length ? { borderBottom: "none" } : null
                }
              >
                {entry.address}
              </TableCell>
              <TableCell
                align="center"
                component="th"
                scope="row"
                style={
                  index + 1 === items.length ? { borderBottom: "none" } : null
                }
              >
                {entry.item ? getDate(entry.item.date) : "-"}
              </TableCell>
              <TableCell
                align="center"
                component="th"
                scope="row"
                style={
                  index + 1 === items.length ? { borderBottom: "none" } : null
                }
              >
                {entry.item ? getDate(entry.item.expirationDate) : "-"}
              </TableCell>

              <TableCell
                align="center"
                component="th"
                scope="row"
                style={
                  index + 1 === items.length ? { borderBottom: "none" } : null
                }
              >
                {NumberFormatCustom(
                  entry.amount.amount !== undefined
                    ? entry.amount.amount + entry.amount.tax
                    : entry.amount
                )}
              </TableCell>
              <TableCell
                align="center"
                component="th"
                scope="row"
                style={
                  index + 1 === items.length ? { borderBottom: "none" } : null
                }
              >
                {entry.amount.fee ? NumberFormatCustom(entry.amount.fee) : "-"}
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
};

export default ItemsTable;
