import React, { useState, Fragment } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  makeStyles,
  useMediaQuery,
  useTheme,
  Grid,
  Typography,
  Button,
  TextField,
} from "@material-ui/core";
import { deleteExpense } from "../../Redux/Action/expensesActions";
import Spinner from "../UI/Spinner";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    padding: theme.spacing(1),
  },
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  marginBottom: {
    marginBottom: theme.spacing(2.5),
  },
  color: {
    color: "#CA0303",
  },
}));

const DeleteExpense = ({ id, setOpen, expense }) => {
  const classes = useStyles();
  const dispatch = useDispatch();
  const user = useSelector((state) => state.user.userData);

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const [name, setName] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [confirmDelete, setConfirm] = useState({
    step: 1,
    firstStepConfirmed: false,
  });

  const validate =
    confirmDelete.step === 1 ? true : name === expense.name ? true : false;

  const onClickHandler = () => {
    if (!confirmDelete.firstStepConfirmed) {
      setConfirm({ ...confirmDelete, step: 2, firstStepConfirmed: true });
    } else {
      setIsLoading(true);
      dispatch(
        deleteExpense(id, user.token, expense._id, setOpen, setIsLoading)
      );
    }
  };

  return isLoading ? (
    <Spinner height={340} />
  ) : (
    <div className={classes.container}>
      <Typography variant="h6">{`Eliminar expensa (paso ${confirmDelete.step})`}</Typography>
      <Grid container className={classes.grid} spacing={1}>
        {!confirmDelete.firstStepConfirmed ? (
          <Grid item xs={12}>
            <Typography className={classes.marginBottom}>
              {`¿Está seguro que deseas eliminar esta expensa?`}
            </Typography>
          </Grid>
        ) : (
          <Fragment>
            <Typography className={classes.marginBottom}>
              Esta acción no se puede deshacer. Esto eliminará permanentemente
              la expensa{" "}
              <span className={classes.color}>{`"${expense.name}"`}</span>.
            </Typography>
            <Typography className={classes.marginBottom}>
              Escriba <span className={classes.color}>{`${expense.name}`}</span>{" "}
              para confirmar
            </Typography>
            <Grid item xs={12}>
              <TextField
                className={classes.marginBottom}
                value={name}
                required
                autoComplete="off"
                fullWidth
                id="name"
                name="name"
                label="Nombre de la expensa"
                inputProps={{
                  maxLength: expense.name.length,
                  pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
                }}
                onChange={(e) => setName(e.target.value)}
                InputLabelProps={{ required: false }}
              />
            </Grid>
          </Fragment>
        )}
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            id="cancel-button"
            variant="outlined"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Cancelar
          </Button>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            disabled={!validate}
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={onClickHandler}
          >
            Aceptar
          </Button>
        </Grid>
      </Grid>
    </div>
  );
};

export default DeleteExpense;
