import React, { useEffect } from "react";
import { Button, Grid, makeStyles, TextField } from "@material-ui/core";
import Spinner from "../UI/Spinner";
import { useForm } from "../../hooks/use-form";
import SelectImage from "../Shared/SelectImage";

const useStyles = makeStyles((theme) => ({
  container: {
    flex: "1",
    display: "flex",
    flexDirection: "column",
    width: "100%",
    height: "100%",
    justifyContent: "space-around",
  },
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  imageContainer: {
    width: "100%",
    height: "100%",
    paddingBottom: theme.spacing(2),
  },
  marginBottom: {
    marginBottom: theme.spacing(2.5),
  },

  buttons: {
    marginTop: theme.spacing(3),
    justifyContent: "flex-end",
    alignItems: "center",
  },
}));

const initialState = {
  name: "",
  address: "",
  phone: "",
  email: "",
};

const Form = ({
  data,
  image,
  setImage,
  edit,
  isLoading,
  onClickHandler,
  hasChanged,
  setHasChanged,
  isMobile,
}) => {
  const classes = useStyles();

  const [form, onChangeHandler, setForm] = useForm(initialState);

  const onChangeData = () => {
    if (setHasChanged && hasChanged === false) {
      setHasChanged(true);
    }
  };

  const onCLick = () => {
    let data = {};

    for (let key in form) {
      data[key] = form[key].value;
    }

    onClickHandler(data, setForm);
  };

  const onImageChangeHandler = (e) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      if (
        file.type === "image/jpeg" ||
        file.type === "image/jpg" ||
        file.type === "image/png"
      ) {
        setImage(file);
      }
    }
    onChangeData();
  };

  const deleteImageHandler = () => {
    setImage(null);
    onChangeData();
  };

  let disabled =
    hasChanged &&
    Object.entries(form).filter(
      (entry) => entry[1].value === "" || entry[1].isValid === false
    ).length === 0
      ? false
      : true;

  useEffect(() => {
    if (!edit) {
      setForm((form) => {
        let copy = { ...form };
        for (let key in form) {
          copy[key] = { value: data[key] || "", isValid: true };
        }
        return copy;
      });

      setHasChanged(false);
    }
  }, [data, edit, setForm, setHasChanged]);

  return isLoading ? (
    <Spinner />
  ) : (
    <div className={classes.container}>
      <Grid container className={classes.grid} spacing={2}>
        <Grid item xs={12}>
          <div className={classes.imageContainer}>
            <SelectImage
              heigth={250}
              width={isMobile ? "auto" : 250}
              image={image}
              setImage={onImageChangeHandler}
              deleteImage={deleteImageHandler}
              textImage="Seleccione una imagen"
              onlyPreview={!edit}
              establishment={data._id}
            />
          </div>
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            disabled={!edit}
            className={classes.marginBottom}
            value={form.name.value}
            required
            autoComplete="off"
            fullWidth
            id="name"
            name="name"
            label="Nombre"
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            inputProps={{
              minLength: 2,
              maxLength: 100,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
            }}
            error={!form.name.isValid}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            disabled={!edit}
            className={classes.marginBottom}
            value={form.address.value}
            required
            autoComplete="off"
            fullWidth
            id="address"
            name="address"
            label="Dirección"
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            inputProps={{
              minLength: 2,
              maxLength: 100,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
            }}
            error={!form.address.isValid}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            disabled={!edit}
            className={classes.marginBottom}
            value={form.phone.value}
            required
            type="tel"
            autoComplete="off"
            fullWidth
            id="phone"
            name="phone"
            label="Telefono"
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            inputProps={{
              maxLength: 20,
              pattern: "^[0-9()-+]+$",
            }}
            error={!form.phone.isValid}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            disabled={!edit}
            className={classes.marginBottom}
            value={form.email.value}
            required
            autoComplete="off"
            fullWidth
            id="email"
            name="email"
            label="Email"
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            inputProps={{
              pattern: "[a-z0-9._%+-]+@[a-z0-9.-]+.[a-z]{2,4}$",
            }}
            error={!form.email.isValid}
            InputLabelProps={{ required: false }}
          />
        </Grid>
      </Grid>

      <Grid container className={classes.buttons} spacing={1}>
        <Grid item xs={12} sm={3}>
          <Button
            disabled={!edit || disabled}
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={onCLick}
          >
            Aceptar
          </Button>
        </Grid>
      </Grid>
    </div>
  );
};

export default Form;
