import React, { useState, Fragment, useEffect } from "react";

import Spinner from "../UI/Spinner";
import Table from "../Shared/Table";
import Modal from "../Shared/Modal";

import { TableCell } from "@material-ui/core";
import { useDispatch, useSelector } from "react-redux";
import { getEstates } from "../../Redux/Action/estatesActions";
import DeleteService from "./DeleteService";
import EditService from "./EditService";

const Cells = ({ row }) => {
  return (
    <Fragment>
      <TableCell component="th" scope="row">
        {row.name}
      </TableCell>
    </Fragment>
  );
};

const Services = ({ user, isLoadingComponent, setIsLoadingComponent }) => {
  const dispatch = useDispatch();
  const [open, setOpen] = useState(false);
  const [current, setCurrent] = useState(null);
  const [action, setAction] = useState();

  const columns = ["Nombre", "Editar", "Eliminar"];

  const rows = useSelector((state) => state.services.services);

  const deleteAction = (current) => {
    setCurrent(current);
    setOpen(true);
  };

  const editAction = (current) => {
    setCurrent(current);
    setOpen(true);
  };

  const actions = {
    edit: <EditService user={user} setOpen={setOpen} current={current} />,
    delete: <DeleteService setOpen={setOpen} current={current} />,
  };

  useEffect(() => {
    dispatch(getEstates(user.token));
  }, [dispatch, user.token, setIsLoadingComponent]);

  return isLoadingComponent ? (
    <Spinner />
  ) : (
    <Fragment>
      <Table
        columns={columns}
        rows={rows}
        Cells={Cells}
        disableColumnDetails={true}
        deleteAction={deleteAction}
        editAction={editAction}
        setAction={setAction}
      />
      <Modal
        handleClose={() => setOpen(false)}
        open={open}
        component={actions[action]}
      />
    </Fragment>
  );
};

export default Services;
