import React from "react";
import { Redirect, Switch } from "react-router-dom";
import { PrivateRoute } from "../helperRoutes";

// Paginas
import ConsortiumPage from "../../pages/ConsortiumPage";
import ConsortiumDetails from "../../pages/ConsortiumDetails";

const UserRoutes = ({ user }) => {
  return (
    <Switch>
      <PrivateRoute
        exact
        path="/consorcios"
        component={() => <ConsortiumPage user={user} />}
        user={user}
      />
      <PrivateRoute
        exact
        path="/consorcios/:id/detalles"
        component={() => <ConsortiumDetails user={user} />}
        user={user}
      />
      <Redirect path="/**" to="/consorcios" />
    </Switch>
  );
};

export default UserRoutes;
