import React, { useState, useEffect } from "react";
import { TableCell } from "@material-ui/core";
import Table from "../Shared/Table";
import Modal from "../Shared/Modal";

import Spinner from "../UI/Spinner";

import { getFormatDate } from "../../hooks/date-hook";
import DeletePayment from "./DeletePayment";
import { useDispatch, useSelector } from "react-redux";
import { getPayments } from "../../Redux/Action/paymentsActions";
import { NumberFormatCustom } from "../../hooks/format-number-hook";

const Cells = ({ row, boxes, isAdmin }) => {
  let name = boxes.filter((entry) => entry._id === row.box)[0].name;
  return (
    <>
      <TableCell component="th" scope="row">
        {getFormatDate(row.date)}
      </TableCell>
      <TableCell component="th" scope="row">
        {name}
      </TableCell>
      <TableCell
        component="th"
        scope="row"
        align={isAdmin ? "left" : "center"}
      >
        {NumberFormatCustom(row.amount.toString().replace(/\./g, ","))}
      </TableCell>
    </>
  );
};

const Payments = ({
  id,
  user,
  currentUF,
  boxes,
  isLoadingComponent,
  setIsLoadingComponent,
}) => {
  const dispatch = useDispatch();
  const [open, setOpen] = useState(false);
  const [action, setAction] = useState(false);
  const [current, setCurrent] = useState();

  const columns = [
    "Fecha",
    "Caja",
    "Monto",
    ...(user.isAdmin ? ["Eliminar"] : []),
  ];

  const payments = useSelector((state) => state.payments.payments).sort(
    (a, b) => {
      let dateA = new Date(a.date);
      let dateB = new Date(b.date);

      if (dateA.getTime() > dateB.getTime()) {
        return -1;
      }
      if (dateA.getTime() < dateB.getTime()) {
        return 1;
      }

      return 0;
    }
  );

  const deletePayment = (current) => {
    setCurrent(current);
    setAction("delete");
    setOpen(true);
  };

  const actions = {
    delete: (
      <DeletePayment
        id={id}
        token={user.token}
        setOpen={setOpen}
        payment={current}
      />
    ),
  };

  useEffect(() => {
    dispatch(getPayments(id, currentUF._id, user.token, setIsLoadingComponent));
  }, [currentUF, dispatch, id, user.token, setIsLoadingComponent]);

  return isLoadingComponent ? (
    <Spinner />
  ) : (
    <>
      <Table
        columns={columns}
        rows={payments}
        Cells={(row) => (
          <Cells row={row.row} boxes={boxes} isAdmin={user.isAdmin} />
        )}
        disableColumnDetails={true}
        disableColumnEdit={true}
        disableColumnDelete={!user.isAdmin}
        deleteAction={deletePayment}
        setAction={setAction}
      />
      <Modal
        handleClose={() => setOpen(false)}
        open={open}
        component={actions[action]}
      />
    </>
  );
};

export default Payments;
