import React, { useState, useEffect } from "react";
import { TableCell } from "@material-ui/core";
import Table from "../../../Shared/Table";
import Modal from "../../../Shared/Modal";

import DetailsExpense from "./Details";

import Spinner from "../../../UI/Spinner";

import { getFormatDate } from "../../../../hooks/date-hook";
import { NumberFormatCustom } from "../../../../hooks/format-number-hook";

const columns = ["Fecha", "Titulo", "Monto", "Detalles"];

const Cells = ({ currentUF, row }) => {
  let aux = row.functionalUnits.filter(
    (entry) => entry.functionalUnit === currentUF._id
  );

  return (
    <>
      <TableCell component="th" scope="row">
        {getFormatDate(row.date)}
      </TableCell>
      <TableCell component="th" scope="row">
        {row.name ? row.name : "Expensa sin titulo"}
      </TableCell>
      <TableCell component="th" scope="row">
        {NumberFormatCustom(aux[0].totalAmount.toString().replace(/\./g, ","))}
      </TableCell>
    </>
  );
};

const Expenses = ({
  expenses,
  currentUF,
  expendituresTypes,
  isLoadingComponent,
  setIsLoadingComponent,
}) => {
  const [open, setOpen] = useState(false);
  const [action, setAction] = useState(false);
  const [current, setCurrent] = useState();
  const [rows, setRows] = useState([]);

  const detailsExpense = (current) => {
    setCurrent(current);
    setAction("details");
    setOpen(true);
  };

  const actions = {
    details: (
      <DetailsExpense
        setOpen={setOpen}
        currentUF={currentUF}
        expense={current}
        expendituresTypes={expendituresTypes}
      />
    ),
  };

  useEffect(() => {
    (async () => {
      let aux = [];

      for (let i = 0; i < expenses.length; i++) {
        expenses[i].functionalUnits.some(
          (entry) => entry.functionalUnit === currentUF._id
        ) && aux.push(expenses[i]);
      }

      aux.sort((a, b) => {
        let dateA = new Date(a.date);
        let dateB = new Date(b.date);

        if (dateA.getTime() > dateB.getTime()) {
          return -1;
        }
        if (dateA.getTime() < dateB.getTime()) {
          return 1;
        }

        return 0;
      });

      setRows(aux);
      setIsLoadingComponent(false);
    })();
  }, [currentUF, expenses, setIsLoadingComponent]);

  return isLoadingComponent ? (
    <Spinner />
  ) : (
    <>
      <Table
        columns={columns}
        rows={rows}
        Cells={(row) => <Cells row={row.row} currentUF={currentUF} />}
        detailsAction={detailsExpense}
        disableColumnEdit={true}
        disableColumnDelete={true}
        setAction={setAction}
      />
      <Modal
        handleClose={() => setOpen(false)}
        open={open}
        component={actions[action]}
      />
    </>
  );
};

export default Expenses;
