import React, { Fragment, useState } from "react";
import {
  Button,
  Grid,
  makeStyles,
  TextField,
  Typography,
  useMediaQuery,
  useTheme,
  Tooltip,
  IconButton,
  FormControl,
  InputLabel,
  Input,
} from "@material-ui/core";
import AddIcon from "@material-ui/icons/Add";
import AddContact from "../Schedule/AddContact";
import Spinner from "../UI/Spinner";
import { useForm } from "../../hooks/use-form";
import ContactsAutoComplete from "../Shared/ContactsAutoComplete";
import Modal from "../Shared/Modal";
import NumberFormat from "react-number-format";
import DatePicker from "../Shared/DatePicker";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    width: theme.spacing(50),
    padding: theme.spacing(5),
    "@media (max-width:650px)": {
      width: theme.spacing(30),
      padding: theme.spacing(1),
    },
    "@media (max-width:400px)": {
      width: theme.spacing(20),
      padding: 0,
    },
  },
  grid: {
    marginTop: theme.spacing(2),

    "& .MuiFormLabel-root": { width: "max-content" },
  },
  textField: {
    "& .MuiSelect-icon": {
      color: theme.palette.secondary.main,
    },
    "& .MuiInputBase-input": {
      height: "auto",
    },
    "& .MuiSelect-selectMenu": {
      minHeight: "auto",
    },
  },
  contact: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "flex-end",
  },
  addButton: {
    marginTop: theme.spacing(2),
    marginLeft: theme.spacing(1),
    padding: theme.spacing(0.5),
  },
  formControl: {
    width: "100%",
  },
  expendituresSection: {
    display: "flex",
    marginTop: theme.spacing(2),
    marginBottom: theme.spacing(2),
  },
  title: {
    fontSize: "14px",
  },
  buttons: {
    marginTop: theme.spacing(2.5),
  },
}));

function NumberFormatPercentage(decimals) {
  return (props) => {
    const { inputRef, onChange, ...other } = props;

    return (
      <NumberFormat
        {...other}
        getInputRef={inputRef}
        onValueChange={(values) => {
          onChange({
            target: {
              value: values.value,
            },
          });
        }}
        thousandSeparator={["."]}
        decimalSeparator=","
        decimalScale={decimals}
        isNumericString
        suffix="%"
      />
    );
  };
}
const NumberFormatPercentage2 = NumberFormatPercentage(2);
const NumberFormatPercentage4 = NumberFormatPercentage(4);

function NumberFormatCustom(props) {
  const { inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={2}
      isNumericString
      prefix="$"
    />
  );
}

const initialState = {
  number: "",
  centId: "",
  apartment: "",
};

const initialCurrentAccount = {
  initialBalance: "0",
  debtInterest: "",
  debtInterests: "",
  debtDate: null,
};

const Form = ({
  contacts,
  getContacts,
  expenditures,
  setExpenditures,
  title,
  setOpen,
  isLoading,
  onClikHandler,
  data,
  hasChanged,
  setHasChanged,
}) => {
  const classes = useStyles();

  const [form, onChangeHandler] = useForm(
    data
      ? {
          number: data.number,
          centId: data.centId || "",
          apartment: data.apartment,
        }
      : initialState
  );

  const [currentAccount, setCurrentAccount] = useState(
    data
      ? {
          initialBalance: data.initialBalance,
          debtInterest: data.debtInterest,
          debtInterests: data.debtInterests,
          debtDate: data.debtDate ? data.debtDate : null,
        }
      : initialCurrentAccount
  );

  const [openAddContact, setOpenAddContact] = useState(false);

  const [owner, setOwner] = useState(data ? data.owner._id : "");

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const onChangeData = () => {
    if (setHasChanged && hasChanged === false) {
      setHasChanged(true);
    }
  };

  const setPercentage = (id, event) => {
    setExpenditures((expenditures) => {
      let i = expenditures.findIndex((expenditure) => {
        if (expenditure.expenditureType === id) {
          return true;
        }
        return false;
      });

      let copy = [...expenditures];

      if (i !== -1) {
        copy[i].percentage = event.target.value;
      }

      return copy;
    });

    onChangeData();
  };

  const handleDateChange = (date) => {
    let formatDate = date.toISOString();
    onChangeData();
    setCurrentAccount({ ...currentAccount, debtDate: formatDate });
  };

  const formatData = () => {
    let aux = {
      number: form.number.value,
      apartment: form.apartment.value,
      owner: owner,
      expendituresTypesPercentages: expenditures,
    };

    aux.initialBalance = currentAccount.initialBalance;

    if (currentAccount.initialBalance < 0) {
      aux.debtInterest = currentAccount.debtInterest;
      aux.debtInterests = currentAccount.debtInterests;
      aux.debtDate = currentAccount.debtDate;
    }

    if (form.centId.value !== "") {
      aux.centId = form.centId.value;
    }

    onClikHandler(aux);
  };

  let disabled =
    hasChanged &&
    expenditures.length > 0 &&
    owner !== "" &&
    !Object.entries(form)
      .filter((entry) => entry[0] !== "centId")
      .some((entry) => entry[1].value === "" || entry[1].isValid === false) &&
    expenditures.some((entry) => entry.percentage <= 100) &&
    (!isNaN(currentAccount.initialBalance) &&
    currentAccount.initialBalance !== ""
      ? currentAccount.initialBalance < 0
        ? !Object.entries(currentAccount)
            .filter((entry) => entry[0] !== "initialBalance")
            .some((entry) => entry[1] === "" || entry[1] === null)
        : true
      : false)
      ? false
      : true;

  return isLoading ? (
    <Spinner height={621} />
  ) : (
    <div>
      <Typography variant="h6">{title}</Typography>
      <Grid
        container
        className={classes.grid}
        spacing={1}
        justifycontent="center"
      >
        <Grid item xs={12} sm={6}>
          <TextField
            className={classes.textField}
            type="number"
            value={form.number.value}
            required
            autoComplete="off"
            fullWidth
            id="number"
            name="number"
            label="Unidad Funcional"
            inputProps={{
              min: "1",
              pattern: "^[0-9]+",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.number.isValid}
            helperText={
              !form.number.isValid &&
              (form.number.value.length < 2
                ? "Pocos caracteres"
                : "Unidad Funcional inválida")
            }
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <div className={classes.contact}>
            <ContactsAutoComplete
              label="Propietario"
              contacts={contacts}
              contact={owner}
              setState={(value) => {
                if (value) {
                  setOwner(value._id);
                } else {
                  setOwner("");
                }
                onChangeData();
              }}
            />
            <Tooltip title="Agregar contacto">
              <IconButton
                className={classes.addButton}
                variant="contained"
                aria-label="add"
                onClick={() => setOpenAddContact(true)}
              >
                <AddIcon />
              </IconButton>
            </Tooltip>
          </div>
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            className={classes.textField}
            type="number"
            value={form.centId.value}
            autoComplete="off"
            fullWidth
            id="centId"
            name="centId"
            label="Centavos Redondeo"
            inputProps={{
              min: "1",
              max: "99999999999999999999",
              pattern: "^[0-9]+",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.centId.isValid}
            helperText={
              !form.centId.isValid &&
              (form.centId.value.length < 2
                ? "Pocos caracteres"
                : "Centavos ID inválido")
            }
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            className={classes.textField}
            value={form.apartment.value}
            required
            autoComplete="off"
            fullWidth
            id="apartment"
            name="apartment"
            label="Piso y Letra"
            inputProps={{
              minLength: 1,
              maxLength: 10,
              pattern: "^[A-Za-z0-9 ]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.apartment.isValid}
            helperText={
              !form.apartment.isValid &&
              (form.apartment.value.length < 2
                ? "Pocos caracteres"
                : "Piso y Letra inválido")
            }
            InputLabelProps={{ required: false }}
          />
        </Grid>

        <Grid item xs={isMobile ? 6 : 12} sm={6}>
          <TextField
            className={classes.textField}
            InputProps={{
              inputComponent: NumberFormatCustom,
            }}
            required
            autoComplete="off"
            label="Saldo inicial"
            id="balance"
            name="balance"
            value={currentAccount.initialBalance}
            onChange={(e) => {
              setCurrentAccount({
                ...currentAccount,
                initialBalance: e.target.value,
              });
              onChangeData();
            }}
            fullWidth
            inputProps={{
              pattern: "[0-9.]+",
              step: ".01",
            }}
            helperText={
              disabled && currentAccount.initialBalance < 0
                ? "Se requieren los demás campos para continuar "
                : null
            }
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={isMobile ? 6 : 12} sm={6}>
          <TextField
            className={classes.textField}
            disabled={
              !isNaN(currentAccount.initialBalance) &&
              currentAccount.initialBalance < 0
                ? false
                : true
            }
            InputProps={{
              inputComponent: NumberFormatPercentage2,
            }}
            value={currentAccount.debtInterest}
            required
            autoComplete="off"
            fullWidth
            id="debtInterest"
            name="debtInterest"
            label="Interes por dia"
            placeholder="0"
            inputProps={{
              min: "0",
              max: "100",
              pattern: "[0-9]+",
              step: ".01",
            }}
            error={
              currentAccount.debtInterest < 0 ||
              currentAccount.debtInterest > 100
            }
            onChange={(e) => {
              setCurrentAccount({
                ...currentAccount,
                debtInterest: e.target.value,
              });
              onChangeData();
            }}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={isMobile ? 6 : 12} sm={6}>
          <TextField
            className={classes.textField}
            disabled={
              !isNaN(currentAccount.initialBalance) &&
              currentAccount.initialBalance < 0
                ? false
                : true
            }
            InputProps={{
              inputComponent: NumberFormatCustom,
            }}
            required
            autoComplete="off"
            label="Intereses adeudados"
            id="debtInterests"
            name="debtInterests"
            value={currentAccount.debtInterests}
            onChange={(e) => {
              setCurrentAccount({
                ...currentAccount,
                debtInterests: e.target.value,
              });
              onChangeData();
            }}
            fullWidth
            inputProps={{
              min: "0",
              pattern: "[0-9.]+",
              step: ".01",
            }}
            helperText={
              currentAccount.debtInterests < 0 ? "No puede ser negativo" : null
            }
            error={currentAccount.debtInterests < 0 ? true : false}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={isMobile ? 6 : 12} sm={6}>
          <DatePicker
            disabled={
              !isNaN(currentAccount.initialBalance) &&
              currentAccount.initialBalance < 0
                ? false
                : true
            }
            label="Fecha"
            selectedDate={currentAccount.debtDate}
            handleDateChange={(e) => handleDateChange(e)}
          />
        </Grid>
        <Grid item xs={12} className={classes.expendituresSection}>
          <Typography className={classes.title}>Clase de gastos:</Typography>
        </Grid>
        {expenditures &&
          expenditures.length > 0 &&
          expenditures.map((expenditure, index) => (
            <Fragment key={index}>
              <Grid item xs={6}>
                <FormControl style={{ width: "100%" }}>
                  <InputLabel htmlFor="my-input">Clase de gasto</InputLabel>
                  <Input
                    id={`expenditureType-${expenditure.name}`}
                    value={expenditure.name}
                    name={`expenditureType-${expenditure.name}`}
                    fullWidth
                    readOnly={true}
                  />
                </FormControl>
              </Grid>
              <Grid item xs={6}>
                <TextField
                  className={classes.textField}
                  InputProps={{
                    inputComponent: NumberFormatPercentage4,
                  }}
                  value={expenditure.percentage}
                  required
                  autoComplete="off"
                  fullWidth
                  id={`percentaje-${expenditure.name}`}
                  name={`percentaje-${expenditure.name}`}
                  label="Porcentaje"
                  placeholder="0"
                  inputProps={{
                    min: "0",
                    max: "100",
                    pattern: "[0-9]+",
                    step: ".01",
                  }}
                  error={expenditures[index].percentage > 100}
                  onChange={setPercentage.bind(
                    this,
                    expenditure.expenditureType
                  )}
                  InputLabelProps={{ required: false }}
                />
              </Grid>
            </Fragment>
          ))}
      </Grid>
      <Grid container className={classes.buttons} spacing={1}>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            id="cancel-button"
            variant="outlined"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Cancelar
          </Button>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            disabled={disabled}
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={formatData}
          >
            Aceptar
          </Button>
        </Grid>
      </Grid>
      <Modal
        handleClose={() => setOpenAddContact(false)}
        open={openAddContact}
        component={
          <AddContact
            setOpen={(value) => {
              getContacts();
              setOpenAddContact(value);
            }}
            preload={setOwner}
          />
        }
      />
    </div>
  );
};

export default Form;
