import React, { useState, Fragment, useEffect } from "react";

import { Container, IconButton, makeStyles, Tooltip } from "@material-ui/core";

import Spinner from "../components/UI/Spinner";
import BackButtonComponent from "../components/Shared/BackButtonComponent";

import { useDispatch, useSelector } from "react-redux";
import { getContracts } from "../Redux/Action/contractsActions";

import { useParams } from "react-router-dom";
import { useHistory } from "react-router-dom";

import ReloadIcon from "@material-ui/icons/Cached";
import { getReceipts } from "../Redux/Action/receiptsActions";
import Receipts from "../components/Receipts/Receipts";

import Tabs from "../components/Shared/Tabs";
import SettlementReceipts from "../components/Liquidations/SettlementReceipts";
import { getSettlementReceipt } from "../Redux/Action/liquidationsActions";

const useStyles = makeStyles((theme) => ({
  root: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    marginTop: theme.spacing(2),
    marginBottom: theme.spacing(2),
  },
  container: {
    width: "100%",
    display: "flex",
    marginBottom: theme.spacing(2),
    alignItems: "center",
    flexDirection: "row",
    justifyContent: "space-between",
  },
  actionsButtons: {
    display: "flex",
    alignItems: "center",
    justifyContent: "flex-end",
  },
  reload: {
    padding: theme.spacing(0.75),
    "@media (min-width:600px)": {
      marginRight: theme.spacing(2.5),
    },
  },
}));

const ReceiptsPage = ({ user, settlementReceipts }) => {
  const classes = useStyles();

  const dispatch = useDispatch();
  const params = useParams();
  const history = useHistory();

  const { id } = params;

  const labels = ["Comprobantes"];

  const contracts = useSelector((state) => state.contracts.contracts);
  const contract = contracts.filter((entry) => entry._id === id);

  let establishment = contract.length > 0 ? contract[0].establishment : "";

  const [isLoading, setIsLoading] = useState(true);
  const [isLoadingTable, setIsLoadingTable] = useState(false);
  const [value, setValue] = useState(0);

  const handleChange = (e) => {
    setValue(e);
  };

  const reloadItems = () => {
    setIsLoadingTable(true);
    if (!settlementReceipts) {
      dispatch(getReceipts(user.token, id, setIsLoadingTable));
    } else {
      dispatch(getSettlementReceipt(user.token, id, setIsLoadingTable));
    }
  };

  useEffect(() => {
    if (!settlementReceipts) {
      dispatch(getContracts(user.token));
      dispatch(getReceipts(user.token, id, setIsLoading));
    } else {
      dispatch(getSettlementReceipt(user.token, id, setIsLoading));
    }
  }, [dispatch, id, user.token, settlementReceipts]);

  return (
    <Container className={classes.root} maxWidth="xl">
      {isLoading ? (
        <Spinner />
      ) : (
        <Fragment>
          {history.action !== "POP" && (
            <BackButtonComponent
              title="Volver"
              onClick={() => history.goBack()}
              mrgBottom={24}
            />
          )}

          <div className={classes.container}>
            <div>
              <Tabs
                value={value}
                setValue={(e) => handleChange(e)}
                labels={labels}
              />
            </div>
            <div className={classes.actionsButtons}>
              <Tooltip title="Recargar tabla">
                <IconButton
                  className={classes.reload}
                  variant="contained"
                  aria-label="add"
                  onClick={reloadItems}
                >
                  <ReloadIcon />
                </IconButton>
              </Tooltip>
            </div>
          </div>

          {settlementReceipts ? (
            <SettlementReceipts
              user={user}
              idContract={id}
              isLoadingTable={isLoadingTable}
            />
          ) : (
            <Receipts
              user={user}
              establishment={establishment}
              idContract={id}
              isLoadingTable={isLoadingTable}
            />
          )}
        </Fragment>
      )}
    </Container>
  );
};

export default ReceiptsPage;
