import React, { Fragment } from "react";
import {
  Button,
  Grid,
  makeStyles,
  TextField,
  Typography,
  useMediaQuery,
  useTheme,
} from "@material-ui/core";

import Spinner from "../UI/Spinner";
import { useForm } from "../../hooks/use-form";

const useStyles = makeStyles((theme) => ({
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  marginBottom: {
    marginBottom: theme.spacing(2.5),
  },
  buttons: {
    marginTop: theme.spacing(2.5),
    "& .MuiTooltip-tooltip": {
      backgroundColor: "red",
    },
  },
}));

const initialState = {
  name: "",
};

const Form = ({
  data,
  title,
  setOpen,
  isLoading,
  onClikHandler,
  hasChanged,
  setHasChanged,
}) => {
  const classes = useStyles();

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const [form, onChangeHandler] = useForm(
    data
      ? {
          name: data.name,
        }
      : initialState
  );

  const onChangeData = () => {
    if (setHasChanged && hasChanged === false) {
      setHasChanged(true);
    }
  };

  const formatData = () => {
    let data = {
      name: form.name.value,
    };

    onClikHandler(data);
  };

  let disabled =
    hasChanged && form.name.value !== "" && form.name.isValid ? false : true;

  return isLoading ? (
    <Spinner height={232} />
  ) : (
    <Fragment>
      <Typography variant="h6">{title}</Typography>
      <Grid container className={classes.grid} spacing={2}>
        <Grid item xs={12}>
          <TextField
            className={classes.marginBottom}
            value={form.name.value}
            required
            autoComplete="newName"
            fullWidth
            id="name"
            name="name"
            label="Nombre"
            inputProps={{
              minLength: 2,
              maxLength: 100,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.name.isValid}
            helperText={
              !form.name.isValid &&
              (form.name.value.length < 2
                ? "Pocos caracteres"
                : "Nombre inválido")
            }
            InputLabelProps={{ required: false }}
          />
        </Grid>
      </Grid>
      <Grid container className={classes.buttons} spacing={1}>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            id="cancel-button"
            variant="outlined"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Cancelar
          </Button>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            disabled={disabled}
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={formatData}
          >
            Aceptar
          </Button>
        </Grid>
      </Grid>
    </Fragment>
  );
};

export default Form;
