import {
  GET_CONTRACTS,
  ADD_CONTRACT,
  EDIT_CONTRACT,
  DELETE_CONTRACT,
  GET_CONTRACTS_ITEMS,
  ADD_ITEM,
  DELETE_ITEM,
  EDIT_ITEM,
  PAY_ITEM,
  GET_RECEIPTS,
  DELETE_RECEIPT,
} from "../Action/actionTypes";

const initialState = { contracts: [], items: [], receipts: [] };

export const contractsReducer = (state = initialState, action) => {
  switch (action.type) {
    case GET_CONTRACTS:
      return {
        ...state,
        contracts: action.payload,
      };
    case ADD_CONTRACT:
      return {
        ...state,
        contracts: action.payload,
      };
    case EDIT_CONTRACT:
      return {
        ...state,
        contracts: action.payload,
      };
    case DELETE_CONTRACT:
      return {
        ...state,
        contracts: action.payload,
      };
    case GET_CONTRACTS_ITEMS:
      return {
        ...state,
        items: action.payload,
      };
    case ADD_ITEM:
      return {
        ...state,
        items: action.payload,
      };
    case EDIT_ITEM:
      return {
        ...state,
        items: action.payload,
      };
    case DELETE_ITEM:
      return {
        ...state,
        items: action.payload,
      };
    case PAY_ITEM:
      return {
        ...state,
        items: action.payload,
      };
    case GET_RECEIPTS:
      return {
        ...state,
        receipts: action.payload,
      };
    case DELETE_RECEIPT:
      return {
        ...state,
        receipts: action.payload,
      };

    default:
      return state;
  }
};

export default contractsReducer;
