import React, { useState } from "react";
import { useDispatch } from "react-redux";

import Form from "./Form";

import { addBank } from "../../Redux/Action/banksActions";

const AddBank = ({ user, setOpen }) => {
  const dispatch = useDispatch();

  const [isLoading, setIsLoading] = useState(false);

  const onClikHandler = (data) => {
    setIsLoading(true);
    dispatch(addBank(user.token, data, setOpen, setIsLoading));
  };

  return (
    <Form
      title="Nuevo banco"
      setOpen={setOpen}
      isLoading={isLoading}
      onClikHandler={onClikHandler}
      hasChanged={true}
    />
  );
};

export default AddBank;
