import React from "react";
import { Redirect, Switch } from "react-router-dom";
import { PrivateRoute } from "../helperRoutes";

// Paginas
import ConsortiumPage from "../../pages/ConsortiumPage";
import RentalPage from "../../pages/RentalPage";
import Schedule from "../../pages/Schedule";
import Providers from "../../pages/Providers";
import ConsortiumDetails from "../../pages/ConsortiumDetails";
import EmailServer from "../../pages/configurationPages/EmailServer";
import ManagementConfig from "../../pages/configurationPages/ManagementConfig";
import ContractDetails from "../../pages/ContractDetails";
import ReceiptsPage from "../../pages/ReceiptsPage";
import CurrentAccount from "../../pages/CurrentAccount";
import Liquidations from "../../pages/Liquidations";

const AdminRoutes = ({ user }) => {
  return (
    <Switch>
      <PrivateRoute
        exact
        path="/consorcios"
        component={() => <ConsortiumPage user={user} />}
        user={user}
      />
      <PrivateRoute
        exact
        path="/alquileres"
        component={() => <RentalPage user={user} />}
        user={user}
      />
      <PrivateRoute
        exact
        path="/alquileres/contratos/:id/detalles"
        component={() => <ContractDetails user={user} />}
        user={user}
      />
      <PrivateRoute
        exact
        path="/alquileres/contratos/:id/comprobantes"
        component={() => (
          <ReceiptsPage user={user} settlementReceipts={false} />
        )}
        user={user}
      />
      <PrivateRoute
        exact
        path="/contactos"
        component={() => <Schedule user={user} />}
        user={user}
      />
      <PrivateRoute
        exact
        path="/contactos/liquidaciones/:id"
        component={() => <Liquidations user={user} />}
        user={user}
      />
      <PrivateRoute
        exact
        path="/contactos/liquidaciones/:id/comprobantes"
        component={() => <ReceiptsPage user={user} settlementReceipts={true} />}
        user={user}
      />
      <PrivateRoute
        exact
        path="/contactos/:id/cuenta-corriente"
        component={() => <CurrentAccount user={user} />}
        user={user}
      />
      <PrivateRoute
        exact
        path="/proveedores"
        component={() => <Providers />}
        user={user}
      />
      <PrivateRoute
        exact
        path="/consorcios/:id/detalles"
        component={() => <ConsortiumDetails user={user} />}
        user={user}
      />
      <PrivateRoute
        exact
        path="/configuracion/establecimiento"
        component={() => <ManagementConfig user={user} />}
        user={user}
      />
      <PrivateRoute
        exact
        path="/configuracion/servidor-correos"
        component={() => <EmailServer user={user} />}
        user={user}
      />
      <Redirect
        path="/**"
        to={
          user.type && user.type === "realstate" ? "/alquileres" : "/consorcios"
        }
      />
    </Switch>
  );
};

export default AdminRoutes;
