import React, { Fragment, useState } from "react";
import {
  makeStyles,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TablePagination,
  TableRow,
  TableSortLabel,
  Paper,
  IconButton,
} from "@material-ui/core";

import DeleteIcon from "@material-ui/icons/DeleteOutlineOutlined";
import EditIcon from "@material-ui/icons/EditOutlined";
import VisibilityIcon from "@material-ui/icons/VisibilityOutlined";

const useStyles = makeStyles(() => ({
  container: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    justifyContent: "space-between",
    boxShadow: "none",
    border: "1px solid #E6EBE8",
    borderRadius: 12,
    overflow: "hidden",

    "& .MuiTableCell-head": {
      color: "#3D4A57",
      backgroundColor: "#F4F7F5",
      fontWeight: 700,
      fontSize: 12,
      letterSpacing: "0.04em",
      borderBottom: "1px solid #E6EBE8",
    },
  },
  iconButton: {
    padding: 0,
  },
  rowActions: {
    width: "120px",
  },
  paginationContainer: {
    width: "100%",
    backgroundColor: "#FFF",
    "& .MuiTablePagination-toolbar": {
      paddingRight: 0,
      paddingLeft: 10,
    },
  },
}));

const descendingComparator = (a, b, orderBy) => {
  if (b[orderBy] < a[orderBy]) {
    return -1;
  }
  if (b[orderBy] > a[orderBy]) {
    return 1;
  }
  return 0;
};

const getComparator = (order, orderBy) => {
  return order === "desc"
    ? (a, b) => descendingComparator(a, b, orderBy)
    : (a, b) => -descendingComparator(a, b, orderBy);
};

const stableSort = (array, comparator) => {
  const stabilizedThis = array.map((el, index) => [el, index]);
  stabilizedThis.sort((a, b) => {
    const order = comparator(a[0], b[0]);
    if (order !== 0) return order;
    return a[1] - b[1];
  });
  return stabilizedThis.map((el) => el[0]);
};

const EnhancedTableHead = ({
  classes,
  columns,
  disabledColumns,
  order,
  orderBy,
  onRequestSort,
}) => {
  const createSortHandler = (property) => (event) => {
    onRequestSort(event, property);
  };

  return (
    <TableHead>
      <TableRow>
        {columns
          .slice(
            0,
            disabledColumns === 3
              ? columns.length - 1
              : columns.length - (3 - disabledColumns)
          )
          .map((column, index) => (
            <TableCell
              key={`column-${index}`}
              sortDirection={orderBy === column.id ? order : false}
            >
              <TableSortLabel
                active={orderBy === column.id}
                direction={orderBy === column.id ? order : "asc"}
                onClick={createSortHandler(column.id)}
              >
                {column.label}
              </TableSortLabel>
            </TableCell>
          ))}
        {disabledColumns === 3 &&
          columns.slice(columns.length - 1).map((column, index) => (
            <TableCell
              key={`columnActions-${index}`}
              align="center"
              sortDirection={orderBy === column.id ? order : false}
            >
              {column.label}
            </TableCell>
          ))}
        {columns
          .slice(columns.length - (3 - disabledColumns))
          .map((column, index) => (
            <TableCell
              key={`columnActions-${index}`}
              align="center"
              sortDirection={orderBy === column.id ? order : false}
            >
              {column.label}
            </TableCell>
          ))}
      </TableRow>
    </TableHead>
  );
};

const TableSort = ({
  columns,
  rows,
  Cells,
  disableColumnDetails,
  disableColumnEdit,
  disableColumnDelete,
  disabledDetails,
  detailsAction,
  editAction,
  deleteAction,
  setAction,
}) => {
  const classes = useStyles();
  const [order, setOrder] = useState("asc");
  const [orderBy, setOrderBy] = useState("amount");
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(30);

  const [disabledColumns] = useState(() => {
    let values = [disableColumnDetails, disableColumnEdit, disableColumnDelete];
    let aux = 0;
    for (let i = 0; i < values.length; i++) {
      if (values[i] === true) {
        aux += 1;
      }
    }

    return aux;
  });

  const handleRequestSort = (event, property) => {
    const isAsc = orderBy === property && order === "asc";
    setOrder(isAsc ? "desc" : "asc");
    setOrderBy(property);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  return (
    <Fragment>
      <TableContainer component={Paper} className={classes.container}>
        <TableContainer>
          <Table
            aria-labelledby="tableTitle"
            size="medium"
            aria-label="enhanced table"
          >
            <EnhancedTableHead
              classes={classes}
              columns={columns}
              disabledColumns={disabledColumns}
              order={order}
              orderBy={orderBy}
              onRequestSort={handleRequestSort}
              rowCount={rows.length}
            />
            <TableBody>
              {stableSort(rows, getComparator(order, orderBy))
                .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                .map((row, index) => {
                  return (
                    <TableRow key={row._id}>
                      <Cells row={row} />
                      {!disableColumnDetails && (
                        <TableCell
                          align="center"
                          className={classes.rowActions}
                        >
                          <IconButton
                            disabled={disabledDetails}
                            className={classes.iconButton}
                            style={{
                              color: disabledDetails ? "#BBB2B2" : "#48BD12",
                            }}
                            onClick={() => {
                              setAction("details");
                              detailsAction(row._id);
                            }}
                          >
                            <VisibilityIcon />
                          </IconButton>
                        </TableCell>
                      )}
                      {!disableColumnEdit && (
                        <TableCell
                          align="center"
                          className={classes.rowActions}
                        >
                          <IconButton
                            className={classes.iconButton}
                            style={{ color: "#1260BD" }}
                            onClick={() => {
                              setAction("edit");
                              editAction(row._id);
                            }}
                          >
                            <EditIcon />
                          </IconButton>
                        </TableCell>
                      )}
                      {!disableColumnDelete && (
                        <TableCell
                          align="center"
                          className={classes.rowActions}
                        >
                          <IconButton
                            className={classes.iconButton}
                            style={{ color: "#CA0303" }}
                            onClick={() => {
                              setAction("delete");
                              deleteAction(row._id);
                            }}
                          >
                            <DeleteIcon />
                          </IconButton>
                        </TableCell>
                      )}
                    </TableRow>
                  );
                })}
            </TableBody>
          </Table>
        </TableContainer>
      </TableContainer>
      <div className={classes.paginationContainer}>
        <TablePagination
          rowsPerPageOptions={[15, 30, 50, 100]}
          component="div"
          count={rows.length}
          rowsPerPage={rowsPerPage}
          page={page}
          onChangePage={handleChangePage}
          onChangeRowsPerPage={handleChangeRowsPerPage}
          labelRowsPerPage="Cantidad"
          labelDisplayedRows={({ from, to, count }) => {
            return `${from}-${to} de ${count}`;
          }}
        />
      </div>
    </Fragment>
  );
};

export default TableSort;
