import React, { useEffect, useState } from "react";
import { makeStyles } from "@material-ui/core";
import Form from "./Form";
import { useDispatch, useSelector } from "react-redux";
import {
  generateExpense,
  getExpendituresAmounts,
} from "../../Redux/Action/expensesActions";
import { getExpenditures } from "../../Redux/Action/expendituresActions";
import Modal from "../Shared/Modal";
import EditExpenditure from "../Expenditure/EditExpenditure";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    padding: theme.spacing(1),
  },
}));

const AddExpense = ({
  id,
  token,
  setOpen,
  expendituresTypes,
  expenditures,
  establishment,
}) => {
  const classes = useStyles();
  const dispatch = useDispatch();

  const boxes = useSelector((state) => state.boxes.boxes);
  const categories = useSelector((state) => state.categories.categories);
  const amounts = useSelector(
    (state) => state.expenses.expendituresTypesAmounts
  );

  const [current, setcurrent] = useState();
  const [isLoading, setIsLoading] = useState(true);
  const [openEdit, setOpenEdit] = useState(false);
  const [dataAmounts, setData] = useState({ date: null });

  const [recurringExpenditures, setRecurringExpenditures] = useState(() => {
    let obj = expenditures
      .filter(
        (expenditure) =>
          expenditure.isRecurrent && expenditure.isRecurrent === true
      )
      .reduce((obj, expenditure) => {
        return [
          ...obj,
          {
            checked: false,
            expenditure: expenditure,
          },
        ];
      }, []);

    return obj;
  });

  const [expendituresT, setExpenditures] = useState(() => {
    let obj = expendituresTypes.reduce((obj, expenditure) => {
      return [
        ...obj,
        {
          expenditureType: expenditure._id,
          amount: "0",
          name: expenditure.name,
          mode: "fixed",
          isValid: true,
        },
      ];
    }, []);

    return obj;
  });

  const onClikHandler = (data) => {
    setIsLoading(true);
    dispatch(generateExpense(id, token, data, setOpen, setIsLoading));
  };

  const editExpenditure = (expenditure) => {
    setcurrent(expenditure);
    setOpenEdit(true);
  };

  const getAmounts = (data) => {
    dispatch(getExpendituresAmounts(id, token, data));
  };

  useEffect(() => {
    dispatch(getExpenditures(id, token, setIsLoading));
  }, [id, token, dispatch]);

  return (
    <div className={classes.container}>
      <Form
        title="Generación de expensa"
        setOpen={setOpen}
        isLoading={isLoading}
        onClikHandler={onClikHandler}
        expenditures={expendituresT.sort((a, b) => {
          if (a.expenditureType > b.expenditureType) {
            return 1;
          }
          if (a.expenditureType < b.expenditureType) {
            return -1;
          }

          return 0;
        })}
        setExpenditures={setExpenditures}
        recurringExpenditures={recurringExpenditures.sort((a, b) => {
          if (a.expenditure._id > b.expenditure._id) {
            return 1;
          }
          if (a.expenditure._id < b.expenditure._id) {
            return -1;
          }

          return 0;
        })}
        setRecurringExpenditures={setRecurringExpenditures}
        editExpenditure={editExpenditure}
        getAmounts={getAmounts}
        amounts={amounts.sort((a, b) => {
          if (a.expenditureType > b.expenditureType) {
            return 1;
          }
          if (a.expenditureType < b.expenditureType) {
            return -1;
          }

          return 0;
        })}
        dataAmounts={dataAmounts}
        setData={setData}
      />
      <Modal
        handleClose={() => setOpenEdit(false)}
        open={openEdit}
        component={
          <EditExpenditure
            establishment={establishment}
            id={id}
            token={token}
            setOpen={setOpenEdit}
            expenditure={current}
            categories={categories}
            expendituresTypes={expendituresTypes}
            boxes={boxes}
            dataAmounts={dataAmounts}
          />
        }
      />
    </div>
  );
};

export default AddExpense;
