import React, { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { makeStyles } from "@material-ui/core";
import Form from "./Form";
import { editFunctionalUnit } from "../../Redux/Action/functionalUnitsActions";
import { getContacts } from "../../Redux/Action/scheduleActions";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    padding: theme.spacing(1),
  },
}));

const EditFunctionalUnit = ({
  id,
  token,
  setOpen,
  functionalUnit,
  expendituresTypes,
}) => {
  const classes = useStyles();
  const dispatch = useDispatch();
  const contacts = useSelector((state) => state.contacts.contacts);

  const [isLoading, setIsLoading] = useState(true);
  const [hasChanged, setHasChanged] = useState(false);
  const [expenditures, setExpenditures] = useState(() => {
    let aux = null;
    let obj = expendituresTypes.reduce((obj, expenditure) => {
      return [
        ...obj,
        {
          expenditureType: expenditure._id,
          percentage: "0",
          name: expenditure.name,
        },
      ];
    }, []);

    for (let i = 0; i < obj.length; i++) {
      aux = functionalUnit.expendituresTypesPercentages.filter(
        (expenditure) =>
          expenditure.expenditureType &&
          expenditure.expenditureType._id === obj[i].expenditureType
      );
      if (aux[0]) {
        obj[i].percentage = aux[0].percentage;
      }
      aux = null;
    }

    return obj;
  });

  const postfunctionalUnit = (data) => {
    setIsLoading(true);
    dispatch(
      editFunctionalUnit(
        id,
        functionalUnit._id,
        token,
        data,
        functionalUnit,
        setOpen,
        setIsLoading
      )
    );
  };

  const reloadContacts = () => {
    setIsLoading(true);
    dispatch(getContacts(token, setIsLoading));
  };

  useEffect(() => {
    dispatch(getContacts(token, setIsLoading));
  }, [id, dispatch, token]);

  return (
    <div className={classes.container}>
      <Form
        title="Editar unidad funcional"
        contacts={contacts}
        getContacts={reloadContacts}
        expenditures={expenditures}
        setExpenditures={setExpenditures}
        setOpen={setOpen}
        isLoading={isLoading}
        onClikHandler={postfunctionalUnit}
        hasChanged={hasChanged}
        setHasChanged={setHasChanged}
        data={functionalUnit}
      />
    </div>
  );
};

export default EditFunctionalUnit;
