import axios from "axios";
import {
  ADD_EXPENSE,
  DELETE_EXPENSE,
  GET_EXPENDITURES_AMOUNTS,
  GET_EXPENSES,
} from "./actionTypes";

import { setSnackData } from "./snackDataActions";

axios.defaults.withCredentials = true;

export const getExpenses = (id, token, setIsLoading) => (dispatch) => {
  axios
    .get(`${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/expenses`, {
      headers: {
        Authorization: "Bearer " + token,
      },
    })
    .then((res) => {
      let expenses = res.data.filter((entry) => entry.type !== "initial");
      let filteredExpenses = res.data.filter(
        (entry) => entry.type !== "expense"
      );

      dispatch({
        type: GET_EXPENSES,
        payload: {
          expenses: expenses,
          filteredExpenses: filteredExpenses,
          expendituresTypesAmounts: [],
        },
      });
      if (setIsLoading) setIsLoading(false);
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }
      if (setIsLoading) setIsLoading(false);
    });
};

export const getExpendituresAmounts =
  (id, token, data, setIsLoading) => (dispatch, getState) => {
    let auxExpenses = getState().expenses.expenses;
    let auxFExpenses = getState().expenses.filteredExpenses;
    let expenses = Array.from(auxExpenses);
    let filteredExpenses = Array.from(auxFExpenses);

    axios
      .post(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/expenses/expenditures-types-amounts`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        dispatch({
          type: GET_EXPENDITURES_AMOUNTS,
          payload: {
            expenses: expenses,
            filteredExpenses: filteredExpenses,
            expendituresTypesAmounts: res.data,
          },
        });
        if (setIsLoading) setIsLoading(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const generateExpense =
  (id, token, data, setOpen, setIsLoading) => (dispatch, getState) => {
    let expenses = getState().expenses.expenses;
    let filteredExpenses = getState().expenses.filteredExpenses;

    axios
      .post(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/expenses`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        expenses.push(res.data);
        dispatch({
          type: ADD_EXPENSE,
          payload: {
            expenses: expenses,
            filteredExpenses: filteredExpenses,
            expendituresTypesAmounts: [],
          },
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Expensa generada con éxito",
            severity: "success",
          })
        );
        setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const deleteExpense =
  (id, token, idE, setOpen, setIsLoading) => (dispatch, getState) => {
    let expenses = getState().expenses.expenses;
    let filteredExpenses = getState().expenses.filteredExpenses;

    axios
      .delete(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/expenses/${idE}`,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        let i = expenses.findIndex((expense) => {
          if (expense._id === idE) {
            return true;
          }
          return false;
        });

        i !== -1 && expenses.splice(i, 1);

        dispatch({
          type: DELETE_EXPENSE,
          payload: {
            expenses: expenses,
            filteredExpenses: filteredExpenses,
            expendituresTypesAmounts: [],
          },
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Expensa eliminada",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

