export const calculateAmounts = (obj, paymentOrders) => {
  let aux = [];

  let copy = Array.from(paymentOrders);

  copy.forEach((element) => {
    for (let item of element.payedItems) {
      item.address = element.contract.property.address;

      if (item.cashToBox !== undefined && item.cashToBox === false) {
        item.amount.amount = 0;
      } else if (
        item.item.payable !== undefined &&
        item.item.payable === false
      ) {
        item.amount.amount = 0;
      }

      aux.push(item);

      obj.totalAmount += item.amount.amount + item.amount.tax;
      if (item.amount.fee) obj.totalFees += item.amount.fee;
    }

    for (let item of element.discounts) {
      item.address = element.contract.property.address;
      aux.push(item);
      obj.totalDiscounts += item.amount;
    }
  });

  obj.toLiquidate = obj.totalAmount - obj.totalFees - obj.totalDiscounts;

  return aux;
};

export const addRecurringDiscount = (item, amounts, setAmounts) => {
  let aux = parseFloat(amounts.toLiquidate) - parseFloat(item.amount);
  let auxDiscounts =
    parseFloat(amounts.totalDiscounts) + parseFloat(item.amount);

  setAmounts({
    ...amounts,
    toLiquidate: parseFloat(aux.toFixed(2)),
    totalDiscounts: parseFloat(auxDiscounts.toFixed(2)),
  });
};

export const deleteRecurringDiscount = (item, amounts, setAmounts) => {
  let aux = parseFloat(amounts.toLiquidate) + parseFloat(item.amount);
  let auxDiscounts =
    parseFloat(amounts.totalDiscounts) - parseFloat(item.amount);

  setAmounts({
    ...amounts,
    toLiquidate: parseFloat(aux.toFixed(2)),
    totalDiscounts: parseFloat(auxDiscounts.toFixed(2)),
  });
};

export const addDiscount = (
  data,
  setDataDiscounts,
  discounts,
  setDiscounts,
  amounts,
  setAmounts
) => {
  let aux = parseFloat(amounts.toLiquidate) - parseFloat(data.amount);
  let auxDiscounts =
    parseFloat(amounts.totalDiscounts) + parseFloat(data.amount);

  setDataDiscounts({
    target: {
      id: "amount",
      value: "",
      validity: { valid: true },
    },
  });

  setDiscounts([...discounts, data]);

  setAmounts({
    ...amounts,
    toLiquidate: aux <= 0 ? 0 : parseFloat(aux.toFixed(2)),
    totalDiscounts: parseFloat(auxDiscounts.toFixed(2)),
  });
};

export const deleteDiscount = (
  index,
  discounts,
  setDiscounts,
  amounts,
  setAmounts
) => {
  let aux =
    parseFloat(amounts.toLiquidate) + parseFloat(discounts[index].amount);

  let auxDiscounts =
    parseFloat(amounts.totalDiscounts) - parseFloat(discounts[index].amount);

  setDiscounts((discounts) => {
    let copy = [...discounts];
    copy.splice(index, 1);
    return copy;
  });

  setAmounts({
    ...amounts,
    toLiquidate: aux <= 0 ? 0 : parseFloat(aux.toFixed(2)),
    totalDiscounts: parseFloat(auxDiscounts.toFixed(2)),
  });
};
