import {
  GET_CONTRACTS,
  GET_CONTRACTS_ITEMS,
  ADD_CONTRACT,
  EDIT_CONTRACT,
  DELETE_CONTRACT,
} from "../Action/actionTypes";

import axios from "axios";

import { setSnackData } from "./snackDataActions";

axios.defaults.withCredentials = true;

export const getContracts = (token, setIsLoading) => (dispatch) => {
  axios
    .get(`${process.env.REACT_APP_BACKEND_URL}/rentals/contracts`, {
      headers: {
        Authorization: "Bearer " + token,
      },
    })
    .then((res) => {
      dispatch({
        type: GET_CONTRACTS,
        payload: res.data,
      });

      if (setIsLoading) setIsLoading(false);
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }

      if (setIsLoading) setIsLoading(false);
    });
};

export const getItemsContract =
  (recent, token, id, setIsLoading, setItems) => (dispatch) => {
    axios
      .get(
        `${process.env.REACT_APP_BACKEND_URL}/rentals/contracts/${id}/items${
          recent ? "/recent" : ""
        }`,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        let aux = res.data.reduce((obj, entry) => {
          return [
            ...obj,
            {
              ...entry,
              ...(entry.status !== "paid" && { checked: false }),
            },
          ];
        }, []);

        dispatch({
          type: GET_CONTRACTS_ITEMS,
          payload: aux,
        });

        if (setItems) setItems(aux);
        if (setIsLoading) setIsLoading(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };

export const addContract =
  (token, formData, auxData, setOpen, setIsLoading) => (dispatch, getState) => {
    let estates = getState().estates.estates;
    let aux = getState().contracts.contracts;
    let contracts = Array.from(aux);

    axios
      .post(
        `${process.env.REACT_APP_BACKEND_URL}/rentals/contracts`,
        formData,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        auxData._id = res.data._id;
        auxData.payments = res.data.payments;
        auxData.pdf = res.data.pdf;
        auxData.establishment = res.data.establishment;

        let i = estates.findIndex((estate) => {
          if (estate._id === auxData.property) {
            return true;
          }
          return false;
        });

        if (i !== -1) {
          auxData.property = {
            _id: estates[i]._id,
            type: estates[i].type,
            owners: estates[i].owners,
            address: estates[i].address,
          };
        }

        contracts.push(auxData);

        dispatch({
          type: ADD_CONTRACT,
          payload: contracts,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Contrato creado",
            severity: "success",
          })
        );

        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };

export const editContract =
  (token, formData, auxData, current, setOpen, setIsLoading) =>
  (dispatch, getState) => {
    let estates = getState().estates.estates;
    let aux = getState().contracts.contracts;

    let contracts = Array.from(aux);

    axios
      .put(
        `${process.env.REACT_APP_BACKEND_URL}/rentals/contracts/${current._id}`,
        formData,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        auxData.pdf = res.data.pdf;

        let i = contracts.findIndex((contract) => {
          if (contract._id === current._id) {
            return true;
          }
          return false;
        });

        let j = estates.findIndex((estate) => {
          if (estate._id === auxData.property) {
            return true;
          }
          return false;
        });

        if (j !== -1) {
          auxData.property = {
            _id: estates[j]._id,
            type: estates[j].type,
            owners: estates[j].owners,
            address: estates[j].address,
          };
        }

        if (i !== -1) {
          contracts[i] = Object.assign(contracts[i], auxData);
        }

        dispatch({
          type: EDIT_CONTRACT,
          payload: contracts,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Contrato editado",
            severity: "success",
          })
        );

        setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };

export const deleteContract =
  (token, id, setOpen, setIsLoading) => (dispatch, getState) => {
    let aux = getState().contracts.contracts;

    let contracts = Array.from(aux);

    axios
      .delete(`${process.env.REACT_APP_BACKEND_URL}/rentals/contracts/${id}`, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((_) => {
        let i = contracts.findIndex((contract) => {
          if (contract._id === id) {
            return true;
          }
          return false;
        });

        i !== -1 && contracts.splice(i, 1);

        dispatch({
          type: DELETE_CONTRACT,
          payload: contracts,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Contrato eliminado",
            severity: "success",
          })
        );

        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };
