import { GET_RECEIPTS, DELETE_RECEIPT } from "../Action/actionTypes";

import axios from "axios";

import { setSnackData } from "./snackDataActions";

axios.defaults.withCredentials = true;

export const getReceipts = (token, id, setIsLoading) => (dispatch) => {
  axios
    .get(
      `${process.env.REACT_APP_BACKEND_URL}/rentals/payment-orders/byContract/${id}`,
      {
        headers: {
          Authorization: "Bearer " + token,
        },
      }
    )
    .then((res) => {
      dispatch({
        type: GET_RECEIPTS,
        payload: res.data,
      });

      if (setIsLoading) setIsLoading(false);
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }

      if (setIsLoading) setIsLoading(false);
    });
};

export const deleteReceipt =
  (token, idReceipt, setOpen, setIsLoading) => (dispatch, getState) => {
    let aux = getState().contracts.receipts;
    let receipts = Array.from(aux);

    axios
      .delete(
        `${process.env.REACT_APP_BACKEND_URL}/rentals/payment-orders/${idReceipt}`,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        let i = receipts.findIndex((entry) => {
          if (entry._id === idReceipt) {
            return true;
          }
          return false;
        });

        i !== -1 && receipts.splice(i, 1);

        dispatch({
          type: DELETE_RECEIPT,
          payload: receipts,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Comprobante y pagos eliminados",
            severity: "success",
          })
        );

        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };
