import React, { Fragment } from "react";
import {
  Button,
  Grid,
  makeStyles,
  MenuItem,
  TextField,
  FormControl,
  FormControlLabel,
  FormLabel,
  RadioGroup,
  Radio,
} from "@material-ui/core";

import { ExpandMore } from "@material-ui/icons";

import { days } from "../../../configs/contracts/DAYS_MONTHS";
import NumberFormat from "react-number-format";
import { useState } from "react";

const useStyles = makeStyles((theme) => ({
  radioGroup: {
    display: "flex",
    justifyContent: "flex-end",
    "& .Mui-checked": {
      color: "#49AC08",
    },
  },
  addButton: {
    backgroundColor: "#49AC08",
    color: "#FAFAFA",
    textTransform: "capitalize",
    fontSize: 12,
    "&:hover": {
      backgroundColor: "#49ac089e",
    },
  },
}));

function NumberFormatCustom(props) {
  const { min, id, inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
            id: id,
            validity: {
              valid: parseFloat(values.value, 10) >= parseFloat(min, 10),
            },
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={3}
      isNumericString
      prefix="$"
    />
  );
}

function NumberFormatPercentage(props) {
  const { min, max, id, inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
            id: id,
            validity: {
              valid:
                parseFloat(values.value, 10) <= parseFloat(max, 10) &&
                parseFloat(values.value, 10) >= parseFloat(min, 10),
            },
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={3}
      isNumericString
      suffix="%"
    />
  );
}

let paymentMethodData = {
  1: "Porcentaje",
  2: "Monto fijo",
};

const TaxOrServiceForm = ({
  feeAmount,
  onChangeData,
  services,
  data,
  setData,
  setForm,
  isMobile,
  onClick,
  disabledButton,
  xs,
  addOrEditItem,
}) => {
  const classes = useStyles();

  const [paymentMethod, setPaymentMethod] = useState(
    parseInt(data.paymentMethod.value)
  );

  const onChange = (e) => {
    let id = e.target.id;
    let value = e.target.value;
    let isValid = e.target.validity.valid;
    let isValidAux = true;
    let aux = 0;

    if (paymentMethod === 1) {
      aux = 100 - parseFloat(e.target.value, 10);

      if (aux > 100 || aux < 0) {
        isValidAux = false;
        aux = 0;
      }
    }

    setForm({
      ...data,
      tenantPay: {
        value: id === "tenantPay" ? value : paymentMethod === 1 ? aux : "",
        isValid: id === "tenantPay" ? isValid : isValidAux,
      },
      ownerPay: {
        value: id === "ownerPay" ? value : paymentMethod === 1 ? aux : "",
        isValid: id === "ownerPay" ? isValid : isValidAux,
      },
    });
  };

  const onChangeShape = (e) => {
    setPaymentMethod(parseInt(e));

    setForm({
      ...data,
      paymentMethod: { value: parseInt(e), isValid: true },
      tenantPay: { value: e === "1" ? "100" : "", isValid: true },
      ownerPay: { value: e === "1" ? "0" : "", isValid: true },
    });
  };

  let auxDisabled = () => {
    let aux = false;

    if (paymentMethod === 1) {
      aux =
        data.tenantPay.value !== "" &&
        data.tenantPay.isValid === true &&
        data.ownerPay.value !== "" &&
        data.ownerPay.isValid === true;
    } else {
      aux = Object.entries(data)
        .filter((entry) => entry[0] === "tenantPay" || entry[0] === "ownerPay")
        .some((entry) => entry[1].value !== "");
    }

    return aux;
  };

  const disabled =
    data.service.value !== "" &&
    data.paymentMethod.value !== "" &&
    auxDisabled()
      ? false
      : true;

  return (
    <Fragment>
      <Grid item xs={isMobile ? 6 : xs || 3}>
        <TextField
          label="Nombre"
          id="name"
          value={data.service.value}
          onChange={(e) => {
            e.target.id = "service";
            setData(e);
            onChangeData && onChangeData();
          }}
          select
          SelectProps={{
            IconComponent: ExpandMore,
          }}
          fullWidth
        >
          <MenuItem value=""></MenuItem>
          {services.map((entry) => (
            <MenuItem key={`select-${entry._id}`} value={entry._id}>
              {entry.name}
            </MenuItem>
          ))}
        </TextField>
      </Grid>
      <Grid item xs={isMobile ? 6 : xs || 3}>
        <TextField
          InputProps={{
            inputComponent: NumberFormatCustom,
          }}
          required
          autoComplete="off"
          label="Importe"
          id="amount"
          name="amount"
          value={data.amount.value}
          onChange={(e) => {
            setData(e);
            onChangeData && onChangeData();
          }}
          fullWidth
          inputProps={{
            min: "0",
            pattern: "[0-9.]+",
            step: ".01",
          }}
          error={!data.amount.isValid}
          InputLabelProps={{ required: false }}
        />
      </Grid>
      <Grid item xs={isMobile ? 6 : xs || 3}>
        <TextField
          label="Forma de pago"
          id="paymentMethod"
          value={paymentMethod}
          onChange={(e) => {
            onChangeShape(e.target.value);
            onChangeData && onChangeData();
          }}
          select
          SelectProps={{
            IconComponent: ExpandMore,
          }}
          fullWidth
        >
          <MenuItem value=""></MenuItem>
          {Object.entries(paymentMethodData).map((entry, index) => (
            <MenuItem key={`select-${entry[0]}-${index}`} value={entry[0]}>
              {entry[1]}
            </MenuItem>
          ))}
        </TextField>
      </Grid>
      <Grid item xs={isMobile ? 6 : xs || 3}>
        <TextField
          disabled={paymentMethod === 2 && data.ownerPay.value !== ""}
          label={
            paymentMethod === 2 && data.ownerPay.value !== ""
              ? "Excedente"
              : "Inquilino paga"
          }
          InputProps={{
            inputComponent:
              paymentMethod === 1 ? NumberFormatPercentage : NumberFormatCustom,
          }}
          required
          autoComplete="off"
          id="tenantPay"
          name="tenantPay"
          value={data.tenantPay.value}
          onChange={(e) => {
            onChange(e);
            onChangeData && onChangeData();
          }}
          fullWidth
          inputProps={
            paymentMethod === 1
              ? {
                  min: "0",
                  max: "100",
                  pattern: "[0-9]+",
                  step: ".01",
                }
              : {
                  min: "0",
                  pattern: "[0-9.]+",
                  step: ".01",
                }
          }
          error={!data.tenantPay.isValid}
          InputLabelProps={{ required: false }}
        />
      </Grid>
      <Grid item xs={isMobile ? 6 : xs || 3}>
        <TextField
          disabled={paymentMethod === 2 && data.tenantPay.value !== ""}
          label={
            paymentMethod === 2 && data.tenantPay.value !== ""
              ? "Excedente"
              : "Propietario paga"
          }
          InputProps={{
            inputComponent:
              paymentMethod === 1 ? NumberFormatPercentage : NumberFormatCustom,
          }}
          required
          autoComplete="off"
          id="ownerPay"
          name="ownerPay"
          value={data.ownerPay.value}
          onChange={(e) => {
            onChange(e);
            onChangeData && onChangeData();
          }}
          fullWidth
          inputProps={
            paymentMethod === 1
              ? {
                  min: "0",
                  max: "100",
                  pattern: "[0-9]+",
                  step: ".01",
                }
              : {
                  min: "0",
                  pattern: "[0-9.]+",
                  step: ".01",
                }
          }
          error={!data.ownerPay.isValid}
          InputLabelProps={{ required: false }}
        />
      </Grid>
      <Grid item xs={isMobile ? 6 : xs || 3}>
        <TextField
          InputProps={{
            inputComponent: feeAmount
              ? NumberFormatCustom
              : NumberFormatPercentage,
          }}
          required
          autoComplete="off"
          label="Honorarios"
          id={feeAmount ? "fee" : "monthlyFeePercentage"}
          name={feeAmount ? "fee" : "monthlyFeePercentage"}
          value={feeAmount ? data.fee.value : data.monthlyFeePercentage.value}
          onChange={(e) => {
            setData(e);
            onChangeData && onChangeData();
          }}
          fullWidth
          inputProps={
            feeAmount
              ? { min: "0", pattern: "[0-9.]+", step: ".01" }
              : {
                  min: "0",
                  max: "100",
                  pattern: "[0-9]+",
                  step: ".01",
                }
          }
          error={!data[feeAmount ? "fee" : "monthlyFeePercentage"].isValid}
          InputLabelProps={{ required: false }}
        />
      </Grid>
      {!addOrEditItem && (
        <Grid item xs={isMobile ? 6 : xs || 3}>
          <TextField
            label="Vence todos los"
            id="expirationDay"
            value={data.expirationDay.value}
            onChange={(e) => {
              e.target.id = "expirationDay";
              setData(e);
              onChangeData && onChangeData();
            }}
            select
            SelectProps={{
              IconComponent: ExpandMore,
            }}
            fullWidth
          >
            <MenuItem value=""></MenuItem>
            {days.map((entry, index) => (
              <MenuItem key={`select-${entry}-${index}`} value={entry}>
                {entry}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
      )}

      <Grid item xs={isMobile ? 12 : disabledButton ? 12 : 6}>
        <FormControl component="fieldset" fullWidth>
          <Grid container alignItems="center">
            <Grid item xs={7}>
              <FormLabel style={{ color: "#616161" }}>
                ¿Liquida al propietario?
              </FormLabel>
            </Grid>
            <Grid item xs={5}>
              <RadioGroup
                className={classes.radioGroup}
                aria-label="payable"
                name="payable"
                value={data.payable.value}
                onChange={(e) => {
                  e.target.id = "payable";
                  setData(e);
                  onChangeData && onChangeData();
                }}
                row
              >
                <FormControlLabel
                  value="true"
                  control={<Radio color="primary" />}
                  label="Sí"
                />
                <FormControlLabel
                  style={{ marginRight: 0 }}
                  value="false"
                  control={<Radio color="primary" />}
                  label="No"
                />
              </RadioGroup>
            </Grid>
          </Grid>
        </FormControl>
      </Grid>

      {!disabledButton && (
        <Grid
          item
          xs={isMobile ? 12 : xs || 6}
          style={{ display: "flex", alignItems: "end" }}
        >
          <Button
            disabled={disabled}
            fullWidth
            disableElevation
            variant="contained"
            className={classes.addButton}
            onClick={() => {
              onClick();
              setPaymentMethod("1");
            }}
          >
            Agregar impuesto
          </Button>
        </Grid>
      )}
    </Fragment>
  );
};

export default TaxOrServiceForm;
