import axios from "axios";
import {
  GET_EXPENDITURES,
  ADD_EXPENDITURE,
  EDIT_EXPENDITURE,
  DELETE_EXPENDITURE,
} from "./actionTypes";
import { getExpendituresAmounts } from "./expensesActions";

import { setSnackData } from "./snackDataActions";

export const getExpenditures =
  (id, token, setIsLoading, expenseId) => (dispatch, getState) => {
    let exp = getState().expenditures.expenditures;
    let fExp = getState().expenditures.filteredExpenditures;
    let expCopy = Array.from(exp);
    let fExpCopy = Array.from(fExp);
    axios
      .get(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/expenditures/${
          expenseId ? expenseId : ""
        }`,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        let expenditures = expCopy;
        let filteredExpenditures = fExpCopy;

        if (expenseId) {
          filteredExpenditures = res.data;
        } else {
          expenditures = res.data;
        }

        dispatch({
          type: GET_EXPENDITURES,
          payload: {
            expenditures: expenditures,
            filteredExpenditures: filteredExpenditures,
          },
        });
        if (setIsLoading) setIsLoading(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const getFile =
  (establishment, fileName, setFile, setIsLoading) => (dispatch) => {
    axios
      .get(
        `${process.env.REACT_APP_BACKEND_URL}/files/${establishment}/${fileName}`
      )
      .then((res) => {
        if (res.data) {
          setFile(res.data);
        }
        if (setIsLoading) setIsLoading(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const addExpenditure =
  (id, token, data, setOpen, setIsLoading) => (dispatch, getState) => {
    const formData = new FormData();

    for (let i = 0; i < data.expendituresTypesPercentages.length; i++) {
      if (data.expendituresTypesPercentages[i].percentage === "") {
        data.expendituresTypesPercentages[i].percentage = 0;
      }
    }

    let fExp = getState().expenditures.filteredExpenditures;
    let fExpCopy = Array.from(fExp);
    let aux = getState().expenditures.expenditures;
    let expenditures = Array.from(aux);
    let categories = getState().categories.categories;
    let subcategories = getState().subcategories.subcategories;
    let providers = getState().providers.providers;

    let category = categories.filter(
      (category) => category._id === data.category
    )[0];
    let subcategory = subcategories.filter(
      (subcategory) => subcategory._id === data.subcategory
    )[0];
    let provider = providers.filter(
      (provider) => provider._id === data.provider
    )[0];

    for (let key in data) {
      if (key === "amount" || key === "expendituresTypesPercentages") {
        formData.append(key, JSON.stringify(data[key]));
      } else {
        formData.append(key, data[key]);
      }
    }

    axios
      .post(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/expenditures`,
        formData,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        let data = res.data;
        data.category = category;
        data.subcategory = subcategory;
        data.provider = provider;

        expenditures.push(data);

        dispatch({
          type: ADD_EXPENDITURE,
          payload: {
            expenditures: expenditures,
            filteredExpenditures: fExpCopy,
          },
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Gasto creado",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const editExpenditure =
  (
    id,
    token,
    idE,
    data,
    currentExpenditure,
    setOpen,
    setIsLoading,
    dataAmounts
  ) =>
  (dispatch, getState) => {
    const formData = new FormData();

    for (let i = 0; i < data.expendituresTypesPercentages.length; i++) {
      if (data.expendituresTypesPercentages[i].percentage === "") {
        data.expendituresTypesPercentages[i].percentage = 0;
      }
    }

    let fExp = getState().expenditures.filteredExpenditures;
    let fExpCopy = Array.from(fExp);
    let aux = getState().expenditures.expenditures;
    let expenditures = Array.from(aux);
    let categories = getState().categories.categories;
    let subcategories = getState().subcategories.subcategories;
    let providers = getState().providers.providers;

    let category = categories.filter(
      (category) => category._id === data.category
    )[0];
    let subcategory = subcategories.filter(
      (subcategory) => subcategory._id === data.subcategory
    )[0];
    let provider = providers.filter(
      (provider) => provider._id === data.provider
    )[0];

    for (let key in data) {
      if (key === "amount" || key === "expendituresTypesPercentages") {
        formData.append(key, JSON.stringify(data[key]));
      } else {
        formData.append(key, data[key]);
      }
    }

    axios
      .put(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/expenditures/${idE}`,
        formData,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        currentExpenditure.isRecurrent = data.isRecurrent;
        currentExpenditure.category = category;
        currentExpenditure.subcategory = subcategory;
        currentExpenditure.provider = provider;
        currentExpenditure.amount = data.amount;
        currentExpenditure.description = data.description;
        currentExpenditure.number = data.number;
        currentExpenditure.status = data.status;
        currentExpenditure.expirationDate = data.expirationDate;
        currentExpenditure.date = data.date;
        currentExpenditure.box = data.box;
        currentExpenditure.file = res.data.file;
        currentExpenditure.expendituresTypesPercentages =
          data.expendituresTypesPercentages;

        let i = expenditures.findIndex((expenditure) => {
          if (expenditure._id === idE) {
            return true;
          }
          return false;
        });

        if (i !== -1) {
          expenditures[i] = currentExpenditure;
        }

        dispatch({
          type: EDIT_EXPENDITURE,
          payload: {
            expenditures: expenditures,
            filteredExpenditures: fExpCopy,
          },
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Gasto editado",
            severity: "success",
          })
        );
        if (dataAmounts) {
          dispatch(getExpendituresAmounts(id, token, dataAmounts));
        }
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };

export const deleteExpenditure =
  (id, token, idE, setOpen, setIsLoading) => (dispatch, getState) => {
    let fExp = getState().expenditures.filteredExpenditures;
    let fExpCopy = Array.from(fExp);
    let aux = getState().expenditures.expenditures;
    let expenditures = Array.from(aux);
    axios
      .delete(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/expenditures/${idE}`,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        let i = expenditures.findIndex((expenditure) => {
          if (expenditure._id === idE) {
            return true;
          }
          return false;
        });

        i !== -1 && expenditures.splice(i, 1);

        dispatch({
          type: DELETE_EXPENDITURE,
          payload: {
            expenditures: expenditures,
            filteredExpenditures: fExpCopy,
          },
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Gasto eliminado",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };
