import axios from "axios";
import {
  GET_BANKS,
  ADD_BANK,
  EDIT_BANK,
  DELETE_BANK,
} from "../Action/actionTypes";

import { setSnackData } from "./snackDataActions";

axios.defaults.withCredentials = true;

export const getBanks = (token, setIsLoading) => (dispatch) => {
  axios
    .get(`${process.env.REACT_APP_BACKEND_URL}/rentals/banks`, {
      headers: {
        Authorization: "Bearer " + token,
      },
    })
    .then((res) => {
      dispatch({
        type: GET_BANKS,
        payload: res.data,
      });

      if (setIsLoading) setIsLoading(false);
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }

      if (setIsLoading) setIsLoading(false);
    });
};

export const addBank =
  (token, data, setOpen, setIsLoading) => (dispatch, getState) => {
    let aux = getState().banks.banks;
    let banks = Array.from(aux);

    axios
      .post(`${process.env.REACT_APP_BACKEND_URL}/rentals/banks`, data, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((res) => {
        banks.push(res.data);

        dispatch({
          type: ADD_BANK,
          payload: banks,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Banco creado",
            severity: "success",
          })
        );

        setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };

export const editBank =
  (token, data, current, setOpen, setIsLoading) => (dispatch, getState) => {
    let aux = getState().banks.banks;
    let banks = Array.from(aux);

    axios
      .put(
        `${process.env.REACT_APP_BACKEND_URL}/rentals/banks/${current._id}`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        let i = banks.findIndex((entry) => {
          if (entry._id === current._id) {
            return true;
          }
          return false;
        });

        if (i !== -1) {
          banks[i] = Object.assign(banks[i], data);
        }

        dispatch({
          type: EDIT_BANK,
          payload: banks,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Banco editado",
            severity: "success",
          })
        );

        setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };

export const deleteBank =
  (token, id, setOpen, setIsLoading) => (dispatch, getState) => {
    let aux = getState().banks.banks;
    let banks = Array.from(aux);

    axios
      .delete(`${process.env.REACT_APP_BACKEND_URL}/rentals/banks/${id}`, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((_) => {
        let i = banks.findIndex((estate) => {
          if (estate._id === id) {
            return true;
          }
          return false;
        });

        i !== -1 && banks.splice(i, 1);

        dispatch({
          type: DELETE_BANK,
          payload: banks,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Banco eliminado",
            severity: "success",
          })
        );

        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };
