const rentMonths = (contract, startMonth, count, base, paidUntil) => {
  const rows = [];
  let amount = base;
  for (let index = 0; index < count; index++) {
    if (index > 0 && index % 6 === 0) amount = +(amount * 1.15).toFixed(2);
    const pending = index >= paidUntil;
    const date = new Date(Date.UTC(2026, startMonth + index, 1, 12));
    const expirationDate = new Date(Date.UTC(2026, startMonth + index, 5, 12));
    rows.push({
      _id: `64f0aa13${String(contract === CT1 ? index + 1 : index + 21).padStart(16, "0")}`,
      status: pending ? "pending" : "paid",
      amount,
      payedAmount: pending ? 0 : amount,
      itemType: 1,
      name: "Alquiler",
      date: date.toISOString(),
      expirationDate: expirationDate.toISOString(),
      createdAt: date.toISOString(),
      notes: pending ? "" : "Cobrado",
      fee: +((amount * 6) / 100).toFixed(2),
      dailyInterestPercentage: 0.5,
      payable: true,
      contract,
      paymentOrders: !pending && index === paidUntil - 1 ? [contract === CT1 ? PO1 : PO3] : [],
      paymentsDates: [],
    });
  }
  return rows;
};

