const itemCard = (id) => {
  const found = items.find((entry) => entry._id === id);
  return {
    _id: found._id,
    name: found.name,
    date: found.date,
    expirationDate: found.expirationDate,
    amount: found.amount,
    fee: found.fee,
    payable: found.payable,
  };
};

const linkedRent = (contract, orderId) =>
  items.find(
    (entry) => entry.contract === contract && entry.paymentOrders.includes(orderId)
  );

