import React, { useState } from "react";
import { useEffect } from "react";

import { useDispatch } from "react-redux";
import Form from "./DetailsComponents/AddItemForm";

import { getServices } from "../../Redux/Action/servicesActions";
import { useForm } from "../../hooks/use-form";
import { addItem } from "../../Redux/Action/itemActions";

const AddItem = ({ id, user, setOpen, setRows, recent }) => {
  const dispatch = useDispatch();

  const [isLoading, setIsLoading] = useState(true);

  const [itemType, setItemType] = useState("");

  const [expirationDate, setExpirationDate] = useState(null);

  const [monthsValue, setMonths] = useState("");

  const [rentalData, setRentalData, setFormRental] = useForm({
    amount: "",
    fee: "",
    notes: "",
  });

  const [dataService, setDataService, setFormService] = useForm({
    service: "",
    amount: "",
    paymentMethod: 1,
    tenantPay: "100",
    ownerPay: "0",
    fee: "",
    expirationDay: "",
    notes: "",
    payable: "true",
  });

  const [dataFreeItem, setDataFreeItem, setFormFreeItem] = useForm({
    name: "",
    amount: "",
    increaseMonths: "",
    increasePercentage: "",
    fee: "",
    dailyInterestPercentage: "",
    payable: "true",
    notes: "",
  });

  const onClikHandler = (data) => {
    setIsLoading(true);
    dispatch(
      addItem(recent, user.token, id, data, setOpen, setIsLoading, setRows)
    );
  };

  useEffect(() => {
    dispatch(getServices(user.token, setIsLoading));
  }, [user.token, dispatch]);

  return (
    <Form
      title="Agregar Item"
      setOpen={setOpen}
      isLoading={isLoading}
      onClikHandler={onClikHandler}
      hasChanged={true}
      itemType={itemType}
      setItemType={setItemType}
      expirationDate={expirationDate}
      setExpirationDate={setExpirationDate}
      monthsValue={monthsValue}
      setMonths={setMonths}
      rentalData={rentalData}
      setRentalData={setRentalData}
      setFormRental={setFormRental}
      dataService={dataService}
      setDataService={setDataService}
      setFormService={setFormService}
      dataFreeItem={dataFreeItem}
      setDataFreeItem={setDataFreeItem}
      setFormFreeItem={setFormFreeItem}
    />
  );
};

export default AddItem;
