import axios from "axios";
import {
  GET_CONSORTIUMS,
  ADD_CONSORTIUM,
  EDIT_CONSORTIUM,
  DELETE_CONSORTIUM,
} from "./actionTypes";

import { setSnackData } from "./snackDataActions";

axios.defaults.withCredentials = true;

export const getConsortiums = (token, setIsLoading) => (dispatch) => {
  axios
    .get(`${process.env.REACT_APP_BACKEND_URL}/consortiums`, {
      headers: {
        Authorization: "Bearer " + token,
      },
    })
    .then((res) => {
      dispatch({
        type: GET_CONSORTIUMS,
        payload: res.data,
      });

      if (setIsLoading) setIsLoading(false);
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }
      if (setIsLoading) setIsLoading(false);
    });
};

export const addConsortium =
  (token, data, setOpen, setIsLoading) => (dispatch, getState) => {
    let aux = getState().consortiums.consortiums;
    let consortiums = Array.from(aux);

    axios
      .post(`${process.env.REACT_APP_BACKEND_URL}/consortiums`, data, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((res) => {
        consortiums.push(res.data);

        dispatch({
          type: ADD_CONSORTIUM,
          payload: consortiums,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Consorcio creado",
            severity: "success",
          })
        );

        setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const editConsortium =
  (token, data, id, setOpen, setIsLoading) => (dispatch, getState) => {
    let aux = getState().consortiums.consortiums;
    let consortiums = Array.from(aux);

    axios
      .put(`${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}`, data, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((_) => {
        let i = consortiums.findIndex((consortium) => {
          if (consortium._id === id) {
            return true;
          }
          return false;
        });

        if (i !== -1) {
          consortiums[i] = Object.assign(consortiums[i], data);
        }

        dispatch({
          type: EDIT_CONSORTIUM,
          payload: consortiums,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Consorcio editado",
            severity: "success",
          })
        );

        setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const deleteConsortium =
  (token, id, setOpen, setIsLoading) => (dispatch, getState) => {
    let aux = getState().consortiums.consortiums;
    let consortiums = Array.from(aux);

    axios
      .delete(`${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}`, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((_) => {
        let i = consortiums.findIndex((entry) => {
          if (entry._id === id) {
            return true;
          }
          return false;
        });

        i !== -1 && consortiums.splice(i, 1);

        dispatch({
          type: DELETE_CONSORTIUM,
          payload: consortiums,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Consorcio eliminado",
            severity: "success",
          })
        );

        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };
