import React from "react";
import { makeStyles } from "@material-ui/core/styles";
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableRow,
  Paper,
  TableHead,
} from "@material-ui/core";

import { NumberFormatCustom } from "../../hooks/format-number-hook";

const useStyles = makeStyles((theme) => ({
  tableContainer: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    justifyContent: "space-between",
    boxShadow: "none",
    backgroundColor: "#F7F9F8",
    border: "1px solid #E6EBE8",
    borderRadius: 12,
    padding: theme.spacing(1, 1.25),
    maxHeight: 225,

    "& .MuiTableCell-head": {
      color: "#000000",
      fontSize: "14px",
      lineHeight: "20px",
      letterSpacing: "0.02em",
      padding: theme.spacing(1),
    },

    "& .MuiTableCell-body": {
      color: "#000000",
      fontSize: "14px",
      lineHeight: "20px",
      letterSpacing: "0.02em",
      padding: theme.spacing(1),
      borderColor: "#E6EBE8",
    },
  },
}));

const SettlementInformation = ({ amounts }) => {
  const classes = useStyles();

  return (
    <TableContainer className={classes.tableContainer} component={Paper}>
      <Table aria-label="simple table">
        <TableHead>
          <TableRow>
            <TableCell align="center">Total</TableCell>
            <TableCell align="center">Honorarios</TableCell>
            <TableCell align="center">Descuentos</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          <TableRow>
            <TableCell
              align="center"
              component="th"
              scope="row"
              style={{ borderBottom: "none" }}
            >
              {NumberFormatCustom(amounts.totalAmount)}
            </TableCell>
            <TableCell
              align="center"
              component="th"
              scope="row"
              style={{ borderBottom: "none" }}
            >
              {NumberFormatCustom(amounts.totalFees)}
            </TableCell>
            <TableCell
              align="center"
              component="th"
              scope="row"
              style={{ borderBottom: "none" }}
            >
              {NumberFormatCustom(amounts.totalDiscounts)}
            </TableCell>
          </TableRow>
        </TableBody>
      </Table>
    </TableContainer>
  );
};

export default SettlementInformation;
