import React, { useState, useEffect } from "react";
import Table from "../Shared/Table";
import Modal from "../Shared/Modal";
import Spinner from "../UI/Spinner";
import DeleteFunctionalUnit from "./DeleteFunctionalUnit";
import EditFunctionalUnit from "./EditFunctionalUnit";
import DetailsFunctionalUnit from "./Details";
import { IconButton, TableCell } from "@material-ui/core";
import { useDispatch, useSelector } from "react-redux";
import { getFunctionalUnits } from "../../Redux/Action/functionalUnitsActions";
import { getExpendituresTypes } from "../../Redux/Action/expendituresTypesActions";

import { NumberFormatCustom } from "../../hooks/format-number-hook";

import FolderIcon from "@material-ui/icons/FolderOpenOutlined";

const columnsMoreActions = ["Ver datos"];

const Cells = ({ row }) => {
  return (
    <>
      <TableCell component="th" scope="row">
        {row.number}
      </TableCell>
      <TableCell component="th" scope="row">
        {row.apartment}
      </TableCell>
      <TableCell component="th" scope="row">
        {`${row.owner.name} ${row.owner.lastname}`}
      </TableCell>
      <TableCell
        component="th"
        scope="row"
        style={{ color: row.balance < 0 ? "#C10909" : "#28BD00" }}
      >
        {NumberFormatCustom(row.balance)}
      </TableCell>
    </>
  );
};
const MoreActions = ({ row, dataAction }) => {
  return (
    <>
      <TableCell align="center" style={{ width: "120px" }}>
        <IconButton
          style={{ color: "#48B", padding: 0 }}
          onClick={() => {
            dataAction(row);
          }}
        >
          <FolderIcon />
        </IconButton>
      </TableCell>
    </>
  );
};

const List = ({
  onClickHandler,
  id,
  user,
  isLoadingComponent,
  setIsLoadingComponent,
}) => {
  const dispatch = useDispatch();
  const [open, setOpen] = useState(false);
  const [current, setCurrent] = useState(null);
  const [action, setAction] = useState();

  const expendituresTypes = useSelector(
    (state) => state.expendituresTypes.expendituresTypes
  );

  const columns = [
    "Unidad funcional",
    "Piso y letra",
    "Propietario",
    "Saldo",
    "Detalles",
    ...(user.isAdmin ? ["Editar", "Eliminar"] : []),
  ];

  const rows = useSelector(
    (state) => state.functionalunits.functionalUnits
  ).sort((a, b) => {
    if (a.number > b.number) {
      return 1;
    }
    if (a.number < b.number) {
      return -1;
    }

    return 0;
  });

  const dataFunctionalUnit = (current) => {
    onClickHandler("functionalUnitData", current);
  };

  const detailsFunctionalUnit = (current) => {
    setCurrent(current);
    setOpen(true);
  };

  const editFunctionalUnit = (current) => {
    setCurrent(current);
    setOpen(true);
  };

  const deleteFunctionalUnit = (current) => {
    setCurrent(current);
    setOpen(true);
  };

  const actions = {
    details: (
      <DetailsFunctionalUnit
        setOpen={setOpen}
        functionalUnit={current}
        expendituresTypes={expendituresTypes}
      />
    ),
    delete: (
      <DeleteFunctionalUnit
        id={id}
        setOpen={setOpen}
        functionalUnit={current}
      />
    ),
    edit: (
      <EditFunctionalUnit
        id={id}
        token={user.token}
        setOpen={setOpen}
        functionalUnit={current}
        expendituresTypes={expendituresTypes}
      />
    ),
  };

  useEffect(() => {
    dispatch(getFunctionalUnits(id, user.token));
    dispatch(getExpendituresTypes(id, user.token, setIsLoadingComponent));
  }, [id, user.token, dispatch, setIsLoadingComponent]);

  return isLoadingComponent ? (
    <Spinner />
  ) : (
    <>
      <Table
        columns={columns}
        columnsMoreActions={columnsMoreActions}
        rows={rows}
        Cells={Cells}
        MoreActions={(row) => (
          <MoreActions row={row.row} dataAction={dataFunctionalUnit} />
        )}
        detailsAction={detailsFunctionalUnit}
        editAction={editFunctionalUnit}
        deleteAction={deleteFunctionalUnit}
        setAction={setAction}
        disableColumnEdit={!user.isAdmin}
        disableColumnDelete={!user.isAdmin}
      />
      <Modal
        handleClose={() => setOpen(false)}
        open={open}
        component={actions[action]}
      />
    </>
  );
};

export default List;
