import React, { useState, useEffect, Fragment } from "react";
import {
  Button,
  Container,
  Grid,
  Hidden,
  IconButton,
  makeStyles,
  Tooltip,
  Typography,
  useMediaQuery,
  useTheme,
} from "@material-ui/core";

import { useDispatch, useSelector } from "react-redux";
import Spinner from "../../components/UI/Spinner";

import Form from "../../components/Establishment/Form";

import EditIcon from "@material-ui/icons/Edit";
import CloseIcon from "@material-ui/icons/Close";
import {
  editEstablishmentData,
  getEstablishmentData,
} from "../../Redux/Action/establishmentActions";

const useStyles = makeStyles((theme) => ({
  root: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    marginTop: theme.spacing(3),
    marginBottom: theme.spacing(3),
    "@media (min-width:960px)": {
      margin: "auto",
      marginTop: theme.spacing(6),
      marginBottom: theme.spacing(6),
    },
  },
  grid: {
    marginBottom: theme.spacing(2),
    justifyContent: "flex-end",
    alignItems: "center",
    "@media (min-width:650px)": {
      flexDirection: "row",
    },
  },
  title: {
    marginBottom: 0,
    fontSize: "20px",
    width: "max-content",
    "@media (min-width:650px)": {
      fontSize: "24px",
    },
  },
  gridButton: {
    display: "flex",
    justifyContent: "flex-end",
  },
}));

const ManagementConfig = ({ user }) => {
  const classes = useStyles();
  const dispatch = useDispatch();

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const establishment = useSelector(
    (state) => state.establishment.establishment
  );

  const [isLoading, setIsLoading] = useState(true);
  const [isLoadingForm, setIsLoadingForm] = useState(false);

  const [image, setImage] = useState(null);

  const [hasChanged, setHasChanged] = useState(false);
  const [edit, setEdit] = useState(false);

  const changeAction = (value) => {
    setEdit(value);
    if (!value) setImage(establishment.image || null);
  };

  const onClickHandler = (data) => {
    setIsLoadingForm(true);

    data.image = image;

    dispatch(
      editEstablishmentData(user.token, data, setEdit, setIsLoadingForm)
    );
  };

  useEffect(() => {
    dispatch(getEstablishmentData(user.token, setIsLoading, setImage));
  }, [user.token, dispatch]);

  return (
    <Container className={classes.root} maxWidth="xl">
      {isLoading ? (
        <Spinner />
      ) : (
        <Fragment>
          <Grid container className={classes.grid}>
            <Grid item xs={isMobile ? 6 : 12} sm={6}>
              <Typography gutterBottom className={classes.title}>
                Establecimiento
              </Typography>
            </Grid>
            <Grid
              item
              xs={isMobile ? 6 : 12}
              sm={6}
              className={classes.gridButton}
            >
              <Hidden xsDown>
                <Button
                  variant="contained"
                  disableElevation
                  startIcon={edit ? <CloseIcon /> : <EditIcon />}
                  onClick={() => changeAction(!edit)}
                  style={
                    edit ? { backgroundColor: "#F73D3D", color: "#FFF" } : null
                  }
                >
                  {edit ? "Cancelar" : "Editar"}
                </Button>
              </Hidden>
              <Hidden smUp>
                <Tooltip title={edit ? "Cancelar" : "Editar"}>
                  <IconButton
                    variant="contained"
                    onClick={() => changeAction(false)}
                    style={edit ? { color: "#F73D3D" } : null}
                  >
                    {edit ? <CloseIcon /> : <EditIcon />}
                  </IconButton>
                </Tooltip>
              </Hidden>
            </Grid>
          </Grid>

          <Form
            data={establishment}
            image={image}
            setImage={setImage}
            edit={edit}
            isLoading={isLoadingForm}
            onClickHandler={onClickHandler}
            hasChanged={hasChanged}
            setHasChanged={setHasChanged}
            isMobile={isMobile}
          />
        </Fragment>
      )}
    </Container>
  );
};

export default ManagementConfig;
