import { createMuiTheme } from "@material-ui/core/styles";

const green = "#3C9A12";
const greenDark = "#2F860F";
const ink = "#1A2330";
const line = "#E6EBE8";

const theme = createMuiTheme({
  palette: {
    primary: {
      main: green,
      dark: greenDark,
      contrastText: "#FFFFFF",
    },
    secondary: {
      main: "#1260BD",
    },
    background: {
      default: "#F3F5F4",
      paper: "#FFFFFF",
    },
    text: {
      primary: ink,
      secondary: "#5C6B7A",
    },
  },
  typography: {
    fontFamily: '"Manrope", "Segoe UI", Roboto, sans-serif',
    h5: {
      fontWeight: 700,
      letterSpacing: "-0.02em",
      color: ink,
    },
    h6: {
      fontWeight: 700,
      letterSpacing: "-0.02em",
    },
    button: {
      textTransform: "none",
      fontWeight: 650,
      letterSpacing: "-0.01em",
    },
  },
  shape: {
    borderRadius: 10,
  },
  overrides: {
    MuiCssBaseline: {
      "@global": {
        body: {
          backgroundColor: "#F3F5F4",
          color: ink,
        },
      },
    },
    MuiButton: {
      root: {
        borderRadius: 8,
        textTransform: "none",
        fontWeight: 650,
        boxShadow: "none",
        padding: "6px 16px",
      },
      contained: {
        color: "#FFFFFF",
        backgroundColor: green,
        boxShadow: "none",
        "&:hover": {
          backgroundColor: greenDark,
          boxShadow: "none",
        },
      },
      containedPrimary: {
        backgroundColor: green,
        "&:hover": {
          backgroundColor: greenDark,
        },
      },
      outlined: {
        borderRadius: 8,
      },
    },
    MuiOutlinedInput: {
      root: {
        borderRadius: 10,
        backgroundColor: "#FFFFFF",
      },
    },
    MuiPaper: {
      rounded: {
        borderRadius: 12,
      },
    },
    MuiDialog: {
      paper: {
        borderRadius: 16,
      },
    },
    MuiMenu: {
      paper: {
        borderRadius: 12,
        border: `1px solid ${line}`,
        boxShadow: "0 12px 32px rgba(26, 35, 48, 0.08)",
      },
    },
    MuiTab: {
      root: {
        textTransform: "none",
        fontWeight: 600,
      },
    },
    MuiTableCell: {
      root: {
        borderBottom: `1px solid ${line}`,
      },
      head: {
        fontWeight: 700,
      },
    },
    MuiTableBody: {
      root: {
        "& .MuiTableRow-root:hover": {
          backgroundColor: "#F6FAF5",
        },
      },
    },
    MuiAppBar: {
      colorDefault: {
        backgroundColor: "#FFFFFF",
        color: ink,
      },
    },
    MuiAlert: {
      root: {
        borderRadius: 10,
        alignItems: "center",
      },
    },
    MuiIconButton: {
      root: {
        borderRadius: 8,
      },
    },
  },
});

export default theme;
