import React, { useState } from "react";
import {
  Button,
  Grid,
  makeStyles,
  MenuItem,
  TextField,
  Typography,
  useMediaQuery,
  useTheme,
} from "@material-ui/core";
import Spinner from "../UI/Spinner";
import { useForm } from "../../hooks/use-form";
import { ExpandMore } from "@material-ui/icons";
import DatePicker from "../Shared/DatePicker";
import NumberFormat from "react-number-format";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    width: theme.spacing(50),
    padding: theme.spacing(5),
    "@media (max-width:650px)": {
      width: theme.spacing(30),
      padding: theme.spacing(1),
    },
    "@media (max-width:400px)": {
      width: theme.spacing(20),
      padding: 0,
    },
  },
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  marginBottom: {
    marginBottom: theme.spacing(2.5),
  },
}));

function NumberFormatCustom(props) {
  const { inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={2}
      isNumericString
      prefix="$"
    />
  );
}

const initialState = {
  box: "",
};

const Form = ({ title, setOpen, isLoading, onClikHandler, balance, boxes }) => {
  const classes = useStyles();

  const [form, onChangeHandler] = useForm(initialState);

  const [date, setDate] = useState(null);
  const [amount, setAmount] = useState(
    parseFloat(balance, 10) >= 0 ? "" : -parseFloat(balance, 10)
  );

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const formatData = () => {
    let data = {
      box: form.box.value,
      amount: amount,
      date: date,
    };

    onClikHandler(data);
  };

  let disabled =
    Object.entries(form).filter(
      (entry) => entry[1].value === "" || entry[1].isValid === false
    ).length === 0
      ? false
      : true;

  return isLoading ? (
    <Spinner height={340} />
  ) : (
    <div>
      <Typography variant="h6">{title}</Typography>
      <Grid container className={classes.grid} spacing={1}>
        <Grid item xs={12}>
          <DatePicker
            label="Fecha"
            selectedDate={date}
            handleDateChange={(e) => setDate(e.toISOString())}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            fullWidth
            label="Caja"
            id="box"
            value={form.box.value}
            onChange={(e) => {
              e.target.id = "box";
              onChangeHandler(e);
            }}
            select
            SelectProps={{
              IconComponent: ExpandMore,
            }}
          >
            <MenuItem value=""></MenuItem>
            {boxes.map((box, index) => (
              <MenuItem key={`select-${index}`} value={box._id}>
                {box.name}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
        <Grid item xs={12}>
          <TextField
            className={classes.marginBottom}
            InputProps={{
              inputComponent: NumberFormatCustom,
            }}
            required
            autoComplete="off"
            label="Monto"
            id="amount"
            name="amount"
            value={amount}
            onChange={(e) => {
              setAmount(parseFloat(e.target.value, 10));
            }}
            fullWidth
            inputProps={{
              min: "0",
              pattern: "[0-9.]+",
              step: ".01",
            }}
            helperText={
              amount < 0
                ? "No puede ser negativo"
                : amount === 0
                ? "No puede ser $0"
                : null
            }
            InputLabelProps={{ required: false }}
          />
        </Grid>

        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            id="cancel-button"
            variant="outlined"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Cancelar
          </Button>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            disabled={disabled}
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={formatData}
          >
            Aceptar
          </Button>
        </Grid>
      </Grid>
    </div>
  );
};

export default Form;
