import React, { Fragment, useState } from "react";
import { makeStyles } from "@material-ui/core/styles";
import {
  AppBar,
  Toolbar,
  Menu,
  Button,
  Typography,
  Hidden,
  Divider,
  List,
  ListSubheader,
  ListItem,
  ListItemText,
  ButtonBase,
} from "@material-ui/core";
import IconButton from "@material-ui/core/IconButton";
import AccountCircle from "@material-ui/icons/AccountCircle";
import MenuIcon from "@material-ui/icons/Menu";
import { useDispatch } from "react-redux";
import { logOutUser } from "../../Redux/Action/userActions";
import { Link, useHistory } from "react-router-dom";

import logo from "../../assets/logo.png";
import { useLocation } from "react-router-dom/cjs/react-router-dom.min";

const useStyles = makeStyles((theme) => ({
  root: {
    flexGrow: 1,
  },
  menuButton: {
    marginRight: theme.spacing(2),
  },
  divLogo: {
    "@media (max-width: 959px)": {
      flexGrow: 1,
    },
  },
  logo: {
    width: 90,
    "@media (max-width: 959px)": {
      width: 75,
    },
  },
  buttonGroup: {
    flexGrow: 1,
    display: "flex",
    flexDirection: "row",
    marginLeft: theme.spacing(8.75),
    "@media (max-width: 800px)": {
      marginLeft: theme.spacing(5),
    },
  },
  button: {
    marginRight: theme.spacing(0.5),
    fontSize: 14,
    fontWeight: 600,
    textTransform: "none",
    color: "#3D4A57",
    borderRadius: 999,
    padding: "6px 14px",
  },
  right: {
    display: "flex",
    flexDirection: "row",
    alignItems: "center",
  },
  divLogoLink: {
    display: "flex",
  },
  btnProfile: {
    padding: "4px 10px 4px 12px",
    borderRadius: 999,
    border: "1px solid #E6EBE8",
    backgroundColor: "#FFFFFF",
    display: "flex",
    alignItems: "center",
    cursor: "pointer",
    "&:hover": {
      backgroundColor: "#F6FAF5",
      borderColor: "#D5E6CF",
    },
  },
  btnProfileText: {
    marginLeft: theme.spacing(0.5),
    marginRight: theme.spacing(1),
  },
  menu: {
    "& .MuiList-padding": {
      padding: 0,
    },
    "& .MuiListSubheader-gutters": {
      paddingLeft: 8,
    },
  },
  item: {
    borderRadius: 8,
    "&:hover": {
      backgroundColor: "#F1F6F0",
      color: "#1F6B08",
    },
  },
  background: {
    backgroundColor: "#E7F6DF",
    color: "#1B5E20",
  },
  logOut: {
    "&:hover": {
      backgroundColor: "#DF4646",
      color: "#FAFAFA",
    },
  },
}));

export default function MenuAppBar({ user, items }) {
  const classes = useStyles();
  const dispatch = useDispatch();
  const history = useHistory();
  const location = useLocation();

  const [anchorEl, setAnchorEl] = useState(null);
  const open = Boolean(anchorEl);

  const handleMenu = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  const logOut = () => {
    dispatch(logOutUser());
    setAnchorEl(null);
  };

  const navigate = (to) => {
    history.push(to);
    setAnchorEl(null);
  };

  return (
    <div className={classes.root}>
      <AppBar
        color="default"
        position="fixed"
        style={{
          boxShadow: "none",
          borderBottom: "1px solid #E6EBE8",
        }}
      >
        <Toolbar>
          <div className={classes.divLogo}>
            <Link
              to={
                user.type && user.type === "realstate"
                  ? "/alquileres"
                  : "/consorcios"
              }
              className={classes.divLogoLink}
            >
              <img src={logo} alt="Asiprop" className={classes.logo} />
            </Link>
          </div>
          <Hidden smDown>
            <div className={classes.buttonGroup}>
              {items
                .filter((entry) => !entry.onlyListItem)
                .map((entry, index) => (
                  <Button
                    key={`button-${index}`}
                    onClick={() => navigate(entry.route)}
                    className={`${classes.button} ${classes.item} ${
                      location.pathname.indexOf(entry.route) !== -1 &&
                      classes.background
                    }`}
                  >
                    {entry.name}
                  </Button>
                ))}
            </div>
            <div className={classes.right}>
              <ButtonBase
                centerRipple
                style={{ paddingLeft: 6 }}
                onClick={handleMenu}
              >
                <div className={classes.btnProfile}>
                  <Typography className={classes.btnProfileText}>
                    {`Hola ${user.name}`}
                  </Typography>

                  <AccountCircle />
                </div>
              </ButtonBase>
              <Menu
                getContentAnchorEl={null}
                id="menu-appbar"
                anchorOrigin={{
                  vertical: "bottom",
                  horizontal: "center",
                }}
                transformOrigin={{
                  vertical: "top",
                  horizontal: "center",
                }}
                anchorEl={anchorEl}
                open={open}
                onClose={handleClose}
                className={classes.menu}
              >
                <List component="nav" style={{ padding: 0 }}>
                  {items
                    .filter((entry) => entry.onlyListItem)
                    .map((entry, index) => (
                      <Fragment key={`listItem-${index}`}>
                        {index === 0 && (
                          <ListSubheader>Configuración</ListSubheader>
                        )}
                        <ListItem
                          button
                          onClick={() => navigate(entry.route)}
                          className={`${classes.item} ${
                            location.pathname.indexOf(entry.route) !== -1 &&
                            classes.background
                          }`}
                        >
                          <ListItemText primary={entry.name} />
                        </ListItem>
                      </Fragment>
                    ))}
                  <ListItem button onClick={logOut} className={classes.logOut}>
                    <ListItemText primary="Cerrar sesión" />
                  </ListItem>
                </List>
              </Menu>
            </div>
          </Hidden>
          <Hidden mdUp>
            <div className={classes.right}>
              <IconButton
                aria-label="account of current user"
                aria-controls="menu-appbar"
                aria-haspopup="true"
                onClick={handleMenu}
                color="inherit"
              >
                <MenuIcon />
              </IconButton>
              <Menu
                getContentAnchorEl={null}
                id="menu-appbar"
                anchorOrigin={{
                  vertical: "bottom",
                  horizontal: "center",
                }}
                transformOrigin={{
                  vertical: "top",
                  horizontal: "center",
                }}
                anchorEl={anchorEl}
                open={open}
                onClose={handleClose}
                className={classes.menu}
              >
                <List component="nav" style={{ padding: 0 }}>
                  {items
                    .filter((entry) => !entry.onlyListItem)
                    .map((entry, index) => (
                      <ListItem
                        key={`listItem-${index}`}
                        button
                        onClick={() => navigate(entry.route)}
                        className={`${classes.item} ${
                          location.pathname.indexOf(entry.route) !== -1 &&
                          classes.background
                        }`}
                      >
                        <ListItemText primary={entry.name} />
                      </ListItem>
                    ))}
                  {items
                    .filter((entry) => entry.onlyListItem)
                    .map((entry, index) => (
                      <Fragment key={`listItem-settings-${index}`}>
                        {index === 0 && (
                          <ListSubheader>Configuración</ListSubheader>
                        )}
                        <ListItem
                          button
                          onClick={() => navigate(entry.route)}
                          className={`${classes.item} ${
                            location.pathname.indexOf(entry.route) !== -1 &&
                            classes.background
                          }`}
                        >
                          <ListItemText primary={entry.name} />
                        </ListItem>
                      </Fragment>
                    ))}
                  <Divider />
                  <ListItem button onClick={logOut} className={classes.logOut}>
                    <ListItemText primary="Cerrar sesión" />
                  </ListItem>
                </List>
              </Menu>
            </div>
          </Hidden>
        </Toolbar>
      </AppBar>
      <Toolbar />
    </div>
  );
}
