import React from "react";
import { useSelector } from "react-redux";

import SnackbarCustom from "./components/UI/SnackbarCustom";

import Navbar from "./components/UI/Navbar";

import PublicRoutes from "./Routes/PublicRoutes";
import PrivateRoutes from "./Routes/PrivateRoutes";
import { makeStyles } from "@material-ui/core";
import ITEMS from "./configs/ITEMS";
import DemoBanner from "./demo/DemoBanner";

const useStyles = makeStyles((theme) => ({
  root: {
    display: "flex",
    flexDirection: "column",
    height: "100vh",
    justifyContent: "space-between",
    backgroundColor: "#F3F5F4",
  },
  content: {
    overflowX: "hidden",
    overflowY: "auto",
    height: "100%",
    minHeight: "90vh",
    flexGrow: 1,
    padding: theme.spacing(2.25),
    marginLeft: 0,
    backgroundColor: "#F3F5F4",
    display: "flex",
    flexDirection: "column",
    ...(process.env.REACT_APP_DEMO === "true" && {
      paddingBottom: 36,
    }),
  },
}));

function App() {
  const classes = useStyles();

  const user = useSelector((state) => state.user.userData);

  return (
    <div className={classes.root}>
      {user && (
        <Navbar user={user} items={ITEMS[user.isAdmin ? "admin" : "user"]} />
      )}
      <div className={classes.content}>
        {!user ? <PublicRoutes user={user} /> : <PrivateRoutes user={user} />}
      </div>
      <SnackbarCustom />
      {process.env.REACT_APP_DEMO === "true" && <DemoBanner />}
    </div>
  );
}

export default App;
