import React from "react";
import Alert from "@material-ui/lab/Alert";
import { Grid, makeStyles } from "@material-ui/core";

const useStyles = makeStyles((theme) => ({
  container: {
    margin: theme.spacing(3, 0),
    minHeight: theme.spacing(6),
    maxHeight: theme.spacing(14),
    overflowX: "hidden",
    overflowY: "auto",
  },
  card: {
    height: theme.spacing(5.25),
    padding: theme.spacing(1, 2),
    alignItems: "center",
    "& .MuiAlert-message": {
      padding: 0,
      fontSize: "13px",
    },
  },
}));

const ListExpenditures = ({
  expenditures,
  expendituresTypes,
  deleteExpenditure,
}) => {
  const classes = useStyles();

  const getName = (id) => {
    let name = expendituresTypes.filter((entry) => entry._id === id)[0].name;
    return name;
  };

  return (
    <div className={classes.container}>
      <Grid container spacing={1}>
        {expenditures.map((expenditure) => (
          <Grid key={expenditure.expenditureType} item xs={12} sm={6}>
            <Alert
              className={classes.card}
              icon={false}
              onClose={
                deleteExpenditure
                  ? () => deleteExpenditure(expenditure.expenditureType)
                  : undefined
              }
            >
              {`${getName(expenditure.expenditureType)} - ${
                expenditure.percentage
              }%`}
            </Alert>
          </Grid>
        ))}
      </Grid>
    </div>
  );
};

export default ListExpenditures;
