import React from "react";
import Modal from "@material-ui/core/Modal";

import { IconButton, makeStyles } from "@material-ui/core";
import CloseIcon from "@material-ui/icons/Close";

const useStyles = makeStyles((theme) => ({
  modal: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    margin: theme.spacing(2),
  },
  paper: {
    width: "100%",
    position: "absolute",
    minWidth: theme.spacing(37.5),
    maxWidth: theme.spacing(71.5),
    maxHeight: "90vh",
    overflow: "auto",
    backgroundColor: theme.palette.background.paper,
    padding: theme.spacing(3),
    borderRadius: 16,
    boxShadow: "0 18px 48px rgba(26, 35, 48, 0.12)",
    outline: "none",
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
  },
  closeButton: {
    position: "absolute",
    right: 0,
    top: 0,
    "&:hover": { backgroundColor: "transparent" },
  },
}));

const CustomModal = ({ open, handleClose, component, maxWidth }) => {
  const classes = useStyles();

  return (
    <Modal
      aria-labelledby="CustomModal"
      aria-describedby="CustomModal"
      className={classes.modal}
      open={open}
    >
      <div
        className={classes.paper}
        style={maxWidth ? { maxWidth: maxWidth } : null}
      >
        <IconButton
          className={classes.closeButton}
          aria-label="cerrar"
          onClick={handleClose}
        >
          <CloseIcon />
        </IconButton>
        {component}
      </div>
    </Modal>
  );
};

export default CustomModal;
