import React, { Fragment, useState } from "react";
import {
  Button,
  Checkbox,
  Grid,
  makeStyles,
  TableCell,
  Typography,
  useMediaQuery,
  useTheme,
} from "@material-ui/core";

import Table from "../Shared/Table";
import Spinner from "../UI/Spinner";
import { useDispatch } from "react-redux";
import { sendEmails } from "../../Redux/Action/expensesActions";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    padding: theme.spacing(1),
    "@media (max-width:400px)": {
      padding: 0,
    },
  },
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  title: {
    fontSize: "14px",
    textAlign: "initial",
  },
  buttons: {
    marginTop: theme.spacing(2.5),
  },
}));

const columns = ["Unidad funcional", "Piso y letra", "Dueño"];

const Cells = ({ row, setChecked }) => {
  return (
    <Fragment>
      <TableCell padding="checkbox">
        <Checkbox
          checked={row.checked}
          onChange={(e) => setChecked(e, row._id)}
        />
      </TableCell>
      <TableCell component="th" scope="row">
        {row.number}
      </TableCell>
      <TableCell component="th" scope="row">
        {row.apartment}
      </TableCell>
      <TableCell component="th" scope="row">
        {`${row.owner.name} ${row.owner.lastname}`}
      </TableCell>
    </Fragment>
  );
};

const SendEmail = ({ id, token, setOpen, expense, functionalUnits }) => {
  const classes = useStyles();
  const dispatch = useDispatch();

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const [isLoading, setIsLoading] = useState(false);

  const [recipients, setRecipients] = useState(() => {
    let obj = [];
    let aux = [];

    for (let i = 0; i < expense.functionalUnits.length; i++) {
      for (let j = 0; j < functionalUnits.length; j++) {
        if (
          functionalUnits[j]._id === expense.functionalUnits[i].functionalUnit
        ) {
          aux.push(functionalUnits[j]);
        }
      }
    }

    obj = aux.reduce((obj, uf) => {
      return [
        ...obj,
        {
          checked: true,
          _id: uf._id,
          number: uf.number,
          apartment: uf.apartment,
          owner: uf.owner,
        },
      ];
    }, []);

    return obj;
  });

  const [selected, setSelected] = useState(() => {
    let obj = recipients.reduce((obj, uf) => {
      return [...obj, uf._id];
    }, []);

    return obj;
  });

  const handleSelectAllClick = (event) => {
    setRecipients((recipients) => {
      let copy = [...recipients];
      let aux = [];

      for (let i = 0; i < copy.length; i++) {
        copy[i].checked = event.target.checked ? true : false;
        if (event.target.checked) {
          aux.push(copy[i]._id);
        }
      }

      setSelected(event.target.checked ? aux : []);

      return copy;
    });
  };

  const setChecked = (event, id) => {
    let i = recipients.findIndex((addressee) => {
      if (addressee._id === id) {
        return true;
      }
      return false;
    });

    setRecipients((recipients) => {
      let copy = [...recipients];

      if (i !== -1) {
        copy[i].checked = event.target.checked;
      }

      return copy;
    });

    if (event.target.checked) {
      setSelected((selected) => {
        let copy = [...selected];

        copy.push(recipients[i]._id);

        return copy;
      });
    } else {
      setSelected((selected) => {
        let i = selected.findIndex((addressee) => {
          if (addressee === id) {
            return true;
          }
          return false;
        });

        let copy = [...selected];

        if (i !== -1) {
          copy.splice(i, 1);
        }

        return copy;
      });
    }
  };

  const onClickHandler = () => {
    setIsLoading(true);
    let data = { functionalUnits: selected };
    dispatch(sendEmails(id, token, expense._id, data, setOpen, setIsLoading));
  };

  let dataSelecting = {
    indeterminate: selected.length > 0 && selected.length < recipients.length,
    checked: recipients.length > 0 && selected.length === recipients.length,
    onChange: handleSelectAllClick,
  };

  return (
    <div
      className={classes.container}
      style={!isLoading ? { width: "100%" } : null}
    >
      {isLoading ? (
        <Spinner />
      ) : (
        <div>
          <Typography variant="h6">Enviar expensas por Email</Typography>

          <Grid container className={classes.grid} spacing={2}>
            <Grid item xs={12} className={classes.expendituresSection}>
              <Typography className={classes.title}>
                Listado de unidades funcionales a las que le llegaran el mail.
              </Typography>
            </Grid>
            <Grid item xs={12}>
              <Table
                selecting={true}
                dataSelecting={dataSelecting}
                columns={columns}
                rows={recipients}
                Cells={(row) => <Cells row={row.row} setChecked={setChecked} />}
                disableColumnDetails={true}
                disableColumnEdit={true}
                disableColumnDelete={true}
              />
            </Grid>
          </Grid>
          <Grid container className={classes.buttons} spacing={1}>
            <Grid item xs={6} sm={isMobile ? 2 : 6}>
              <Button
                id="cancel-button"
                variant="outlined"
                color="primary"
                disableElevation
                fullWidth
                onClick={() => setOpen(false)}
              >
                Cancelar
              </Button>
            </Grid>
            <Grid item xs={6} sm={isMobile ? 2 : 6}>
              <Button
                disabled={selected.length <= 0 ? true : false}
                variant="contained"
                color="primary"
                disableElevation
                fullWidth
                onClick={onClickHandler}
              >
                Enviar
              </Button>
            </Grid>
          </Grid>
        </div>
      )}
    </div>
  );
};

export default SendEmail;
