import React from "react";
import TextField from "@material-ui/core/TextField";
import Grid from "@material-ui/core/Grid";

import MenuItem from "@material-ui/core/MenuItem";

import {
  FormControl,
  FormControlLabel,
  Radio,
  RadioGroup,
} from "@material-ui/core";

export default function EstablishmentFormControls({ onChangeHandler, form }) {
  return (
    <>
      <Grid item xs={12}>
        <TextField
          variant="outlined"
          fullWidth
          required
          name="type"
          label="Establecimiento"
          id="type"
          onChange={(e) => onChangeHandler({ ...form, type: e.target.value })}
          value={form.type}
          select
          InputLabelProps={{ required: false }}
        >
          <MenuItem value={"consortium"}>Consorcio</MenuItem>
          <MenuItem value={"realstate"}>Inmobiliaria</MenuItem>
        </TextField>
      </Grid>
      <Grid item xs={12} justifycontent="center" container>
        <FormControl component="fieldset" required>
          <RadioGroup
            row
            aria-label="exists"
            name="exists"
            value={form.exists}
            onChange={(e) =>
              onChangeHandler({ ...form, exists: e.target.value })
            }
          >
            <FormControlLabel
              value={"false"}
              control={<Radio />}
              label="Nuevo"
            />
            <FormControlLabel
              value={"true"}
              control={<Radio />}
              label="Existente"
            />
          </RadioGroup>
        </FormControl>
      </Grid>
    </>
  );
}
