import React, { useState, useEffect } from "react";
import {
  Button,
  Grid,
  Hidden,
  IconButton,
  makeStyles,
  Tooltip,
  Typography,
  useMediaQuery,
  useTheme,
  TableCell,
} from "@material-ui/core";
import AddIcon from "@material-ui/icons/Add";
import ReloadIcon from "@material-ui/icons/Cached";
import Table from "../Shared/Table";
import Modal from "../Shared/Modal";
import { useDispatch, useSelector } from "react-redux";
import { getCategories } from "../../Redux/Action/categoriesActions";
import Spinner from "../UI/Spinner";

import AddCategory from "./AddCategory";
import DeleteCategory from "./DeleteCategory";
import EditCategory from "./EditCategory";

const useStyles = makeStyles((theme) => ({
  root: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    marginTop: theme.spacing(2),
  },
  grid: {
    marginBottom: theme.spacing(2),
    justifyContent: "flex-end",
    alignItems: "center",
    "@media (min-width:650px)": {
      flexDirection: "row",
    },
  },
  gridButton: {
    display: "flex",
    justifyContent: "flex-end",
  },
  reload: {
    padding: theme.spacing(0.75),
    marginRight: theme.spacing(2.5),
  },
  add: {
    padding: theme.spacing(0.75),
  },
  title: {
    marginBottom: 0,
    fontSize: "20px",
    width: "max-content",
    "@media (min-width:650px)": {
      fontSize: "24px",
    },
  },
}));

const columns = ["Categoría", "Editar", "Eliminar"];

const Cells = ({ row }) => {
  return (
    <>
      <TableCell component="th" scope="row">
        {row.name}
      </TableCell>
    </>
  );
};

const Categories = ({ id, token }) => {
  const classes = useStyles();
  const dispatch = useDispatch();

  const [isLoading, setIsLoading] = useState(true);
  const [open, setOpen] = useState(false);
  const [current, setCurrent] = useState(null);
  const [action, setAction] = useState(false);

  const rows = useSelector((state) => state.categories.categories).sort(
    (a, b) => {
      if (a.name.toUpperCase() > b.name.toUpperCase()) {
        return 1;
      }
      if (a.name.toUpperCase() < b.name.toUpperCase()) {
        return -1;
      }

      return 0;
    }
  );

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const reload = () => {
    setIsLoading(true);
    dispatch(getCategories(id, token, setIsLoading));
  };

  const addConsortium = () => {
    setAction("add");
    setOpen(true);
  };

  const editCategory = (current) => {
    setOpen(true);
    setCurrent(current);
  };
  const deleteCategory = (current) => {
    setOpen(true);
    setCurrent(current);
  };

  const actions = {
    add: <AddCategory id={id} token={token} setOpen={setOpen} />,
    edit: (
      <EditCategory
        id={id}
        token={token}
        setOpen={setOpen}
        category={current}
      />
    ),
    delete: <DeleteCategory id={id} setOpen={setOpen} category={current} />,
  };

  useEffect(() => {
    dispatch(getCategories(id, token, setIsLoading));
  }, [id, token, dispatch]);

  return isLoading ? (
    <Spinner />
  ) : (
    <>
      <Grid container className={classes.grid}>
        <Grid item xs={isMobile ? 6 : 12} sm={6}>
          <Typography gutterBottom className={classes.title}>
            Categorias
          </Typography>
        </Grid>
        <Grid item xs={isMobile ? 6 : 12} sm={6} className={classes.gridButton}>
          <Hidden xsDown>
            <Tooltip title="Recargar tabla">
              <IconButton
                className={classes.reload}
                variant="contained"
                aria-label="add"
                onClick={reload}
              >
                <ReloadIcon />
              </IconButton>
            </Tooltip>
            <Button
              variant="contained"
              disableElevation
              startIcon={<AddIcon />}
              onClick={addConsortium}
            >
              Agregar
            </Button>
          </Hidden>
          <Hidden smUp>
            <Tooltip title="Recargar tabla">
              <IconButton
                className={classes.reload}
                variant="contained"
                aria-label="add"
                onClick={reload}
              >
                <ReloadIcon />
              </IconButton>
            </Tooltip>
            <Tooltip title="Agregar">
              <IconButton
                className={classes.add}
                variant="contained"
                aria-label="add"
                onClick={addConsortium}
              >
                <AddIcon />
              </IconButton>
            </Tooltip>
          </Hidden>
        </Grid>
      </Grid>
      <Table
        columns={columns}
        rows={rows}
        Cells={Cells}
        disableColumnDetails={true}
        editAction={editCategory}
        deleteAction={deleteCategory}
        setAction={setAction}
      />
      <Modal
        handleClose={() => setOpen(false)}
        open={open}
        component={actions[action]}
      />
    </>
  );
};

export default Categories;
