import React, { Fragment } from "react";
import { Button, Grid, makeStyles, TextField } from "@material-ui/core";
import NumberFormat from "react-number-format";

const useStyles = makeStyles((theme) => ({
  addButton: {
    backgroundColor: "#49AC08",
    color: "#FAFAFA",
    textTransform: "capitalize",
    fontSize: 12,
    "&:hover": {
      backgroundColor: "#49ac089e",
    },
  },
}));

function NumberFormatCustom(props) {
  const { min, id, inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
            id: id,
            validity: {
              valid: parseFloat(values.value, 10) > parseFloat(min, 10),
            },
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={2}
      isNumericString
      prefix="$"
    />
  );
}

const DiscountsForm = ({
  isMobile,
  data,
  setData,
  setForm,
  addDiscount,
  amounts,
}) => {
  const classes = useStyles();

  const onClick = () => {
    let aux = {};

    for (let key in data) {
      if (data[key].value !== "") {
        aux[key] = data[key].value;
      }
    }

    setForm((data) => {
      let copy = { ...data };
      for (let key in data) {
        copy[key] = {
          value: "",
          isValid: true,
        };
      }
      return copy;
    });

    addDiscount(aux);
  };

  let disabled = !Object.entries(data)
    .filter((entry) => entry[0] !== "note")
    .some((entry) => entry[1].value === "" || entry[1].isValid !== true)
    ? false
    : true;

  return (
    <Fragment>
      <Grid item xs={12} sm={6}>
        <TextField
          value={data.concept.value}
          required
          autoComplete="off"
          fullWidth
          id="concept"
          name="concept"
          label="Tipo"
          inputProps={{
            minLength: 2,
            maxLength: 100,
            pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
          }}
          onChange={setData}
          error={!data.concept.isValid}
          InputLabelProps={{ required: false }}
        />
      </Grid>

      <Grid item xs={12} sm={6}>
        <TextField
          InputProps={{
            inputComponent: NumberFormatCustom,
          }}
          required
          autoComplete="off"
          label="Importe"
          id="amount"
          name="amount"
          value={data.amount.value}
          onChange={(e) => {
            let value = parseFloat(e.target.value);

            if (
              data.amount.value === "" &&
              data.amount.isValid === true &&
              isNaN(value) &&
              amounts.remainsToPay === 0
            ) {
              e.target.validity.valid = true;
            }

            if (e.target.value !== "") setData(e);
          }}
          fullWidth
          inputProps={{
            min: "0",
            pattern: "[0-9.]+",
            step: ".01",
          }}
          error={!data.amount.isValid}
          InputLabelProps={{ required: false }}
        />
      </Grid>
      <Grid item xs={isMobile ? 12 : 6}>
        <TextField
          id="note"
          label="Nota (Opcional)"
          multiline
          value={data.note.value}
          variant="outlined"
          onChange={setData}
          fullWidth
          inputProps={{
            maxLength: 300,
            pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
          }}
          error={!data.note.isValid}
        />
      </Grid>
      <Grid
        item
        xs={isMobile ? 12 : 6}
        style={{ display: "flex", alignItems: "end" }}
      >
        <Button
          disabled={disabled}
          fullWidth
          disableElevation
          variant="contained"
          className={classes.addButton}
          onClick={onClick}
        >
          Agregar descuento
        </Button>
      </Grid>
    </Fragment>
  );
};

export default DiscountsForm;
