import React, { Fragment } from "react";
import {
  FormControl,
  FormHelperText,
  Grid,
  Input,
  InputLabel,
  MenuItem,
  TextField,
} from "@material-ui/core";

import { ExpandMore } from "@material-ui/icons";

import { months, days } from "../../../configs/contracts/DAYS_MONTHS";
import NumberFormat from "react-number-format";

function NumberFormatCustom(props) {
  const { min, id, inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
            id: id,
            validity: {
              valid: parseFloat(values.value, 10) >= parseFloat(min, 10),
            },
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={3}
      isNumericString
      prefix="$"
    />
  );
}

function NumberFormatPercentage(props) {
  const { min, max, id, inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
            id: id,
            validity: {
              valid:
                parseFloat(values.value, 10) <= parseFloat(max, 10) &&
                parseFloat(values.value, 10) >= parseFloat(min, 10),
            },
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={3}
      isNumericString
      suffix="%"
    />
  );
}

const Rental = ({
  data,
  setData,
  onChangeData,
  isMobile,
  xs,
  addOrEditItem,
}) => {
  const getAmount = () => {
    if (data.amount.value !== "" && data.monthlyFeePercentage.value !== "") {
      return (data.monthlyFeePercentage.value * data.amount.value) / 100;
    }

    return "0";
  };

  return (
    <Fragment>
      {!addOrEditItem && (
        <Grid item xs={isMobile ? 6 : xs || 3}>
          <TextField
            label="Meses"
            id="months"
            value={data.months.value}
            onChange={(e) => {
              e.target.id = "months";
              setData(e);
              onChangeData();
            }}
            select
            SelectProps={{
              IconComponent: ExpandMore,
            }}
            fullWidth
          >
            <MenuItem value=""></MenuItem>
            {months.map((entry, index) => (
              <MenuItem key={`select-${entry}-${index}`} value={entry}>
                {entry}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
      )}

      <Grid item xs={isMobile ? 6 : xs || 3}>
        <TextField
          InputProps={{
            inputComponent: NumberFormatCustom,
          }}
          required
          autoComplete="off"
          label="Importe"
          id="amount"
          name="amount"
          value={data.amount.value}
          onChange={(e) => {
            setData(e);
            onChangeData();
          }}
          fullWidth
          inputProps={{
            min: "0",
            pattern: "[0-9.]+",
            step: ".01",
          }}
          error={!data.amount.isValid}
          InputLabelProps={{ required: false }}
        />
      </Grid>

      {!addOrEditItem && (
        <Fragment>
          <Grid item xs={isMobile ? 6 : xs || 3}>
            <TextField
              InputProps={{
                inputComponent: NumberFormatPercentage,
              }}
              value={data.increasePercentage.value}
              autoComplete="off"
              fullWidth
              id="increasePercentage"
              name="increasePercentage"
              label="% Aumento"
              placeholder="0"
              inputProps={{
                min: "0",
                max: "100",
                pattern: "[0-9]+",
                step: ".01",
              }}
              error={!data.increasePercentage.isValid}
              onChange={(e) => {
                setData(e);
                onChangeData();
              }}
            />
          </Grid>
          <Grid item xs={isMobile ? 6 : xs || 3}>
            <TextField
              label="Aumento cada"
              id="increaseMonths"
              value={data.increaseMonths.value}
              onChange={(e) => {
                e.target.id = "increaseMonths";
                setData(e);
                onChangeData();
              }}
              select
              SelectProps={{
                IconComponent: ExpandMore,
              }}
              fullWidth
            >
              <MenuItem value=""></MenuItem>
              {months.map((entry, index) => (
                <MenuItem key={`select-${entry}-${index}`} value={entry}>
                  {`${entry} meses`}
                </MenuItem>
              ))}
            </TextField>
          </Grid>
        </Fragment>
      )}
      <Grid item xs={isMobile ? 6 : xs || 3}>
        <TextField
          InputProps={{
            inputComponent: addOrEditItem
              ? NumberFormatCustom
              : NumberFormatPercentage,
          }}
          value={
            addOrEditItem ? data.fee.value : data.monthlyFeePercentage.value
          }
          autoComplete="off"
          fullWidth
          id={addOrEditItem ? "fee" : "monthlyFeePercentage"}
          name={addOrEditItem ? "fee" : "monthlyFeePercentage"}
          label="Honorarios"
          placeholder="0"
          inputProps={
            addOrEditItem
              ? { min: "0", pattern: "[0-9.]+", step: ".01" }
              : {
                  min: "0",
                  max: "100",
                  pattern: "[0-9]+",
                  step: ".01",
                }
          }
          error={!data[addOrEditItem ? "fee" : "monthlyFeePercentage"].isValid}
          onChange={(e) => {
            setData(e);
            onChangeData();
          }}
        />
      </Grid>
      {!addOrEditItem && (
        <Fragment>
          <Grid item xs={isMobile ? 6 : xs || 3}>
            <FormControl style={{ width: "100%" }}>
              <InputLabel htmlFor="my-input">Monto honorarios</InputLabel>
              <Input
                id="amountFee"
                value={getAmount()}
                name="amountFee"
                fullWidth
                readOnly={true}
                inputComponent={NumberFormatCustom}
              />
              <FormHelperText id="helper-text-password">
                Solo lectura
              </FormHelperText>
            </FormControl>
          </Grid>

          <Grid item xs={isMobile ? 6 : xs || 3}>
            <TextField
              label="Vence todos los"
              id="expirationDay"
              value={data.expirationDay.value}
              onChange={(e) => {
                e.target.id = "expirationDay";
                setData(e);
                onChangeData();
              }}
              select
              SelectProps={{
                IconComponent: ExpandMore,
              }}
              fullWidth
            >
              <MenuItem value=""></MenuItem>
              {days.map((entry, index) => (
                <MenuItem key={`select-${entry}-${index}`} value={entry}>
                  {entry}
                </MenuItem>
              ))}
            </TextField>
          </Grid>
          <Grid item xs={isMobile ? 6 : xs || 3}>
            <TextField
              InputProps={{
                inputComponent: NumberFormatPercentage,
              }}
              value={data.dailyInterestPercentage.value}
              autoComplete="off"
              fullWidth
              id="dailyInterestPercentage"
              name="dailyInterestPercentage"
              label="Interés diario"
              helperText="*por vencimiento"
              placeholder="0"
              inputProps={{
                min: "0",
                max: "100",
                pattern: "[0-9]+",
                step: ".01",
              }}
              error={!data.dailyInterestPercentage.isValid}
              onChange={(e) => {
                setData(e);
                onChangeData();
              }}
            />
          </Grid>
        </Fragment>
      )}
    </Fragment>
  );
};

export default Rental;
