export const calculateIndividualInterests = (item, date) => {
  let interest = 0;

  const diffTime =
    new Date(date) -
    (item.paymentsDates && item.paymentsDates.length !== 0
      ? new Date(item.paymentsDates[item.paymentsDates.length - 1].date)
      : new Date(item.expirationDate));

  const diffDays = diffTime / (1000 * 60 * 60 * 24);

  if (item.dailyInterestPercentage && item.amount) {
    let aux =
      ((item.payedAmount ? item.amount - item.payedAmount : item.amount) *
        (parseFloat(diffDays.toFixed()) * item.dailyInterestPercentage)) /
      100;

    interest = parseFloat(aux.toFixed(2));

    item.interestAmount = parseFloat(aux.toFixed(2));
  }

  if (item.itemType === 2) {
    item.cashToBox = false;
  }

  return interest;
};

export const calculateGroupInterests = (obj, items, date) => {
  let copyItems = Array.from(items);
  let sum = 0;

  for (let entry of copyItems) {
    if (entry.itemType === 2) {
      obj.totalAmount += 0;
      obj.remainsToPay += 0;
    } else {
      obj.totalAmount += entry.amount - entry.payedAmount;
      obj.remainsToPay += entry.amount - entry.payedAmount;
    }

    sum += calculateIndividualInterests(entry, date);
  }

  obj.taxes = sum;

  return copyItems;
};

export const handleChangeCashToBox = (
  event,
  id,
  items,
  setItems,
  amounts,
  setAmounts,
  setDataPayments
) => {
  let copy = Array.from(items);

  let item = {};

  let auxTotalAmount = parseFloat(amounts.totalAmount);
  let auxRemainsToPay = parseFloat(amounts.remainsToPay);

  let checked = event.target.checked;

  let i = copy.findIndex((entry) => {
    if (entry._id === id) {
      return true;
    }
    return false;
  });

  if (i !== -1) {
    item = copy[i];
    copy[i].cashToBox = checked;

    let amountToPay = 0;

    if (item.paymentMethod === 1) {
      amountToPay +=
        (item.amount * item.tenantPercentage) / 100 - item.payedAmount;
    } else {
      if (item.tenantAmount) {
        amountToPay = item.tenantAmount - item.payedAmount;
      } else {
        amountToPay = item.amount - item.ownerAmount - item.payedAmount;
      }
    }

    if (checked) {
      auxTotalAmount += amountToPay;
      auxRemainsToPay =
        auxTotalAmount -
          amounts.positiveBalance -
          amounts.payments -
          amounts.discounts <=
        0
          ? 0
          : auxTotalAmount -
            amounts.positiveBalance -
            amounts.payments -
            amounts.discounts;
    } else {
      auxTotalAmount -= amountToPay;
      auxRemainsToPay -= amountToPay;
    }

    setAmounts({
      ...amounts,
      totalAmount:
        auxTotalAmount <= 0 ? 0 : parseFloat(auxTotalAmount.toFixed(2)),
      remainsToPay:
        auxRemainsToPay <= 0 ? 0 : parseFloat(auxRemainsToPay.toFixed(2)),
    });

    setDataPayments({
      target: {
        id: "amount",
        value:
          auxRemainsToPay > 0 ? parseFloat(auxRemainsToPay.toFixed(2)) : "",
        validity: { valid: true },
      },
    });
  }

  setItems(copy);
};

export const onChangeChecked = (
  e,
  id,
  values,
  setValues,
  setDataPayments,
  setAmounts,
  amounts
) => {
  let value = e.target.value;

  let aux = 0;

  setValues({ ...values, [id]: value });

  if (value === "true") {
    aux =
      parseFloat(amounts.payments) + parseFloat(amounts.discounts) >=
      parseFloat(amounts.taxes) +
        parseFloat(amounts.totalAmount) -
        parseFloat(amounts.positiveBalance)
        ? 0
        : parseFloat(amounts.totalAmount) +
          parseFloat(amounts.taxes) -
          parseFloat(amounts.positiveBalance) -
          (parseFloat(amounts.payments) + parseFloat(amounts.discounts));
  } else {
    aux =
      parseFloat(amounts.payments) + parseFloat(amounts.discounts) >=
      parseFloat(amounts.totalAmount) - parseFloat(amounts.positiveBalance)
        ? 0
        : parseFloat(amounts.remainsToPay) - parseFloat(amounts.taxes);
  }

  setDataPayments({
    target: {
      id: "amount",
      value: aux > 0 ? parseFloat(aux.toFixed(2)) : "",
      validity: { valid: true },
    },
  });

  setAmounts({
    ...amounts,
    remainsToPay: aux > 0 ? parseFloat(aux.toFixed(2)) : 0,
  });
};

export const addPayment = (
  data,
  setDataPayments,
  payments,
  setPayments,
  amounts,
  setAmounts,
  setFormDiscounts
) => {
  let aux = parseFloat(amounts.remainsToPay) - parseFloat(data.amount);
  let collect = parseFloat(amounts.payments) + parseFloat(data.amount);

  setDataPayments({
    target: {
      id: "amount",
      value: aux <= 0 ? "" : parseFloat(aux.toFixed(2)),
      validity: { valid: true },
    },
  });

  setPayments([...payments, data]);

  setAmounts({
    ...amounts,
    remainsToPay: aux <= 0 ? 0 : parseFloat(aux.toFixed(2)),
    payments: parseFloat(collect.toFixed(2)),
  });

  setFormDiscounts((dataDiscounts) => {
    let copy = { ...dataDiscounts };
    for (let key in dataDiscounts) {
      copy[key] = {
        value: "",
        isValid: true,
      };
    }
    return copy;
  });
};

export const deletePayment = (
  index,
  values,
  setDataPayments,
  payments,
  setPayments,
  amounts,
  setAmounts
) => {
  let aux = 0;

  if (values.checked === "false") {
    aux =
      parseFloat(amounts.payments) +
        parseFloat(amounts.discounts) -
        parseFloat(payments[index].amount) >=
      parseFloat(amounts.totalAmount) - parseFloat(amounts.positiveBalance)
        ? 0
        : parseFloat(amounts.totalAmount) -
          parseFloat(amounts.positiveBalance) -
          (parseFloat(amounts.payments) +
            parseFloat(amounts.discounts) -
            parseFloat(payments[index].amount));
  } else {
    aux =
      parseFloat(amounts.payments) +
        parseFloat(amounts.discounts) -
        parseFloat(payments[index].amount) >=
      parseFloat(amounts.totalAmount) -
        parseFloat(amounts.positiveBalance) +
        parseFloat(amounts.taxes)
        ? 0
        : parseFloat(amounts.totalAmount) +
          parseFloat(amounts.taxes) -
          (parseFloat(amounts.payments) +
            parseFloat(amounts.discounts) -
            parseFloat(payments[index].amount));
  }

  let collect =
    parseFloat(amounts.payments) - parseFloat(payments[index].amount);

  setDataPayments({
    target: {
      id: "amount",
      value: aux <= 0 ? "" : parseFloat(aux.toFixed(2)),
      validity: { valid: true },
    },
  });

  setPayments((payments) => {
    let copy = [...payments];
    copy.splice(index, 1);
    return copy;
  });

  setAmounts({
    ...amounts,
    remainsToPay: aux <= 0 ? 0 : parseFloat(aux.toFixed(2)),
    payments: parseFloat(collect.toFixed(2)),
  });
};

