export const setChecked = (
  event,
  id,
  recipients,
  setRecipients,
  setSelected
) => {
  let i = recipients.findIndex((addressee) => {
    if (addressee._id === id) {
      return true;
    }
    return false;
  });

  setRecipients((recipients) => {
    let copy = [...recipients];

    if (i !== -1) {
      copy[i].checked = event.target.checked;
    }

    return copy;
  });

  if (event.target.checked) {
    setSelected((selected) => {
      let copy = [...selected];

      copy.push(recipients[i]._id);

      return copy;
    });
  } else {
    setSelected((selected) => {
      let i = selected.findIndex((addressee) => {
        if (addressee === id) {
          return true;
        }
        return false;
      });

      let copy = [...selected];

      if (i !== -1) {
        copy.splice(i, 1);
      }

      return copy;
    });
  }
};

export const handleSelectAllClick = (event, setRecipients, setSelected) => {
  setRecipients((recipients) => {
    let copy = [...recipients];
    let aux = [];

    for (let i = 0; i < copy.length; i++) {
      copy[i].checked = event.target.checked ? true : false;
      if (event.target.checked) {
        aux.push(copy[i]._id);
      }
    }

    setSelected(event.target.checked ? aux : []);

    return copy;
  });
};
