import {
  ADD_ITEM,
  DELETE_ITEM,
  EDIT_ITEM,
  PAY_ITEM,
} from "../Action/actionTypes";

import axios from "axios";

import { setSnackData } from "./snackDataActions";

axios.defaults.withCredentials = true;

export const addItem =
  (recent, token, id, data, setOpen, setIsLoading, setItems) => (dispatch) => {
    axios
      .post(
        `${process.env.REACT_APP_BACKEND_URL}/rentals/contracts/${id}/items`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        return axios.get(
          `${process.env.REACT_APP_BACKEND_URL}/rentals/contracts/${id}/items${
            recent ? "/recent" : ""
          }`,
          {
            headers: {
              Authorization: "Bearer " + token,
            },
          }
        );
      })
      .then((res) => {
        let aux = res.data.reduce((obj, entry) => {
          return [
            ...obj,
            {
              ...entry,
              ...(entry.status !== "paid" && { checked: false }),
            },
          ];
        }, []);

        dispatch({
          type: ADD_ITEM,
          payload: aux,
        });

        if (setItems) setItems(aux);

        dispatch(
          setSnackData({
            open: true,
            message: "Item creado",
            severity: "success",
          })
        );

        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };

export const editItem =
  (token, idContract, idItem, data, setOpen, setIsLoading, setItems) =>
  (dispatch, getState) => {
    let aux = getState().contracts.items;
    let items = Array.from(aux);

    axios
      .put(
        `${process.env.REACT_APP_BACKEND_URL}/rentals/contracts/${idContract}/items/${idItem}`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        let i = items.findIndex((entry) => {
          if (entry._id === idItem) {
            return true;
          }
          return false;
        });

        if (i !== -1) {
          items[i] = Object.assign(items[i], data);
        }

        let aux = items.reduce((obj, entry) => {
          return [
            ...obj,
            {
              ...entry,
              ...(entry.status !== "paid" && { checked: false }),
            },
          ];
        }, []);

        dispatch({
          type: EDIT_ITEM,
          payload: aux,
        });

        if (setItems) setItems(aux);

        dispatch(
          setSnackData({
            open: true,
            message: "Item editado",
            severity: "success",
          })
        );

        setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };

export const deleteItem =
  (token, idContract, idItem, setOpen, setIsLoading, setItems) =>
  (dispatch, getState) => {
    let aux = getState().contracts.items;
    let items = Array.from(aux);

    axios
      .delete(
        `${process.env.REACT_APP_BACKEND_URL}/rentals/contracts/${idContract}/items/${idItem}`,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        let i = items.findIndex((entry) => {
          if (entry._id === idItem) {
            return true;
          }
          return false;
        });

        i !== -1 && items.splice(i, 1);

        let aux = items.reduce((obj, entry) => {
          return [
            ...obj,
            {
              ...entry,
              ...(entry.status !== "paid" && { checked: false }),
            },
          ];
        }, []);

        dispatch({
          type: DELETE_ITEM,
          payload: aux,
        });

        if (setItems) setItems(aux);

        dispatch(
          setSnackData({
            open: true,
            message: "Item eliminado",
            severity: "success",
          })
        );

        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };

export const payItem =
  (recent, token, id, data, setOpen, setIsLoading, setItems, resetSelected) =>
  (dispatch) => {
    data.contract = id;
    axios
      .post(
        `${process.env.REACT_APP_BACKEND_URL}/rentals/payment-orders`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        return axios.get(
          `${process.env.REACT_APP_BACKEND_URL}/rentals/contracts/${id}/items${
            recent ? "/recent" : ""
          }`,
          {
            headers: {
              Authorization: "Bearer " + token,
            },
          }
        );
      })
      .then((res) => {
        let aux = res.data.reduce((obj, entry) => {
          return [
            ...obj,
            {
              ...entry,
              ...(entry.status !== "paid" && { checked: false }),
            },
          ];
        }, []);

        dispatch({
          type: PAY_ITEM,
          payload: aux,
        });

        if (setItems) setItems(aux);
        if (resetSelected) resetSelected();

        dispatch(
          setSnackData({
            open: true,
            message: data.items.length > 1 ? "Items cobrados" : "Item cobrado",
            severity: "success",
          })
        );

        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };
