import React, { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { makeStyles } from "@material-ui/core";
import Form from "./Form";
import { editExpenditure } from "../../Redux/Action/expendituresActions";
import { getSubcategories } from "../../Redux/Action/subcategoriesActions";
import { getProviders } from "../../Redux/Action/providersActions";
import { getCategories } from "../../Redux/Action/categoriesActions";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    padding: theme.spacing(1),
  },
}));

const EditExpenditure = ({
  establishment,
  id,
  token,
  setOpen,
  expenditure,
  categories,
  expendituresTypes,
  boxes,
  dataAmounts,
}) => {
  const classes = useStyles();
  const dispatch = useDispatch();
  const subcategories = useSelector(
    (state) => state.subcategories.subcategories
  );
  const providers = useSelector((state) => state.providers.providers);

  const subcategoriesFilter = (id) => {
    let arr = [];

    if (categories.length > 0 && id !== "") {
      arr = subcategories.filter((entry) => entry.category._id === id);
    }

    return arr;
  };

  const [isLoading, setIsLoading] = useState(true);
  const [hasChanged, setHasChanged] = useState(false);
  const [expenditures, setExpenditures] = useState(() => {
    let aux = null;
    let obj = expendituresTypes.reduce((obj, expenditure) => {
      return [
        ...obj,
        {
          expenditureType: expenditure._id,
          percentage: "0",
          name: expenditure.name,
        },
      ];
    }, []);

    for (let i = 0; i < obj.length; i++) {
      aux = expenditure.expendituresTypesPercentages.filter(
        (expenditure) => expenditure.expenditureType === obj[i].expenditureType
      );
      if (aux[0]) {
        obj[i].percentage = aux[0].percentage;
      }
      aux = null;
    }

    return obj;
  });

  const onClikHandler = (data) => {
    setIsLoading(true);

    dispatch(
      editExpenditure(
        id,
        token,
        expenditure._id,
        data,
        expenditure,
        setOpen,
        setIsLoading,
        dataAmounts
      )
    );
  };

  useEffect(() => {
    dispatch(getCategories(id, token));
    dispatch(getProviders(token));
    dispatch(getSubcategories(id, token, setIsLoading));
  }, [expenditure, id, token, dispatch]);

  return (
    <div className={classes.container}>
      <Form
        categories={categories}
        subcategories={subcategoriesFilter}
        providers={providers}
        title="Editar gasto"
        setOpen={setOpen}
        isLoading={isLoading}
        onClikHandler={onClikHandler}
        hasChanged={hasChanged}
        setHasChanged={setHasChanged}
        data={expenditure}
        expenditures={expenditures}
        setExpenditures={setExpenditures}
        boxes={boxes}
        establishment={establishment}
      />
    </div>
  );
};

export default EditExpenditure;
