import {
  GET_ESTATES,
  ADD_ESTATE,
  EDIT_ESTATE,
  DELETE_ESTATE,
} from "../Action/actionTypes";

const initialState = { estates: [] };

export const estatesReducer = (state = initialState, action) => {
  switch (action.type) {
    case GET_ESTATES:
      return {
        ...state,
        estates: action.payload,
      };
    case ADD_ESTATE:
      return {
        ...state,
        estates: action.payload,
      };
    case EDIT_ESTATE:
      return {
        ...state,
        estates: action.payload,
      };
    case DELETE_ESTATE:
      return {
        ...state,
        estates: action.payload,
      };
    default:
      return state;
  }
};

export default estatesReducer;
