import axios from "axios";
import { GET_DATA_SERVER, EDIT_DATA_SERVER } from "./actionTypes";
import { setSnackData } from "./snackDataActions";

export const getEmailServerData = (token, setIsLoading) => (dispatch) => {
  axios
    .get(`${process.env.REACT_APP_BACKEND_URL}/establishment/email-server`, {
      headers: {
        Authorization: "Bearer " + token,
      },
    })
    .then((res) => {
      let aux = res.data === "" ? {} : res.data;
      dispatch({
        type: GET_DATA_SERVER,
        payload: aux,
      });
      if (setIsLoading) setIsLoading(false);
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }
      if (setIsLoading) setIsLoading(false);
    });
};

export const editEmailServerData =
  (token, data, setEdit, setIsLoading) => (dispatch, getState) => {
    let aux = getState().emailServer.dataServer;
    let dataServer = { ...aux };

    axios
      .put(
        `${process.env.REACT_APP_BACKEND_URL}/establishment/email-server`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        dataServer = Object.assign(dataServer, data);

        dispatch({
          type: EDIT_DATA_SERVER,
          payload: dataServer,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Servidor de correos actualizado",
            severity: "success",
          })
        );

        if (setEdit) setEdit(false);
        if (setIsLoading) setIsLoading(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };
