import React, { Fragment } from "react";
import {
  Button,
  FormControl,
  FormControlLabel,
  FormLabel,
  Grid,
  makeStyles,
  MenuItem,
  RadioGroup,
  TextField,
  Radio,
} from "@material-ui/core";

import { ExpandMore } from "@material-ui/icons";

import { months, days } from "../../../configs/contracts/DAYS_MONTHS";
import NumberFormat from "react-number-format";

const useStyles = makeStyles((theme) => ({
  addButton: {
    backgroundColor: "#49AC08",
    color: "#FAFAFA",
    textTransform: "capitalize",
    fontSize: 12,
    "&:hover": {
      backgroundColor: "#49ac089e",
    },
  },
  radioGroup: {
    display: "flex",
    justifyContent: "flex-end",
    "& .Mui-checked": {
      color: "#49AC08",
    },
  },
}));

function NumberFormatCustom(props) {
  const { min, id, inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
            id: id,
            validity: {
              valid: parseFloat(values.value, 10) >= parseFloat(min, 10),
            },
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={3}
      isNumericString
      prefix="$"
    />
  );
}

function NumberFormatPercentage(props) {
  const { min, max, id, inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
            id: id,
            validity: {
              valid:
                parseFloat(values.value, 10) <= parseFloat(max, 10) &&
                parseFloat(values.value, 10) >= parseFloat(min, 10),
            },
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={3}
      isNumericString
      suffix="%"
    />
  );
}

const FreeItemForm = ({
  feeAmount,
  edit,
  onChangeData,
  data,
  setData,
  isMobile,
  onClick,
  disabledButton,
  xs,
  addOrEditItem,
}) => {
  const classes = useStyles();

  const disabled =
    data.name.value !== "" && data.name.isValid === true ? false : true;

  return (
    <Fragment>
      <Grid item xs={isMobile ? 6 : xs || 3}>
        <TextField
          value={data.name.value}
          required
          autoComplete="off"
          fullWidth
          id="name"
          name="name"
          label="Nombre"
          inputProps={{
            minLength: 2,
            maxLength: 100,
            pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
          }}
          onChange={(e) => {
            setData(e);
            onChangeData && onChangeData();
          }}
          error={!data.name.isValid}
          InputLabelProps={{ required: false }}
        />
      </Grid>
      <Grid item xs={isMobile ? 6 : xs || 3}>
        <TextField
          InputProps={{
            inputComponent: NumberFormatCustom,
          }}
          required
          autoComplete="off"
          label="Importe"
          id="amount"
          name="amount"
          value={data.amount.value}
          onChange={(e) => {
            setData(e);
            onChangeData && onChangeData();
          }}
          fullWidth
          inputProps={{
            min: "0",
            pattern: "[0-9.]+",
            step: ".01",
          }}
          error={!data.amount.isValid}
          InputLabelProps={{ required: false }}
        />
      </Grid>
      {!edit && (
        <Grid item xs={isMobile ? 6 : xs || 3}>
          <TextField
            label="Aumento cada"
            id="increaseMonths"
            value={data.increaseMonths.value}
            onChange={(e) => {
              e.target.id = "increaseMonths";
              setData(e);
              onChangeData && onChangeData();
            }}
            select
            SelectProps={{
              IconComponent: ExpandMore,
            }}
            fullWidth
          >
            <MenuItem value=""></MenuItem>
            {months.map((entry, index) => (
              <MenuItem key={`select-${entry}-${index}`} value={entry}>
                {`${entry} meses`}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
      )}
      {!edit && (
        <Grid item xs={isMobile ? 6 : xs || 3}>
          <TextField
            InputProps={{
              inputComponent: NumberFormatPercentage,
            }}
            value={data.increasePercentage.value}
            autoComplete="off"
            fullWidth
            id="increasePercentage"
            name="increasePercentage"
            label="% Aumento"
            placeholder="0"
            inputProps={{
              min: "0",
              max: "100",
              pattern: "[0-9]+",
              step: ".01",
            }}
            error={!data.increasePercentage.isValid}
            onChange={(e) => {
              setData(e);
              onChangeData && onChangeData();
            }}
          />
        </Grid>
      )}
      <Grid item xs={isMobile ? 6 : xs || 3}>
        <TextField
          InputProps={{
            inputComponent: feeAmount
              ? NumberFormatCustom
              : NumberFormatPercentage,
          }}
          required
          autoComplete="off"
          label="Honorarios"
          id={feeAmount ? "fee" : "monthlyFeePercentage"}
          name={feeAmount ? "fee" : "monthlyFeePercentage"}
          value={feeAmount ? data.fee.value : data.monthlyFeePercentage.value}
          onChange={(e) => {
            setData(e);
            onChangeData && onChangeData();
          }}
          fullWidth
          inputProps={
            feeAmount
              ? { min: "0", pattern: "[0-9.]+", step: ".01" }
              : {
                  min: "0",
                  max: "100",
                  pattern: "[0-9]+",
                  step: ".01",
                }
          }
          error={!data[feeAmount ? "fee" : "monthlyFeePercentage"].isValid}
          InputLabelProps={{ required: false }}
        />
      </Grid>
      {!addOrEditItem && (
        <Grid item xs={isMobile ? 6 : xs || 3}>
          <TextField
            label="Vence todos los"
            id="expirationDay"
            value={data.expirationDay.value}
            onChange={(e) => {
              e.target.id = "expirationDay";
              setData(e);
              onChangeData && onChangeData();
            }}
            select
            SelectProps={{
              IconComponent: ExpandMore,
            }}
            fullWidth
          >
            <MenuItem value=""></MenuItem>
            {days.map((entry, index) => (
              <MenuItem key={`select-${entry}-${index}`} value={entry}>
                {entry}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
      )}
      <Grid item xs={isMobile ? 6 : xs || 3}>
        <TextField
          InputProps={{
            inputComponent: NumberFormatPercentage,
          }}
          value={data.dailyInterestPercentage.value}
          autoComplete="off"
          fullWidth
          id="dailyInterestPercentage"
          name="dailyInterestPercentage"
          label="Interés diario"
          helperText="*por vencimiento"
          placeholder="0"
          inputProps={{
            min: "0",
            max: "100",
            pattern: "[0-9]+",
            step: ".01",
          }}
          error={!data.dailyInterestPercentage.isValid}
          onChange={(e) => {
            setData(e);
            onChangeData && onChangeData();
          }}
        />
      </Grid>
      <Grid item xs={isMobile ? 12 : disabledButton ? 12 : 6}>
        <FormControl component="fieldset" fullWidth>
          <Grid container alignItems="center">
            <Grid item xs={7}>
              <FormLabel style={{ color: "#616161" }}>
                ¿Liquida al propietario?
              </FormLabel>
            </Grid>
            <Grid item xs={5}>
              <RadioGroup
                className={classes.radioGroup}
                aria-label="payable"
                name="payable"
                value={data.payable.value}
                onChange={(e) => {
                  e.target.id = "payable";
                  setData(e);
                  onChangeData && onChangeData();
                }}
                row
              >
                <FormControlLabel
                  value="true"
                  control={<Radio color="primary" />}
                  label="Sí"
                />
                <FormControlLabel
                  style={{ marginRight: 0 }}
                  value="false"
                  control={<Radio color="primary" />}
                  label="No"
                />
              </RadioGroup>
            </Grid>
          </Grid>
        </FormControl>
      </Grid>
      {!disabledButton && (
        <Grid
          item
          xs={isMobile ? 12 : xs || 6}
          style={{ display: "flex", alignItems: "center" }}
        >
          <Button
            disabled={disabled}
            fullWidth
            disableElevation
            variant="contained"
            className={classes.addButton}
            onClick={onClick}
          >
            Agregar item libre
          </Button>
        </Grid>
      )}
    </Fragment>
  );
};

export default FreeItemForm;
