import React, { Fragment, useRef, useEffect, useState } from "react";
import { makeStyles } from "@material-ui/core/styles";
import Button from "@material-ui/core/Button";
import DeleteIcon from "@material-ui/icons/Delete";
import { FormControlLabel } from "@material-ui/core";

import ImageNoAvailable from "../../assets/ImageNoAvailable.png";

const useStyles = makeStyles((theme) => ({
  input: {
    display: "none",
  },
  delete: {
    position: "relative",
    top: theme.spacing(1),
    right: theme.spacing(1),
    cursor: "pointer",
    color: "#F24726",
  },
  button: {
    backgroundRepeat: "no-repeat",
    backgroundSize: "160px 160px",
    border: "2px solid",
    borderColor: theme.palette.grey[700],
    borderRadius: theme.spacing(1.5),
    width: theme.spacing(20),
    height: theme.spacing(20),
    display: "flex",
    justifyContent: "center",
    backgroundPosition: "center",
    "@media (max-width:600px)": {
      width: theme.spacing(14.875),
      height: theme.spacing(14.875),
      backgroundSize: "119px 119px",
    },
  },
  buttonText: {
    width: "min-content",
    textAlign: "center",
    fontSize: 16,
  },
}));

const SelectImage = ({
  heigth,
  width,
  image,
  setImage,
  deleteImage,
  textImage,
  establishment,
  onlyPreview,
}) => {
  const classes = useStyles();
  const [background, setBackground] = useState();
  const ref = useRef();
  const onClickHandler = () => {
    ref.current.click();
  };

  useEffect(() => {
    setBackground(
      image
        ? typeof image === "string"
          ? `${process.env.REACT_APP_BACKEND_URL}/files/${establishment}/${image}`
          : URL.createObjectURL(image)
        : ImageNoAvailable
    );
  }, [image, establishment, setBackground]);

  return (
    <Fragment>
      <FormControlLabel
        style={{ display: "none" }}
        control={
          <input
            accept="image/*"
            className={classes.input}
            id="contained-button-file"
            type="file"
            onChange={setImage}
            ref={ref}
          />
        }
      />
      <div
        className={classes.button}
        style={{
          backgroundImage: background && `url(${background})`,
          justifyContent: "flex-end",
          height: heigth,
          width: width,
          backgroundSize: "contain",
        }}
      >
        {!onlyPreview && (
          <Button
            disableRipple={true}
            component="span"
            onClick={onClickHandler}
            disabled={image && true}
            fullWidth
          >
            {!image && <b className={classes.buttonText}>{textImage}</b>}
          </Button>
        )}
        {image && !onlyPreview && (
          <i
            className={classes.delete}
            onClick={() => {
              deleteImage();
              ref.current.value = null;
            }}
          >
            <DeleteIcon size="lg" />
          </i>
        )}
      </div>
    </Fragment>
  );
};

export default SelectImage;
