import React, { useState } from "react";
import { useEffect } from "react";
import { useDispatch } from "react-redux";
import Form from "./Form";

import { getServices } from "../../Redux/Action/servicesActions";
import { getEstates } from "../../Redux/Action/estatesActions";
import { useForm } from "../../hooks/use-form";
import { editContract } from "../../Redux/Action/contractsActions";

const EditContract = ({ user, current, setOpen, contacts, estates }) => {
  const dispatch = useDispatch();

  const [isLoading, setIsLoading] = useState(true);
  const [hasChanged, setHasChanged] = useState(false);

  const [property, setProperty] = useState(current.property._id);

  const [tenants, setTenants] = useState(current.tenants || []);
  const [guarantors, setGuarantors] = useState(current.guarantors || []);

  const [rentalData, setRentalData] = useForm({
    months: current.months,
    amount: current.amount,
    increasePercentage: current.increasePercentage,
    increaseMonths: current.increaseMonths,
    monthlyFeePercentage: current.monthlyFeePercentage,
    expirationDay: current.expirationDay,
    dailyInterestPercentage: current.dailyInterestPercentage,
  });

  const [contractData, setContractData] = useForm({
    deposit: current.deposit,
    currency: current.currency,
    depositKeeper: current.depositKeeper,
    feePercentage: current.feePercentage,
    startingDate: current.startingDate,
  });

  const [pdf, setPdf] = useState(
    current.pdf ? { pdf: current.pdf, name: "PDF Contrato" } : null
  );

  const [items, setItems] = useState(current.items || []);
  const [services, setServices] = useState(current.services || []);

  const onClikHandler = () => {
    let servicesAux = [];
    let tenantsAux = [];
    let guarantorsAux = [];

    let auxData = {
      property,
      items,
      services,
      tenants,
      guarantors,
    };

    const formData = new FormData();

    formData.append("property", property);

    if (items.length > 0) {
      formData.append("items", JSON.stringify(items));
    }

    if (services.length > 0) {
      for (let i = 0; i < services.length; i++) {
        servicesAux.push({ ...services[i], service: services[i].service._id });
      }

      formData.append("services", JSON.stringify(servicesAux));
    }

    for (let i = 0; i < tenants.length; i++) {
      tenantsAux.push(tenants[i]._id);
    }

    formData.append("tenants", JSON.stringify(tenantsAux));

    for (let i = 0; i < guarantors.length; i++) {
      guarantorsAux.push(guarantors[i]._id);
    }

    formData.append("guarantors", JSON.stringify(guarantorsAux));

    for (let key in rentalData) {
      formData.append(key, rentalData[key].value);
      auxData[key] = rentalData[key].value;
    }

    for (let key in contractData) {
      formData.append(key, contractData[key].value);
      auxData[key] = contractData[key].value;
    }

    if (pdf !== null) {
      formData.append("pdf", pdf);
    }

    setIsLoading(true);
    dispatch(
      editContract(
        user.token,
        formData,
        auxData,
        current,
        setOpen,
        setIsLoading
      )
    );
  };

  const reloadEstates = () => {
    setIsLoading(true);
    dispatch(getEstates(user.token, setIsLoading));
  };

  useEffect(() => {
    dispatch(getServices(user.token, setIsLoading));
  }, [user.token, dispatch]);

  return (
    <Form
      title="Nuevo contrato"
      user={user}
      contacts={contacts}
      reloadEstates={reloadEstates}
      property={property}
      setProperty={setProperty}
      tenants={tenants}
      setTenants={setTenants}
      guarantors={guarantors}
      setGuarantors={setGuarantors}
      rentalData={rentalData}
      setRentalData={setRentalData}
      contractData={contractData}
      setContractData={setContractData}
      pdf={pdf}
      setPdf={setPdf}
      items={items}
      setItems={setItems}
      services={services}
      setServices={setServices}
      estates={estates}
      setOpen={setOpen}
      isLoading={isLoading}
      onClikHandler={onClikHandler}
      hasChanged={hasChanged}
      setHasChanged={setHasChanged}
      establishment={current.establishment}
    />
  );
};

export default EditContract;
