import React, { useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { makeStyles } from "@material-ui/core";
import Form from "./Form";
import { editConsortium } from "../../Redux/Action/consortiumsActions";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    padding: theme.spacing(1),
  },
}));

const EditConsortium = ({ consortium, setOpen }) => {
  const classes = useStyles();
  const dispatch = useDispatch();
  const user = useSelector((state) => state.user.userData);

  const [isLoading, setIsLoading] = useState(false);
  const [hasChanged, setHasChanged] = useState(false);

  const sendData = (data) => {
    setIsLoading(true);
    dispatch(
      editConsortium(user.token, data, consortium._id, setOpen, setIsLoading)
    );
  };

  return (
    <div className={classes.container}>
      <Form
        title="Editar consorcio"
        setOpen={setOpen}
        isLoading={isLoading}
        onClikHandler={sendData}
        data={consortium}
        hasChanged={hasChanged}
        setHasChanged={setHasChanged}
      />
    </div>
  );
};

export default EditConsortium;
