import React from "react";
import {
  Button,
  Hidden,
  IconButton,
  makeStyles,
  Tooltip,
} from "@material-ui/core";

import ArrowBackIcon from "@material-ui/icons/ArrowBack";

const useStyles = makeStyles((theme) => ({
  container: {
    width: "100%",
    display: "flex",
    justifyContent: "flex-start",
    marginBottom: theme.spacing(1),
  },
  backButton: {
    color: theme.palette.grey[700],
    borderColor: theme.palette.grey[700],
  },
  arrowBack: { marginLeft: -theme.spacing(2), color: theme.palette.grey[700] },
}));

const BackButtonComponent = ({ title, onClick, mrgBottom }) => {
  const classes = useStyles();

  return (
    <div
      className={classes.container}
      style={mrgBottom ? { marginBottom: mrgBottom } : null}
    >
      <Hidden xsDown>
        <Button
          variant="outlined"
          disableElevation
          startIcon={<ArrowBackIcon />}
          onClick={onClick}
          className={classes.backButton}
        >
          {title}
        </Button>
      </Hidden>
      <Hidden smUp>
        <Tooltip title={title}>
          <IconButton
            variant="outlined"
            aria-label="goBack"
            onClick={onClick}
            className={classes.arrowBack}
          >
            <ArrowBackIcon />
          </IconButton>
        </Tooltip>
      </Hidden>
    </div>
  );
};

export default BackButtonComponent;
