import {
  GET_PAYMENT_ORDERS,
  GET_SETTLEMENT_RECEIPTS,
  LIQUIDATE,
  GET_RECURRING_DISCOUNTS,
  DELETE_RECURRING_DISCOUNT,
  DELETE_SETTLEMENT_RECEIPT,
} from "../Action/actionTypes";

import axios from "axios";

import { setSnackData } from "./snackDataActions";

axios.defaults.withCredentials = true;

export const getPaymentOrders =
  (token, ownerId, setIsLoading, setRows) => (dispatch) => {
    axios
      .get(
        `${process.env.REACT_APP_BACKEND_URL}/rentals/payment-orders/byContact/${ownerId}`,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        let aux = res.data.reduce((obj, entry) => {
          return [
            ...obj,
            {
              ...entry,
              checked: false,
            },
          ];
        }, []);

        aux.forEach((element) => {
          let percentage = 1;

          let index = element.contract.property.owners.findIndex(
            (entry) => entry.owner === ownerId
          );

          for (let item of element.payedItems) {
            if (index !== -1) {
              percentage = element.contract.property.owners[index].percentage;
            }

            if (item.item) {
              let aux = item.item.amount / item.amount.amount;

              item.amount.amount = (percentage / 100) * item.amount.amount;
              item.amount.tax = (percentage / 100) * item.amount.tax;
              item.amount.fee = (percentage / 100) * (aux * item.item.fee);
            } else {
              item.amount.fee = 0;
            }
          }

          for (let item of element.discounts) {
            if (index !== -1) {
              item.amount = (percentage / 100) * item.amount;
            }
          }
        });

        dispatch({
          type: GET_PAYMENT_ORDERS,
          payload: aux,
        });

        if (setRows) setRows(aux);
        if (setIsLoading) setIsLoading(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };

