export const liquidate =
  (token, data, setOpen, setIsLoading, setItems, resetSelected, ownerId) =>
  (dispatch) => {
    axios
      .post(`${process.env.REACT_APP_BACKEND_URL}/rentals/liquidations`, data, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((_) => {
        return axios.get(
          `${process.env.REACT_APP_BACKEND_URL}/rentals/payment-orders/byContact/${ownerId}`,
          {
            headers: {
              Authorization: "Bearer " + token,
            },
          }
        );
      })
      .then((res) => {
        let aux = res.data.reduce((obj, entry) => {
          return [
            ...obj,
            {
              ...entry,
              checked: false,
            },
          ];
        }, []);

        aux.forEach((element) => {
          for (let item of element.payedItems) {
            if (item.item) {
              let aux = item.item.amount / item.amount.amount;
              item.amount.fee = aux * item.item.fee;
            } else {
              item.amount.fee = 0;
            }
          }
        });

        dispatch({
          type: LIQUIDATE,
          payload: aux,
        });

        if (setItems) setItems(aux);
        if (resetSelected) resetSelected();
        if (setOpen) setOpen(false);

        dispatch(
          setSnackData({
            open: true,
            message: "Items liquidados",
            severity: "success",
          })
        );
      })

      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };

