export const deleteRecurringDiscount =
  (token, id, setOpen, setIsLoading, setItems) => (dispatch, getState) => {
    let aux = getState().liquidations.recurringDiscounts;
    let recurringDiscounts = Array.from(aux);

    axios
      .delete(
        `${process.env.REACT_APP_BACKEND_URL}/rentals/liquidations/discounts/${id}`,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )

      .then((_) => {
        let i = recurringDiscounts.findIndex((entry) => {
          if (entry._id === id) {
            return true;
          }
          return false;
        });

        if (i !== -1) {
          recurringDiscounts.splice(i, 1);
        }

        dispatch({
          type: DELETE_RECURRING_DISCOUNT,
          payload: recurringDiscounts,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Descuento recurrente eliminado",
            severity: "success",
          })
        );

        if (setItems) setItems(recurringDiscounts);
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };

