import React from "react";
import Button from "@material-ui/core/Button";
import TextField from "@material-ui/core/TextField";
import Link from "@material-ui/core/Link";
import Grid from "@material-ui/core/Grid";
import { makeStyles } from "@material-ui/core/styles";
import { useForm } from "../../hooks/use-form";
import { Link as RRLink } from "react-router-dom";
import Spinner from "../UI/Spinner";
import { logInUser } from "../../Redux/Action/userActions";
import { useDispatch } from "react-redux";

const useStyles = makeStyles((theme) => ({
  form: {
    width: "100%", // Fix IE 11 issue.
    marginTop: theme.spacing(1),
  },
  submit: {
    margin: theme.spacing(3, 0, 2),
  },
  resetPassword: {
    textAlign: "right",
  },
}));

export default function LoginForm() {
  const classes = useStyles();
  const dispatch = useDispatch();

  const [form, onChangeHandler] = useForm({
    email: "",
    password: "",
  });

  const [isLoading, setIsLoading] = React.useState(false);

  const submitHandler = async (e) => {
    e.preventDefault();
    let data = {
      email: form.email.value,
      password: form.password.value,
    };
    setIsLoading(true);
    dispatch(logInUser(data, setIsLoading));
  };

  return !isLoading ? (
    <form className={classes.form} onSubmit={submitHandler}>
      <TextField
        variant="outlined"
        margin="normal"
        required
        fullWidth
        id="email"
        label="Email"
        name="email"
        autoComplete="email"
        type="email"
        autoFocus
        value={form.email.value}
        onChange={onChangeHandler}
        inputProps={{
          maxLength: 256,
        }}
        InputLabelProps={{ required: false }}
      />
      <TextField
        variant="outlined"
        margin="normal"
        required
        fullWidth
        name="password"
        label="Password"
        type="password"
        id="password"
        autoComplete="current-password"
        value={form.password.value}
        onChange={onChangeHandler}
        inputProps={{
          pattern: "[a-zA-Z0-9@#!$&?.*]*$",
          minLength: 8,
        }}
        InputLabelProps={{ required: false }}
      />
      <Button
        type="submit"
        fullWidth
        variant="contained"
        color="primary"
        className={classes.submit}
      >
        Ingresar
      </Button>
      <Grid container justifycontent="flex-end">
        <Grid item xs={6}>
          <Link variant="body2" component={RRLink} to="/registro">
            No tenés cuenta? Registrate
          </Link>
        </Grid>
        <Grid item xs={6} className={classes.resetPassword}>
          <Link variant="body2" component={RRLink} to="/restablecer-contraseña">
            Olvidé mi contraseña
          </Link>
        </Grid>
      </Grid>
    </form>
  ) : (
    <Spinner />
  );
}
