import React, { useState, useEffect, Fragment } from "react";
import {
  Button,
  Container,
  Grid,
  Hidden,
  IconButton,
  makeStyles,
  Tooltip,
  Typography,
  useMediaQuery,
  useTheme,
  TableCell,
} from "@material-ui/core";

import Table from "../components/Shared/Table";
import Modal from "../components/Shared/Modal";
import AddContact from "../components/Schedule/AddContact";
import EditContact from "../components/Schedule/EditContact";
import DeleteContact from "../components/Schedule/DeleteContact";
import DetailsContact from "../components/Schedule/Details";
import { useDispatch, useSelector } from "react-redux";
import { getContacts } from "../Redux/Action/scheduleActions";
import Spinner from "../components/UI/Spinner";
import EnableWebAccess from "../components/Schedule/EnableWebAccess";

import AddIcon from "@material-ui/icons/Add";
import ReloadIcon from "@material-ui/icons/Cached";
import LanguageIcon from "@material-ui/icons/Language";
import AccountBalanceWalletIcon from "@material-ui/icons/AccountBalanceWallet";
import AssignmentIcon from "@material-ui/icons/Assignment";
import { useHistory } from "react-router-dom";

const useStyles = makeStyles((theme) => ({
  root: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    marginTop: theme.spacing(2),
    marginBottom: theme.spacing(2),
  },
  grid: {
    marginBottom: theme.spacing(2),
    justifyContent: "flex-end",
    alignItems: "center",
    "@media (min-width:650px)": {
      flexDirection: "row",
    },
  },
  gridButton: {
    display: "flex",
    justifyContent: "flex-end",
  },
  reload: {
    padding: theme.spacing(0.75),
    marginRight: theme.spacing(2.5),
  },
  add: {
    padding: theme.spacing(0.75),
  },
  title: {
    marginBottom: 0,
    fontSize: "20px",
    width: "max-content",
    "@media (min-width:650px)": {
      fontSize: "24px",
    },
  },
}));

const columnsMoreActions = ["Liquidar", "Habilitar acceso", "Cuenta corriente"];

const Cells = ({ row }) => {
  return (
    <TableCell component="th" scope="row">
      {`${row.name} ${row.lastname}`}
    </TableCell>
  );
};

const MoreActions = ({ row, onClick, seeCurrentAccount }) => {
  let disabled = row.hasUser;
  return (
    <Fragment>
      <TableCell align="center" style={{ width: "120px" }}>
        <IconButton
          style={{ color: "#4fac99", padding: 0 }}
          onClick={() => onClick(row)}
        >
          <AssignmentIcon />
        </IconButton>
      </TableCell>
      <TableCell align="center" style={{ width: "120px" }}>
        <IconButton
          disabled={disabled}
          style={{ color: disabled ? "#BBB2B2" : "#48B", padding: 0 }}
          onClick={() => onClick(row, "enableWebAccess")}
        >
          <LanguageIcon />
        </IconButton>
      </TableCell>
      <TableCell align="center" style={{ width: "120px" }}>
        <Tooltip title="Cuenta corriente">
          <IconButton
            onClick={() => seeCurrentAccount(row._id)}
            style={{ color: "#4488BB", padding: 0 }}
          >
            <AccountBalanceWalletIcon />
          </IconButton>
        </Tooltip>
      </TableCell>
    </Fragment>
  );
};

const Schedule = ({ user }) => {
  const classes = useStyles();
  const dispatch = useDispatch();
  const history = useHistory();

  const [isLoading, setIsLoading] = useState(true);
  const [open, setOpen] = useState(false);
  const [currentContact, setCurrentContact] = useState(null);
  const [action, setAction] = useState(false);
  const columns = ["Nombre y apellido", "Detalles", "Editar", "Eliminar"];

  const rows = useSelector((state) => state.contacts.contacts);

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const reload = () => {
    setIsLoading(true);
    dispatch(getContacts(user.token, setIsLoading));
  };

  const addContact = () => {
    setAction("add");
    setOpen(true);
  };

  const liquidations = (current) => {
    history.push(`/contactos/liquidaciones/${current._id}`);
  };

  const enableWebAccess = (current) => {
    setAction("enableWebAccess");
    setCurrentContact(current);
    setOpen(true);
  };

  const seeCurrentAccount = (id) => {
    history.push(`/contactos/${id}/cuenta-corriente`);
  };

  const detailsContact = (current) => {
    setCurrentContact(current);
    setOpen(true);
  };

  const editContact = (current) => {
    setCurrentContact(current);
    setOpen(true);
  };

  const deleteContact = (current) => {
    setCurrentContact(current);
    setOpen(true);
  };

  const actions = {
    add: <AddContact setOpen={setOpen} />,
    edit: <EditContact contact={currentContact} setOpen={setOpen} />,
    delete: <DeleteContact contact={currentContact} setOpen={setOpen} />,
    details: <DetailsContact contact={currentContact} setOpen={setOpen} />,
    enableWebAccess: (
      <EnableWebAccess user={user} contact={currentContact} setOpen={setOpen} />
    ),
  };

  useEffect(() => {
    dispatch(getContacts(user.token, setIsLoading));
  }, [user.token, dispatch]);

  return (
    <Container className={classes.root} maxWidth="xl">
      {isLoading ? (
        <Spinner />
      ) : (
        <>
          <Grid container className={classes.grid}>
            <Grid item xs={isMobile ? 6 : 12} sm={6}>
              <Typography gutterBottom className={classes.title}>
                Contactos
              </Typography>
            </Grid>
            <Grid
              item
              xs={isMobile ? 6 : 12}
              sm={6}
              className={classes.gridButton}
            >
              <Hidden xsDown>
                <Tooltip title="Recargar tabla">
                  <IconButton
                    className={classes.reload}
                    variant="contained"
                    aria-label="add"
                    onClick={reload}
                  >
                    <ReloadIcon />
                  </IconButton>
                </Tooltip>
                <Button
                  variant="contained"
                  disableElevation
                  startIcon={<AddIcon />}
                  onClick={addContact}
                >
                  Agregar
                </Button>
              </Hidden>
              <Hidden smUp>
                <Tooltip title="Recargar tabla">
                  <IconButton
                    className={classes.reload}
                    variant="contained"
                    aria-label="add"
                    onClick={reload}
                  >
                    <ReloadIcon />
                  </IconButton>
                </Tooltip>
                <Tooltip title="Agregar">
                  <IconButton
                    className={classes.add}
                    variant="contained"
                    aria-label="add"
                    onClick={addContact}
                  >
                    <AddIcon />
                  </IconButton>
                </Tooltip>
              </Hidden>
            </Grid>
          </Grid>
          <Table
            columns={columns}
            columnsMoreActions={columnsMoreActions}
            rows={rows}
            Cells={Cells}
            MoreActions={(row) => (
              <MoreActions
                row={row.row}
                onClick={(row, action) => {
                  if (action === "enableWebAccess") {
                    enableWebAccess(row);
                  } else {
                    liquidations(row);
                  }
                }}
                seeCurrentAccount={seeCurrentAccount}
              />
            )}
            detailsAction={detailsContact}
            editAction={editContact}
            deleteAction={deleteContact}
            setAction={setAction}
          />
          <Modal
            handleClose={() => setOpen(false)}
            open={open}
            component={actions[action]}
          />
        </>
      )}
    </Container>
  );
};

export default Schedule;
