import React, { useState } from "react";
import { useDispatch } from "react-redux";

import Form from "./Form";

import { addService } from "../../Redux/Action/servicesActions";

const AddService = ({ user, setOpen }) => {
  const dispatch = useDispatch();

  const [isLoading, setIsLoading] = useState(false);

  const onClikHandler = (data) => {
    setIsLoading(true);
    dispatch(addService(user.token, data, setOpen, setIsLoading));
  };

  return (
    <Form
      title="Nuevo impuesto/servicio"
      setOpen={setOpen}
      isLoading={isLoading}
      onClikHandler={onClikHandler}
      hasChanged={true}
    />
  );
};

export default AddService;
