import {
  accountOf,
  banks,
  boxes,
  categories,
  consortiums,
  contacts,
  contracts,
  discounts,
  emailServer,
  establishment,
  expenditureTypes,
  expenditures,
  expenses,
  functionalUnits,
  items,
  liquidations,
  orderForContact,
  orderForContract,
  paymentOrders,
  payments,
  properties,
  providers,
  services,
  subcategories,
  transactions,
} from "./data";

const clone = (value) => JSON.parse(JSON.stringify(value));

const partsOf = (path) => path.split("/").filter(Boolean);

const byConsortium = (rows, id) => rows.filter((row) => row.consortium === id);

const recentLimit = () => {
  const date = new Date("2026-10-05T12:00:00.000Z");
  date.setDate(date.getDate() + 60);
  return date;
};

export const resolveDemoRequest = (path, body) => {
  const parts = partsOf(path);

  if (parts[0] === "consortiums" && parts.length === 1) return consortiums;

  if (parts[0] === "consortiums" && parts.length >= 3) {
    const consortiumId = parts[1];
    const section = parts[2];
    const extra = parts[3];

    if (section === "functional-units" && !extra) {
      return functionalUnits.filter((row) => row.consortium === consortiumId);
    }
    if (section === "functional-units" && parts[4] === "transactions") {
      return accountOf(
        transactions.filter((row) => row.functionalUnit === extra)
      );
    }
    if (section === "expenditures-types") {
      return byConsortium(expenditureTypes, consortiumId);
    }
    if (section === "categories") return byConsortium(categories, consortiumId);
    if (section === "subcategories") {
      return byConsortium(subcategories, consortiumId);
    }
    if (section === "boxes") return byConsortium(boxes, consortiumId);
    if (section === "expenses" && extra === "expenditures-types-amounts") {
      return expenditureTypes
        .filter((row) => row.consortium === consortiumId)
        .map((row) => ({
          expenditureType: row._id,
          amount: expenditures
            .filter(
              (entry) =>
                entry.consortium === consortiumId &&
                !entry.expense &&
                (!entry.isRecurrent ||
                  (body &&
                    Array.isArray(body.recurrentExpenditures) &&
                    body.recurrentExpenditures.includes(entry._id)))
            )
            .reduce((sum, entry) => {
              const share = entry.expendituresTypesPercentages.find(
                (item) => item.expenditureType === row._id
              );
              if (!share) return sum;
              return sum + (entry.amount.amount * share.percentage) / 100;
            }, 0),
        }));
    }
    if (section === "expenses" && !extra) {
      return expenses.filter((row) => row.consortium === consortiumId);
    }
    if (section === "expenditures") {
      return expenditures.filter((row) => {
        if (row.consortium !== consortiumId) return false;
        return extra ? row.expense === extra : !row.expense;
      });
    }
    if (section === "payments" && extra) {
      return payments.filter(
        (row) => row.consortium === consortiumId && row.functionalUnit === extra
      );
    }
  }

  if (parts[0] === "contacts" && parts.length === 1) return contacts;
  if (parts[0] === "contacts" && parts[2] === "transactions") {
    return accountOf(transactions.filter((row) => row.contact === parts[1]));
  }

  if (parts[0] === "providers") return providers;
  if (parts[0] === "establishment" && parts.length === 1) return establishment;
  if (parts[0] === "establishment" && parts[1] === "email-server") {
    return emailServer;
  }

  if (parts[0] === "rentals" && parts[1] === "properties") return properties;
  if (parts[0] === "rentals" && parts[1] === "services") return services;
  if (parts[0] === "rentals" && parts[1] === "banks") return banks;

  if (parts[0] === "rentals" && parts[1] === "contracts" && parts.length === 2) {
    return contracts;
  }
  if (
    parts[0] === "rentals" &&
    parts[1] === "contracts" &&
    parts[3] === "items"
  ) {
    const contractItems = items.filter((row) => row.contract === parts[2]);
    if (parts[4] === "recent") {
      const limit = recentLimit();
      return contractItems.filter(
        (row) => row.status === "pending" && new Date(row.expirationDate) < limit
      );
    }
    return contractItems;
  }

  if (
    parts[0] === "rentals" &&
    parts[1] === "payment-orders" &&
    parts[2] === "byContact"
  ) {
    return paymentOrders
      .filter((order) =>
        order.owners.some((owner) => owner.owner === parts[3] && !owner.liquidation)
      )
      .map(orderForContact);
  }
  if (
    parts[0] === "rentals" &&
    parts[1] === "payment-orders" &&
    parts[2] === "byContract"
  ) {
    return paymentOrders
      .filter((order) => order.contract === parts[3])
      .map(orderForContract);
  }

  if (
    parts[0] === "rentals" &&
    parts[1] === "liquidations" &&
    parts[2] === "discounts"
  ) {
    return discounts.filter((row) => row.owner === parts[3]);
  }
  if (parts[0] === "rentals" && parts[1] === "liquidations" && parts[2]) {
    return liquidations.filter((row) => row.owner === parts[2]);
  }

  console.warn("[demo] Sin datos para", path);
  return [];
};

export const demoResponse = (path, body) => clone(resolveDemoRequest(path, body));
