import React, { Fragment, useState } from "react";
import {
  Button,
  Grid,
  makeStyles,
  Typography,
  useMediaQuery,
  useTheme,
  Tooltip,
  TextField,
} from "@material-ui/core";
import { Alert } from "@material-ui/lab";

import PaymentMethod from "./PaymentMethod";
import Spinner from "../../UI/Spinner";
import { NumberFormatCustom } from "../../../hooks/format-number-hook";
import { paymentMethods } from "../../../configs/contracts/items/PAYMENT_METHODS";

import ItemCard from "../../Shared/ItemCard";
import DatePicker from "../../Shared/DatePicker";
import PaymentInformation from "./PaymentInformation";
import ItemsTable from "./ItemsTable";
import DiscountsForm from "./DiscountsForm";

import {
  handleChangeCashToBox,
  addDiscount,
  addPayment,
  deleteDiscount,
  deletePayment,
  handleSelectAllClick,
  onChangeChecked,
  setChecked,
} from "./hooks";

import SendEmail from "./SendEmail";
import RadioComponent from "./RadioComponent";

import ReceiptIcon from "@material-ui/icons/Receipt";
import MoneyOffIcon from "@material-ui/icons/MoneyOff";
import InfoIcon from "@material-ui/icons/Info";

const useStyles = makeStyles((theme) => ({
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "left",
  },
  cardContainer: {
    padding: theme.spacing(0.5, 0.5, 0, 0),
    overflowX: "hidden",
    overflowY: "auto",
    maxHeight: theme.spacing(13.75),
  },
  buttons: {
    justifyContent: "center",
    marginTop: theme.spacing(3.5),
    "& .MuiTooltip-tooltip": {
      backgroundColor: "red",
    },
  },
}));

const Form = ({
  individual,
  title,
  setOpen,
  isLoading,
  onClickHandler,
  amounts,
  setAmounts,
  items,
  setItems,
  values,
  setValues,
  handleDateChange,
  dataPayments,
  setDataPayments,
  setFormPayments,
  dataDiscounts,
  setDataDiscounts,
  setFormDiscounts,
  payments,
  setPayments,
  discounts,
  setDiscounts,
  recipients,
  setRecipients,
  selected,
  setSelected,
}) => {
  const classes = useStyles();

  const [viewInfo, setViewInfo] = useState(true);

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("800"), {
    defaultMatches: true,
  });

  const moveElement = (fromIndex, toIndex) => {
    setItems((items) => {
      let copy = [...items];
      var element = copy[fromIndex];
      copy.splice(fromIndex, 1);
      copy.splice(toIndex, 0, element);

      return copy;
    });
  };

  const isIndividualService = () => {
    if (individual) {
      let aux = items.filter((entry) => entry.itemType === 2);
      if (aux.length > 0) return true;
    }

    return false;
  };

  const thereIsAtLeastOneService = () => {
    let aux = items.filter((entry) => entry.itemType === 2);

    if (aux.length > 0) return true;

    return false;
  };

  let dataSelecting = {
    indeterminate: selected.length > 0 && selected.length < recipients.length,
    checked: recipients.length > 0 && selected.length === recipients.length,
    onChange: (e) => handleSelectAllClick(e, setRecipients, setSelected),
  };

  const helperText = () => {
    if (values.sendEmail === "true" && selected.length <= 0) {
      return "Al menos debes seleccionar un destinatario";
    }

    return "";
  };

  let disabled =
    (values.checked === "true"
      ? amounts.payments + amounts.discounts >= amounts.taxes
      : true) && (values.sendEmail === "true" ? selected.length > 0 : true)
      ? false
      : true;

  return isLoading ? (
    <Spinner height={843} />
  ) : (
    <Fragment>
      <Typography variant="h6">{title}</Typography>
      <Grid container className={classes.grid} spacing={2}>
        {(isIndividualService() || thereIsAtLeastOneService()) && viewInfo && (
          <Grid item xs={12}>
            <Alert
              severity="error"
              icon={<InfoIcon fontSize="inherit" />}
              onClose={() => {
                setViewInfo(false);
              }}
            >
              Nota: Si el inquilino paga el total de la factura, no debe
              ingresar dinero a caja.
            </Alert>
          </Grid>
        )}
        <Grid item xs={12}>
          <ItemsTable
            items={items}
            isIndividualService={isIndividualService()}
            thereIsAtLeastOneService={thereIsAtLeastOneService()}
            checked={values.checked}
            moveElement={moveElement}
            handleChange={(e, id) =>
              handleChangeCashToBox(
                e,
                id,
                items,
                setItems,
                amounts,
                setAmounts,
                setDataPayments
              )
            }
          />
        </Grid>

        <Grid item xs={12}>
          <PaymentInformation checked={values.checked} amounts={amounts} />
        </Grid>

        <Grid item xs={12} sm={6}>
          <DatePicker
            label="Fecha de cobro"
            selectedDate={values.date}
            handleDateChange={(e) => handleDateChange(e)}
          />
        </Grid>

        {!isIndividualService() && (
          <Grid
            item
            xs={12}
            sm={6}
            style={{ display: "flex", alignItems: "end" }}
          >
            <RadioComponent
              title="¿Aplica intereses?"
              values={values}
              onChangeChecked={(e, id) =>
                onChangeChecked(
                  e,
                  id,
                  values,
                  setValues,
                  setDataPayments,
                  setAmounts,
                  amounts
                )
              }
            />
          </Grid>
        )}

        <Grid item xs={12}>
          <TextField
            id="notes"
            label="Notas"
            placeholder="(Opcional. Para el comprobante)"
            multiline
            value={values.notes.value}
            variant="outlined"
            onChange={(e) => {
              setValues({
                ...values,
                notes: {
                  value: e.target.value,
                  isValid: e.target.validity.valid,
                },
              });
            }}
            fullWidth
            inputProps={{
              maxLength: 300,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
            }}
            error={!values.notes.isValid}
          />
        </Grid>

        <Grid item xs={12}>
          <Typography variant="h6">
            Agregar pago{" "}
            {amounts.remainsToPay > 0 && (
              <Fragment>
                <span style={{ color: "#158900", fontSize: 14 }}>
                  {`(Falta pagar:\n`}
                </span>
                <span style={{ color: "#158900", fontSize: 14 }}>
                  {NumberFormatCustom(amounts.remainsToPay)})
                </span>
              </Fragment>
            )}
          </Typography>
        </Grid>

        <PaymentMethod
          isMobile={isMobile}
          data={dataPayments}
          setData={setDataPayments}
          setForm={setFormPayments}
          addPayment={(data) =>
            addPayment(
              data,
              setDataPayments,
              payments,
              setPayments,
              amounts,
              setAmounts,
              setFormDiscounts
            )
          }
          amounts={amounts}
        />

        {payments.length > 0 && (
          <Grid item xs={12}>
            <div className={classes.cardContainer}>
              {payments.map((entry, index) => (
                <ItemCard
                  key={`itemCard-payments-${index}`}
                  title={paymentMethods[entry.type]}
                  subtitle={NumberFormatCustom(parseFloat(entry.amount))}
                  Icon={ReceiptIcon}
                  action={() =>
                    deletePayment(
                      index,
                      values,
                      setDataPayments,
                      payments,
                      setPayments,
                      amounts,
                      setAmounts
                    )
                  }
                />
              ))}
            </div>
          </Grid>
        )}

        <Grid item xs={12} style={{ padding: "16px 8px 8px" }}>
          <Typography variant="h6">
            Agregar descuento{" "}
            {amounts.remainsToPay > 0 && (
              <span style={{ color: "#158900", fontSize: 14 }}>(Opcional)</span>
            )}
          </Typography>
        </Grid>

        <DiscountsForm
          isMobile={isMobile}
          data={dataDiscounts}
          setData={setDataDiscounts}
          setForm={setFormDiscounts}
          addDiscount={(data) =>
            addDiscount(
              data,
              setDataPayments,
              setDataDiscounts,
              discounts,
              setDiscounts,
              amounts,
              setAmounts
            )
          }
          amounts={amounts}
        />

        {discounts.length > 0 && (
          <Grid item xs={12}>
            <div className={classes.cardContainer}>
              {discounts.map((entry, index) => (
                <ItemCard
                  key={`itemCard-payments-${index}`}
                  title={`${entry.concept} (Descuento)`}
                  subtitle={NumberFormatCustom(parseFloat(entry.amount))}
                  Icon={MoneyOffIcon}
                  action={() =>
                    deleteDiscount(
                      index,
                      values,
                      setDataPayments,
                      discounts,
                      setDiscounts,
                      amounts,
                      setAmounts
                    )
                  }
                />
              ))}
            </div>
          </Grid>
        )}

        <SendEmail
          values={values}
          setValues={setValues}
          recipients={recipients}
          dataSelecting={dataSelecting}
          setChecked={(e, id) =>
            setChecked(e, id, recipients, setRecipients, setSelected)
          }
          handleSelectAllClick={(e) =>
            handleSelectAllClick(e, setRecipients, setSelected)
          }
        />
      </Grid>
      <Grid container className={classes.buttons} spacing={1}>
        <Grid item xs={6} sm={isMobile ? 6 : 3}>
          <Button
            id="cancel-button"
            variant="outlined"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Cancelar
          </Button>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 6 : 3}>
          <Tooltip title={helperText()} leaveDelay={5000} interactive>
            <div>
              <Button
                disabled={disabled}
                variant="contained"
                color="primary"
                disableElevation
                fullWidth
                onClick={onClickHandler}
              >
                {isIndividualService() ||
                (values.checked === "false" && amounts.payments === 0)
                  ? "Cobrar"
                  : (values.checked === "true"
                      ? amounts.totalAmount +
                        amounts.taxes -
                        amounts.positiveBalance
                      : amounts.totalAmount - amounts.positiveBalance) <=
                    parseFloat(amounts.payments) + parseFloat(amounts.discounts)
                  ? "Cobrar"
                  : values.checked === "true" &&
                    parseFloat(amounts.payments) +
                      parseFloat(amounts.discounts) <
                      amounts.taxes
                  ? NumberFormatCustom(amounts.taxes, "Minimo $")
                  : "Cobro Parcial"}
              </Button>
            </div>
          </Tooltip>
        </Grid>
      </Grid>
    </Fragment>
  );
};

export default Form;
