import {
  GET_BOXES,
  ADD_BOX,
  EDIT_BOX,
  DELETE_BOX,
} from "../Action/actionTypes";

const initialState = { boxes: [] };

export const boxesReducer = (state = initialState, action) => {
  switch (action.type) {
    case GET_BOXES:
      return {
        ...state,
        boxes: action.payload,
      };
    case ADD_BOX:
      return {
        ...state,
        boxes: action.payload,
      };
    case EDIT_BOX:
      return {
        ...state,
        boxes: action.payload,
      };
    case DELETE_BOX:
      return {
        ...state,
        boxes: action.payload,
      };
    default:
      return state;
  }
};

export default boxesReducer;
