import axios from "axios";
import {
  GET_SERVICES,
  ADD_SERVICE,
  EDIT_SERVICE,
  DELETE_SERVICE,
} from "../Action/actionTypes";

import { setSnackData } from "./snackDataActions";

axios.defaults.withCredentials = true;

export const getServices = (token, setIsLoading) => (dispatch) => {
  axios
    .get(`${process.env.REACT_APP_BACKEND_URL}/rentals/services`, {
      headers: {
        Authorization: "Bearer " + token,
      },
    })
    .then((res) => {
      dispatch({
        type: GET_SERVICES,
        payload: res.data,
      });

      if (setIsLoading) setIsLoading(false);
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }

      if (setIsLoading) setIsLoading(false);
    });
};

export const addService =
  (token, data, setOpen, setIsLoading) => (dispatch, getState) => {
    let aux = getState().services.services;
    let services = Array.from(aux);

    axios
      .post(`${process.env.REACT_APP_BACKEND_URL}/rentals/services`, data, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((res) => {
        services.push(res.data);

        dispatch({
          type: ADD_SERVICE,
          payload: services,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Servicio creado",
            severity: "success",
          })
        );

        setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };

export const editService =
  (token, data, current, setOpen, setIsLoading) => (dispatch, getState) => {
    let aux = getState().services.services;
    let services = Array.from(aux);

    axios
      .put(
        `${process.env.REACT_APP_BACKEND_URL}/rentals/services/${current._id}`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        let i = services.findIndex((entry) => {
          if (entry._id === current._id) {
            return true;
          }
          return false;
        });

        if (i !== -1) {
          services[i] = Object.assign(services[i], data);
        }

        dispatch({
          type: EDIT_SERVICE,
          payload: services,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Servicio editado",
            severity: "success",
          })
        );

        setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };

export const deleteService =
  (token, id, setOpen, setIsLoading) => (dispatch, getState) => {
    let aux = getState().services.services;
    let services = Array.from(aux);

    axios
      .delete(`${process.env.REACT_APP_BACKEND_URL}/rentals/services/${id}`, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((_) => {
        let i = services.findIndex((estate) => {
          if (estate._id === id) {
            return true;
          }
          return false;
        });

        i !== -1 && services.splice(i, 1);

        dispatch({
          type: DELETE_SERVICE,
          payload: services,
        });

        dispatch(
          setSnackData({
            open: true,
            message: "Servicio eliminado",
            severity: "success",
          })
        );

        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }

        if (setIsLoading) setIsLoading(false);
      });
  };
