import React, { Fragment } from "react";
import {
  Button,
  FormControl,
  FormControlLabel,
  FormLabel,
  Grid,
  makeStyles,
  Radio,
  RadioGroup,
  TextField,
} from "@material-ui/core";
import NumberFormat from "react-number-format";

const useStyles = makeStyles((theme) => ({
  addButton: {
    backgroundColor: "#49AC08",
    color: "#FAFAFA",
    textTransform: "capitalize",
    fontSize: 12,
    "&:hover": {
      backgroundColor: "#49ac089e",
    },
  },
  radioGroup: {
    display: "flex",
    justifyContent: "flex-end",
    "& .Mui-checked": {
      color: "#49AC08",
    },
  },
}));

function NumberFormatCustom(props) {
  const { min, id, inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
            id: id,
            validity: {
              valid: parseFloat(values.value, 10) > parseFloat(min, 10),
            },
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={2}
      isNumericString
      prefix="$"
    />
  );
}

const DiscountsForm = ({
  isMobile,
  data,
  setData,
  setForm,
  addDiscount,
  amounts,
}) => {
  const classes = useStyles();

  const onClick = () => {
    let aux = {};

    for (let key in data) {
      if (data[key].value !== "") {
        aux[key] = data[key].value;
      }
    }

    setForm((data) => {
      let copy = { ...data };
      for (let key in data) {
        copy[key] = {
          value: key === "isRecurrent" || key === "cashFromBox" ? "false" : "",
          isValid: true,
        };
      }
      return copy;
    });

    addDiscount(aux);
  };

  let disabled = !Object.entries(data)
    .filter((entry) => entry[0] !== "isRecurrent" || entry[0] !== "cashFromBox")
    .some((entry) => entry[1].value === "" || entry[1].isValid !== true)
    ? false
    : true;

  return (
    <Fragment>
      <Grid item xs={12} sm={6}>
        <TextField
          value={data.concept.value}
          required
          autoComplete="off"
          fullWidth
          id="concept"
          name="concept"
          label="Concepto"
          inputProps={{
            minLength: 2,
            maxLength: 100,
            pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
          }}
          onChange={setData}
          error={!data.concept.isValid}
          InputLabelProps={{ required: false }}
        />
      </Grid>

      <Grid item xs={12} sm={6}>
        <TextField
          InputProps={{
            inputComponent: NumberFormatCustom,
          }}
          required
          autoComplete="off"
          label="Importe"
          id="amount"
          name="amount"
          value={data.amount.value}
          onChange={(e) => {
            let value = parseFloat(e.target.value);

            if (value < amounts.toLiquidate) {
              e.target.validity.valid = true;
            } else {
              e.target.validity.valid = false;
            }

            if (e.target.value !== "") setData(e);
          }}
          fullWidth
          inputProps={{
            min: "0",
            pattern: "[0-9.]+",
            step: ".01",
          }}
          error={!data.amount.isValid}
          InputLabelProps={{ required: false }}
        />
      </Grid>
      <Grid item xs={12} sm={6}>
        <FormControl component="fieldset" fullWidth>
          <Grid container alignItems="center">
            <Grid item xs={7}>
              <FormLabel style={{ color: "#616161" }}>
                ¿Es recurrente?
              </FormLabel>
            </Grid>
            <Grid item xs={5}>
              <RadioGroup
                className={classes.radioGroup}
                name="radio"
                value={data.isRecurrent.value}
                onChange={(e) => {
                  let aux = {
                    target: {
                      id: "isRecurrent",
                      value: e.target.value,
                    },
                    validity: { valid: true },
                  };

                  setData(aux);
                }}
                row
              >
                <FormControlLabel
                  value="true"
                  control={
                    <Radio
                      color="primary"
                      disableRipple
                      style={{
                        padding: 0,
                        marginRight: 8,
                      }}
                    />
                  }
                  label="Sí"
                />
                <FormControlLabel
                  style={{ marginRight: 0 }}
                  value="false"
                  control={
                    <Radio
                      color="primary"
                      disableRipple
                      style={{
                        padding: 0,
                        marginRight: 8,
                        marginLeft: 8,
                      }}
                    />
                  }
                  label="No"
                />
              </RadioGroup>
            </Grid>
          </Grid>
        </FormControl>
      </Grid>
      {data.isRecurrent.value === "false" && (
        <Grid item xs={12} sm={6}>
          <FormControl component="fieldset" fullWidth>
            <Grid container alignItems="center">
              <Grid item xs={7}>
                <FormLabel style={{ color: "#616161" }}>
                  ¿Sale dinero de caja?
                </FormLabel>
              </Grid>
              <Grid item xs={5}>
                <RadioGroup
                  className={classes.radioGroup}
                  name="radio"
                  value={data.cashFromBox.value}
                  onChange={(e) => {
                    let aux = {
                      target: {
                        id: "cashFromBox",
                        value: e.target.value,
                      },
                      validity: { valid: true },
                    };

                    setData(aux);
                  }}
                  row
                >
                  <FormControlLabel
                    value="true"
                    control={
                      <Radio
                        color="primary"
                        disableRipple
                        style={{
                          padding: 0,
                          marginRight: 8,
                        }}
                      />
                    }
                    label="Sí"
                  />
                  <FormControlLabel
                    style={{ marginRight: 0 }}
                    value="false"
                    control={
                      <Radio
                        color="primary"
                        disableRipple
                        style={{
                          padding: 0,
                          marginRight: 8,
                          marginLeft: 8,
                        }}
                      />
                    }
                    label="No"
                  />
                </RadioGroup>
              </Grid>
            </Grid>
          </FormControl>
        </Grid>
      )}
      <Grid
        item
        xs={isMobile ? 12 : data.isRecurrent.value === "false" ? 12 : 6}
        style={{ display: "flex", alignItems: "end" }}
      >
        <Button
          disabled={disabled}
          fullWidth
          disableElevation
          variant="contained"
          className={classes.addButton}
          onClick={onClick}
        >
          Agregar descuento
        </Button>
      </Grid>
    </Fragment>
  );
};

export default DiscountsForm;
