import React from "react";
import Button from "@material-ui/core/Button";
import TextField from "@material-ui/core/TextField";
import { makeStyles } from "@material-ui/core/styles";
import { useForm } from "../../hooks/use-form";
import Spinner from "../UI/Spinner";
import { changePassword } from "../../Redux/Action/userActions";
import { useDispatch } from "react-redux";
import { useHistory, useParams } from "react-router";

const useStyles = makeStyles((theme) => ({
  form: {
    width: "100%", // Fix IE 11 issue.
    marginTop: theme.spacing(1),
  },
  submit: {
    margin: theme.spacing(3, 0, 2),
  },
  resetPassword: {
    textAlign: "right",
  },
}));

export default function ChangePasswordForm() {
  const classes = useStyles();
  const dispatch = useDispatch();
  const history = useHistory();
  const token = useParams().token;

  const [form, onChangeHandler] = useForm({
    password: "",
    repassword: "",
  });

  const navigate = () => {
    history.replace("/");
  };

  const [isLoading, setIsLoading] = React.useState(false);

  const submitHandler = async (e) => {
    e.preventDefault();
    const password = form.password.value;
    const repassword = form.repassword.value;

    if (password === repassword) {
      let data = {
        token,
        password,
      };
      setIsLoading(true);
      dispatch(changePassword(data, setIsLoading, navigate));
    }
  };

  return !isLoading ? (
    <form className={classes.form} onSubmit={submitHandler}>
      <TextField
        variant="outlined"
        margin="normal"
        required
        fullWidth
        name="password"
        label="Password"
        type="password"
        id="password"
        autoComplete="new-password"
        value={form.password.value}
        onChange={onChangeHandler}
        inputProps={{
          pattern: "[a-zA-Z0-9@#!$&?.*]*$",
          minLength: 8,
        }}
        InputLabelProps={{ required: false }}
      />
      <TextField
        variant="outlined"
        margin="normal"
        required
        fullWidth
        name="repassword"
        label="Reingrese Password"
        type="password"
        id="repassword"
        autoComplete="new-password"
        value={form.repassword.value}
        onChange={onChangeHandler}
        inputProps={{
          pattern: "[a-zA-Z0-9@#!$&?.*]*$",
          minLength: 8,
        }}
        error={form.password.value !== form.repassword.value}
        helperText={
          form.password.value !== form.repassword.value
            ? "Los passwords deben coincidir"
            : ""
        }
        InputLabelProps={{ required: false }}
      />
      <Button
        type="submit"
        fullWidth
        variant="contained"
        color="primary"
        className={classes.submit}
      >
        Cambiar
      </Button>
    </form>
  ) : (
    <Spinner />
  );
}
