import React, { useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { makeStyles } from "@material-ui/core";
import Form from "./Form";
import { addPayment } from "../../Redux/Action/paymentsActions";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    padding: theme.spacing(1),
  },
}));

const AddPayment = ({ id, idUF, token, boxes, setOpen }) => {
  const classes = useStyles();
  const dispatch = useDispatch();

  const [isLoading, setIsLoading] = useState(false);

  const currentUF = useSelector(
    (state) => state.functionalunits.functionalUnits
  ).filter((uf) => uf._id === idUF)[0];

  const onClikHandler = (data) => {
    setIsLoading(true);
    dispatch(addPayment(id, idUF, token, data, setOpen, setIsLoading));
  };

  return (
    <div className={classes.container}>
      <Form
        title="Registar pago"
        setOpen={setOpen}
        isLoading={isLoading}
        onClikHandler={onClikHandler}
        balance={currentUF.balance}
        boxes={boxes}
      />
    </div>
  );
};

export default AddPayment;
