import axios from "axios";
import {
  GET_PROVIDERS,
  ADD_PROVIDER,
  EDIT_PROVIDER,
  DELETE_PROVIDER,
} from "./actionTypes";

import { setSnackData } from "./snackDataActions";

export const getProviders = (token, setIsLoading) => (dispatch) => {
  axios
    .get(`${process.env.REACT_APP_BACKEND_URL}/providers`, {
      headers: {
        Authorization: "Bearer " + token,
      },
    })
    .then((res) => {
      const providers = res.data.sort((a, b) => a.name.localeCompare(b.name));
      
      dispatch({
        type: GET_PROVIDERS,
        payload: providers,
      });
      if (setIsLoading) setIsLoading(false);
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }
      if (setIsLoading) setIsLoading(false);
    });
};

export const addProvider =
  (token, data, setOpen, setIsLoading) => (dispatch, getState) => {
    let providers = getState().providers.providers;
    axios
      .post(`${process.env.REACT_APP_BACKEND_URL}/providers`, data, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((res) => {
        providers.push(res.data);
        dispatch({
          type: ADD_PROVIDER,
          payload: providers,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Proveedor creado",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const editProvider =
  (token, idProv, data, setOpen, setIsLoading) => (dispatch, getState) => {
    let providers = getState().providers.providers;
    axios
      .put(`${process.env.REACT_APP_BACKEND_URL}/providers/${idProv}`, data, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((_) => {
        let i = providers.findIndex((provider) => {
          if (provider._id === idProv) {
            return true;
          }
          return false;
        });

        if (i !== -1) {
          providers[i] = Object.assign(providers[i], data);
        }

        dispatch({
          type: EDIT_PROVIDER,
          payload: providers,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Proveedor editado",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const deleteProvider =
  (token, idProv, setOpen, setIsLoading) => (dispatch, getState) => {
    let providers = getState().providers.providers;
    axios
      .delete(`${process.env.REACT_APP_BACKEND_URL}/providers/${idProv}`, {
        headers: {
          Authorization: "Bearer " + token,
        },
      })
      .then((res) => {
        let i = providers.findIndex((provider) => {
          if (provider._id === idProv) {
            return true;
          }
          return false;
        });

        i !== -1 && providers.splice(i, 1);

        dispatch({
          type: DELETE_PROVIDER,
          payload: providers,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Proveedor eliminado",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };
