import React, { Fragment } from "react";
import { makeStyles } from "@material-ui/core/styles";
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableRow,
  Paper,
  TableHead,
  Checkbox,
  Grid,
  FormControl,
  FormLabel,
  RadioGroup,
  FormControlLabel,
  Radio,
} from "@material-ui/core";

const useStyles = makeStyles((theme) => ({
  radioGroup: {
    display: "flex",
    justifyContent: "flex-end",
    "& .Mui-checked": {
      color: "#49AC08",
    },
  },
  tableContainer: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    justifyContent: "space-between",
    boxShadow: "none",
    backgroundColor: "#F7F9F8",
    border: "1px solid #E6EBE8",
    borderRadius: 12,
    padding: theme.spacing(1, 1.25),
    maxHeight: 225,

    "& .MuiTableCell-head": {
      color: "#000000",
      fontSize: "14px",
      lineHeight: "20px",
      letterSpacing: "0.02em",
      padding: theme.spacing(1),
    },

    "& .MuiTableCell-body": {
      color: "#000000",
      fontSize: "14px",
      lineHeight: "20px",
      letterSpacing: "0.02em",
      padding: theme.spacing(1),
      borderColor: "#E6EBE8",
    },

    "& .MuiIconButton-root": {
      padding: 0,
    },

    "& .Mui-checked": {
      color: "#49AC08",
    },
  },
  titleSection: {
    display: "flex",
    alignItems: "center",
    "& .MuiBadge-dot": {
      backgroundColor: theme.palette.secondary.light,
    },
  },

  titleChat: {
    marginLeft: theme.spacing(1),
  },
  rowActions: {
    width: 0,
    "@media (min-width:650px)": {
      width: "80px",
    },
  },
  iconButton: {
    padding: 0,
  },
}));

const SendEmail = ({
  values,
  setValues,
  recipients,
  dataSelecting,
  setChecked,
  handleSelectAllClick,
}) => {
  const classes = useStyles();

  const onClickHandler = (e) => {
    setValues({ ...values, sendEmail: e.target.value });
    handleSelectAllClick({
      target: { checked: e.target.value === "true" ? true : false },
    });
  };

  return (
    <Fragment>
      <Grid item xs={12} style={{ paddingTop: 16 }}>
        <FormControl component="fieldset" fullWidth>
          <Grid container alignItems="center">
            <Grid item xs={7}>
              <FormLabel style={{ color: "#616161" }}>
                ¿Enviar comprobante por correo?
              </FormLabel>
            </Grid>
            <Grid item xs={5}>
              <RadioGroup
                className={classes.radioGroup}
                aria-label="payable"
                name="payable"
                value={values.sendEmail}
                onChange={onClickHandler}
                row
              >
                <FormControlLabel
                  value="true"
                  control={
                    <Radio
                      color="primary"
                      disableRipple
                      style={{
                        padding: 0,
                        marginRight: 8,
                      }}
                    />
                  }
                  label="Sí"
                />
                <FormControlLabel
                  style={{ marginRight: 0 }}
                  value="false"
                  control={
                    <Radio
                      color="primary"
                      disableRipple
                      style={{
                        padding: 0,
                        marginRight: 8,
                        marginLeft: 8,
                      }}
                    />
                  }
                  label="No"
                />
              </RadioGroup>
            </Grid>
          </Grid>
        </FormControl>
      </Grid>
      {values.sendEmail === "true" && (
        <Grid item xs={12}>
          <TableContainer className={classes.tableContainer} component={Paper}>
            <Table aria-label="simple table">
              <TableHead>
                <TableRow>
                  <TableCell colSpan={3}>Destinatarios</TableCell>
                </TableRow>
                <TableRow>
                  <TableCell padding="checkbox">
                    <Checkbox
                      indeterminate={dataSelecting.indeterminate}
                      checked={dataSelecting.checked}
                      onChange={dataSelecting.onChange}
                    />
                  </TableCell>
                  <TableCell align="center">Nombre</TableCell>
                  <TableCell align="center">Apellido</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {recipients.map((entry, index) => (
                  <TableRow key={`tenant-${index}`}>
                    <TableCell
                      padding="checkbox"
                      style={
                        index + 1 === recipients.length
                          ? { borderBottom: "none" }
                          : null
                      }
                    >
                      <Checkbox
                        checked={entry.checked}
                        onChange={(e) => setChecked(e, entry._id)}
                      />
                    </TableCell>
                    <TableCell
                      align="center"
                      component="th"
                      scope="row"
                      style={
                        index + 1 === recipients.length
                          ? { borderBottom: "none" }
                          : null
                      }
                    >
                      {entry.name}
                    </TableCell>
                    <TableCell
                      align="center"
                      component="th"
                      scope="row"
                      style={
                        index + 1 === recipients.length
                          ? { borderBottom: "none" }
                          : null
                      }
                    >
                      {entry.lastname}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Grid>
      )}
    </Fragment>
  );
};

export default SendEmail;
