import { IconButton, TableCell } from "@material-ui/core";
import React, { Fragment, useState } from "react";
import { useSelector } from "react-redux";
import { getFormatDate } from "../../hooks/date-hook";
import Modal from "../Shared/Modal";
import Table from "../Shared/Table";
import Spinner from "../UI/Spinner";

import FileIcon from "@material-ui/icons/Description";
import DeleteReceipt from "./DeleteReceipt";

const Cells = ({ row }) => {
  return (
    <Fragment>
      <TableCell component="th" scope="row">
        {getFormatDate(row.createdAt)}
      </TableCell>
      <TableCell style={{ minWidth: 80 }} component="th" scope="row">
        {row.paymentOrders.length}
      </TableCell>
      <TableCell style={{ minWidth: 150 }} component="th" scope="row">
        {row.notes || "-"}
      </TableCell>

      <TableCell style={{ width: 120 }} component="th" scope="row">
        <a
          href={`${process.env.REACT_APP_BACKEND_URL}/files/${row.establishment}/${row._id}.pdf`}
          rel="noreferrer"
          target="_blank"
        >
          <IconButton
            style={{ padding: 0 }}
            variant="contained"
            color="primary"
          >
            <FileIcon />
          </IconButton>
        </a>
      </TableCell>
    </Fragment>
  );
};

const SettlementReceipts = ({ user, isLoadingTable }) => {
  const [open, setOpen] = useState(false);
  const [current, setCurrent] = useState(null);
  const [action, setAction] = useState();

  const columns = ["Fecha", "Ordenes de pago", "Notas", "Ver PDF", "Eliminar"];

  const rows = useSelector((state) => state.liquidations.settlementReceipts);

  const deleteAction = (current) => {
    setCurrent(current);
    setOpen(true);
  };

  const actions = {
    delete: <DeleteReceipt user={user} setOpen={setOpen} current={current} />,
  };

  return isLoadingTable ? (
    <Spinner height={300} />
  ) : (
    <Fragment>
      <Table
        columns={columns}
        rows={rows}
        Cells={Cells}
        deleteAction={deleteAction}
        setAction={setAction}
        disableColumnDetails={true}
        disableColumnEdit={true}
      />
      <Modal
        handleClose={() => setOpen(false)}
        open={open}
        component={actions[action]}
      />
    </Fragment>
  );
};

export default SettlementReceipts;
