import React, { Fragment } from "react";
import {
  Button,
  Grid,
  makeStyles,
  TextField,
  Typography,
  useMediaQuery,
  useTheme,
  MenuItem,
  Tooltip,
  IconButton,
} from "@material-ui/core";
import NumberFormat from "react-number-format";
import { ExpandMore } from "@material-ui/icons";
import Spinner from "../UI/Spinner";
import { useForm } from "../../hooks/use-form";

import { propertyTypes } from "../../configs/PROPERTY_TYPES";
import { useState } from "react";
import ContactsAutoComplete from "../Shared/ContactsAutoComplete";
import Modal from "../Shared/Modal";

import AddContact from "../Schedule/AddContact";
import ItemCard from "../Shared/ItemCard";

import PersonAddIcon from "@material-ui/icons/PersonAdd";
import AddIcon from "@material-ui/icons/Add";
import PersonIcon from "@material-ui/icons/Person";
import SelectImage from "../Shared/SelectImage";

import { useEffect } from "react";
import axios from "axios";

const useStyles = makeStyles((theme) => ({
  imageContainer: {
    display: "flex",
    flexDirection: "row",
    justifyContent: "space-between",
    alignItems: "flex-start",
    marginTop: theme.spacing(2),
    "@media (max-width:600px)": {
      flexDirection: "column",
    },
  },
  grid: {
    marginTop: theme.spacing(1),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  contact: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "flex-end",
  },
  addButton: {
    marginTop: theme.spacing(2),
    marginLeft: theme.spacing(1),
    padding: theme.spacing(0.5),
  },
  cardContainer: {
    padding: theme.spacing(0.5, 0.5, 0, 0),
    overflowX: "hidden",
    overflowY: "auto",
    maxHeight: theme.spacing(13.75),
  },
  marginBottom: {
    marginBottom: theme.spacing(2.5),
  },
  buttons: {
    marginTop: theme.spacing(2.5),
    "& .MuiTooltip-tooltip": {
      backgroundColor: "red",
    },
  },
}));

function NumberFormatPercentage(props) {
  const { inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={2}
      isNumericString
      suffix="%"
    />
  );
}

const initialState = {
  type: "",
  number: "",
  province: "",
  department: "",
  location: "",
  address: "",
};

const Form = ({
  title,
  contacts,
  getContacts,
  setOpen,
  isLoading,
  percentage,
  setPercentage,
  overallPercentage,
  setOverallPercentage,
  owners,
  setOwners,
  onClikHandler,
  data,
  hasChanged,
  setHasChanged,
}) => {
  const classes = useStyles();

  const [form, onChangeHandler] = useForm(
    data
      ? {
          type: data.type,
          number: data.number,
          province: data.province,
          department: data.department,
          location: data.location,
          address: data.address,
        }
      : initialState
  );

  const [image, setImage] = useState(null);

  const [contact, setContact] = useState("");

  const [openAddContact, setOpenAddContact] = useState(false);

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const onChangeData = () => {
    if (setHasChanged && hasChanged === false) {
      setHasChanged(true);
    }
  };

  const addOwner = () => {
    let sum = 0;

    for (let i = 0; i < owners.length; i++) {
      sum += parseFloat(owners[i].percentage);
    }

    let i = contacts.findIndex((entry) => {
      if (entry._id === contact) {
        return true;
      }
      return false;
    });

    let j = owners.findIndex((entry) => {
      if (entry.owner._id === contact) {
        return true;
      }
      return false;
    });

    if (i !== -1 && j === -1) {
      setOwners([
        ...owners,
        {
          owner: {
            _id: contacts[i]._id,
            name: contacts[i].name,
            lastname: contacts[i].lastname,
          },
          percentage: percentage,
        },
      ]);

      setPercentage((percentage) => {
        let aux = sum + parseFloat(percentage, 10);
        setOverallPercentage(aux);

        if (aux === 100) {
          return "0";
        }

        let aux2 = 100 - aux;
        return aux2.toString();
      });
    }

    setContact("");
  };

  const deleteOwner = (id, percentageOwner) => {
    setOwners((owners) => {
      let copy = [...owners];
      let i = copy.findIndex((entry) => {
        if (entry.owner._id === id) {
          return true;
        }
        return false;
      });

      i !== -1 && copy.splice(i, 1);

      return copy;
    });

    setPercentage((percentage) => {
      let aux = parseFloat(percentage, 10) + parseFloat(percentageOwner, 10);
      setOverallPercentage(100 - aux);
      return aux.toString();
    });
  };

  const onImageChangeHandler = (e) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      if (
        file.type === "image/jpeg" ||
        file.type === "image/jpg" ||
        file.type === "image/png"
      ) {
        setImage(file);
      }
    }
    onChangeData();
  };

  const deleteImageHandler = () => {
    setImage(null);
    onChangeData();
  };

  const formatData = () => {
    let data = {
      image: image,
      type: form.type.value,
      owners: owners,
      number: form.number.value,
      province: form.province.value,
      department: form.department.value,
      location: form.location.value,
      address: form.address.value,
    };

    onClikHandler(data);
  };

  let disabled =
    hasChanged &&
    !Object.entries(form).some((entry) => entry[1].value === "") &&
    owners.length &&
    overallPercentage === 100
      ? false
      : true;

  useEffect(() => {
    let isMounted = true;
    if (isMounted && data && data.image) {
      (async () => {
        const res = await axios.get(
          `${process.env.REACT_APP_BACKEND_URL}/files/${data.establishment}/${data.image}`,
          {
            responseType: "blob",
            headers: { "Access-Control-Allow-Origin": "*" },
          }
        );

        setImage(res.data);
      })();
    }
    return () => {
      isMounted = false;
    };
  }, [data]);

  return isLoading ? (
    <Spinner height={612} />
  ) : (
    <Fragment>
      <Typography variant="h6">{title}</Typography>
      <div className={classes.imageContainer}>
        <div style={{ marginRight: 16 }}>
          <SelectImage
            heigth={128}
            width={128}
            image={image}
            setImage={onImageChangeHandler}
            deleteImage={deleteImageHandler}
            backgroundSize={"150px"}
            textImage="Seleccione una imagen"
          />
        </div>
        <Grid
          container
          className={classes.grid}
          style={{ marginTop: 0 }}
          spacing={2}
        >
          <Grid item xs={12}>
            <TextField
              label="Tipo"
              id="type"
              value={form.type.value}
              onChange={(e) => {
                e.target.id = "type";
                onChangeHandler(e);
                onChangeData();
              }}
              select
              SelectProps={{
                IconComponent: ExpandMore,
              }}
              fullWidth
            >
              <MenuItem value=""></MenuItem>
              {Object.entries(propertyTypes).map((entry, index) => (
                <MenuItem key={`select-${entry[0]}-${index}`} value={entry[0]}>
                  {entry[1]}
                </MenuItem>
              ))}
            </TextField>
          </Grid>
          <Grid item xs={isMobile ? 5 : 6}>
            <ContactsAutoComplete
              label="Propietario"
              contacts={contacts}
              contact={contact}
              setState={(value) => {
                if (value) {
                  setContact(value._id);
                } else {
                  setContact("");
                }
                onChangeData();
              }}
            />
          </Grid>
          <Grid item xs={3}>
            <TextField
              InputProps={{
                inputComponent: NumberFormatPercentage,
              }}
              disabled={overallPercentage === 100}
              value={percentage}
              autoComplete="off"
              fullWidth
              id="percentage"
              name="percentage"
              label="Porcentaje"
              placeholder="0"
              inputProps={{
                min: "0",
                max: "100",
                pattern: "[0-9]+",
                step: ".01",
              }}
              error={percentage < 0 || percentage > 100}
              onChange={(e) => {
                setPercentage(e.target.value);
                onChangeData();
              }}
            />
          </Grid>
          <Grid item xs={isMobile ? 4 : 3}>
            <div className={classes.contact}>
              <Tooltip title="Agregar contacto">
                <IconButton
                  className={classes.addButton}
                  variant="contained"
                  aria-label="add"
                  onClick={() => setOpenAddContact(true)}
                >
                  <PersonAddIcon />
                </IconButton>
              </Tooltip>
              <Tooltip title="Agregar propietario">
                <div>
                  <IconButton
                    disabled={overallPercentage === 100}
                    className={classes.addButton}
                    variant="contained"
                    aria-label="add"
                    onClick={addOwner}
                  >
                    <AddIcon />
                  </IconButton>
                </div>
              </Tooltip>
            </div>
          </Grid>
        </Grid>
      </div>
      <Grid container className={classes.grid} spacing={2}>
        {owners.length > 0 && (
          <Grid item xs={12}>
            <div className={classes.cardContainer}>
              {owners.map((entry, index) => (
                <ItemCard
                  key={`itemCard-${index}`}
                  title={`${entry.owner.name} ${entry.owner.lastname}`}
                  subtitle={`(${entry.percentage}%)`}
                  Icon={PersonIcon}
                  action={() => deleteOwner(entry.owner._id, entry.percentage)}
                />
              ))}
            </div>
          </Grid>
        )}
        <Grid item xs={12}>
          <TextField
            type="number"
            autoComplete="off"
            value={form.number.value}
            required
            fullWidth
            id="number"
            name="number"
            label="Legajo"
            inputProps={{
              min: 1,
              max: 99999999,
              pattern: "^[0-9]+",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.number.isValid}
            helperText={!form.number.isValid && "Legajo inválido"}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            value={form.province.value}
            required
            autoComplete="off"
            fullWidth
            name="province"
            id="province"
            label="Provincia"
            inputProps={{
              minLength: 2,
              maxLength: 100,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ . -]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.province.isValid}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            value={form.department.value}
            required
            autoComplete="off"
            fullWidth
            name="department"
            id="department"
            label="Partido"
            inputProps={{
              minLength: 2,
              maxLength: 100,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ . -]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.department.isValid}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            value={form.location.value}
            required
            autoComplete="off"
            fullWidth
            name="location"
            id="location"
            label="Localidad"
            inputProps={{
              minLength: 2,
              maxLength: 100,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ . -]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.location.isValid}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            value={form.address.value}
            required
            autoComplete="off"
            fullWidth
            name="address"
            id="address"
            label="Dirección"
            inputProps={{
              minLength: 2,
              maxLength: 100,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ . -]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.address.isValid}
            InputLabelProps={{ required: false }}
          />
        </Grid>
      </Grid>
      <Grid container className={classes.buttons} spacing={1}>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            id="cancel-button"
            variant="outlined"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Cancelar
          </Button>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Tooltip
            title={
              disabled
                ? overallPercentage < 100
                  ? "Los porcentajes de los propietarios deben sumar el 100%"
                  : "Debe rellenar todos los campos para poder continuar"
                : ""
            }
            leaveDelay={5000}
            interactive
          >
            <div>
              <Button
                disabled={disabled}
                variant="contained"
                color="primary"
                disableElevation
                fullWidth
                onClick={formatData}
              >
                Aceptar
              </Button>
            </div>
          </Tooltip>
        </Grid>
      </Grid>
      <Modal
        handleClose={() => setOpenAddContact(false)}
        open={openAddContact}
        component={
          <AddContact
            setOpen={(value) => {
              getContacts();
              setOpenAddContact(value);
            }}
            preload={setContact}
          />
        }
      />
    </Fragment>
  );
};

export default Form;
