import React, { useState, Fragment } from "react";
import { makeStyles } from "@material-ui/core/styles";
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  Paper,
  IconButton,
  Collapse,
  Box,
} from "@material-ui/core";

import FolderIcon from "@material-ui/icons/FolderOpenOutlined";
import DeleteIcon from "@material-ui/icons/DeleteOutlineOutlined";
import EditIcon from "@material-ui/icons/EditOutlined";
import VisibilityIcon from "@material-ui/icons/VisibilityOutlined";
import KeyboardArrowDownIcon from "@material-ui/icons/KeyboardArrowDown";
import KeyboardArrowUpIcon from "@material-ui/icons/KeyboardArrowUp";

const useStyles = makeStyles(() => ({
  container: {
    flex: 1,
    display: "flex",
    flexDirection: "column",
    justifyContent: "space-between",
    boxShadow: "none",
    border: "1px solid #E6EBE8",
    borderRadius: 12,
    overflow: "hidden",

    "& .MuiTableCell-head": {
      color: "#3D4A57",
      backgroundColor: "#F4F7F5",
      fontWeight: 700,
      fontSize: 12,
      letterSpacing: "0.04em",
      borderBottom: "1px solid #E6EBE8",
    },
  },
  table: {
    minWidth: 400,
  },
  iconButton: {
    padding: 0,
  },
  rowActions: {
    width: "120px",
  },
  box: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    flexDirection: "column",
  },
}));

const CollapsibleTable = ({
  dataIcon,
  columns,
  columnsMoreActions,
  rows,
  Cells,
  MoreActions,
  disableColumnDetails,
  disableColumnEdit,
  disableColumnDelete,
  disabledDetails,
  disabledDelete,
  detailsAction,
  editAction,
  deleteAction,
  setAction,
  DataCollapsible,
  setIsLoadingDC,
}) => {
  const classes = useStyles();

  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(30);
  const [current, setCurrent] = useState(null);

  const [disabledColumns] = useState(() => {
    let values = [disableColumnDetails, disableColumnEdit, disableColumnDelete];
    let aux = 0;
    for (let i = 0; i < values.length; i++) {
      if (values[i] === true) {
        aux += 1;
      }
    }
    return aux;
  });

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const Row = ({ row, current, setCurrent }) => {
    const open = current === row._id ? true : false;

    return (
      <Fragment>
        <TableRow>
          <TableCell>
            <IconButton
              aria-label="expand row"
              size="small"
              onClick={() => {
                setIsLoadingDC(true);
                if (open) {
                  setCurrent(null);
                } else {
                  setCurrent(row._id);
                }
              }}
            >
              {open ? <KeyboardArrowUpIcon /> : <KeyboardArrowDownIcon />}
            </IconButton>
          </TableCell>
          <Cells row={row} />
          {MoreActions && <MoreActions row={row} />}
          {!disableColumnDetails && (
            <TableCell align="center" className={classes.rowActions}>
              <IconButton
                disabled={disabledDetails}
                className={classes.iconButton}
                style={{
                  color: disabledDetails ? "#BBB2B2" : "#48BD12",
                }}
                onClick={() => {
                  setAction("details");
                  detailsAction(row);
                }}
              >
                {dataIcon ? <FolderIcon /> : <VisibilityIcon />}
              </IconButton>
            </TableCell>
          )}
          {!disableColumnEdit && (
            <TableCell align="center" className={classes.rowActions}>
              <IconButton
                className={classes.iconButton}
                style={{ color: "#1260BD" }}
                onClick={() => {
                  setAction("edit");
                  editAction(row);
                }}
              >
                <EditIcon />
              </IconButton>
            </TableCell>
          )}
          {!disableColumnDelete && (
            <TableCell align="center" className={classes.rowActions}>
              <IconButton
                disabled={disabledDelete}
                className={classes.iconButton}
                style={{
                  color: disabledDelete ? "#BBB2B2" : "#CA0303",
                }}
                onClick={() => {
                  setAction("delete");
                  deleteAction(row);
                }}
              >
                <DeleteIcon />
              </IconButton>
            </TableCell>
          )}
        </TableRow>
        <TableRow>
          <TableCell style={{ paddingBottom: 0, paddingTop: 0 }} colSpan={8}>
            <Collapse in={open} timeout="auto" unmountOnExit>
              <Box margin={2} className={classes.box}>
                <DataCollapsible row={row} />
              </Box>
            </Collapse>
          </TableCell>
        </TableRow>
      </Fragment>
    );
  };

  return (
    <TableContainer component={Paper} className={classes.container}>
      <Table className={classes.table} aria-label="simple table">
        <TableHead>
          <TableRow>
            <TableCell />
            {columns
              .slice(
                0,
                disabledColumns === 3
                  ? columns.length - 1
                  : columns.length - (3 - disabledColumns)
              )
              .map((column, index) => (
                <TableCell key={index}>{column}</TableCell>
              ))}
            {disabledColumns === 3 &&
              columns.slice(columns.length - 1).map((column, index) => (
                <TableCell key={index} align="center">
                  {column}
                </TableCell>
              ))}
            {columnsMoreActions &&
              columnsMoreActions.map((column, index) => (
                <TableCell key={index} align="center">
                  {column}
                </TableCell>
              ))}
            {columns
              .slice(columns.length - (3 - disabledColumns))
              .map((column, index) => (
                <TableCell key={index} align="center">
                  {column}
                </TableCell>
              ))}
          </TableRow>
        </TableHead>
        <TableBody className={classes.tableBody}>
          {rows
            .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
            .map((row) => (
              <Row
                key={row._id}
                row={row}
                current={current}
                setCurrent={setCurrent}
              />
            ))}
        </TableBody>
      </Table>
      <TablePagination
        rowsPerPageOptions={[15, 30, 50, 100]}
        component="div"
        count={rows.length}
        rowsPerPage={rowsPerPage}
        page={page}
        onChangePage={handleChangePage}
        onChangeRowsPerPage={handleChangeRowsPerPage}
        labelRowsPerPage="Items por página"
        labelDisplayedRows={({ from, to, count }) => {
          return `${from}-${to} de ${count}`;
        }}
      />
    </TableContainer>
  );
};

export default CollapsibleTable;
