import React, { useState } from "react";
import {
  Button,
  Grid,
  makeStyles,
  TextField,
  Typography,
  useMediaQuery,
  useTheme,
} from "@material-ui/core";
import Spinner from "../UI/Spinner";
import { useForm } from "../../hooks/use-form";
import NumberFormat from "react-number-format";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    width: theme.spacing(50),
    padding: theme.spacing(5),
    "@media (max-width:650px)": {
      width: theme.spacing(30),
      padding: theme.spacing(1),
    },
    "@media (max-width:400px)": {
      width: theme.spacing(20),
      padding: 0,
    },
  },
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  marginBottom: {
    marginBottom: theme.spacing(2.5),
  },
}));

function NumberFormatCustom(props) {
  const { inputRef, onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
      getInputRef={inputRef}
      onValueChange={(values) => {
        onChange({
          target: {
            value: values.value,
          },
        });
      }}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={2}
      isNumericString
      prefix="$"
    />
  );
}

const initialState = {
  nameConsortium: "",
  addressConsortium: "",
};

const Form = ({
  title,
  setOpen,
  isLoading,
  onClikHandler,
  data,
  hasChanged,
  setHasChanged,
}) => {
  const classes = useStyles();

  const [balance, setBalance] = useState(
    data ? (data.balance.amount ? data.balance.amount : data.balance) : "0"
  );

  const [form, onChangeHandler] = useForm(
    data
      ? {
          nameConsortium: data.name,
          addressConsortium: data.address,
        }
      : initialState
  );

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const onChangeData = () => {
    if (setHasChanged && hasChanged === false) {
      setHasChanged(true);
    }
  };

  const formatData = () => {
    let data = {
      name: form.nameConsortium.value,
      address: form.addressConsortium.value,
      balance: balance,
    };

    onClikHandler(data);
  };

  let disabled =
    hasChanged &&
    Object.entries(form).filter(
      (entry) => entry[1].value === "" || entry[1].isValid === false
    ).length === 0
      ? false
      : true;

  return isLoading ? (
    <Spinner height={340} />
  ) : (
    <div>
      <Typography variant="h6">{title}</Typography>
      <Grid container className={classes.grid} spacing={1}>
        <Grid item xs={12}>
          <TextField
            value={form.nameConsortium.value}
            required
            autoComplete="off"
            fullWidth
            id="nameConsortium"
            name="name"
            label="Nombre"
            inputProps={{
              minLength: 2,
              maxLength: 100,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ .]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.nameConsortium.isValid}
            helperText={
              !form.nameConsortium.isValid &&
              (form.nameConsortium.value.length < 2
                ? "Pocos caracteres"
                : "Nombre inválido")
            }
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            value={form.addressConsortium.value}
            required
            autoComplete="off"
            fullWidth
            name="address"
            id="addressConsortium"
            label="Dirección"
            inputProps={{
              minLength: 2,
              maxLength: 100,
              pattern: "^[0-9a-zA-ZñÑáéíóúÁÉÍÓÚüÜ . -]+$",
            }}
            onChange={(e) => {
              onChangeHandler(e);
              onChangeData();
            }}
            error={!form.addressConsortium.isValid}
            helperText={
              !form.addressConsortium.isValid &&
              (form.addressConsortium.value.length < 2
                ? "Pocos caracteres"
                : "Dirección inválida")
            }
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            className={classes.marginBottom}
            InputProps={{
              inputComponent: NumberFormatCustom,
            }}
            required
            autoComplete="off"
            label="Saldo inicial"
            id="balance"
            name="balance"
            value={balance}
            onChange={(e) => {
              setBalance(parseFloat(e.target.value, 10));
              onChangeData();
            }}
            fullWidth
            inputProps={{
              pattern: "[0-9.]+",
              step: ".01",
            }}
            InputLabelProps={{ required: false }}
          />
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            id="cancel-button"
            variant="outlined"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Cancelar
          </Button>
        </Grid>
        <Grid item xs={6} sm={isMobile ? 2 : 6}>
          <Button
            disabled={disabled}
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={formatData}
          >
            Aceptar
          </Button>
        </Grid>
      </Grid>
    </div>
  );
};

export default Form;
