import axios from "axios";
import { GET_BOXES, ADD_BOX, EDIT_BOX, DELETE_BOX } from "./actionTypes";

import { setSnackData } from "./snackDataActions";

export const getBoxes = (id, token, setIsLoading) => (dispatch) => {
  axios
    .get(`${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/boxes`, {
      headers: {
        Authorization: "Bearer " + token,
      },
    })
    .then((res) => {
      dispatch({
        type: GET_BOXES,
        payload: res.data,
      });
      if (setIsLoading) setIsLoading(false);
    })
    .catch((err) => {
      if (err.response) {
        dispatch(
          setSnackData({
            open: true,
            message: err.response.data.message,
            severity: "error",
          })
        );
      }
      if (setIsLoading) setIsLoading(false);
    });
};

export const addBox =
  (id, token, data, setOpen, setIsLoading) => (dispatch, getState) => {
    let boxes = getState().boxes.boxes;
    axios
      .post(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/boxes`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((res) => {
        boxes.push(res.data);
        dispatch({
          type: ADD_BOX,
          payload: boxes,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Caja creada",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const editBox =
  (id, token, idBox, data, setOpen, setIsLoading) => (dispatch, getState) => {
    let boxes = getState().boxes.boxes;
    axios
      .put(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/boxes/${idBox}`,
        data,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        let i = boxes.findIndex((box) => {
          if (box._id === idBox) {
            return true;
          }
          return false;
        });

        if (i !== -1) {
          boxes[i] = Object.assign(boxes[i], data);
        }

        dispatch({
          type: EDIT_BOX,
          payload: boxes,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Caja editada",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };

export const deleteBox =
  (id, token, idBox, setOpen, setIsLoading) => (dispatch, getState) => {
    let boxes = getState().boxes.boxes;
    axios
      .delete(
        `${process.env.REACT_APP_BACKEND_URL}/consortiums/${id}/boxes/${idBox}`,
        {
          headers: {
            Authorization: "Bearer " + token,
          },
        }
      )
      .then((_) => {
        let i = boxes.findIndex((box) => {
          if (box._id === idBox) {
            return true;
          }
          return false;
        });

        i !== -1 && boxes.splice(i, 1);

        dispatch({
          type: DELETE_BOX,
          payload: boxes,
        });
        dispatch(
          setSnackData({
            open: true,
            message: "Caja eliminada",
            severity: "success",
          })
        );
        if (setOpen) setOpen(false);
      })
      .catch((err) => {
        if (err.response) {
          dispatch(
            setSnackData({
              open: true,
              message: err.response.data.message,
              severity: "error",
            })
          );
        }
        if (setIsLoading) setIsLoading(false);
      });
  };
