import React, { useState, Fragment } from "react";
import {
  makeStyles,
  Typography,
  Grid,
  FormControl,
  InputLabel,
  Input,
  Button,
  useTheme,
  useMediaQuery,
  IconButton,
  Tooltip,
} from "@material-ui/core";
import { getFormatDate } from "../../hooks/date-hook";
import ListExpenditures from "../FunctionalUnits/ListExpenditures";
import VisibilityIcon from "@material-ui/icons/Visibility";

const useStyles = makeStyles((theme) => ({
  container: {
    textAlign: "center",
    padding: theme.spacing(1),
  },
  grid: {
    marginTop: theme.spacing(2),
    flexDirection: "row",
    justifyContent: "center",
    alignItems: "center",
  },
  expendituresSection: {
    display: "flex",
    marginTop: theme.spacing(2),
    marginBottom: theme.spacing(2),
  },
  title: {
    fontSize: "14px",
  },
  marginTop: {
    marginTop: theme.spacing(2.5),
  },
  button: {
    marginTop: theme.spacing(2),
    padding: theme.spacing(0.5),
  },
}));

const Details = ({
  establishment,
  setOpen,
  expenditure,
  expendituresTypes,
  boxes,
}) => {
  const classes = useStyles();

  const theme = useTheme();
  const screen = "xs";
  const isMobile = useMediaQuery(theme.breakpoints.down(screen), {
    defaultMatches: true,
  });

  const [expenditures] = useState(() => {
    let obj = expenditure.expendituresTypesPercentages.reduce(
      (obj, expenditure) => {
        return [
          ...obj,
          {
            expenditureType: expenditure.expenditureType,
            percentage: expenditure.percentage,
          },
        ];
      },
      []
    );

    return obj;
  });

  return (
    <div className={classes.container}>
      <Typography variant="h6">Detalles del gasto</Typography>
      <Grid container className={classes.grid} spacing={1}>
        <Grid item xs={12}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Categoria</InputLabel>
            <Input
              id="category"
              value={expenditure.category.name}
              name="category"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        {expenditure.subcategory && (
          <Grid item xs={12}>
            <FormControl style={{ width: "100%" }}>
              <InputLabel htmlFor="my-input">Subcategoria</InputLabel>
              <Input
                id="subcategory"
                value={expenditure.subcategory.name}
                name="subcategory"
                fullWidth
                readOnly={true}
              />
            </FormControl>
          </Grid>
        )}
        <Grid item xs={12}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Proveedor</InputLabel>
            <Input
              id="provider"
              value={expenditure.provider.name}
              name="provider"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        <Grid item xs={isMobile ? 6 : 12} sm={10}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Monto</InputLabel>
            <Input
              id="amount"
              value={expenditure.amount.amount}
              name="amount"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        <Grid item xs={isMobile ? 6 : 12} sm={2}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Moneda</InputLabel>
            <Input
              id="currency"
              value={expenditure.amount.currency}
              name="currency"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        {expenditure.description && (
          <Grid item xs={12}>
            <FormControl style={{ width: "100%" }}>
              <InputLabel htmlFor="my-input">Descripcion</InputLabel>
              <Input
                id="description"
                value={expenditure.description}
                name="description"
                fullWidth
                readOnly={true}
                multiline={true}
              />
            </FormControl>
          </Grid>
        )}
        <Grid
          item
          xs={expenditure.file ? (isMobile ? 6 : 12) : 12}
          sm={expenditure.file ? 10 : 12}
        >
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Factura Nº</InputLabel>
            <Input
              id="number"
              value={expenditure.number}
              name="number"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        {expenditure.file && (
          <Grid item xs={isMobile ? 6 : 12} sm={2}>
            <Tooltip title="Ver factura">
              <a
                href={`${process.env.REACT_APP_BACKEND_URL}/files/${establishment}/${expenditure.file}`}
                rel="noreferrer"
                target="_blank"
              >
                <IconButton
                  variant="contained"
                  color="primary"
                  className={classes.button}
                >
                  <VisibilityIcon />
                </IconButton>
              </a>
            </Tooltip>
          </Grid>
        )}
        <Grid item xs={12}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Imputación</InputLabel>
            <Input
              id="date"
              value={getFormatDate(expenditure.date)}
              name="date"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        <Grid item xs={12}>
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Vencimiento</InputLabel>
            <Input
              id="expiration"
              value={getFormatDate(expenditure.expirationDate)}
              name="expiration"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        <Grid
          item
          xs={12}
          sm={expenditure.box && expenditure.box !== "" ? 6 : 12}
        >
          <FormControl style={{ width: "100%" }}>
            <InputLabel htmlFor="my-input">Estado de pago</InputLabel>
            <Input
              id="status"
              value={expenditure.status}
              name="status"
              fullWidth
              readOnly={true}
            />
          </FormControl>
        </Grid>
        {expenditure.box && expenditure.box !== "" && (
          <Grid item xs={12} sm={6}>
            <FormControl style={{ width: "100%" }}>
              <InputLabel htmlFor="my-input">Caja</InputLabel>
              <Input
                id="box"
                value={
                  boxes.filter((entry) => entry._id === expenditure.box)[0].name
                }
                name="box"
                fullWidth
                readOnly={true}
              />
            </FormControl>
          </Grid>
        )}
        <Grid item xs={12}>
          {expenditure.expendituresTypesPercentages.length > 0 && (
            <Fragment>
              <Grid item xs={12} className={classes.expendituresSection}>
                <Typography className={classes.title}>
                  Clase de gastos:
                </Typography>
              </Grid>
              <ListExpenditures
                expenditures={expenditures}
                expendituresTypes={expendituresTypes}
              />
            </Fragment>
          )}
        </Grid>
        <Grid item xs={12} sm={6}>
          <Button
            className={classes.marginTop}
            variant="contained"
            color="primary"
            disableElevation
            fullWidth
            onClick={() => setOpen(false)}
          >
            Aceptar
          </Button>
        </Grid>
      </Grid>
    </div>
  );
};

export default Details;
