import NumberFormat from "react-number-format";

export const NumberFormatCustom = (
  value,
  prefix,
  fixedDecimalScale,
  suffix
) => {
  return (
    <NumberFormat
      value={value}
      prefix={prefix || "$"}
      suffix={suffix}
      displayType={"text"}
      thousandSeparator={["."]}
      decimalSeparator=","
      decimalScale={2}
      fixedDecimalScale={fixedDecimalScale}
    />
  );
};
