import React, { useEffect, useState } from "react";
import { useDispatch } from "react-redux";
import { useForm } from "../../hooks/use-form";
import { payItem } from "../../Redux/Action/itemActions";
import { getBanks } from "../../Redux/Action/banksActions";

import Form from "./PaymentComponents/Form";
import {
  calculateGroupInterests,
  calculateIndividualInterests,
} from "./PaymentComponents/hooks";
import { getTransactions } from "../../Redux/Action/scheduleActions";

const PayItems = ({
  user,
  idContract,
  idContactCC,
  recent,
  individual,
  setOpen,
  current,
  setRows,
  tenants,
  resetSelected,
}) => {
  const dispatch = useDispatch();

  const [isLoading, setIsLoading] = useState(true);

  const [amounts, setAmounts] = useState({});
  const [items, setItems] = useState([]);

  const [values, setValues] = useState({});

  const [dataPayments, setDataPayments, setFormPayments] = useForm({
    bank: "",
    amount: "",
    number: "",
    expirationDate: null,
    date: null,
  });

  const [dataDiscounts, setDataDiscounts, setFormDiscounts] = useForm({
    amount: "",
    concept: "",
    note: "",
  });

  const [payments, setPayments] = useState([]);
  const [discounts, setDiscounts] = useState([]);
  const [recipients, setRecipients] = useState([]);
  const [selected, setSelected] = useState([]);

  const handleDateChange = (date) => {
    let formatDate = date.toISOString();
    setValues({
      ...values,
      date: formatDate,
    });

    let obj = {
      totalAmount: 0,
      taxes: 0,
      remainsToPay: 0,
      payments: 0,
    };

    if (!individual) {
      let aux = calculateGroupInterests(obj, current, formatDate);
      setItems(aux);
    } else {
      obj.totalAmount += current.amount;
      obj.remainsToPay += current.amount;
      obj.taxes = calculateIndividualInterests(current, formatDate);

      setItems([current]);
    }

    setAmounts({ ...amounts, ...obj });
  };

  const onClickHandler = () => {
    setIsLoading(true);

    let data = {
      date: values.date,
      items: [],
      sendEmail: values.sendEmail === "true" ? true : false,
    };

    for (let entry of items) {
      data.items.push({
        item: entry._id,
        ...(entry.hasOwnProperty("cashToBox")
          ? { cashToBox: entry.cashToBox }
          : {}),
      });
    }

    if (values.notes.value !== "") data.notes = values.notes.value;

    if (values.sendEmail === "true") data.receivers = selected;

    if (individual) {
      data.applyInterests =
        items[0].itemType !== 2
          ? values.checked === "true"
            ? true
            : false
          : false;
    } else {
      data.applyInterests = values.checked === "true" ? true : false;
    }

    if (payments.length > 0) data.payments = payments;

    if (discounts.length > 0) data.discounts = discounts;

    dispatch(
      payItem(
        recent,
        user.token,
        idContract,
        data,
        setOpen,
        setIsLoading,
        setRows,
        resetSelected
      )
    );
  };

  useEffect(() => {
    (async () => {
      let currentDate = new Date();

      let obj = {
        totalAmount: 0,
        taxes: 0,
        remainsToPay: 0,
        payments: 0,
        discounts: 0,
        positiveBalance: 0,
      };

      if (!individual) {
        let aux = calculateGroupInterests(
          obj,
          current,
          currentDate.toISOString()
        );

        setItems(aux);
      } else {
        if (current.itemType === 2) {
          obj.totalAmount += 0;
          obj.remainsToPay += 0;
        } else {
          obj.totalAmount += current.amount - current.payedAmount;
          obj.remainsToPay += current.amount - current.payedAmount;
        }

        obj.taxes = calculateIndividualInterests(
          current,
          currentDate.toISOString()
        );

        setItems([current]);
      }

      setValues({
        checked: "false",
        date: currentDate.toISOString(),
        sendEmail: "true",
        notes: { value: "", isValid: true },
      });

      let arr = [];
      arr = tenants.reduce((arr, tenant) => {
        return [
          ...arr,
          {
            ...tenant,
            checked: true,
          },
        ];
      }, []);

      setSelected(() => {
        let aux = [];
        for (let entry of arr) {
          if (entry._id) aux.push(entry._id);
        }
        return aux;
      });

      setRecipients(arr);

      const setPositiveBalance = (balance) => {
        let value = parseFloat(balance);

        if (obj.remainsToPay - value <= 0) {
          obj.remainsToPay = 0;
        } else {
          obj.remainsToPay -= value;
        }

        obj.positiveBalance = value;

        setAmounts(obj);

        setFormPayments((dataPayments) => {
          let copy = { ...dataPayments };
          for (let key in dataPayments) {
            copy[key] = {
              value: key === "amount" ? obj.remainsToPay : "",
              isValid: true,
            };
          }
          return copy;
        });
      };

      dispatch(getBanks(user.token));
      dispatch(
        getTransactions(
          user.token,
          idContactCC,
          setIsLoading,
          setPositiveBalance
        )
      );
    })();
  }, [
    dispatch,
    user.token,
    idContactCC,
    individual,
    current,
    setFormPayments,
    tenants,
  ]);

  return (
    <Form
      individual={individual}
      title={individual ? `Cobrar (${current.name})` : "Cobrar Items"}
      setOpen={setOpen}
      isLoading={isLoading}
      onClickHandler={onClickHandler}
      amounts={amounts}
      setAmounts={setAmounts}
      items={items}
      setItems={setItems}
      values={values}
      setValues={setValues}
      handleDateChange={handleDateChange}
      dataPayments={dataPayments}
      setDataPayments={setDataPayments}
      setFormPayments={setFormPayments}
      dataDiscounts={dataDiscounts}
      setDataDiscounts={setDataDiscounts}
      setFormDiscounts={setFormDiscounts}
      payments={payments}
      setPayments={setPayments}
      discounts={discounts}
      setDiscounts={setDiscounts}
      recipients={recipients}
      setRecipients={setRecipients}
      selected={selected}
      setSelected={setSelected}
    />
  );
};

export default PayItems;
