import React, { useState, useEffect } from "react";
import TextField from "@material-ui/core/TextField";
import Autocomplete from "@material-ui/lab/Autocomplete";

const EstatesAutoComplete = ({ label, estates, property, setState }) => {
  const [value, setValue] = useState(null);

  useEffect(() => {
    setValue(
      property ? estates.filter((entry) => entry._id === property)[0] : null
    );
  }, [estates, property]);

  return (
    <Autocomplete
      fullWidth
      autoComplete={false}
      freeSolo
      value={value}
      id="controllable-states"
      options={estates.sort()}
      getOptionLabel={(option) => {
        if (option === "") {
          return "";
        }
        return `${option.address}, ${option.location} - (${option.owners[0].owner.name} ${option.owners[0].owner.lastname})`;
      }}
      renderInput={(params) => <TextField {...params} label={label} />}
      onChange={(event, newValue) => {
        if (newValue !== null) {
          setValue(newValue);
          setState(newValue);
        } else {
          setValue("");
          setState(null);
        }
      }}
    />
  );
};

export default EstatesAutoComplete;
